-- ══════════════════════════════════════════════════════════════════════════
-- legacy/add-gdpr.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter :: Module 5 — RODO / GDPR compliance (additive, non-breaking)
-- Run in the Supabase SQL Editor. Safe to re-run.
--
-- Adds: per-applicant consent fields + an immutable consent ledger, a
-- configurable retention window per company, and an anonymization routine
-- (scheduled via pg_cron when available) that scrubs PII + raw resume text
-- from candidates older than the retention window.
-- ============================================================================

-- 1) Retention window per company (days).
ALTER TABLE companies ADD COLUMN IF NOT EXISTS retention_days integer NOT NULL DEFAULT 180;

-- 2) Consent snapshot on the applicant row.
ALTER TABLE candidates ADD COLUMN IF NOT EXISTS consent_given          boolean NOT NULL DEFAULT false;
ALTER TABLE candidates ADD COLUMN IF NOT EXISTS consent_at             timestamptz;
ALTER TABLE candidates ADD COLUMN IF NOT EXISTS consent_ip             inet;
ALTER TABLE candidates ADD COLUMN IF NOT EXISTS consent_policy_version text;
ALTER TABLE candidates ADD COLUMN IF NOT EXISTS anonymized_at          timestamptz;

-- 3) Immutable consent ledger (audit trail beyond the candidate snapshot).
CREATE TABLE IF NOT EXISTS consent_logs (
    id             uuid PRIMARY KEY DEFAULT uuid_generate_v4(),
    company_id     uuid REFERENCES companies(id) ON DELETE CASCADE,
    candidate_id   uuid REFERENCES candidates(id) ON DELETE SET NULL,
    action         text NOT NULL CHECK (action IN ('granted', 'withdrawn', 'updated')),
    policy_version text,
    ip_address     inet,
    user_agent     text,
    created_at     timestamptz DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_consent_candidate ON consent_logs(candidate_id);

ALTER TABLE consent_logs ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "company_read_consent" ON consent_logs;
CREATE POLICY "company_read_consent" ON consent_logs FOR SELECT USING (
    company_id IN (
        SELECT company_id FROM company_users
        WHERE privy_user_id = current_setting('app.current_privy_user_id', true)
           OR auth_user_id = auth.uid()
    )
);

-- 4) Log a consent action (called from the public apply flow -> anon allowed).
CREATE OR REPLACE FUNCTION log_consent(
    p_candidate_id   uuid,
    p_action         text,
    p_policy_version text,
    p_ip             text,
    p_user_agent     text
)
RETURNS jsonb AS $$
DECLARE v_company_id uuid;
BEGIN
    SELECT company_id INTO v_company_id FROM candidates WHERE id = p_candidate_id;
    IF v_company_id IS NULL THEN RETURN jsonb_build_object('ok', false, 'reason', 'no_candidate'); END IF;

    INSERT INTO consent_logs (company_id, candidate_id, action, policy_version, ip_address, user_agent)
    VALUES (v_company_id, p_candidate_id, p_action, NULLIF(p_policy_version, ''),
            NULLIF(p_ip, '')::inet, NULLIF(p_user_agent, ''));

    IF p_action = 'granted' THEN
        UPDATE candidates
        SET consent_given = true,
            consent_at = now(),
            consent_ip = NULLIF(p_ip, '')::inet,
            consent_policy_version = NULLIF(p_policy_version, '')
        WHERE id = p_candidate_id;
    ELSIF p_action = 'withdrawn' THEN
        UPDATE candidates SET consent_given = false WHERE id = p_candidate_id;
    END IF;

    RETURN jsonb_build_object('ok', true);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- 5) Anonymize candidates past their company's retention window.
--    Scrubs PII + raw resume text; KEEPS non-PII analytics (scores, source,
--    timestamps). Skips hired candidates and already-anonymized rows.
--    `email` is NOT NULL/unique, so we redact to a stable placeholder.
CREATE OR REPLACE FUNCTION anonymize_expired_candidates()
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE affected integer;
BEGIN
    UPDATE candidates c
    SET resume_raw_text = NULL,
        cv_url          = NULL,
        full_name       = 'Anonymized Candidate',
        email           = 'redacted-' || c.id || '@anonymized.invalid',
        phone           = NULL,
        linkedin_url    = NULL,
        consent_ip      = NULL,
        anonymized_at   = now()
    FROM companies o
    WHERE c.company_id = o.id
      AND c.anonymized_at IS NULL
      AND c.status <> 'hired'
      AND c.applied_at < now() - make_interval(days => o.retention_days);
    GET DIAGNOSTICS affected = ROW_COUNT;
    RETURN affected;
END;
$$;

-- 6) Manual, company-scoped anonymization trigger for recruiters/admins.
CREATE OR REPLACE FUNCTION run_anonymization(p_privy_user_id text)
RETURNS jsonb AS $$
DECLARE v_company_id uuid; v_retention integer; affected integer;
BEGIN
    SELECT cu.company_id, co.retention_days INTO v_company_id, v_retention
    FROM company_users cu JOIN companies co ON co.id = cu.company_id
    WHERE cu.privy_user_id = p_privy_user_id LIMIT 1;
    IF v_company_id IS NULL THEN RAISE EXCEPTION 'RECRUITER_NOT_FOUND'; END IF;

    UPDATE candidates c
    SET resume_raw_text = NULL, cv_url = NULL, full_name = 'Anonymized Candidate',
        email = 'redacted-' || c.id || '@anonymized.invalid',
        phone = NULL, linkedin_url = NULL, consent_ip = NULL, anonymized_at = now()
    WHERE c.company_id = v_company_id
      AND c.anonymized_at IS NULL
      AND c.status <> 'hired'
      AND c.applied_at < now() - make_interval(days => v_retention);
    GET DIAGNOSTICS affected = ROW_COUNT;
    RETURN jsonb_build_object('ok', true, 'anonymized', affected);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- 7) Update a company's retention window (admin).
CREATE OR REPLACE FUNCTION set_retention_days(p_privy_user_id text, p_days integer)
RETURNS jsonb AS $$
DECLARE v_company_id uuid;
BEGIN
    SELECT company_id INTO v_company_id FROM company_users WHERE privy_user_id = p_privy_user_id LIMIT 1;
    IF v_company_id IS NULL THEN RAISE EXCEPTION 'RECRUITER_NOT_FOUND'; END IF;
    IF p_days < 30 OR p_days > 3650 THEN RAISE EXCEPTION 'RETENTION_OUT_OF_RANGE'; END IF;
    UPDATE companies SET retention_days = p_days WHERE id = v_company_id;
    RETURN jsonb_build_object('ok', true, 'retention_days', p_days);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

GRANT EXECUTE ON FUNCTION log_consent(uuid, text, text, text, text) TO authenticated, anon;
GRANT EXECUTE ON FUNCTION run_anonymization(text)                   TO authenticated;
GRANT EXECUTE ON FUNCTION set_retention_days(text, integer)         TO authenticated;

-- 8) Schedule daily anonymization at 03:30 if pg_cron is enabled (no-op otherwise).
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_cron') THEN
        PERFORM cron.schedule('runbutter-anonymize-daily', '30 3 * * *',
            $cron$ SELECT anonymize_expired_candidates(); $cron$);
    END IF;
END$$;

-- ══════════════════════════════════════════════════════════════════════════
-- legacy/add-message-templates.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter :: Custom email templates + candidate messaging (additive)
-- Run in the Supabase SQL Editor. Safe to re-run.
--
-- Lets recruiters create reusable, editable email templates (invite, decline,
-- offer, reminder, custom) with {{variables}}, send them to candidates from the
-- dashboard, and keep a message history per candidate.
--
-- This script is self-contained and idempotent: it enables its own extension,
-- drops any stale versions of the RPCs (which otherwise cause PostgREST 400
-- "could not choose the best candidate function" errors), recreates everything,
-- and forces a PostgREST schema-cache reload at the end.
-- ============================================================================

-- uuid_generate_v4() lives in uuid-ossp. The base schema enables it, but we do
-- it here too so this migration works even if run on its own.
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

CREATE TABLE IF NOT EXISTS message_templates (
    id         uuid PRIMARY KEY DEFAULT uuid_generate_v4(),
    company_id uuid REFERENCES companies(id) ON DELETE CASCADE,
    name       text NOT NULL,
    subject    text NOT NULL,
    body       text NOT NULL,
    category   text NOT NULL DEFAULT 'custom',  -- invite | decline | offer | reminder | custom
    created_at timestamptz DEFAULT now(),
    updated_at timestamptz DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_msg_templates_company ON message_templates(company_id);

CREATE TABLE IF NOT EXISTS candidate_messages (
    id           uuid PRIMARY KEY DEFAULT uuid_generate_v4(),
    company_id   uuid REFERENCES companies(id) ON DELETE CASCADE,
    candidate_id uuid REFERENCES candidates(id) ON DELETE CASCADE,
    subject      text,
    body         text,
    sent_by      uuid REFERENCES company_users(id) ON DELETE SET NULL,
    created_at   timestamptz DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_cand_messages_candidate ON candidate_messages(candidate_id, created_at DESC);

ALTER TABLE message_templates  ENABLE ROW LEVEL SECURITY;
ALTER TABLE candidate_messages ENABLE ROW LEVEL SECURITY;

DO $$
DECLARE t text;
BEGIN
    FOREACH t IN ARRAY ARRAY['message_templates', 'candidate_messages'] LOOP
        EXECUTE format('DROP POLICY IF EXISTS "company_read_%1$s" ON %1$I;', t);
        EXECUTE format($f$
            CREATE POLICY "company_read_%1$s" ON %1$I FOR SELECT USING (
                company_id IN (
                    SELECT company_id FROM company_users
                    WHERE privy_user_id = current_setting('app.current_privy_user_id', true)
                       OR auth_user_id = auth.uid()
                )
            );
        $f$, t);
    END LOOP;
END$$;

-- Seed sensible defaults for any company that has none yet.
INSERT INTO message_templates (company_id, name, subject, body, category)
SELECT c.id, d.name, d.subject, d.body, d.category
FROM companies c
CROSS JOIN (VALUES
    ('Interview invitation',
     'Interview invitation — {{position}} at {{company}}',
     E'Hi {{first_name}},\n\nThanks for applying for {{position}} at {{company}}. We were impressed and would love to invite you to an interview.\n\nPlease let us know your availability over the next few days and we''ll send a calendar invite.\n\nLooking forward to speaking with you!\n\nBest regards,\nThe {{company}} Hiring Team',
     'invite'),
    ('Polite rejection',
     'Update on your application for {{position}}',
     E'Hi {{first_name}},\n\nThank you for your interest in {{position}} at {{company}} and for the time you invested in applying.\n\nAfter careful consideration, we won''t be moving forward at this stage. This was a competitive process and the decision was not easy. We''d be glad to keep your details on file for future roles that match your skills.\n\nWishing you the very best,\nThe {{company}} Hiring Team',
     'decline'),
    ('Offer',
     'Your offer from {{company}}',
     E'Hi {{first_name}},\n\nWe''re delighted to offer you the {{position}} role at {{company}}! We''ll follow up shortly with the full details.\n\nCongratulations — we''re excited about the prospect of you joining the team.\n\nBest regards,\nThe {{company}} Hiring Team',
     'offer'),
    ('Assessment reminder',
     'Reminder: finish your assessment for {{position}}',
     E'Hi {{first_name}},\n\nJust a friendly nudge to complete your short assessment for {{position}} at {{company}}. It takes about 5 minutes and is the next step in your application.\n\nThanks!\nThe {{company}} Hiring Team',
     'reminder')
) AS d(name, subject, body, category)
WHERE NOT EXISTS (SELECT 1 FROM message_templates m WHERE m.company_id = c.id);

-- RPCs --------------------------------------------------------------------
-- Drop EVERY existing overload of these function names first. CREATE OR REPLACE
-- only replaces a function with an identical signature; if an older version with
-- different argument types exists, you end up with two overloads and PostgREST
-- returns HTTP 400 ("could not choose the best candidate function"). This wipes
-- the slate so the definitions below are the only ones that exist.
DO $$
DECLARE r record;
BEGIN
    FOR r IN
        SELECT 'DROP FUNCTION IF EXISTS ' || oid::regprocedure || ' CASCADE;' AS stmt
        FROM pg_proc
        WHERE pronamespace = 'public'::regnamespace
          AND proname IN ('get_message_templates', 'upsert_message_template',
                          'delete_message_template', 'log_candidate_message')
    LOOP
        EXECUTE r.stmt;
    END LOOP;
END$$;

CREATE OR REPLACE FUNCTION get_message_templates(p_privy_user_id text)
RETURNS jsonb AS $$
DECLARE v_company_id uuid;
BEGIN
    SELECT company_id INTO v_company_id FROM company_users WHERE privy_user_id = p_privy_user_id LIMIT 1;
    IF v_company_id IS NULL THEN RETURN '[]'::jsonb; END IF;
    -- Order by created_at directly off the table; building the JSON object
    -- explicitly keeps the payload to the 5 fields the UI needs. (The previous
    -- version ordered by t.created_at on a subquery that didn't select it,
    -- which raised "column t.created_at does not exist" for any real company.)
    RETURN (
        SELECT COALESCE(jsonb_agg(
            jsonb_build_object(
                'id', t.id, 'name', t.name, 'subject', t.subject,
                'body', t.body, 'category', t.category
            ) ORDER BY t.created_at
        ), '[]'::jsonb)
        FROM message_templates t
        WHERE t.company_id = v_company_id
    );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION upsert_message_template(
    p_privy_user_id text, p_id uuid, p_name text, p_subject text, p_body text, p_category text
)
RETURNS jsonb AS $$
DECLARE v_company_id uuid; v_row message_templates;
BEGIN
    SELECT company_id INTO v_company_id FROM company_users WHERE privy_user_id = p_privy_user_id LIMIT 1;
    IF v_company_id IS NULL THEN RAISE EXCEPTION 'RECRUITER_NOT_FOUND'; END IF;

    IF p_id IS NULL THEN
        INSERT INTO message_templates (company_id, name, subject, body, category)
        VALUES (v_company_id, p_name, p_subject, p_body, COALESCE(NULLIF(p_category,''),'custom'))
        RETURNING * INTO v_row;
    ELSE
        UPDATE message_templates
        SET name = p_name, subject = p_subject, body = p_body,
            category = COALESCE(NULLIF(p_category,''),'custom'), updated_at = now()
        WHERE id = p_id AND company_id = v_company_id
        RETURNING * INTO v_row;
        IF v_row.id IS NULL THEN RAISE EXCEPTION 'TEMPLATE_NOT_FOUND'; END IF;
    END IF;
    RETURN row_to_json(v_row);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION delete_message_template(p_privy_user_id text, p_id uuid)
RETURNS jsonb AS $$
DECLARE v_company_id uuid;
BEGIN
    SELECT company_id INTO v_company_id FROM company_users WHERE privy_user_id = p_privy_user_id LIMIT 1;
    IF v_company_id IS NULL THEN RAISE EXCEPTION 'RECRUITER_NOT_FOUND'; END IF;
    DELETE FROM message_templates WHERE id = p_id AND company_id = v_company_id;
    RETURN jsonb_build_object('ok', true);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Records a sent message in history (called by the send route after delivery).
CREATE OR REPLACE FUNCTION log_candidate_message(
    p_privy_user_id text, p_candidate_id uuid, p_subject text, p_body text
)
RETURNS jsonb AS $$
DECLARE v_company_id uuid; v_user_id uuid; v_cand_company uuid;
BEGIN
    SELECT id, company_id INTO v_user_id, v_company_id FROM company_users WHERE privy_user_id = p_privy_user_id LIMIT 1;
    IF v_company_id IS NULL THEN RAISE EXCEPTION 'RECRUITER_NOT_FOUND'; END IF;
    SELECT company_id INTO v_cand_company FROM candidates WHERE id = p_candidate_id;
    IF v_cand_company IS NULL OR v_cand_company <> v_company_id THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;

    INSERT INTO candidate_messages (company_id, candidate_id, subject, body, sent_by)
    VALUES (v_company_id, p_candidate_id, p_subject, p_body, v_user_id);
    RETURN jsonb_build_object('ok', true);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

GRANT EXECUTE ON FUNCTION get_message_templates(text)                                   TO authenticated, anon;
GRANT EXECUTE ON FUNCTION upsert_message_template(text, uuid, text, text, text, text)   TO authenticated, anon;
GRANT EXECUTE ON FUNCTION delete_message_template(text, uuid)                           TO authenticated, anon;
GRANT EXECUTE ON FUNCTION log_candidate_message(text, uuid, text, text)                 TO authenticated, anon;

-- Force PostgREST to reload its schema cache so the new RPCs are callable
-- immediately (a freshly created function can otherwise 404/400 until reload).
NOTIFY pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- legacy/add-my-team.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter :: Module 4 — "My Team" post-hire workspace (additive, non-breaking)
-- Run in the Supabase SQL Editor. Safe to re-run.
--
-- "My Team" = candidates with status = 'hired'. No separate employees table —
-- we read the hired candidate + their latest assessment scores directly.
-- Adds: weekly pulse check-ins, 2-strike retention alerts, persisted
-- onboarding checklist tasks, and the RPCs the workspace needs.
-- ============================================================================

-- 1) Weekly pulse check-ins.
CREATE TABLE IF NOT EXISTS pulse_checkins (
    id           uuid PRIMARY KEY DEFAULT uuid_generate_v4(),
    company_id   uuid REFERENCES companies(id) ON DELETE CASCADE,
    candidate_id uuid REFERENCES candidates(id) ON DELETE CASCADE,
    week_start   date NOT NULL,
    mood         text NOT NULL CHECK (mood IN ('happy', 'balanced', 'overwhelmed')),
    note         text,
    created_at   timestamptz DEFAULT now(),
    UNIQUE (candidate_id, week_start)
);
CREATE INDEX IF NOT EXISTS idx_pulse_candidate ON pulse_checkins(candidate_id, week_start DESC);

-- 2) Retention alerts (fired by the streak trigger below).
CREATE TABLE IF NOT EXISTS retention_alerts (
    id           uuid PRIMARY KEY DEFAULT uuid_generate_v4(),
    company_id   uuid REFERENCES companies(id) ON DELETE CASCADE,
    candidate_id uuid REFERENCES candidates(id) ON DELETE CASCADE,
    reason       text NOT NULL,
    is_resolved  boolean NOT NULL DEFAULT false,
    created_at   timestamptz DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_alerts_open ON retention_alerts(company_id) WHERE NOT is_resolved;

-- 3) Persisted onboarding checklist tasks (items themselves are generated
--    client-side from traits; we only store completion state by task_key).
CREATE TABLE IF NOT EXISTS onboarding_tasks (
    id           uuid PRIMARY KEY DEFAULT uuid_generate_v4(),
    company_id   uuid REFERENCES companies(id) ON DELETE CASCADE,
    candidate_id uuid REFERENCES candidates(id) ON DELETE CASCADE,
    task_key     text NOT NULL,
    title        text NOT NULL,
    is_done      boolean NOT NULL DEFAULT false,
    created_at   timestamptz DEFAULT now(),
    UNIQUE (candidate_id, task_key)
);
CREATE INDEX IF NOT EXISTS idx_onb_tasks_candidate ON onboarding_tasks(candidate_id);

-- 4) Fire a high-priority retention alert on two consecutive 'overwhelmed' weeks.
CREATE OR REPLACE FUNCTION check_pulse_streak()
RETURNS trigger AS $$
DECLARE prev_mood text;
BEGIN
    IF NEW.mood = 'overwhelmed' THEN
        SELECT mood INTO prev_mood FROM pulse_checkins
        WHERE candidate_id = NEW.candidate_id AND week_start = (NEW.week_start - 7)
        ORDER BY week_start DESC LIMIT 1;

        IF prev_mood = 'overwhelmed' THEN
            INSERT INTO retention_alerts (company_id, candidate_id, reason)
            VALUES (NEW.company_id, NEW.candidate_id, 'overwhelmed_2wk');
        END IF;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_pulse_streak ON pulse_checkins;
CREATE TRIGGER trg_pulse_streak AFTER INSERT ON pulse_checkins
    FOR EACH ROW EXECUTE FUNCTION check_pulse_streak();

-- 5) RLS (writes via SECURITY DEFINER RPCs; these guard direct reads).
ALTER TABLE pulse_checkins   ENABLE ROW LEVEL SECURITY;
ALTER TABLE retention_alerts ENABLE ROW LEVEL SECURITY;
ALTER TABLE onboarding_tasks ENABLE ROW LEVEL SECURITY;

DO $$
DECLARE t text;
BEGIN
    FOREACH t IN ARRAY ARRAY['pulse_checkins', 'retention_alerts', 'onboarding_tasks'] LOOP
        EXECUTE format('DROP POLICY IF EXISTS "company_read_%1$s" ON %1$I;', t);
        EXECUTE format($f$
            CREATE POLICY "company_read_%1$s" ON %1$I FOR SELECT USING (
                company_id IN (
                    SELECT company_id FROM company_users
                    WHERE privy_user_id = current_setting('app.current_privy_user_id', true)
                       OR auth_user_id = auth.uid()
                )
            );
        $f$, t);
    END LOOP;
END$$;

-- 6) RPCs.
CREATE OR REPLACE FUNCTION get_my_team(p_privy_user_id text)
RETURNS jsonb AS $$
DECLARE v_company_id uuid;
BEGIN
    SELECT company_id INTO v_company_id FROM company_users WHERE privy_user_id = p_privy_user_id LIMIT 1;
    IF v_company_id IS NULL THEN RETURN '[]'::jsonb; END IF;

    RETURN (
        SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb)
        FROM (
            SELECT
                can.id, can.full_name, can.email, can.position_id, can.updated_at,
                pos.title AS position_title, pos.neuro_profile AS position_neuro_profile,
                res.overall_score, res.personality_score, res.work_style_score, res.cognitive_score,
                res.personality_data, res.work_style_data,
                (SELECT mood FROM pulse_checkins p WHERE p.candidate_id = can.id ORDER BY week_start DESC LIMIT 1) AS latest_mood,
                EXISTS (SELECT 1 FROM retention_alerts a WHERE a.candidate_id = can.id AND NOT a.is_resolved) AS has_alert,
                (SELECT count(*) FROM onboarding_tasks o WHERE o.candidate_id = can.id) AS task_total,
                (SELECT count(*) FROM onboarding_tasks o WHERE o.candidate_id = can.id AND o.is_done) AS task_done
            FROM candidates can
            LEFT JOIN positions pos ON pos.id = can.position_id
            LEFT JOIN LATERAL (
                SELECT * FROM assessment_results r WHERE r.candidate_id = can.id
                ORDER BY completed_at DESC NULLS LAST LIMIT 1
            ) res ON true
            WHERE can.company_id = v_company_id AND can.status = 'hired'
            ORDER BY can.updated_at DESC
        ) t
    );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION record_pulse(
    p_privy_user_id text, p_candidate_id uuid, p_week_start date, p_mood text, p_note text
)
RETURNS jsonb AS $$
DECLARE v_company_id uuid; v_cand_company uuid;
BEGIN
    SELECT company_id INTO v_company_id FROM company_users WHERE privy_user_id = p_privy_user_id LIMIT 1;
    IF v_company_id IS NULL THEN RAISE EXCEPTION 'RECRUITER_NOT_FOUND'; END IF;
    SELECT company_id INTO v_cand_company FROM candidates WHERE id = p_candidate_id;
    IF v_cand_company IS NULL OR v_cand_company <> v_company_id THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;

    INSERT INTO pulse_checkins (company_id, candidate_id, week_start, mood, note)
    VALUES (v_company_id, p_candidate_id, p_week_start, p_mood, NULLIF(p_note, ''))
    ON CONFLICT (candidate_id, week_start) DO UPDATE SET mood = EXCLUDED.mood, note = EXCLUDED.note;

    RETURN jsonb_build_object('ok', true);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION get_onboarding_tasks(p_privy_user_id text, p_candidate_id uuid)
RETURNS jsonb AS $$
DECLARE v_company_id uuid;
BEGIN
    SELECT company_id INTO v_company_id FROM company_users WHERE privy_user_id = p_privy_user_id LIMIT 1;
    IF v_company_id IS NULL THEN RETURN '[]'::jsonb; END IF;
    RETURN (
        SELECT COALESCE(jsonb_agg(row_to_json(o)), '[]'::jsonb)
        FROM (
            SELECT task_key, title, is_done FROM onboarding_tasks
            WHERE candidate_id = p_candidate_id AND company_id = v_company_id
        ) o
    );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION set_onboarding_task(
    p_privy_user_id text, p_candidate_id uuid, p_task_key text, p_title text, p_is_done boolean
)
RETURNS jsonb AS $$
DECLARE v_company_id uuid; v_cand_company uuid;
BEGIN
    SELECT company_id INTO v_company_id FROM company_users WHERE privy_user_id = p_privy_user_id LIMIT 1;
    IF v_company_id IS NULL THEN RAISE EXCEPTION 'RECRUITER_NOT_FOUND'; END IF;
    SELECT company_id INTO v_cand_company FROM candidates WHERE id = p_candidate_id;
    IF v_cand_company IS NULL OR v_cand_company <> v_company_id THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;

    INSERT INTO onboarding_tasks (company_id, candidate_id, task_key, title, is_done)
    VALUES (v_company_id, p_candidate_id, p_task_key, p_title, p_is_done)
    ON CONFLICT (candidate_id, task_key) DO UPDATE SET is_done = EXCLUDED.is_done, title = EXCLUDED.title;

    RETURN jsonb_build_object('ok', true);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

GRANT EXECUTE ON FUNCTION get_my_team(text)                              TO authenticated, anon;
GRANT EXECUTE ON FUNCTION record_pulse(text, uuid, date, text, text)     TO authenticated, anon;
GRANT EXECUTE ON FUNCTION get_onboarding_tasks(text, uuid)               TO authenticated, anon;
GRANT EXECUTE ON FUNCTION set_onboarding_task(text, uuid, text, text, boolean) TO authenticated, anon;

-- ══════════════════════════════════════════════════════════════════════════
-- legacy/add-resume-search.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter :: Module 1 — Zero-cost resume search (additive, non-breaking)
-- Run this in the Supabase SQL Editor. Safe to re-run (idempotent).
--
-- Adds raw resume text + a generated tsvector + GIN index to `candidates`,
-- and a search RPC that mirrors get_candidates_for_recruiter() but filters
-- and ranks by native Postgres Full-Text Search. No LLM tokens involved.
-- ============================================================================

-- 1) Raw extracted CV text (filled server-side by pdf-parse / mammoth).
ALTER TABLE candidates ADD COLUMN IF NOT EXISTS resume_raw_text text;

-- 2) Generated FTS vector. 'simple' config keeps tech tokens intact
--    (React stays React, no stemming) and works for mixed PL/EN content.
--    Generated + STORED so it stays in sync automatically and is indexable.
ALTER TABLE candidates
  ADD COLUMN IF NOT EXISTS resume_tsv tsvector
  GENERATED ALWAYS AS (to_tsvector('simple', coalesce(resume_raw_text, ''))) STORED;

-- 3) GIN index = single-digit-ms Boolean queries across tens of thousands of rows.
CREATE INDEX IF NOT EXISTS idx_candidates_resume_tsv ON candidates USING gin (resume_tsv);

-- Optional: track when text was last extracted (useful for backfill / re-parse).
ALTER TABLE candidates ADD COLUMN IF NOT EXISTS resume_parsed_at timestamptz;

-- ----------------------------------------------------------------------------
-- 4) SECURE RPC: search candidates for a recruiter by Boolean keyword query.
--    Mirrors get_candidates_for_recruiter() exactly (same return shape) so the
--    dashboard can swap between them with no mapping changes.
--
--    p_query uses websearch syntax (injection-safe, never throws):
--       react node           -> react AND node
--       react or vue         -> react OR vue
--       react -junior        -> react AND NOT junior
--       "node.js"            -> exact phrase
--    Empty/null query -> returns all company candidates (same as the list view).
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION search_candidates_for_recruiter(
    p_privy_user_id text,
    p_query text DEFAULT NULL
)
RETURNS jsonb AS $$
DECLARE
    v_company_id UUID;
    v_query      tsquery;
    v_q          text := nullif(btrim(coalesce(p_query, '')), '');
BEGIN
    SELECT company_id INTO v_company_id
    FROM company_users WHERE privy_user_id = p_privy_user_id LIMIT 1;

    IF v_company_id IS NULL THEN
        RETURN '[]'::jsonb;
    END IF;

    -- No query -> behave like the plain list (most recent first).
    IF v_q IS NULL THEN
        RETURN (
            SELECT COALESCE(jsonb_agg(row_to_json(c)), '[]'::jsonb)
            FROM (
                SELECT can.*,
                       pos.title AS position_title,
                       0::real   AS keyword_density,
                       (SELECT jsonb_agg(res ORDER BY completed_at DESC)
                          FROM assessment_results res WHERE res.candidate_id = can.id) AS assessment_results
                FROM candidates can
                LEFT JOIN positions pos ON can.position_id = pos.id
                WHERE can.company_id = v_company_id
                ORDER BY can.applied_at DESC
            ) c
        );
    END IF;

    -- websearch_to_tsquery is safe against arbitrary user input.
    v_query := websearch_to_tsquery('simple', v_q);

    RETURN (
        SELECT COALESCE(jsonb_agg(row_to_json(c)), '[]'::jsonb)
        FROM (
            SELECT can.*,
                   pos.title AS position_title,
                   ts_rank(can.resume_tsv, v_query) AS keyword_density,
                   (SELECT jsonb_agg(res ORDER BY completed_at DESC)
                      FROM assessment_results res WHERE res.candidate_id = can.id) AS assessment_results
            FROM candidates can
            LEFT JOIN positions pos ON can.position_id = pos.id
            WHERE can.company_id = v_company_id
              AND (
                    can.resume_tsv @@ v_query          -- resume keyword hit
                 OR can.full_name ILIKE '%' || v_q || '%'   -- still match name
                 OR can.email     ILIKE '%' || v_q || '%'   -- ...and email
              )
            -- best keyword fit first, then most recent
            ORDER BY ts_rank(can.resume_tsv, v_query) DESC, can.applied_at DESC
        ) c
    );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

GRANT EXECUTE ON FUNCTION search_candidates_for_recruiter(text, text) TO authenticated, anon;

-- ══════════════════════════════════════════════════════════════════════════
-- legacy/add-source-attribution.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter :: Module 3 — Source Tracking & Attribution (additive, non-breaking)
-- Run in the Supabase SQL Editor. Safe to re-run.
--
-- Adds per-position tracking links (with UTM defaults + click counts), captures
-- UTM params + referrer on each candidate, and exposes RPCs to generate links,
-- list their performance, register clicks, and summarise source attribution.
-- ============================================================================

-- 1) Tracking links: one+ shareable link per position, each with a short token.
CREATE TABLE IF NOT EXISTS tracking_links (
    id           uuid PRIMARY KEY DEFAULT uuid_generate_v4(),
    company_id   uuid REFERENCES companies(id) ON DELETE CASCADE,
    position_id  uuid REFERENCES positions(id) ON DELETE CASCADE,
    token        text UNIQUE NOT NULL DEFAULT substr(replace(uuid_generate_v4()::text, '-', ''), 1, 12),
    label        text,
    source       text,             -- channel: linkedin, indeed, pracuj_pl, referral, ...
    utm_source   text,
    utm_medium   text,
    utm_campaign text,
    click_count  integer NOT NULL DEFAULT 0,
    is_active    boolean NOT NULL DEFAULT true,
    created_at   timestamptz DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_tracking_links_company  ON tracking_links(company_id);
CREATE INDEX IF NOT EXISTS idx_tracking_links_position ON tracking_links(position_id);

-- 2) Attribution columns on the applicant row.
ALTER TABLE candidates ADD COLUMN IF NOT EXISTS utm_source   text;
ALTER TABLE candidates ADD COLUMN IF NOT EXISTS utm_medium   text;
ALTER TABLE candidates ADD COLUMN IF NOT EXISTS utm_campaign text;
ALTER TABLE candidates ADD COLUMN IF NOT EXISTS referrer     text;
ALTER TABLE candidates ADD COLUMN IF NOT EXISTS tracking_link_id uuid REFERENCES tracking_links(id) ON DELETE SET NULL;

CREATE INDEX IF NOT EXISTS idx_candidates_source        ON candidates(company_id, source);
CREATE INDEX IF NOT EXISTS idx_candidates_tracking_link ON candidates(tracking_link_id);

-- 3) RLS (writes go through SECURITY DEFINER RPCs; this guards direct reads).
ALTER TABLE tracking_links ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Company can view tracking links" ON tracking_links;
CREATE POLICY "Company can view tracking links" ON tracking_links
    FOR SELECT USING (
        company_id IN (
            SELECT company_id FROM company_users
            WHERE privy_user_id = current_setting('app.current_privy_user_id', true)
               OR auth_user_id = auth.uid()
        )
    );

-- 4) Create a tracking link (recruiter-owned position only).
CREATE OR REPLACE FUNCTION create_tracking_link(
    p_privy_user_id text,
    p_position_id   uuid,
    p_label         text,
    p_source        text,
    p_utm_source    text,
    p_utm_medium    text,
    p_utm_campaign  text
)
RETURNS jsonb AS $$
DECLARE
    v_company_id uuid;
    v_pos_company uuid;
    v_row tracking_links;
BEGIN
    SELECT company_id INTO v_company_id FROM company_users WHERE privy_user_id = p_privy_user_id LIMIT 1;
    IF v_company_id IS NULL THEN RAISE EXCEPTION 'RECRUITER_NOT_FOUND'; END IF;

    SELECT company_id INTO v_pos_company FROM positions WHERE id = p_position_id;
    IF v_pos_company IS NULL OR v_pos_company <> v_company_id THEN
        RAISE EXCEPTION 'POSITION_NOT_FOUND_OR_FORBIDDEN';
    END IF;

    INSERT INTO tracking_links (company_id, position_id, label, source, utm_source, utm_medium, utm_campaign)
    VALUES (v_company_id, p_position_id, NULLIF(p_label, ''), NULLIF(p_source, ''),
            NULLIF(p_utm_source, ''), NULLIF(p_utm_medium, ''), NULLIF(p_utm_campaign, ''))
    RETURNING * INTO v_row;

    RETURN row_to_json(v_row);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- 5) List a company's tracking links with click + applicant counts.
CREATE OR REPLACE FUNCTION get_tracking_links(p_privy_user_id text)
RETURNS jsonb AS $$
DECLARE v_company_id uuid;
BEGIN
    SELECT company_id INTO v_company_id FROM company_users WHERE privy_user_id = p_privy_user_id LIMIT 1;
    IF v_company_id IS NULL THEN RETURN '[]'::jsonb; END IF;

    RETURN (
        SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY t.created_at DESC), '[]'::jsonb)
        FROM (
            SELECT tl.*,
                   pos.title AS position_title,
                   (SELECT count(*) FROM candidates c WHERE c.tracking_link_id = tl.id) AS applicant_count
            FROM tracking_links tl
            LEFT JOIN positions pos ON pos.id = tl.position_id
            WHERE tl.company_id = v_company_id
        ) t
    );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- 6) Register a click and return attribution defaults (public / candidate-facing).
CREATE OR REPLACE FUNCTION register_link_click(p_token text)
RETURNS jsonb AS $$
DECLARE v_row tracking_links;
BEGIN
    UPDATE tracking_links
       SET click_count = click_count + 1
     WHERE token = p_token AND is_active = true
    RETURNING * INTO v_row;

    IF v_row.id IS NULL THEN RETURN NULL; END IF;

    RETURN jsonb_build_object(
        'id', v_row.id,
        'position_id', v_row.position_id,
        'source', v_row.source,
        'utm_source', v_row.utm_source,
        'utm_medium', v_row.utm_medium,
        'utm_campaign', v_row.utm_campaign
    );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- 7) Source attribution summary: applicants, assessed, hired, avg match per source.
CREATE OR REPLACE FUNCTION get_source_attribution(p_privy_user_id text)
RETURNS jsonb AS $$
DECLARE v_company_id uuid;
BEGIN
    SELECT company_id INTO v_company_id FROM company_users WHERE privy_user_id = p_privy_user_id LIMIT 1;
    IF v_company_id IS NULL THEN RETURN '[]'::jsonb; END IF;

    RETURN (
        SELECT COALESCE(jsonb_agg(row_to_json(s) ORDER BY s.applicants DESC), '[]'::jsonb)
        FROM (
            SELECT
                COALESCE(NULLIF(c.source, ''), 'direct') AS source,
                count(*) AS applicants,
                count(*) FILTER (
                    WHERE c.status IN ('assessment_completed','interview_scheduled','interviewed','offered','hired')
                ) AS assessed,
                count(*) FILTER (WHERE c.status = 'hired') AS hired,
                round(avg(r.overall_score)) AS avg_match
            FROM candidates c
            LEFT JOIN LATERAL (
                SELECT overall_score FROM assessment_results ar
                WHERE ar.candidate_id = c.id
                ORDER BY completed_at DESC NULLS LAST LIMIT 1
            ) r ON true
            WHERE c.company_id = v_company_id
            GROUP BY COALESCE(NULLIF(c.source, ''), 'direct')
        ) s
    );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- 8) Permissions.
GRANT EXECUTE ON FUNCTION create_tracking_link(text, uuid, text, text, text, text, text) TO authenticated, anon;
GRANT EXECUTE ON FUNCTION get_tracking_links(text)      TO authenticated, anon;
GRANT EXECUTE ON FUNCTION register_link_click(text)     TO authenticated, anon;
GRANT EXECUTE ON FUNCTION get_source_attribution(text)  TO authenticated, anon;

-- ══════════════════════════════════════════════════════════════════════════
-- legacy/add-treasury-dataset.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter :: Module 2 — Talent Treasury dataset (additive, non-breaking)
-- Run in the Supabase SQL Editor. Safe to re-run.
--
-- Provides ONE secure RPC that returns a company's candidates with their
-- latest assessment scores in a single call. The faceted sidebar, sliders,
-- sorting and micro-insights are all computed client-side for instant,
-- zero-reload interaction — so this is the only DB round-trip the page needs.
-- ============================================================================

-- Speeds up the "latest result per candidate" lookup below.
CREATE INDEX IF NOT EXISTS idx_results_candidate_completed
  ON assessment_results (candidate_id, completed_at DESC);

CREATE OR REPLACE FUNCTION get_treasury_dataset(p_privy_user_id text)
RETURNS jsonb AS $$
DECLARE
    v_company_id uuid;
BEGIN
    SELECT company_id INTO v_company_id
    FROM company_users WHERE privy_user_id = p_privy_user_id LIMIT 1;

    IF v_company_id IS NULL THEN
        RETURN '[]'::jsonb;
    END IF;

    RETURN (
        SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb)
        FROM (
            SELECT
                can.id,
                can.full_name,
                can.email,
                can.phone,
                can.source,
                can.status,
                can.applied_at,
                can.position_id,
                (can.resume_raw_text IS NOT NULL AND length(can.resume_raw_text) > 0) AS has_resume,
                pos.title         AS position_title,
                pos.neuro_profile AS position_neuro_profile,
                (res.id IS NOT NULL) AS has_assessment,
                res.overall_score,
                res.screening_score,
                res.personality_score,
                res.work_style_score,
                res.cognitive_score,
                -- Big-5 sub-scores (kept for richer facets / radar later).
                NULLIF(res.personality_data->>'openness', '')::numeric          AS big5_openness,
                NULLIF(res.personality_data->>'conscientiousness', '')::numeric  AS big5_conscientiousness,
                NULLIF(res.personality_data->>'extraversion', '')::numeric       AS big5_extraversion,
                NULLIF(res.personality_data->>'agreeableness', '')::numeric      AS big5_agreeableness,
                NULLIF(res.personality_data->>'neuroticism', '')::numeric        AS big5_neuroticism
            FROM candidates can
            LEFT JOIN positions pos ON pos.id = can.position_id
            LEFT JOIN LATERAL (
                SELECT *
                FROM assessment_results r
                WHERE r.candidate_id = can.id
                ORDER BY r.completed_at DESC NULLS LAST
                LIMIT 1
            ) res ON true
            WHERE can.company_id = v_company_id
        ) t
    );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

GRANT EXECUTE ON FUNCTION get_treasury_dataset(text) TO authenticated, anon;

-- ══════════════════════════════════════════════════════════════════════════
-- legacy/add-webhooks.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter :: Outgoing webhooks / integrations (additive, BYO-URL)
-- Run in the Supabase SQL Editor. Safe to re-run.
--
-- Each company can register its own webhook URLs (Slack / Discord incoming
-- webhooks, or a generic JSON endpoint for Zapier / Make / n8n). RunButter POSTs
-- to them on key events — no platform API keys, no cost on our side. The end
-- user pastes a URL they own; we just deliver JSON to it.
-- ============================================================================

CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

CREATE TABLE IF NOT EXISTS webhook_endpoints (
    id         uuid PRIMARY KEY DEFAULT uuid_generate_v4(),
    company_id uuid REFERENCES companies(id) ON DELETE CASCADE,
    label      text NOT NULL DEFAULT '',
    type       text NOT NULL DEFAULT 'generic',  -- slack | discord | generic
    url        text NOT NULL,
    events     text[] NOT NULL DEFAULT ARRAY['application.created','candidate.stage_changed','candidate.hired'],
    is_active  boolean NOT NULL DEFAULT true,
    created_at timestamptz DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_webhook_endpoints_company ON webhook_endpoints(company_id);

ALTER TABLE webhook_endpoints ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "company_read_webhook_endpoints" ON webhook_endpoints;
CREATE POLICY "company_read_webhook_endpoints" ON webhook_endpoints FOR SELECT USING (
    company_id IN (
        SELECT company_id FROM company_users
        WHERE privy_user_id = current_setting('app.current_privy_user_id', true)
           OR auth_user_id = auth.uid()
    )
);

-- RPCs --------------------------------------------------------------------
-- Drop every existing overload first so re-runs can't create ambiguous
-- functions (PostgREST 400 "could not choose the best candidate function").
DO $$
DECLARE r record;
BEGIN
    FOR r IN
        SELECT 'DROP FUNCTION IF EXISTS ' || oid::regprocedure || ' CASCADE;' AS stmt
        FROM pg_proc
        WHERE pronamespace = 'public'::regnamespace
          AND proname IN ('get_webhook_endpoints', 'upsert_webhook_endpoint', 'delete_webhook_endpoint')
    LOOP
        EXECUTE r.stmt;
    END LOOP;
END$$;

CREATE OR REPLACE FUNCTION get_webhook_endpoints(p_privy_user_id text)
RETURNS jsonb AS $$
DECLARE v_company_id uuid;
BEGIN
    SELECT company_id INTO v_company_id FROM company_users WHERE privy_user_id = p_privy_user_id LIMIT 1;
    IF v_company_id IS NULL THEN RETURN '[]'::jsonb; END IF;
    RETURN (
        SELECT COALESCE(jsonb_agg(
            jsonb_build_object(
                'id', t.id, 'label', t.label, 'type', t.type,
                'url', t.url, 'events', t.events, 'is_active', t.is_active
            ) ORDER BY t.created_at
        ), '[]'::jsonb)
        FROM webhook_endpoints t
        WHERE t.company_id = v_company_id
    );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION upsert_webhook_endpoint(
    p_privy_user_id text, p_id uuid, p_label text, p_type text, p_url text,
    p_events text[], p_is_active boolean
)
RETURNS jsonb AS $$
DECLARE v_company_id uuid; v_row webhook_endpoints;
BEGIN
    SELECT company_id INTO v_company_id FROM company_users WHERE privy_user_id = p_privy_user_id LIMIT 1;
    IF v_company_id IS NULL THEN RAISE EXCEPTION 'RECRUITER_NOT_FOUND'; END IF;
    IF p_url IS NULL OR p_url = '' THEN RAISE EXCEPTION 'URL_REQUIRED'; END IF;

    IF p_id IS NULL THEN
        INSERT INTO webhook_endpoints (company_id, label, type, url, events, is_active)
        VALUES (
            v_company_id, COALESCE(p_label, ''), COALESCE(NULLIF(p_type, ''), 'generic'), p_url,
            COALESCE(p_events, ARRAY['application.created','candidate.stage_changed','candidate.hired']),
            COALESCE(p_is_active, true)
        )
        RETURNING * INTO v_row;
    ELSE
        UPDATE webhook_endpoints
        SET label = COALESCE(p_label, ''),
            type = COALESCE(NULLIF(p_type, ''), 'generic'),
            url = p_url,
            events = COALESCE(p_events, events),
            is_active = COALESCE(p_is_active, is_active)
        WHERE id = p_id AND company_id = v_company_id
        RETURNING * INTO v_row;
        IF v_row.id IS NULL THEN RAISE EXCEPTION 'ENDPOINT_NOT_FOUND'; END IF;
    END IF;
    RETURN row_to_json(v_row);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION delete_webhook_endpoint(p_privy_user_id text, p_id uuid)
RETURNS jsonb AS $$
DECLARE v_company_id uuid;
BEGIN
    SELECT company_id INTO v_company_id FROM company_users WHERE privy_user_id = p_privy_user_id LIMIT 1;
    IF v_company_id IS NULL THEN RAISE EXCEPTION 'RECRUITER_NOT_FOUND'; END IF;
    DELETE FROM webhook_endpoints WHERE id = p_id AND company_id = v_company_id;
    RETURN jsonb_build_object('ok', true);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

GRANT EXECUTE ON FUNCTION get_webhook_endpoints(text)                                            TO authenticated, anon;
GRANT EXECUTE ON FUNCTION upsert_webhook_endpoint(text, uuid, text, text, text, text[], boolean) TO authenticated, anon;
GRANT EXECUTE ON FUNCTION delete_webhook_endpoint(text, uuid)                                    TO authenticated, anon;

NOTIFY pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0001_platform_core.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter Platform Core — 0001_platform_core.sql
-- Universal relational foundation for the CRM / Business-OS pivot.
--
-- Run on a BRANCH / staging Supabase DB (NOT prod live). Deny-by-default RLS;
-- all access goes through SECURITY DEFINER RPCs that take p_privy_user_id and
-- verify workspace membership (matches the existing Privy auth pattern, and
-- closes the multi-tenant read hole the legacy tables currently have).
-- ============================================================================

create extension if not exists pgcrypto;   -- gen_random_uuid()

create or replace function set_updated_at() returns trigger language plpgsql as $$
begin new.updated_at = now(); return new; end $$;

-- 1. WORKSPACES — tenant root --------------------------------------------------
create table if not exists workspaces (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  slug text unique not null,
  plan text not null default 'free',
  logo_url text,
  settings jsonb not null default '{}',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
drop trigger if exists trg_workspaces_upd on workspaces;
create trigger trg_workspaces_upd before update on workspaces for each row execute function set_updated_at();

-- 2. ACCOUNTS — internal user seats (Privy logins) -----------------------------
create table if not exists accounts (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspaces(id) on delete cascade,
  privy_user_id text not null,
  email text, full_name text, avatar_url text,
  role text not null default 'member',          -- owner | admin | member
  created_at timestamptz not null default now(),
  unique (workspace_id, privy_user_id)
);
create index if not exists idx_accounts_privy on accounts(privy_user_id);

create or replace function is_workspace_member(p_workspace uuid, p_privy text)
returns boolean language sql stable as $$
  select exists (select 1 from accounts a
                 where a.workspace_id = p_workspace and a.privy_user_id = p_privy);
$$;

-- 3. CRM ORGANIZATIONS — deferred to the Sales module (0004).
-- The existing prod DB already has a `companies` table (the TENANT), so we must
-- NOT create a colliding CRM `companies` table here. The universal CRM org
-- entity ships with Sales as `organizations`; recruitment needs only
-- people + pipelines + psychometrics, keeping these migrations purely additive.

-- 4. PEOPLE — universal person entity (contacts, candidates, employees) --------
create table if not exists people (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspaces(id) on delete cascade,
  primary_company_id uuid,                 -- FK added with CRM organizations (Sales module)
  first_name text, last_name text, email text, phone text, title text,
  source text, linkedin_url text, avatar_url text,
  resume_raw_text text,                 -- zero-cost FTS source (pdf-parse/mammoth)
  resume_parsed_at timestamptz,
  custom_fields jsonb not null default '{}',
  search_tsv tsvector generated always as (
    to_tsvector('english',
      coalesce(first_name,'')||' '||coalesce(last_name,'')||' '||coalesce(title,'')||' '||
      coalesce(email,'')||' '||coalesce(resume_raw_text,''))
  ) stored,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists idx_people_ws      on people(workspace_id);
create index if not exists idx_people_company on people(primary_company_id);
create index if not exists idx_people_tsv     on people using gin(search_tsv);   -- <5ms boolean search
drop trigger if exists trg_people_upd on people;
create trigger trg_people_upd before update on people for each row execute function set_updated_at();

-- 5. PIPELINES + STAGES — configurable, multi-purpose workflows ----------------
create table if not exists pipelines (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspaces(id) on delete cascade,
  name text not null,
  kind text not null default 'custom',          -- sales | recruitment | hris | custom
  target text not null default 'person',        -- person | company
  position int not null default 0,
  created_at timestamptz not null default now()
);
create index if not exists idx_pipelines_ws on pipelines(workspace_id);

create table if not exists pipeline_stages (
  id uuid primary key default gen_random_uuid(),
  pipeline_id uuid not null references pipelines(id) on delete cascade,
  workspace_id uuid not null references workspaces(id) on delete cascade,  -- denormalized for RLS
  name text not null,
  color text not null default '#64748b',
  position int not null default 0,
  stage_type text not null default 'open',      -- open | won | lost
  created_at timestamptz not null default now()
);
create index if not exists idx_stages_pipeline on pipeline_stages(pipeline_id, position);

-- 6. PIPELINE_RECORDS — relational connector: one entity → many pipelines ------
create table if not exists pipeline_records (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspaces(id) on delete cascade,
  pipeline_id uuid not null references pipelines(id) on delete cascade,
  stage_id uuid not null references pipeline_stages(id) on delete restrict,
  person_id uuid references people(id) on delete cascade,
  company_id uuid,                               -- CRM org link (Sales module)
  owner_account_id uuid references accounts(id) on delete set null,
  title text, amount numeric(14,2), currency text default 'USD',
  status text not null default 'active',         -- active | won | lost
  position double precision not null default 0,  -- cheap drag-reordering
  entered_stage_at timestamptz not null default now(),
  custom_fields jsonb not null default '{}',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint chk_record_subject check (person_id is not null or company_id is not null)
);
create index if not exists idx_records_board   on pipeline_records(pipeline_id, stage_id, position);
create index if not exists idx_records_person  on pipeline_records(person_id);
create index if not exists idx_records_company on pipeline_records(company_id);
drop trigger if exists trg_records_upd on pipeline_records;
create trigger trg_records_upd before update on pipeline_records for each row execute function set_updated_at();

create or replace function stamp_stage_change() returns trigger language plpgsql as $$
begin if new.stage_id is distinct from old.stage_id then new.entered_stage_at = now(); end if; return new; end $$;
drop trigger if exists trg_records_stage on pipeline_records;
create trigger trg_records_stage before update on pipeline_records for each row execute function stamp_stage_change();

-- 7. PSYCHOMETRICS — per-person; discrete int columns + raw jsonb --------------
create table if not exists psychometrics (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspaces(id) on delete cascade,
  person_id uuid not null references people(id) on delete cascade,
  overall int, logic int, stress_resistance int, empathy int,
  openness int, conscientiousness int, extraversion int, agreeableness int, neuroticism int,
  raw jsonb not null default '{}',
  assessed_at timestamptz not null default now(),
  created_at timestamptz not null default now()
);
create index if not exists idx_psych_person on psychometrics(person_id, assessed_at desc);

-- 8. ASSETS — IT / equipment inventory (HRIS module) --------------------------
create table if not exists assets (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspaces(id) on delete cascade,
  name text not null,
  category text not null default 'other',        -- laptop | monitor | phone | license | other
  serial_number text,
  status text not null default 'available',      -- available | assigned | repair | retired
  assigned_to_person_id uuid references people(id) on delete set null,
  purchased_at date, value numeric(12,2), notes text,
  custom_fields jsonb not null default '{}',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists idx_assets_ws       on assets(workspace_id);
create index if not exists idx_assets_assignee on assets(assigned_to_person_id);
drop trigger if exists trg_assets_upd on assets;
create trigger trg_assets_upd before update on assets for each row execute function set_updated_at();

-- 9. OBJECT_FIELDS — lightweight extensibility (renders custom_fields jsonb) ---
create table if not exists object_fields (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspaces(id) on delete cascade,
  object_type text not null,                     -- person | company | pipeline_record | asset
  field_key text not null,
  label text not null,
  data_type text not null default 'text',        -- text|number|select|date|boolean|relation
  options jsonb not null default '{}',
  position int not null default 0,
  unique (workspace_id, object_type, field_key)
);

-- 10. RLS — enable (NOT force) so SECURITY DEFINER RPCs work; no permissive
-- policies ⇒ anon/authenticated get zero direct table access. All I/O via RPCs.
do $$ declare t text; begin
  foreach t in array array['workspaces','accounts','people','pipelines',
    'pipeline_stages','pipeline_records','psychometrics','assets','object_fields'] loop
    execute format('alter table %I enable row level security;', t);
  end loop; end $$;

-- 11. Example RPC — zero-cost boolean resume search (the access pattern) --------
-- websearch_to_tsquery gives `React Node -Junior "node.js"` syntax for free.
create or replace function search_people(p_privy text, p_workspace uuid, p_query text)
returns setof people language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  return query
    select * from people p
    where p.workspace_id = p_workspace
      and (coalesce(p_query,'') = '' or p.search_tsv @@ websearch_to_tsquery('english', p_query))
    order by case when coalesce(p_query,'')='' then 0
                  else ts_rank(p.search_tsv, websearch_to_tsquery('english', p_query)) end desc,
             p.created_at desc
    limit 200;
end $$;
grant execute on function search_people(text, uuid, text) to authenticated, anon;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0002_pipeline_templates_and_rpcs.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter Platform Core — 0002_pipeline_templates_and_rpcs.sql
-- Default pipeline templates (Sales / Recruitment / HRIS) + core board RPCs.
-- Depends on 0001_platform_core.sql.
-- ============================================================================

-- Seed the three default pipelines + stages for a workspace (idempotent per kind).
create or replace function seed_default_pipelines(p_workspace uuid)
returns void language plpgsql security definer set search_path = public as $$
declare v_pipeline uuid;
begin
  -- SALES (CRM) --------------------------------------------------------------
  if not exists (select 1 from pipelines where workspace_id = p_workspace and kind = 'sales') then
    insert into pipelines (workspace_id, name, kind, target, position)
      values (p_workspace, 'Sales', 'sales', 'company', 0) returning id into v_pipeline;
    insert into pipeline_stages (pipeline_id, workspace_id, name, color, position, stage_type) values
      (v_pipeline, p_workspace, 'Lead',        '#94a3b8', 0, 'open'),
      (v_pipeline, p_workspace, 'Discovery',   '#60a5fa', 1, 'open'),
      (v_pipeline, p_workspace, 'Proposal',    '#a78bfa', 2, 'open'),
      (v_pipeline, p_workspace, 'Closed Won',  '#34d399', 3, 'won'),
      (v_pipeline, p_workspace, 'Closed Lost', '#f87171', 4, 'lost');
  end if;

  -- RECRUITMENT (ATS) --------------------------------------------------------
  if not exists (select 1 from pipelines where workspace_id = p_workspace and kind = 'recruitment') then
    insert into pipelines (workspace_id, name, kind, target, position)
      values (p_workspace, 'Recruitment', 'recruitment', 'person', 1) returning id into v_pipeline;
    insert into pipeline_stages (pipeline_id, workspace_id, name, color, position, stage_type) values
      (v_pipeline, p_workspace, 'Applicant',  '#94a3b8', 0, 'open'),
      (v_pipeline, p_workspace, 'Assessment', '#60a5fa', 1, 'open'),
      (v_pipeline, p_workspace, 'Interview',  '#a78bfa', 2, 'open'),
      (v_pipeline, p_workspace, 'Offered',    '#fbbf24', 3, 'open'),
      (v_pipeline, p_workspace, 'Hired',      '#34d399', 4, 'won'),
      (v_pipeline, p_workspace, 'Rejected',   '#f87171', 5, 'lost');
  end if;

  -- HRIS (Onboarding / Team) -------------------------------------------------
  if not exists (select 1 from pipelines where workspace_id = p_workspace and kind = 'hris') then
    insert into pipelines (workspace_id, name, kind, target, position)
      values (p_workspace, 'Onboarding', 'hris', 'person', 2) returning id into v_pipeline;
    insert into pipeline_stages (pipeline_id, workspace_id, name, color, position, stage_type) values
      (v_pipeline, p_workspace, 'Pre-boarding', '#94a3b8', 0, 'open'),
      (v_pipeline, p_workspace, 'Onboarding',   '#60a5fa', 1, 'open'),
      (v_pipeline, p_workspace, 'Active',       '#34d399', 2, 'won'),
      (v_pipeline, p_workspace, 'Offboarding',  '#f87171', 3, 'lost');
  end if;
end $$;
grant execute on function seed_default_pipelines(uuid) to authenticated, anon;

-- Return a full board (stages + records joined to their person/company) as jsonb.
create or replace function get_pipeline_board(p_privy text, p_pipeline uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_workspace uuid;
begin
  select workspace_id into v_workspace from pipelines where id = p_pipeline;
  if v_workspace is null then raise exception 'PIPELINE_NOT_FOUND'; end if;
  if not is_workspace_member(v_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;

  return jsonb_build_object(
    'stages', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', s.id, 'name', s.name, 'color', s.color, 'stage_type', s.stage_type
      ) order by s.position)
      from pipeline_stages s where s.pipeline_id = p_pipeline), '[]'::jsonb),
    'records', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', r.id, 'stage_id', r.stage_id, 'title', r.title, 'amount', r.amount,
        'status', r.status, 'position', r.position,
        'person', case when pe.id is null then null else jsonb_build_object(
          'id', pe.id, 'name', trim(coalesce(pe.first_name,'')||' '||coalesce(pe.last_name,'')),
          'title', pe.title, 'avatar_url', pe.avatar_url) end,
        'company', null   -- CRM organizations join added with the Sales module
      ) order by r.position)
      from pipeline_records r
      left join people pe on pe.id = r.person_id
      where r.pipeline_id = p_pipeline), '[]'::jsonb)
  );
end $$;
grant execute on function get_pipeline_board(text, uuid) to authenticated, anon;

-- Move a record to a stage / reorder (drag-and-drop persistence).
create or replace function move_pipeline_record(p_privy text, p_record uuid, p_stage uuid, p_position double precision)
returns void language plpgsql security definer set search_path = public as $$
declare v_workspace uuid;
begin
  select workspace_id into v_workspace from pipeline_records where id = p_record;
  if v_workspace is null then raise exception 'RECORD_NOT_FOUND'; end if;
  if not is_workspace_member(v_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;

  update pipeline_records
     set stage_id = p_stage,
         position = p_position,
         status   = coalesce((select case when s.stage_type = 'open' then 'active' else s.stage_type end
                              from pipeline_stages s where s.id = p_stage), status)
   where id = p_record;
end $$;
grant execute on function move_pipeline_record(text, uuid, uuid, double precision) to authenticated, anon;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0003_bridge_recruitment.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter Platform Core — 0003_bridge_recruitment.sql
-- Non-destructive bridge: lift the existing ATS data into the universal tables
-- WITHOUT touching or dropping anything. Idempotent (safe to re-run).
-- Depends on 0001 + 0002. Run AFTER them.
--
-- legacy companies(tenant) -> workspaces (same id)   | company_users -> accounts
-- candidates -> people (legacy_candidate_id link)    | assessment_results -> psychometrics
-- candidate.status -> a row in the Recruitment pipeline
-- ============================================================================

-- 0. traceability column for idempotent candidate sync
alter table people add column if not exists legacy_candidate_id uuid;
create unique index if not exists idx_people_legacy on people(legacy_candidate_id) where legacy_candidate_id is not null;

-- 1. workspaces <- companies (the existing TENANT table; preserve the UUID so the
--    existing company_id already equals workspace_id — zero data migration needed).
insert into workspaces (id, name, slug, plan, created_at)
select c.id, c.name,
       coalesce(nullif(c.subdomain,''), 'ws-' || left(c.id::text, 8)),
       coalesce(c.plan, 'free'), coalesce(c.created_at, now())
from companies c
on conflict (id) do nothing;

-- 2. accounts <- company_users
insert into accounts (workspace_id, privy_user_id, email, full_name, role, created_at)
select cu.company_id, cu.privy_user_id, cu.email, cu.full_name, coalesce(cu.role,'member'), coalesce(cu.created_at, now())
from company_users cu
where cu.privy_user_id is not null
  and exists (select 1 from workspaces w where w.id = cu.company_id)
on conflict (workspace_id, privy_user_id) do nothing;

-- 3. seed the default pipelines for every workspace
do $$ declare w record; begin
  for w in select id from workspaces loop perform seed_default_pipelines(w.id); end loop;
end $$;

-- 4. people <- candidates
insert into people (workspace_id, first_name, last_name, email, phone, title, source,
                    resume_raw_text, resume_parsed_at, legacy_candidate_id, created_at)
select c.company_id,
       split_part(coalesce(c.full_name,''), ' ', 1),
       nullif(btrim(regexp_replace(coalesce(c.full_name,''), '^\S+\s*', '')), ''),
       c.email, c.phone, p.title, c.source,
       c.resume_raw_text, c.resume_parsed_at, c.id, coalesce(c.applied_at, now())
from candidates c
left join positions p on p.id = c.position_id
where exists (select 1 from workspaces w where w.id = c.company_id)
  and not exists (select 1 from people pe where pe.legacy_candidate_id = c.id);

-- 5. psychometrics <- assessment_results (discrete int columns + raw jsonb)
--    Assumes Big-5 values in personality_data are numeric.
insert into psychometrics (workspace_id, person_id, overall, logic,
                           openness, conscientiousness, extraversion, agreeableness, neuroticism,
                           raw, assessed_at)
select pe.workspace_id, pe.id,
       ar.overall_score, ar.cognitive_score,
       (ar.personality_data->>'openness')::numeric::int,
       (ar.personality_data->>'conscientiousness')::numeric::int,
       (ar.personality_data->>'extraversion')::numeric::int,
       (ar.personality_data->>'agreeableness')::numeric::int,
       (ar.personality_data->>'neuroticism')::numeric::int,
       to_jsonb(ar), coalesce(ar.completed_at, now())
from assessment_results ar
join people pe on pe.legacy_candidate_id = ar.candidate_id
where not exists (select 1 from psychometrics ps where ps.person_id = pe.id);

-- 6. pipeline_records <- candidate.status (into the Recruitment pipeline)
insert into pipeline_records (workspace_id, pipeline_id, stage_id, person_id, title, status, position, created_at)
select pe.workspace_id, pl.id, st.id, pe.id,
       trim(coalesce(pe.first_name,'')||' '||coalesce(pe.last_name,'')),
       case when st.stage_type='won' then 'won' when st.stage_type='lost' then 'lost' else 'active' end,
       0, coalesce(c.applied_at, now())
from candidates c
join people pe on pe.legacy_candidate_id = c.id
join pipelines pl on pl.workspace_id = pe.workspace_id and pl.kind = 'recruitment'
join pipeline_stages st on st.pipeline_id = pl.id and st.name = (
  case lower(coalesce(c.status,'applied'))
    when 'applied' then 'Applicant'
    when 'screening' then 'Applicant'
    when 'assessment_sent' then 'Assessment'
    when 'assessment_completed' then 'Assessment'
    when 'interview_scheduled' then 'Interview'
    when 'interviewed' then 'Interview'
    when 'offered' then 'Offered'
    when 'hired' then 'Hired'
    when 'rejected' then 'Rejected'
    else 'Applicant' end)
where not exists (select 1 from pipeline_records r where r.person_id = pe.id and r.pipeline_id = pl.id);

-- 7. RPCs the new shell calls (workspace resolve, generic list, pipeline-by-kind)
create or replace function get_my_workspace(p_privy text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare w workspaces;
begin
  select ws.* into w from accounts a join workspaces ws on ws.id = a.workspace_id
   where a.privy_user_id = p_privy order by a.created_at limit 1;
  if w.id is null then return null; end if;
  return jsonb_build_object('id', w.id, 'name', w.name, 'slug', w.slug, 'plan', w.plan);
end $$;
grant execute on function get_my_workspace(text) to authenticated, anon;

create or replace function get_pipeline_by_kind(p_privy text, p_workspace uuid, p_kind text)
returns uuid language plpgsql security definer set search_path = public as $$
declare v uuid;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  select id into v from pipelines where workspace_id = p_workspace and kind = p_kind order by position limit 1;
  return v;
end $$;
grant execute on function get_pipeline_by_kind(text, uuid, text) to authenticated, anon;

create or replace function list_records(p_privy text, p_workspace uuid, p_object text)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;

  if p_object = 'people' then
    return coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', pe.id,
        'name', trim(coalesce(pe.first_name,'')||' '||coalesce(pe.last_name,'')),
        'title', pe.title, 'company', null, 'email', pe.email, 'source', pe.source,
        'synergy', (select ps.overall from psychometrics ps where ps.person_id = pe.id
                    order by ps.assessed_at desc limit 1)
      ) order by pe.created_at desc)
      from people pe
      where pe.workspace_id = p_workspace), '[]'::jsonb);

  elsif p_object = 'companies' then
    return '[]'::jsonb;   -- CRM organizations ship with the Sales module (0004)

  elsif p_object = 'assets' then
    return coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', a.id, 'name', a.name, 'category', a.category,
        'serial_number', a.serial_number, 'status', a.status,
        'assigned_to', (select trim(coalesce(pe.first_name,'')||' '||coalesce(pe.last_name,''))
                        from people pe where pe.id = a.assigned_to_person_id)
      ) order by a.created_at desc)
      from assets a where a.workspace_id = p_workspace), '[]'::jsonb);
  end if;
  return '[]'::jsonb;
end $$;
grant execute on function list_records(text, uuid, text) to authenticated, anon;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0004_crm_finance.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter Platform Core — 0004_crm_finance.sql
-- Sales/CRM organizations + Finance (invoices, expenses). Additive & prod-safe.
-- Depends on 0001–0003. Run AFTER them.
-- ============================================================================

-- 1. ORGANIZATIONS — the CRM "company" entity (named to avoid the tenant clash)
create table if not exists organizations (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspaces(id) on delete cascade,
  name text not null, domain text, industry text, employee_count int,
  custom_fields jsonb not null default '{}',
  search_tsv tsvector generated always as (
    to_tsvector('english', coalesce(name,'')||' '||coalesce(domain,'')||' '||coalesce(industry,''))
  ) stored,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists idx_orgs_ws  on organizations(workspace_id);
create index if not exists idx_orgs_tsv on organizations using gin(search_tsv);
drop trigger if exists trg_orgs_upd on organizations;
create trigger trg_orgs_upd before update on organizations for each row execute function set_updated_at();

-- 2. INVOICES (accounts receivable)
create table if not exists invoices (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspaces(id) on delete cascade,
  number text, organization_id uuid references organizations(id) on delete set null,
  amount numeric(14,2) not null default 0, currency text not null default 'USD',
  status text not null default 'draft',   -- draft | sent | paid | overdue
  issued_at date, due_at date, notes text,
  custom_fields jsonb not null default '{}',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists idx_invoices_ws on invoices(workspace_id);
drop trigger if exists trg_invoices_upd on invoices;
create trigger trg_invoices_upd before update on invoices for each row execute function set_updated_at();

-- 3. EXPENSES (accounts payable)
create table if not exists expenses (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspaces(id) on delete cascade,
  vendor text, category text not null default 'other',  -- payroll|software|office|travel|other
  amount numeric(14,2) not null default 0, currency text not null default 'USD',
  status text not null default 'pending', -- pending | approved | paid
  spent_at date, notes text,
  custom_fields jsonb not null default '{}',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists idx_expenses_ws on expenses(workspace_id);
drop trigger if exists trg_expenses_upd on expenses;
create trigger trg_expenses_upd before update on expenses for each row execute function set_updated_at();

-- 4. RLS (enable only; access via SECURITY DEFINER RPCs)
do $$ declare t text; begin
  foreach t in array array['organizations','invoices','expenses'] loop
    execute format('alter table %I enable row level security;', t);
  end loop; end $$;

-- 5. Finance summary RPC
create or replace function get_finance_summary(p_privy text, p_workspace uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  return jsonb_build_object(
    'revenue',     coalesce((select sum(amount) from invoices where workspace_id=p_workspace and status='paid'),0),
    'outstanding', coalesce((select sum(amount) from invoices where workspace_id=p_workspace and status in ('sent','overdue')),0),
    'expenses',    coalesce((select sum(amount) from expenses where workspace_id=p_workspace and status in ('approved','paid')),0),
    'invoices',    coalesce((select count(*) from invoices where workspace_id=p_workspace),0)
  );
end $$;
grant execute on function get_finance_summary(text, uuid) to authenticated, anon;

-- 6. Extend list_records for the new objects (companies->organizations, invoices, expenses)
create or replace function list_records(p_privy text, p_workspace uuid, p_object text)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;

  if p_object = 'people' then
    return coalesce((select jsonb_agg(jsonb_build_object(
      'id', pe.id, 'name', trim(coalesce(pe.first_name,'')||' '||coalesce(pe.last_name,'')),
      'title', pe.title, 'company', co.name, 'email', pe.email, 'source', pe.source,
      'synergy', (select ps.overall from psychometrics ps where ps.person_id=pe.id order by ps.assessed_at desc limit 1)
    ) order by pe.created_at desc)
    from people pe left join organizations co on co.id = pe.primary_company_id
    where pe.workspace_id=p_workspace), '[]'::jsonb);

  elsif p_object in ('companies','organizations') then
    return coalesce((select jsonb_agg(jsonb_build_object(
      'id', o.id, 'name', o.name, 'domain', o.domain, 'industry', o.industry, 'employee_count', o.employee_count
    ) order by o.created_at desc)
    from organizations o where o.workspace_id=p_workspace), '[]'::jsonb);

  elsif p_object = 'invoices' then
    return coalesce((select jsonb_agg(jsonb_build_object(
      'id', i.id, 'number', i.number, 'company', o.name, 'amount', i.amount,
      'status', i.status, 'due_at', i.due_at
    ) order by i.created_at desc)
    from invoices i left join organizations o on o.id = i.organization_id
    where i.workspace_id=p_workspace), '[]'::jsonb);

  elsif p_object = 'expenses' then
    return coalesce((select jsonb_agg(jsonb_build_object(
      'id', e.id, 'vendor', e.vendor, 'category', e.category, 'amount', e.amount,
      'status', e.status, 'spent_at', e.spent_at
    ) order by e.created_at desc)
    from expenses e where e.workspace_id=p_workspace), '[]'::jsonb);

  elsif p_object = 'assets' then
    return coalesce((select jsonb_agg(jsonb_build_object(
      'id', a.id, 'name', a.name, 'category', a.category, 'serial_number', a.serial_number,
      'status', a.status,
      'assigned_to', (select trim(coalesce(pe.first_name,'')||' '||coalesce(pe.last_name,'')) from people pe where pe.id=a.assigned_to_person_id)
    ) order by a.created_at desc)
    from assets a where a.workspace_id=p_workspace), '[]'::jsonb);
  end if;
  return '[]'::jsonb;
end $$;
grant execute on function list_records(text, uuid, text) to authenticated, anon;

-- 7. Light demo seed so Sales/Finance aren't empty on first view (only if none).
--    Clearly disposable sample rows — delete anytime.
do $$
declare w record;
begin
  for w in select id from workspaces loop
    if not exists (select 1 from organizations where workspace_id = w.id) then
      insert into organizations (workspace_id, name, domain, industry, employee_count) values
        (w.id, 'Northwind Labs', 'northwind.io', 'SaaS', 120),
        (w.id, 'Lumen Devtools', 'lumen.dev', 'Developer Tools', 45),
        (w.id, 'Vertex Finance', 'vertex.co', 'Fintech', 80);
    end if;
    if not exists (select 1 from invoices where workspace_id = w.id) then
      insert into invoices (workspace_id, number, organization_id, amount, status, issued_at, due_at)
      select w.id, 'INV-100'||gs, (select id from organizations o where o.workspace_id=w.id order by random() limit 1),
             (array[24000,12000,36000])[gs], (array['paid','sent','overdue'])[gs],
             now()::date - (gs*14), now()::date + (30-gs*14)
      from generate_series(1,3) gs;
    end if;
    if not exists (select 1 from expenses where workspace_id = w.id) then
      insert into expenses (workspace_id, vendor, category, amount, status, spent_at) values
        (w.id, 'AWS', 'software', 2400, 'paid', now()::date - 5),
        (w.id, 'WeWork', 'office', 3200, 'approved', now()::date - 12),
        (w.id, 'Payroll', 'payroll', 48000, 'paid', now()::date - 1);
    end if;
  end loop;
end $$;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0005_auto_provision_workspace.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter Platform Core — 0005_auto_provision_workspace.sql
-- Make the platform work for NEW customers automatically. The 0003 bridge was a
-- one-time backfill; these triggers keep the platform in sync going forward:
--   new tenant company  -> workspace (+ default pipelines)
--   new company_user    -> account
-- Trigger bodies are exception-safe: a sync failure can NEVER block signup.
-- Depends on 0001–0004. Run AFTER them.
-- ============================================================================

-- tenant company -> workspace (+ seed pipelines)
create or replace function sync_company_to_workspace()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  begin
    insert into workspaces (id, name, slug, plan, created_at)
    values (new.id, new.name,
            coalesce(nullif(new.subdomain,''), 'ws-' || left(new.id::text, 8)),
            coalesce(new.plan, 'free'), coalesce(new.created_at, now()))
    on conflict (id) do nothing;
    perform seed_default_pipelines(new.id);
  exception when others then
    null;  -- best-effort; never block tenant creation
  end;
  return new;
end $$;

drop trigger if exists trg_company_to_workspace on companies;
create trigger trg_company_to_workspace after insert on companies
  for each row execute function sync_company_to_workspace();

-- company_user -> account (the workspace exists by now: companies trigger ran first)
create or replace function sync_company_user_to_account()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  begin
    if new.privy_user_id is not null then
      insert into accounts (workspace_id, privy_user_id, email, full_name, role, created_at)
      values (new.company_id, new.privy_user_id, new.email, new.full_name,
              coalesce(new.role, 'member'), coalesce(new.created_at, now()))
      on conflict (workspace_id, privy_user_id) do nothing;
    end if;
  exception when others then
    null;  -- best-effort; never block user creation
  end;
  return new;
end $$;

drop trigger if exists trg_company_user_to_account on company_users;
create trigger trg_company_user_to_account after insert on company_users
  for each row execute function sync_company_user_to_account();

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0006_projects.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter Platform Core — 0006_projects.sql
-- Plane-style Project Management: projects + issues (board reuses the existing
-- kanban engine). Additive & prod-safe. Depends on 0001–0005.
-- ============================================================================

-- 1. PROJECTS
create table if not exists projects (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspaces(id) on delete cascade,
  name text not null,
  identifier text,                       -- short code, e.g. LAUNCH
  description text,
  color text not null default '#6366f1',
  lead_account_id uuid references accounts(id) on delete set null,
  status text not null default 'active', -- active | paused | completed | cancelled
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists idx_projects_ws on projects(workspace_id);
drop trigger if exists trg_projects_upd on projects;
create trigger trg_projects_upd before update on projects for each row execute function set_updated_at();

-- 2. ISSUES (tasks)
create table if not exists issues (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspaces(id) on delete cascade,
  project_id uuid references projects(id) on delete cascade,
  title text not null,
  description text,
  status text not null default 'backlog',  -- backlog | todo | in_progress | done | cancelled
  priority text not null default 'none',   -- none | low | medium | high | urgent
  assignee_account_id uuid references accounts(id) on delete set null,
  sort_order double precision not null default 0,
  due_date date,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists idx_issues_ws on issues(workspace_id);
create index if not exists idx_issues_project on issues(project_id, status, sort_order);
drop trigger if exists trg_issues_upd on issues;
create trigger trg_issues_upd before update on issues for each row execute function set_updated_at();

-- 3. RLS
do $$ declare t text; begin
  foreach t in array array['projects','issues'] loop
    execute format('alter table %I enable row level security;', t);
  end loop; end $$;

-- 4. move an issue between states (drag-and-drop persistence)
create or replace function move_issue(p_privy text, p_issue uuid, p_status text, p_sort double precision)
returns void language plpgsql security definer set search_path = public as $$
declare v_ws uuid;
begin
  select workspace_id into v_ws from issues where id = p_issue;
  if v_ws is null then raise exception 'ISSUE_NOT_FOUND'; end if;
  if not is_workspace_member(v_ws, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  update issues set status = p_status, sort_order = p_sort where id = p_issue;
end $$;
grant execute on function move_issue(text, uuid, text, double precision) to authenticated, anon;

-- 5. extend list_records for projects + issues (full redefinition)
create or replace function list_records(p_privy text, p_workspace uuid, p_object text)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;

  if p_object = 'people' then
    return coalesce((select jsonb_agg(jsonb_build_object(
      'id', pe.id, 'name', trim(coalesce(pe.first_name,'')||' '||coalesce(pe.last_name,'')),
      'title', pe.title, 'company', co.name, 'email', pe.email, 'source', pe.source,
      'synergy', (select ps.overall from psychometrics ps where ps.person_id=pe.id order by ps.assessed_at desc limit 1)
    ) order by pe.created_at desc)
    from people pe left join organizations co on co.id = pe.primary_company_id
    where pe.workspace_id=p_workspace), '[]'::jsonb);

  elsif p_object in ('companies','organizations') then
    return coalesce((select jsonb_agg(jsonb_build_object(
      'id', o.id, 'name', o.name, 'domain', o.domain, 'industry', o.industry, 'employee_count', o.employee_count
    ) order by o.created_at desc) from organizations o where o.workspace_id=p_workspace), '[]'::jsonb);

  elsif p_object = 'invoices' then
    return coalesce((select jsonb_agg(jsonb_build_object(
      'id', i.id, 'number', i.number, 'company', o.name, 'amount', i.amount, 'status', i.status, 'due_at', i.due_at
    ) order by i.created_at desc)
    from invoices i left join organizations o on o.id = i.organization_id
    where i.workspace_id=p_workspace), '[]'::jsonb);

  elsif p_object = 'expenses' then
    return coalesce((select jsonb_agg(jsonb_build_object(
      'id', e.id, 'vendor', e.vendor, 'category', e.category, 'amount', e.amount, 'status', e.status, 'spent_at', e.spent_at
    ) order by e.created_at desc) from expenses e where e.workspace_id=p_workspace), '[]'::jsonb);

  elsif p_object = 'projects' then
    return coalesce((select jsonb_agg(jsonb_build_object(
      'id', pr.id, 'name', pr.name, 'identifier', pr.identifier, 'status', pr.status,
      'issues', (select count(*) from issues i where i.project_id = pr.id)
    ) order by pr.created_at desc) from projects pr where pr.workspace_id=p_workspace), '[]'::jsonb);

  elsif p_object = 'issues' then
    return coalesce((select jsonb_agg(jsonb_build_object(
      'id', i.id, 'name', i.title, 'project', pr.name, 'status', i.status,
      'priority', i.priority, 'due_date', i.due_date,
      'assignee', (select a.full_name from accounts a where a.id = i.assignee_account_id)
    ) order by i.sort_order)
    from issues i left join projects pr on pr.id = i.project_id
    where i.workspace_id=p_workspace), '[]'::jsonb);

  elsif p_object = 'assets' then
    return coalesce((select jsonb_agg(jsonb_build_object(
      'id', a.id, 'name', a.name, 'category', a.category, 'serial_number', a.serial_number, 'status', a.status,
      'assigned_to', (select trim(coalesce(pe.first_name,'')||' '||coalesce(pe.last_name,'')) from people pe where pe.id=a.assigned_to_person_id)
    ) order by a.created_at desc) from assets a where a.workspace_id=p_workspace), '[]'::jsonb);
  end if;
  return '[]'::jsonb;
end $$;
grant execute on function list_records(text, uuid, text) to authenticated, anon;

-- 6. demo seed (single-row RETURNING INTO is fine; only multi-row is not)
do $$
declare w record; v_proj uuid;
begin
  for w in select id from workspaces loop
    if not exists (select 1 from projects where workspace_id = w.id) then
      insert into projects (workspace_id, name, identifier, status)
        values (w.id, 'Platform Launch', 'LAUNCH', 'active')
        returning id into v_proj;
      insert into issues (workspace_id, project_id, title, status, priority, sort_order) values
