notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0032_automations.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter Platform Core — 0032_automations.sql
-- Automations engine + open integration layer, workspace-scoped.
--
--  • connections       — outgoing webhook targets (BYO URL: Zapier/Make/n8n/Slack)
--  • automations       — rules: trigger (object + event + conditions) → actions
--  • automation_events — outbox filled by AFTER-triggers, drained by the dispatcher
--  • automation_runs   — execution log
--  • api_keys          — incoming REST/MCP auth (sha256 hash stored; key shown once)
--
-- Table triggers only enqueue an event when the workspace actually has an enabled
-- rule for that object, so the outbox stays empty until automations exist. The
-- dispatcher (/api/automations/dispatch) and the incoming API (/api/v1/*) call the
-- service-role-only RPCs at the bottom. No LLM / no platform API cost — users
-- bring their own webhook URL and their own API key.
--
-- Additive, idempotent & prod-safe. Depends on 0001–0031. Run AFTER them.
-- ============================================================================

create extension if not exists pgcrypto;

-- 1. CONNECTIONS — outgoing webhook endpoints the user owns.
create table if not exists connections (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspaces(id) on delete cascade,
  label text not null default '',
  kind text not null default 'generic',   -- generic | slack | discord | zapier | make | n8n
  url text not null,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists idx_connections_ws on connections(workspace_id);
drop trigger if exists trg_connections_upd on connections;
create trigger trg_connections_upd before update on connections for each row execute function set_updated_at();
alter table connections enable row level security;

-- 2. AUTOMATIONS — the rules. actions run as owner_privy (a workspace member).
create table if not exists automations (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspaces(id) on delete cascade,
  owner_privy text not null,
  name text not null default 'Untitled automation',
  enabled boolean not null default true,
  object text not null,                    -- companies | people | invoices | expenses | transactions | products | campaigns | projects | issues
  event text not null default 'created',   -- created | updated
  conditions jsonb not null default '[]'::jsonb,   -- [{ field, op, value }]
  actions jsonb not null default '[]'::jsonb,      -- [{ type, config }]
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists idx_automations_ws on automations(workspace_id);
create index if not exists idx_automations_lookup on automations(workspace_id, object, enabled);
drop trigger if exists trg_automations_upd on automations;
create trigger trg_automations_upd before update on automations for each row execute function set_updated_at();
alter table automations enable row level security;

-- 3. AUTOMATION_EVENTS — the outbox.
create table if not exists automation_events (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspaces(id) on delete cascade,
  object text not null,
  event text not null,
  record_id uuid,
  payload jsonb not null default '{}'::jsonb,
  status text not null default 'pending',  -- pending | processing | done | error
  attempts int not null default 0,
  created_at timestamptz not null default now(),
  processed_at timestamptz
);
create index if not exists idx_autoevents_pending on automation_events(status, created_at) where status = 'pending';
alter table automation_events enable row level security;

-- 4. AUTOMATION_RUNS — execution log.
create table if not exists automation_runs (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspaces(id) on delete cascade,
  automation_id uuid references automations(id) on delete set null,
  automation_name text,
  action_type text,
  status text not null default 'ok',       -- ok | error
  detail text,
  created_at timestamptz not null default now()
);
create index if not exists idx_autoruns_ws on automation_runs(workspace_id, created_at desc);
alter table automation_runs enable row level security;

-- 5. API_KEYS — incoming REST / MCP auth. Only the hash is stored.
create table if not exists api_keys (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspaces(id) on delete cascade,
  name text not null default 'API key',
  prefix text not null,                    -- e.g. hb_1a2b3c (for display)
  key_hash text not null,                  -- sha256 hex of the full key
  created_by_privy text,
  last_used_at timestamptz,
  revoked boolean not null default false,
  created_at timestamptz not null default now()
);
create index if not exists idx_apikeys_ws on api_keys(workspace_id);
create index if not exists idx_apikeys_hash on api_keys(key_hash) where revoked = false;
alter table api_keys enable row level security;

-- ============================================================================
-- 6. Event emitter — one function, attached to every generic object table.
--    Only enqueues when the workspace has an enabled rule for that object slug,
--    so tables without automations pay ~nothing.
-- ============================================================================
create or replace function emit_automation_event()
returns trigger language plpgsql security definer set search_path = public as $$
declare v_ws uuid := NEW.workspace_id;
begin
  if exists (select 1 from automations a where a.workspace_id = v_ws and a.enabled and a.object = TG_ARGV[0]) then
    insert into automation_events (workspace_id, object, event, record_id, payload)
    values (v_ws, TG_ARGV[0], case when TG_OP = 'INSERT' then 'created' else 'updated' end, NEW.id, to_jsonb(NEW));
  end if;
  return NEW;
end $$;

do $$
declare r record;
begin
  for r in select * from (values
    ('organizations','companies'), ('people','people'), ('invoices','invoices'),
    ('expenses','expenses'), ('transactions','transactions'), ('products','products'),
    ('campaigns','campaigns'), ('projects','projects'), ('issues','issues')
  ) as x(tbl, slug) loop
    execute format('drop trigger if exists trg_autoevt_%1$s on %1$s;', r.tbl);
    execute format('create trigger trg_autoevt_%1$s after insert or update on %1$s for each row execute function emit_automation_event(%2$L);', r.tbl, r.slug);
  end loop;
end $$;

-- ============================================================================
-- 7. User-facing RPCs (Privy pattern, membership-checked).
-- ============================================================================

-- Automations CRUD
create or replace function get_automations(p_privy text, p_workspace uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
    'id', a.id, 'name', a.name, 'enabled', a.enabled, 'object', a.object, 'event', a.event,
    'conditions', a.conditions, 'actions', a.actions, 'updated_at', a.updated_at
  ) order by a.created_at desc) from automations a where a.workspace_id = p_workspace), '[]'::jsonb);
end $$;
grant execute on function get_automations(text, uuid) to authenticated, anon;

create or replace function save_automation(p_privy text, p_workspace uuid, p_id uuid, p_data jsonb)
returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  if p_id is null then
    insert into automations (workspace_id, owner_privy, name, enabled, object, event, conditions, actions)
    values (p_workspace, p_privy, coalesce(nullif(p_data->>'name',''),'Untitled automation'),
            coalesce((p_data->>'enabled')::boolean, true), p_data->>'object',
            coalesce(nullif(p_data->>'event',''),'created'),
            coalesce(p_data->'conditions','[]'::jsonb), coalesce(p_data->'actions','[]'::jsonb))
    returning id into v_id;
  else
    update automations set
      name = coalesce(nullif(p_data->>'name',''), name),
      enabled = coalesce((p_data->>'enabled')::boolean, enabled),
      object = coalesce(nullif(p_data->>'object',''), object),
      event = coalesce(nullif(p_data->>'event',''), event),
      conditions = coalesce(p_data->'conditions', conditions),
      actions = coalesce(p_data->'actions', actions)
    where id = p_id and workspace_id = p_workspace
    returning id into v_id;
  end if;
  return v_id;
end $$;
grant execute on function save_automation(text, uuid, uuid, jsonb) to authenticated, anon;

create or replace function set_automation_enabled(p_privy text, p_id uuid, p_enabled boolean)
returns void language plpgsql security definer set search_path = public as $$
declare my uuid[] := (select array_agg(workspace_id) from accounts where privy_user_id = p_privy);
begin
  update automations set enabled = p_enabled where id = p_id and workspace_id = any(my);
end $$;
grant execute on function set_automation_enabled(text, uuid, boolean) to authenticated, anon;

create or replace function delete_automation(p_privy text, p_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare my uuid[] := (select array_agg(workspace_id) from accounts where privy_user_id = p_privy);
begin
  delete from automations where id = p_id and workspace_id = any(my);
end $$;
grant execute on function delete_automation(text, uuid) to authenticated, anon;

create or replace function get_automation_runs(p_privy text, p_workspace uuid, p_limit int default 30)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
    'id', r.id, 'automation_name', r.automation_name, 'action_type', r.action_type,
    'status', r.status, 'detail', r.detail, 'created_at', r.created_at
  ) order by r.created_at desc) from (
    select * from automation_runs where workspace_id = p_workspace order by created_at desc limit greatest(1, least(coalesce(p_limit,30), 100))
  ) r), '[]'::jsonb);
end $$;
grant execute on function get_automation_runs(text, uuid, int) to authenticated, anon;

-- Connections CRUD
create or replace function get_connections(p_privy text, p_workspace uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
    'id', c.id, 'label', c.label, 'kind', c.kind, 'url', c.url, 'is_active', c.is_active
  ) order by c.created_at) from connections c where c.workspace_id = p_workspace), '[]'::jsonb);
end $$;
grant execute on function get_connections(text, uuid) to authenticated, anon;

create or replace function save_connection(p_privy text, p_workspace uuid, p_id uuid, p_label text, p_kind text, p_url text, p_active boolean)
returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  if p_url is null or p_url = '' then raise exception 'URL_REQUIRED'; end if;
  if p_id is null then
    insert into connections (workspace_id, label, kind, url, is_active)
    values (p_workspace, coalesce(p_label,''), coalesce(nullif(p_kind,''),'generic'), p_url, coalesce(p_active, true))
    returning id into v_id;
  else
    update connections set label = coalesce(p_label, label), kind = coalesce(nullif(p_kind,''), kind),
      url = p_url, is_active = coalesce(p_active, is_active)
    where id = p_id and workspace_id = p_workspace returning id into v_id;
  end if;
  return v_id;
end $$;
grant execute on function save_connection(text, uuid, uuid, text, text, text, boolean) to authenticated, anon;

create or replace function delete_connection(p_privy text, p_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare my uuid[] := (select array_agg(workspace_id) from accounts where privy_user_id = p_privy);
begin
  delete from connections where id = p_id and workspace_id = any(my);
end $$;
grant execute on function delete_connection(text, uuid) to authenticated, anon;

-- API keys — create returns the full key ONCE; list never returns it.
create or replace function get_api_keys(p_privy text, p_workspace uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
    'id', k.id, 'name', k.name, 'prefix', k.prefix, 'last_used_at', k.last_used_at, 'revoked', k.revoked, 'created_at', k.created_at
  ) order by k.created_at desc) from api_keys k where k.workspace_id = p_workspace), '[]'::jsonb);
end $$;
grant execute on function get_api_keys(text, uuid) to authenticated, anon;

create or replace function create_api_key(p_privy text, p_workspace uuid, p_name text)
returns text language plpgsql security definer set search_path = public as $$
declare v_key text; v_prefix text;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  v_key := 'hb_' || encode(gen_random_bytes(24), 'hex');
  v_prefix := left(v_key, 11);
  insert into api_keys (workspace_id, name, prefix, key_hash, created_by_privy)
  values (p_workspace, coalesce(nullif(p_name,''),'API key'), v_prefix, encode(digest(v_key, 'sha256'), 'hex'), p_privy);
  return v_key;   -- shown once, never stored in plaintext
end $$;
grant execute on function create_api_key(text, uuid, text) to authenticated, anon;

create or replace function revoke_api_key(p_privy text, p_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare my uuid[] := (select array_agg(workspace_id) from accounts where privy_user_id = p_privy);
begin
  update api_keys set revoked = true where id = p_id and workspace_id = any(my);
end $$;
grant execute on function revoke_api_key(text, uuid) to authenticated, anon;

-- ============================================================================
-- 8. System RPCs — service_role ONLY (called by the dispatcher + incoming API).
--    NOT granted to authenticated/anon: they cross workspace boundaries.
-- ============================================================================
create or replace function claim_automation_events(p_max int default 25)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v jsonb;
begin
  with picked as (
    select id from automation_events where status = 'pending' order by created_at limit greatest(1, least(coalesce(p_max,25), 100)) for update skip locked
  ), upd as (
    update automation_events e set status = 'processing', attempts = e.attempts + 1
    from picked where e.id = picked.id returning e.*
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', id, 'workspace_id', workspace_id, 'object', object, 'event', event, 'record_id', record_id, 'payload', payload
  )), '[]'::jsonb) into v from upd;
  return v;
end $$;
revoke all on function claim_automation_events(int) from public, authenticated, anon;
grant execute on function claim_automation_events(int) to service_role;

create or replace function get_event_automations(p_workspace uuid, p_object text, p_event text)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  return coalesce((select jsonb_agg(jsonb_build_object(
    'id', a.id, 'name', a.name, 'owner_privy', a.owner_privy, 'conditions', a.conditions, 'actions', a.actions
  )) from automations a where a.workspace_id = p_workspace and a.enabled and a.object = p_object and a.event = p_event), '[]'::jsonb);
end $$;
revoke all on function get_event_automations(uuid, text, text) from public, authenticated, anon;
grant execute on function get_event_automations(uuid, text, text) to service_role;

create or replace function complete_automation_event(p_id uuid, p_status text)
returns void language plpgsql security definer set search_path = public as $$
begin
  update automation_events set status = p_status, processed_at = now() where id = p_id;
end $$;
revoke all on function complete_automation_event(uuid, text) from public, authenticated, anon;
grant execute on function complete_automation_event(uuid, text) to service_role;

create or replace function log_automation_run(p_workspace uuid, p_automation uuid, p_name text, p_action text, p_status text, p_detail text)
returns void language plpgsql security definer set search_path = public as $$
begin
  insert into automation_runs (workspace_id, automation_id, automation_name, action_type, status, detail)
  values (p_workspace, p_automation, p_name, p_action, coalesce(nullif(p_status,''),'ok'), p_detail);
end $$;
revoke all on function log_automation_run(uuid, uuid, text, text, text, text) from public, authenticated, anon;
grant execute on function log_automation_run(uuid, uuid, text, text, text, text) to service_role;

create or replace function get_connection_url(p_workspace uuid, p_id uuid)
returns text language plpgsql security definer set search_path = public as $$
begin
  return (select url from connections where id = p_id and workspace_id = p_workspace and is_active);
end $$;
revoke all on function get_connection_url(uuid, uuid) from public, authenticated, anon;
grant execute on function get_connection_url(uuid, uuid) to service_role;

-- Incoming API/MCP: resolve a presented key hash → workspace + acting identity.
create or replace function resolve_api_key(p_hash text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_row api_keys;
begin
  select * into v_row from api_keys where key_hash = p_hash and revoked = false limit 1;
  if v_row.id is null then return null; end if;
  update api_keys set last_used_at = now() where id = v_row.id;
  return jsonb_build_object('id', v_row.id, 'workspace_id', v_row.workspace_id, 'owner_privy', v_row.created_by_privy);
end $$;
revoke all on function resolve_api_key(text) from public, authenticated, anon;
grant execute on function resolve_api_key(text) to service_role;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0033_automations_v2.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter Platform Core — 0033_automations_v2.sql
-- Automations + integrations, phase 2. Borrows the proven patterns:
--   • Activepieces-style trigger types — record event, INCOMING WEBHOOK, schedule
--   • Svix-style webhook delivery — HMAC signing secret, retries, delivery log
--
-- Extends 0032 (additive ALTERs, redefines a few RPCs). Idempotent & prod-safe.
-- Depends on 0001–0032. Run AFTER them.
-- ============================================================================

create extension if not exists pgcrypto;

-- automations: trigger type + inbound webhook token + schedule + last_run
alter table automations add column if not exists trigger_type text not null default 'event';  -- event | webhook | schedule
alter table automations add column if not exists webhook_token text;
alter table automations add column if not exists schedule jsonb;    -- { every: 'minute'|'hour'|'day', at?: 'HH:MM' }
alter table automations add column if not exists last_run_at timestamptz;
create unique index if not exists idx_automations_webhook_token on automations(webhook_token) where webhook_token is not null;
create index if not exists idx_automations_schedule on automations(trigger_type) where trigger_type = 'schedule';

-- connections: per-endpoint signing secret (Svix style)
alter table connections add column if not exists secret text;
update connections set secret = 'whsec_' || encode(gen_random_bytes(24), 'hex') where secret is null;

-- events: direct-target automation, retry/backoff, source, error
alter table automation_events add column if not exists automation_id uuid;   -- set for webhook/schedule (direct) events
alter table automation_events add column if not exists source text not null default 'trigger';  -- trigger | webhook | schedule
alter table automation_events add column if not exists next_attempt_at timestamptz;
alter table automation_events add column if not exists last_error text;

-- webhook delivery log (Svix-style observability + retry)
create table if not exists webhook_deliveries (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspaces(id) on delete cascade,
  connection_id uuid,
  automation_id uuid,
  url text,
  status text not null default 'pending',   -- ok | failed
  response_code int,
  attempts int not null default 1,
  detail text,
  created_at timestamptz not null default now()
);
create index if not exists idx_webhook_deliveries_ws on webhook_deliveries(workspace_id, created_at desc);
alter table webhook_deliveries enable row level security;

-- ============================================================================
-- Redefined user RPCs — carry the new fields.
-- ============================================================================
create or replace function get_automations(p_privy text, p_workspace uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
    'id', a.id, 'name', a.name, 'enabled', a.enabled, 'trigger_type', a.trigger_type,
    'object', a.object, 'event', a.event, 'conditions', a.conditions, 'actions', a.actions,
    'webhook_token', a.webhook_token, 'schedule', a.schedule, 'updated_at', a.updated_at
  ) order by a.created_at desc) from automations a where a.workspace_id = p_workspace), '[]'::jsonb);
end $$;
grant execute on function get_automations(text, uuid) to authenticated, anon;

-- save_automation v2 — trigger_type/schedule; auto-mint a webhook token when needed.
create or replace function save_automation(p_privy text, p_workspace uuid, p_id uuid, p_data jsonb)
returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid; v_tt text := coalesce(nullif(p_data->>'trigger_type',''),'event');
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  if p_id is null then
    insert into automations (workspace_id, owner_privy, name, enabled, trigger_type, object, event, conditions, actions, schedule, webhook_token)
    values (p_workspace, p_privy, coalesce(nullif(p_data->>'name',''),'Untitled automation'),
            coalesce((p_data->>'enabled')::boolean, true), v_tt,
            coalesce(nullif(p_data->>'object',''),'companies'), coalesce(nullif(p_data->>'event',''),'created'),
            coalesce(p_data->'conditions','[]'::jsonb), coalesce(p_data->'actions','[]'::jsonb),
            case when v_tt = 'schedule' then p_data->'schedule' else null end,
            case when v_tt = 'webhook' then 'hook_' || encode(gen_random_bytes(18),'hex') else null end)
    returning id into v_id;
  else
    update automations set
      name = coalesce(nullif(p_data->>'name',''), name),
      enabled = coalesce((p_data->>'enabled')::boolean, enabled),
      trigger_type = v_tt,
      object = coalesce(nullif(p_data->>'object',''), object),
      event = coalesce(nullif(p_data->>'event',''), event),
      conditions = coalesce(p_data->'conditions', conditions),
      actions = coalesce(p_data->'actions', actions),
      schedule = case when v_tt = 'schedule' then p_data->'schedule' else null end,
      -- mint a token the first time a rule becomes a webhook trigger; keep it otherwise
      webhook_token = case when v_tt = 'webhook' then coalesce(webhook_token, 'hook_' || encode(gen_random_bytes(18),'hex')) else null end
    where id = p_id and workspace_id = p_workspace
    returning id into v_id;
  end if;
  return v_id;
end $$;
grant execute on function save_automation(text, uuid, uuid, jsonb) to authenticated, anon;

-- get_connections v2 — include the signing secret (owner needs it to verify).
create or replace function get_connections(p_privy text, p_workspace uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
    'id', c.id, 'label', c.label, 'kind', c.kind, 'url', c.url, 'is_active', c.is_active, 'secret', c.secret
  ) order by c.created_at) from connections c where c.workspace_id = p_workspace), '[]'::jsonb);
end $$;
grant execute on function get_connections(text, uuid) to authenticated, anon;

create or replace function get_webhook_deliveries(p_privy text, p_workspace uuid, p_limit int default 20)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
    'id', d.id, 'url', d.url, 'status', d.status, 'response_code', d.response_code, 'attempts', d.attempts, 'detail', d.detail, 'created_at', d.created_at
  ) order by d.created_at desc) from (
    select * from webhook_deliveries where workspace_id = p_workspace order by created_at desc limit greatest(1, least(coalesce(p_limit,20), 100))
  ) d), '[]'::jsonb);
end $$;
grant execute on function get_webhook_deliveries(text, uuid, int) to authenticated, anon;

-- ============================================================================
-- System RPCs (service_role only) — dispatcher, inbound webhook, scheduler.
-- ============================================================================

-- Inbound webhook trigger: external tools POST to /api/hooks/<token>.
create or replace function enqueue_webhook_event(p_token text, p_payload jsonb)
returns jsonb language plpgsql security definer set search_path = public as $$
declare a automations;
begin
  select * into a from automations where webhook_token = p_token and enabled limit 1;
  if a.id is null then return null; end if;
  insert into automation_events (workspace_id, object, event, record_id, payload, source, automation_id)
  values (a.workspace_id, coalesce(a.object,'webhook'), 'webhook', null, coalesce(p_payload,'{}'::jsonb), 'webhook', a.id);
  return jsonb_build_object('ok', true, 'automation', a.name);
end $$;
revoke all on function enqueue_webhook_event(text, jsonb) from public, authenticated, anon;
grant execute on function enqueue_webhook_event(text, jsonb) to service_role;

-- Scheduler: enqueue due schedule automations. Cron calls this then the dispatcher.
create or replace function enqueue_scheduled_automations()
returns int language plpgsql security definer set search_path = public as $$
declare a automations; n int := 0; v_due boolean;
begin
  for a in select * from automations where trigger_type = 'schedule' and enabled loop
    v_due := case coalesce(a.schedule->>'every','day')
      when 'minute' then a.last_run_at is null or a.last_run_at < now() - interval '1 minute'
      when 'hour'   then a.last_run_at is null or a.last_run_at < now() - interval '1 hour'
      else a.last_run_at is null or a.last_run_at < now() - interval '1 day'
    end;
    if v_due then
      insert into automation_events (workspace_id, object, event, payload, source, automation_id)
      values (a.workspace_id, coalesce(a.object,'schedule'), 'schedule', jsonb_build_object('now', now()), 'schedule', a.id);
      update automations set last_run_at = now() where id = a.id;
      n := n + 1;
    end if;
  end loop;
  return n;
end $$;
revoke all on function enqueue_scheduled_automations() from public, authenticated, anon;
grant execute on function enqueue_scheduled_automations() to service_role;

-- claim v2 — respect retry backoff (next_attempt_at).
create or replace function claim_automation_events(p_max int default 25)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v jsonb;
begin
  with picked as (
    select id from automation_events
    where status = 'pending' and (next_attempt_at is null or next_attempt_at <= now())
    order by created_at limit greatest(1, least(coalesce(p_max,25), 100)) for update skip locked
  ), upd as (
    update automation_events e set status = 'processing', attempts = e.attempts + 1
    from picked where e.id = picked.id returning e.*
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', id, 'workspace_id', workspace_id, 'object', object, 'event', event, 'record_id', record_id,
    'payload', payload, 'source', source, 'automation_id', automation_id, 'attempts', attempts
  )), '[]'::jsonb) into v from upd;
  return v;
end $$;
revoke all on function claim_automation_events(int) from public, authenticated, anon;
grant execute on function claim_automation_events(int) to service_role;

-- Requeue a failed event with backoff (dispatcher decides max attempts).
create or replace function retry_automation_event(p_id uuid, p_backoff_seconds int, p_err text)
returns void language plpgsql security definer set search_path = public as $$
begin
  update automation_events set status = 'pending', next_attempt_at = now() + (p_backoff_seconds || ' seconds')::interval, last_error = p_err where id = p_id;
end $$;
revoke all on function retry_automation_event(uuid, int, text) from public, authenticated, anon;
grant execute on function retry_automation_event(uuid, int, text) to service_role;

-- Fetch a single automation (for webhook/schedule direct-target events).
create or replace function get_automation_by_id(p_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  return (select jsonb_build_object('id', a.id, 'name', a.name, 'owner_privy', a.owner_privy, 'workspace_id', a.workspace_id, 'conditions', a.conditions, 'actions', a.actions)
          from automations a where a.id = p_id and a.enabled);
end $$;
revoke all on function get_automation_by_id(uuid) from public, authenticated, anon;
grant execute on function get_automation_by_id(uuid) to service_role;

-- Connection with its signing secret (supersedes get_connection_url).
create or replace function get_connection(p_workspace uuid, p_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  return (select jsonb_build_object('id', id, 'label', label, 'url', url, 'secret', secret)
          from connections where id = p_id and workspace_id = p_workspace and is_active);
end $$;
revoke all on function get_connection(uuid, uuid) from public, authenticated, anon;
grant execute on function get_connection(uuid, uuid) to service_role;

create or replace function log_webhook_delivery(p_workspace uuid, p_connection uuid, p_automation uuid, p_url text, p_status text, p_code int, p_attempts int, p_detail text)
returns void language plpgsql security definer set search_path = public as $$
begin
  insert into webhook_deliveries (workspace_id, connection_id, automation_id, url, status, response_code, attempts, detail)
  values (p_workspace, p_connection, p_automation, p_url, coalesce(nullif(p_status,''),'ok'), p_code, coalesce(p_attempts,1), p_detail);
end $$;
revoke all on function log_webhook_delivery(uuid, uuid, uuid, text, text, int, int, text) from public, authenticated, anon;
grant execute on function log_webhook_delivery(uuid, uuid, uuid, text, text, int, int, text) to service_role;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0034_docs_ai.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter Platform Core — 0034_docs_ai.sql
-- Docs module + BYO-AI. Users store their OWN provider keys (Claude/OpenAI/
-- Gemini/OpenRouter) encrypted at rest; RunButter proxies calls, so there is no
-- platform token cost — the user funds their own AI. The key ciphertext is
-- written/read only by service-role RPCs (the API routes); user RPCs only ever
-- see a masked hint.
--
-- Additive, idempotent & prod-safe. Depends on 0001–0033. Run AFTER them.
-- ============================================================================

-- 1. DOCS — freeform documents (markdown body), workspace-scoped.
create table if not exists docs (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspaces(id) on delete cascade,
  title text not null default 'Untitled',
  body text not null default '',
  created_by_privy text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists idx_docs_ws on docs(workspace_id, updated_at desc);
drop trigger if exists trg_docs_upd on docs;
create trigger trg_docs_upd before update on docs for each row execute function set_updated_at();
alter table docs enable row level security;

-- 2. AI_PROVIDERS — one BYO key per provider per workspace (AES-GCM ciphertext).
create table if not exists ai_providers (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspaces(id) on delete cascade,
  provider text not null,                 -- claude | openai | gemini | openrouter
  model text not null default '',
  key_cipher text not null,
  key_iv text not null,
  key_tag text not null,
  key_hint text not null default '',      -- e.g. …a1b2
  is_default boolean not null default false,
  enabled boolean not null default true,
  created_by_privy text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create unique index if not exists idx_ai_providers_uniq on ai_providers(workspace_id, provider);
drop trigger if exists trg_ai_providers_upd on ai_providers;
create trigger trg_ai_providers_upd before update on ai_providers for each row execute function set_updated_at();
alter table ai_providers enable row level security;

-- ── Docs RPCs ─────────────────────────────────────────────────────────────────
create or replace function get_docs(p_privy text, p_workspace uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
    'id', d.id, 'title', d.title, 'snippet', left(d.body, 140), 'updated_at', d.updated_at
  ) order by d.updated_at desc) from docs d where d.workspace_id = p_workspace), '[]'::jsonb);
end $$;
grant execute on function get_docs(text, uuid) to authenticated, anon;

create or replace function get_doc(p_privy text, p_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare my uuid[] := (select array_agg(workspace_id) from accounts where privy_user_id = p_privy);
begin
  return (select to_jsonb(t) from (select id, title, body, updated_at from docs where id = p_id and workspace_id = any(my)) t);
end $$;
grant execute on function get_doc(text, uuid) to authenticated, anon;

create or replace function save_doc(p_privy text, p_workspace uuid, p_id uuid, p_title text, p_body text)
returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  if p_id is null then
    insert into docs (workspace_id, title, body, created_by_privy)
    values (p_workspace, coalesce(nullif(p_title,''),'Untitled'), coalesce(p_body,''), p_privy) returning id into v_id;
  else
    update docs set title = coalesce(nullif(p_title,''), title), body = coalesce(p_body, body)
    where id = p_id and workspace_id = p_workspace returning id into v_id;
  end if;
  return v_id;
end $$;
grant execute on function save_doc(text, uuid, uuid, text, text) to authenticated, anon;

create or replace function delete_doc(p_privy text, p_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare my uuid[] := (select array_agg(workspace_id) from accounts where privy_user_id = p_privy);
begin
  delete from docs where id = p_id and workspace_id = any(my);
end $$;
grant execute on function delete_doc(text, uuid) to authenticated, anon;

-- ── AI provider RPCs (user: masked only) ──────────────────────────────────────
create or replace function get_ai_providers(p_privy text, p_workspace uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
    'id', a.id, 'provider', a.provider, 'model', a.model, 'key_hint', a.key_hint, 'is_default', a.is_default, 'enabled', a.enabled
  ) order by a.created_at) from ai_providers a where a.workspace_id = p_workspace), '[]'::jsonb);
end $$;
grant execute on function get_ai_providers(text, uuid) to authenticated, anon;

create or replace function set_ai_provider_meta(p_privy text, p_id uuid, p_model text, p_default boolean, p_enabled boolean)
returns void language plpgsql security definer set search_path = public as $$
declare my uuid[] := (select array_agg(workspace_id) from accounts where privy_user_id = p_privy);
declare v_ws uuid;
begin
  select workspace_id into v_ws from ai_providers where id = p_id and workspace_id = any(my);
  if v_ws is null then return; end if;
  if p_default then update ai_providers set is_default = false where workspace_id = v_ws; end if;
  update ai_providers set model = coalesce(p_model, model), is_default = coalesce(p_default, is_default), enabled = coalesce(p_enabled, enabled) where id = p_id;
end $$;
grant execute on function set_ai_provider_meta(text, uuid, text, boolean, boolean) to authenticated, anon;

create or replace function delete_ai_provider(p_privy text, p_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare my uuid[] := (select array_agg(workspace_id) from accounts where privy_user_id = p_privy);
begin
  delete from ai_providers where id = p_id and workspace_id = any(my);
end $$;
grant execute on function delete_ai_provider(text, uuid) to authenticated, anon;

-- ── AI provider secrets (service_role only) ───────────────────────────────────
-- Store/replace an encrypted key (called by /api/ai/keys after sealing it).
create or replace function store_ai_provider(p_privy text, p_workspace uuid, p_provider text, p_model text, p_cipher text, p_iv text, p_tag text, p_hint text)
returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid; v_has_default boolean;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  select exists(select 1 from ai_providers where workspace_id = p_workspace and is_default) into v_has_default;
  insert into ai_providers (workspace_id, provider, model, key_cipher, key_iv, key_tag, key_hint, is_default, created_by_privy)
  values (p_workspace, p_provider, coalesce(p_model,''), p_cipher, p_iv, p_tag, coalesce(p_hint,''), not v_has_default, p_privy)
  on conflict (workspace_id, provider) do update set
    model = coalesce(nullif(excluded.model,''), ai_providers.model),
    key_cipher = excluded.key_cipher, key_iv = excluded.key_iv, key_tag = excluded.key_tag, key_hint = excluded.key_hint, enabled = true
  returning id into v_id;
  return v_id;
end $$;
revoke all on function store_ai_provider(text, uuid, text, text, text, text, text, text) from public, authenticated, anon;
grant execute on function store_ai_provider(text, uuid, text, text, text, text, text, text) to service_role;

-- Return the default (or any enabled) provider's ciphertext, member-checked.
create or replace function get_ai_secret(p_privy text, p_workspace uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare a ai_providers;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  select * into a from ai_providers where workspace_id = p_workspace and enabled order by is_default desc, created_at limit 1;
  if a.id is null then return null; end if;
  return jsonb_build_object('provider', a.provider, 'model', a.model, 'cipher', a.key_cipher, 'iv', a.key_iv, 'tag', a.key_tag);
end $$;
revoke all on function get_ai_secret(text, uuid) from public, authenticated, anon;
grant execute on function get_ai_secret(text, uuid) to service_role;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0035_automation_hardening.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter Platform Core — 0035_automation_hardening.sql
-- Fixes an automation-recursion hazard and adds the wrapper RPCs the
-- dispatcher uses for record actions.
--
-- THE BUG: emit_automation_event() fires on every INSERT/UPDATE. If a rule's
-- action mutates the same object it triggers on (e.g. "invoices updated →
-- update this record", or "X created → create X"), the action's write enqueues
-- a fresh event that matches the same rule → infinite loop, growing the outbox
-- forever.
--
-- THE FIX: dispatcher record-actions run through wrapper RPCs that set a
-- transaction-local flag (set_config(..., is_local => true)); the trigger
-- skips enqueueing when the flag is present in the same transaction. Manual /
-- app / API writes are unaffected.
--
-- Additive, idempotent & prod-safe. Depends on 0032–0033. Run AFTER them.
-- ============================================================================

-- Trigger v2 — skip writes made BY an automation action.
create or replace function emit_automation_event()
returns trigger language plpgsql security definer set search_path = public as $$
declare v_ws uuid := NEW.workspace_id;
begin
  if coalesce(current_setting('app.automation_depth', true), '') = '1' then return NEW; end if;
  if exists (select 1 from automations a where a.workspace_id = v_ws and a.enabled and a.object = TG_ARGV[0]) then
    insert into automation_events (workspace_id, object, event, record_id, payload)
    values (v_ws, TG_ARGV[0], case when TG_OP = 'INSERT' then 'created' else 'updated' end, NEW.id, to_jsonb(NEW));
  end if;
  return NEW;
end $$;

-- Wrapper RPCs (service_role only): same create/update as the app, but flagged
-- so the trigger won't re-enqueue. Same transaction ⇒ the local flag reaches
-- the trigger; it evaporates at commit.
create or replace function automation_create_record(p_privy text, p_workspace uuid, p_object text, p_data jsonb)
returns uuid language plpgsql security definer set search_path = public as $$
begin
  perform set_config('app.automation_depth', '1', true);
  return create_record(p_privy, p_workspace, p_object, p_data);
end $$;
revoke all on function automation_create_record(text, uuid, text, jsonb) from public, authenticated, anon;
grant execute on function automation_create_record(text, uuid, text, jsonb) to service_role;

create or replace function automation_update_record(p_privy text, p_object text, p_id uuid, p_data jsonb)
returns void language plpgsql security definer set search_path = public as $$
begin
  perform set_config('app.automation_depth', '1', true);
  perform update_record(p_privy, p_object, p_id, p_data);
end $$;
revoke all on function automation_update_record(text, text, uuid, jsonb) from public, authenticated, anon;
grant execute on function automation_update_record(text, text, uuid, jsonb) to service_role;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0036_assets_crud.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter Platform Core — 0036_assets_crud.sql
-- BUG FIX: assets could not be created/edited. list_records and delete_record
-- knew about assets, but create_record / get_record / update_record had no
-- assets branch (and the UI had no form), so "New asset" was impossible in the
-- app, the REST API, and MCP alike.
--
-- Redefines the generic CRUD monolith IN FULL (copied from 0031, the previous
-- latest) with an assets branch added to create/get/update. Also attaches the
-- automation event trigger to assets so rules can react to them.
--
-- Additive, idempotent & prod-safe. Depends on 0001–0035. Run AFTER them.
-- ============================================================================

-- get_record — + assets (full redefinition, from 0031).
create or replace function get_record(p_privy text, p_object text, p_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare my uuid[] := (select array_agg(workspace_id) from accounts where privy_user_id = p_privy);
begin
  if p_object in ('companies','organizations') then
    return (select to_jsonb(t) from (select id, name, domain, industry, employee_count, tax_id, address, country from organizations where id=p_id and workspace_id = any(my)) t);
  elsif p_object = 'people' then
    return (select to_jsonb(t) from (select id, first_name, last_name, email, phone, title, source from people where id=p_id and workspace_id = any(my)) t);
  elsif p_object = 'invoices' then
    return (select to_jsonb(t) from (select id, number, organization_id, kind, direction, amount, status, category, issued_at, due_at, notes from invoices where id=p_id and workspace_id = any(my)) t);
  elsif p_object = 'expenses' then
    return (select to_jsonb(t) from (select id, vendor, category, amount, status, spent_at, notes from expenses where id=p_id and workspace_id = any(my)) t);
  elsif p_object = 'transactions' then
    return (select to_jsonb(t) from (select id, txn_date, description, amount, currency, category, method, status, tax_rate, bank_account_id, notes from transactions where id=p_id and workspace_id = any(my)) t);
  elsif p_object = 'products' then
    return (select to_jsonb(t) from (select id, name, sku, description, unit_price, unit, category, image_url from products where id=p_id and workspace_id = any(my)) t);
  elsif p_object = 'campaigns' then
    return (select to_jsonb(t) from (select id, name, channel, status, budget, spend, leads, starts_on, ends_on, notes from campaigns where id=p_id and workspace_id = any(my)) t);
  elsif p_object = 'projects' then
    return (select to_jsonb(t) from (select id, name, identifier, status, description from projects where id=p_id and workspace_id = any(my)) t);
  elsif p_object = 'issues' then
    return (select to_jsonb(t) from (select id, title, status, priority, due_date, description from issues where id=p_id and workspace_id = any(my)) t);
  elsif p_object = 'assets' then
    return (select to_jsonb(t) from (select id, name, category, serial_number, status, assigned_to_person_id from assets where id=p_id and workspace_id = any(my)) t);
  end if;
  return null;
end $$;
grant execute on function get_record(text, text, uuid) to authenticated, anon;

-- create_record — + assets (from 0031). import_records reuses this (CSV import).
create or replace function create_record(p_privy text, p_workspace uuid, p_object text, p_data jsonb)
returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  if p_object in ('companies','organizations') then
    insert into organizations (workspace_id, name, domain, industry, employee_count, tax_id, address, country)
    values (p_workspace, p_data->>'name', nullif(p_data->>'domain',''), nullif(p_data->>'industry',''), nullif(p_data->>'employee_count','')::int,
            nullif(p_data->>'tax_id',''), nullif(p_data->>'address',''), nullif(p_data->>'country',''))
    returning id into v_id;
  elsif p_object = 'people' then
    insert into people (workspace_id, first_name, last_name, email, phone, title, source)
    values (p_workspace, p_data->>'first_name', nullif(p_data->>'last_name',''), nullif(p_data->>'email',''), nullif(p_data->>'phone',''), nullif(p_data->>'title',''), nullif(p_data->>'source',''))
    returning id into v_id;
  elsif p_object = 'invoices' then
    insert into invoices (workspace_id, number, organization_id, kind, direction, amount, status, category, issued_at, due_at, notes)
    values (p_workspace, nullif(p_data->>'number',''), nullif(p_data->>'organization_id','')::uuid, coalesce(nullif(p_data->>'kind',''),'invoice'), coalesce(nullif(p_data->>'direction',''),'income'),
            coalesce(nullif(p_data->>'amount','')::numeric,0), coalesce(nullif(p_data->>'status',''),'draft'), nullif(p_data->>'category',''),
            nullif(p_data->>'issued_at','')::date, nullif(p_data->>'due_at','')::date, nullif(p_data->>'notes',''))
    returning id into v_id;
  elsif p_object = 'expenses' then
    insert into expenses (workspace_id, vendor, category, amount, status, spent_at, notes)
    values (p_workspace, nullif(p_data->>'vendor',''), coalesce(nullif(p_data->>'category',''),'other'), coalesce(nullif(p_data->>'amount','')::numeric,0), coalesce(nullif(p_data->>'status',''),'pending'), nullif(p_data->>'spent_at','')::date, nullif(p_data->>'notes',''))
    returning id into v_id;
  elsif p_object = 'transactions' then
    insert into transactions (workspace_id, bank_account_id, txn_date, description, amount, currency, category, method, status, tax_rate, tags, notes)
    values (p_workspace, nullif(p_data->>'bank_account_id','')::uuid,
            coalesce(nullif(p_data->>'txn_date','')::date, now()::date), nullif(p_data->>'description',''),
            coalesce(nullif(regexp_replace(coalesce(p_data->>'amount',''), '[^0-9.-]', '', 'g'),'')::numeric, 0),
            coalesce(nullif(p_data->>'currency',''),'USD'), nullif(p_data->>'category',''),
            coalesce(nullif(p_data->>'method',''),'transfer'), coalesce(nullif(p_data->>'status',''),'posted'),
            nullif(p_data->>'tax_rate','')::numeric,
            case when nullif(p_data->>'tags','') is not null then string_to_array(p_data->>'tags', ',') else '{}'::text[] end,
            nullif(p_data->>'notes',''))
    returning id into v_id;
  elsif p_object = 'products' then
    insert into products (workspace_id, name, sku, description, unit_price, unit, category, image_url)
    values (p_workspace, p_data->>'name', nullif(p_data->>'sku',''), nullif(p_data->>'description',''), coalesce(nullif(p_data->>'unit_price','')::numeric,0), nullif(p_data->>'unit',''), nullif(p_data->>'category',''), nullif(p_data->>'image_url',''))
    returning id into v_id;
  elsif p_object = 'campaigns' then
    insert into campaigns (workspace_id, name, channel, status, budget, spend, leads, starts_on, ends_on, notes)
    values (p_workspace, p_data->>'name', coalesce(nullif(p_data->>'channel',''),'email'), coalesce(nullif(p_data->>'status',''),'planned'),
            coalesce(nullif(p_data->>'budget','')::numeric,0), coalesce(nullif(p_data->>'spend','')::numeric,0), coalesce(nullif(p_data->>'leads','')::int,0),
            nullif(p_data->>'starts_on','')::date, nullif(p_data->>'ends_on','')::date, nullif(p_data->>'notes',''))
    returning id into v_id;
  elsif p_object = 'projects' then
    insert into projects (workspace_id, name, identifier, status, description)
    values (p_workspace, p_data->>'name', nullif(p_data->>'identifier',''), coalesce(nullif(p_data->>'status',''),'active'), nullif(p_data->>'description',''))
    returning id into v_id;
  elsif p_object = 'issues' then
    insert into issues (workspace_id, title, status, priority, due_date, description)
    values (p_workspace, p_data->>'title', coalesce(nullif(p_data->>'status',''),'backlog'), coalesce(nullif(p_data->>'priority',''),'none'), nullif(p_data->>'due_date','')::date, nullif(p_data->>'description',''))
    returning id into v_id;
  elsif p_object = 'assets' then
    insert into assets (workspace_id, name, category, serial_number, status, assigned_to_person_id)
    values (p_workspace, p_data->>'name', coalesce(nullif(p_data->>'category',''),'other'), nullif(p_data->>'serial_number',''),
            coalesce(nullif(p_data->>'status',''),'available'), nullif(p_data->>'assigned_to_person_id','')::uuid)
    returning id into v_id;
  else
    raise exception 'UNKNOWN_OBJECT: %', p_object;
  end if;
  return v_id;
end $$;
grant execute on function create_record(text, uuid, text, jsonb) to authenticated, anon;

-- update_record — + assets (from 0031).
create or replace function update_record(p_privy text, p_object text, p_id uuid, p_data jsonb)
returns void language plpgsql security definer set search_path = public as $$
declare my uuid[] := (select array_agg(workspace_id) from accounts where privy_user_id = p_privy);
begin
  if p_object in ('companies','organizations') then
    update organizations set name=coalesce(nullif(p_data->>'name',''),name), domain=nullif(p_data->>'domain',''), industry=nullif(p_data->>'industry',''), employee_count=nullif(p_data->>'employee_count','')::int,
      tax_id=nullif(p_data->>'tax_id',''), address=nullif(p_data->>'address',''), country=nullif(p_data->>'country','')
    where id=p_id and workspace_id = any(my);
  elsif p_object = 'people' then
    update people set first_name=nullif(p_data->>'first_name',''), last_name=nullif(p_data->>'last_name',''), email=nullif(p_data->>'email',''), phone=nullif(p_data->>'phone',''), title=nullif(p_data->>'title',''), source=nullif(p_data->>'source','')
    where id=p_id and workspace_id = any(my);
  elsif p_object = 'invoices' then
    update invoices set number=nullif(p_data->>'number',''), organization_id=nullif(p_data->>'organization_id','')::uuid,
      kind=coalesce(nullif(p_data->>'kind',''),kind), direction=coalesce(nullif(p_data->>'direction',''),direction),
      amount=coalesce(nullif(p_data->>'amount','')::numeric,amount),
      status=coalesce(nullif(p_data->>'status',''),status), category=nullif(p_data->>'category',''),
      issued_at=nullif(p_data->>'issued_at','')::date, due_at=nullif(p_data->>'due_at','')::date, notes=nullif(p_data->>'notes','')
    where id=p_id and workspace_id = any(my);
  elsif p_object = 'expenses' then
    update expenses set vendor=nullif(p_data->>'vendor',''), category=coalesce(nullif(p_data->>'category',''),category), amount=coalesce(nullif(p_data->>'amount','')::numeric,amount), status=coalesce(nullif(p_data->>'status',''),status), spent_at=nullif(p_data->>'spent_at','')::date, notes=nullif(p_data->>'notes','')
    where id=p_id and workspace_id = any(my);
  elsif p_object = 'transactions' then
    update transactions set
      bank_account_id = case when p_data ? 'bank_account_id' then nullif(p_data->>'bank_account_id','')::uuid else bank_account_id end,
      txn_date = coalesce(nullif(p_data->>'txn_date','')::date, txn_date),
      description = case when p_data ? 'description' then nullif(p_data->>'description','') else description end,
      amount = coalesce(nullif(regexp_replace(coalesce(p_data->>'amount',''), '[^0-9.-]', '', 'g'),'')::numeric, amount),
      category = case when p_data ? 'category' then nullif(p_data->>'category','') else category end,
      method = coalesce(nullif(p_data->>'method',''), method),
      status = coalesce(nullif(p_data->>'status',''), status),
      tax_rate = case when p_data ? 'tax_rate' then nullif(p_data->>'tax_rate','')::numeric else tax_rate end,
      notes = case when p_data ? 'notes' then nullif(p_data->>'notes','') else notes end
    where id=p_id and workspace_id = any(my);
  elsif p_object = 'products' then
    update products set name=coalesce(nullif(p_data->>'name',''),name), sku=nullif(p_data->>'sku',''), description=nullif(p_data->>'description',''), unit_price=coalesce(nullif(p_data->>'unit_price','')::numeric,unit_price), unit=nullif(p_data->>'unit',''), category=nullif(p_data->>'category',''), image_url=nullif(p_data->>'image_url','')
    where id=p_id and workspace_id = any(my);
  elsif p_object = 'campaigns' then
    update campaigns set name=coalesce(nullif(p_data->>'name',''),name), channel=coalesce(nullif(p_data->>'channel',''),channel), status=coalesce(nullif(p_data->>'status',''),status),
      budget=coalesce(nullif(p_data->>'budget','')::numeric,budget), spend=coalesce(nullif(p_data->>'spend','')::numeric,spend), leads=coalesce(nullif(p_data->>'leads','')::int,leads),
      starts_on=nullif(p_data->>'starts_on','')::date, ends_on=nullif(p_data->>'ends_on','')::date, notes=nullif(p_data->>'notes','')
    where id=p_id and workspace_id = any(my);
  elsif p_object = 'projects' then
    update projects set name=coalesce(nullif(p_data->>'name',''),name), identifier=nullif(p_data->>'identifier',''), status=coalesce(nullif(p_data->>'status',''),status), description=nullif(p_data->>'description','')
    where id=p_id and workspace_id = any(my);
  elsif p_object = 'issues' then
    update issues set title=coalesce(nullif(p_data->>'title',''),title), status=coalesce(nullif(p_data->>'status',''),status), priority=coalesce(nullif(p_data->>'priority',''),priority), due_date=nullif(p_data->>'due_date','')::date, description=nullif(p_data->>'description','')
    where id=p_id and workspace_id = any(my);
  elsif p_object = 'assets' then
    update assets set name=coalesce(nullif(p_data->>'name',''),name), category=coalesce(nullif(p_data->>'category',''),category),
      serial_number = case when p_data ? 'serial_number' then nullif(p_data->>'serial_number','') else serial_number end,
      status=coalesce(nullif(p_data->>'status',''),status),
      assigned_to_person_id = case when p_data ? 'assigned_to_person_id' then nullif(p_data->>'assigned_to_person_id','')::uuid else assigned_to_person_id end
    where id=p_id and workspace_id = any(my);
  else
    raise exception 'UNKNOWN_OBJECT: %', p_object;
  end if;
end $$;
grant execute on function update_record(text, text, uuid, jsonb) to authenticated, anon;

-- Automations can now react to assets too (trigger was missing from 0032).
drop trigger if exists trg_autoevt_assets on assets;
create trigger trg_autoevt_assets after insert or update on assets for each row execute function emit_automation_event('assets');

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0037_pgcrypto_fix.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter Platform Core — 0037_pgcrypto_fix.sql
-- BUG FIX: "function gen_random_bytes(integer) does not exist" when saving an
-- automation (webhook trigger) or creating an API key.
--
-- ROOT CAUSE: on Supabase, pgcrypto is installed into the `extensions` schema,
-- but our SECURITY DEFINER functions pin `set search_path = public`, so
-- gen_random_bytes()/digest() are invisible at RUNTIME (the migrations passed
-- because the SQL editor's search path includes `extensions`).
--
-- FIX: remove the pgcrypto dependency entirely, using core pg_catalog
-- functions that are visible under any search path:
--   • gen_random_uuid()  — cryptographically strong (pg_strong_random), PG13+
--   • sha256(bytea)      — core since PG11; same output as Node's sha256 hex,
--                          so resolve_api_key and /api auth keep working.
--
-- Additive, idempotent & prod-safe. Depends on 0032–0033. Run AFTER them.
-- ============================================================================

-- save_automation — full redefinition from 0033, token minting via UUID.
create or replace function save_automation(p_privy text, p_workspace uuid, p_id uuid, p_data jsonb)
returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid; v_tt text := coalesce(nullif(p_data->>'trigger_type',''),'event');
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  if p_id is null then
    insert into automations (workspace_id, owner_privy, name, enabled, trigger_type, object, event, conditions, actions, schedule, webhook_token)
    values (p_workspace, p_privy, coalesce(nullif(p_data->>'name',''),'Untitled automation'),
            coalesce((p_data->>'enabled')::boolean, true), v_tt,
            coalesce(nullif(p_data->>'object',''),'companies'), coalesce(nullif(p_data->>'event',''),'created'),
            coalesce(p_data->'conditions','[]'::jsonb), coalesce(p_data->'actions','[]'::jsonb),
            case when v_tt = 'schedule' then p_data->'schedule' else null end,
            case when v_tt = 'webhook' then 'hook_' || replace(gen_random_uuid()::text, '-', '') else null end)
    returning id into v_id;
  else
    update automations set
      name = coalesce(nullif(p_data->>'name',''), name),
      enabled = coalesce((p_data->>'enabled')::boolean, enabled),
      trigger_type = v_tt,
      object = coalesce(nullif(p_data->>'object',''), object),
      event = coalesce(nullif(p_data->>'event',''), event),
      conditions = coalesce(p_data->'conditions', conditions),
      actions = coalesce(p_data->'actions', actions),
      schedule = case when v_tt = 'schedule' then p_data->'schedule' else null end,
      webhook_token = case when v_tt = 'webhook' then coalesce(webhook_token, 'hook_' || replace(gen_random_uuid()::text, '-', '')) else null end
    where id = p_id and workspace_id = p_workspace
    returning id into v_id;
  end if;
  return v_id;
end $$;
grant execute on function save_automation(text, uuid, uuid, jsonb) to authenticated, anon;

-- create_api_key — UUID-based key + core sha256 (from 0032).
create or replace function create_api_key(p_privy text, p_workspace uuid, p_name text)
returns text language plpgsql security definer set search_path = public as $$
declare v_key text; v_prefix text;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  v_key := 'hb_' || replace(gen_random_uuid()::text, '-', '') || replace(gen_random_uuid()::text, '-', '');
  v_prefix := left(v_key, 11);
  insert into api_keys (workspace_id, name, prefix, key_hash, created_by_privy)
  values (p_workspace, coalesce(nullif(p_name,''),'API key'), v_prefix, encode(sha256(v_key::bytea), 'hex'), p_privy);
  return v_key;   -- shown once, never stored in plaintext
end $$;
grant execute on function create_api_key(text, uuid, text) to authenticated, anon;

-- Defensive backfill: any connection that missed its signing secret in 0033.
update connections set secret = 'whsec_' || replace(gen_random_uuid()::text, '-', '') where secret is null or secret = '';

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0038_ai_custom_provider.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter Platform Core — 0038_ai_custom_provider.sql
-- "Every model": adds a custom OpenAI-compatible provider to BYO-AI. Users can
-- point Docs AI at ANY endpoint speaking the OpenAI chat format (Groq, Mistral,
-- DeepSeek, Together, xAI, Ollama, LM Studio, LiteLLM proxies, …) by storing a
-- base URL alongside their key.
--
-- Additive, idempotent & prod-safe. Depends on 0034. Run AFTER it.
-- ============================================================================

alter table ai_providers add column if not exists base_url text;

-- get_ai_providers — include base_url for display (masked key hint only).
create or replace function get_ai_providers(p_privy text, p_workspace uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
    'id', a.id, 'provider', a.provider, 'model', a.model, 'key_hint', a.key_hint,
    'is_default', a.is_default, 'enabled', a.enabled, 'base_url', a.base_url
  ) order by a.created_at) from ai_providers a where a.workspace_id = p_workspace), '[]'::jsonb);
end $$;
grant execute on function get_ai_providers(text, uuid) to authenticated, anon;

-- store_ai_provider — new signature with p_base_url. Drop the old 8-arg
-- overload first so PostgREST never sees an ambiguous pair.
drop function if exists store_ai_provider(text, uuid, text, text, text, text, text, text);
create or replace function store_ai_provider(p_privy text, p_workspace uuid, p_provider text, p_model text, p_cipher text, p_iv text, p_tag text, p_hint text, p_base_url text default null)
returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid; v_has_default boolean;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  select exists(select 1 from ai_providers where workspace_id = p_workspace and is_default) into v_has_default;
  insert into ai_providers (workspace_id, provider, model, key_cipher, key_iv, key_tag, key_hint, base_url, is_default, created_by_privy)
  values (p_workspace, p_provider, coalesce(p_model,''), p_cipher, p_iv, p_tag, coalesce(p_hint,''), nullif(p_base_url,''), not v_has_default, p_privy)
  on conflict (workspace_id, provider) do update set
    model = coalesce(nullif(excluded.model,''), ai_providers.model),
    key_cipher = excluded.key_cipher, key_iv = excluded.key_iv, key_tag = excluded.key_tag, key_hint = excluded.key_hint,
    base_url = coalesce(excluded.base_url, ai_providers.base_url), enabled = true
  returning id into v_id;
  return v_id;
end $$;
revoke all on function store_ai_provider(text, uuid, text, text, text, text, text, text, text) from public, authenticated, anon;
grant execute on function store_ai_provider(text, uuid, text, text, text, text, text, text, text) to service_role;

-- get_ai_secret — return base_url so the proxy can reach custom endpoints.
create or replace function get_ai_secret(p_privy text, p_workspace uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare a ai_providers;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  select * into a from ai_providers where workspace_id = p_workspace and enabled order by is_default desc, created_at limit 1;
  if a.id is null then return null; end if;
  return jsonb_build_object('provider', a.provider, 'model', a.model, 'base_url', a.base_url, 'cipher', a.key_cipher, 'iv', a.key_iv, 'tag', a.key_tag);
end $$;
revoke all on function get_ai_secret(text, uuid) from public, authenticated, anon;
grant execute on function get_ai_secret(text, uuid) to service_role;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0039_nav_activity.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter Platform Core — 0039_nav_activity.sql
-- Sidebar unread badges: "how many NEW records since I last looked at each
-- tab?" One RPC, one round trip. The client keeps a per-tab last-seen
-- timestamp (localStorage) and sends it as jsonb; keys missing from p_since
-- default to now(), so first-time users start clean instead of seeing a
-- badge storm. Covers both tenancy models: workspace objects (new platform)
-- and candidates (legacy ATS via company_users).
--
-- Additive, idempotent & prod-safe. Depends on 0001–0034. Run AFTER them.
-- ============================================================================

create or replace function get_nav_activity(p_privy text, p_since jsonb)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_ws uuid;
  v_company uuid;
  v_now timestamptz := now();
  out_j jsonb := '{}'::jsonb;
begin
  select workspace_id into v_ws from accounts where privy_user_id = p_privy limit 1;
  select company_id into v_company from company_users where privy_user_id = p_privy limit 1;

  if v_ws is not null then
    out_j := out_j || jsonb_build_object(
      'people',       (select count(*) from people        where workspace_id = v_ws and created_at > coalesce(nullif(p_since->>'people','')::timestamptz, v_now)),
      'companies',    (select count(*) from organizations  where workspace_id = v_ws and created_at > coalesce(nullif(p_since->>'companies','')::timestamptz, v_now)),
      'invoices',     (select count(*) from invoices       where workspace_id = v_ws and coalesce(kind,'invoice') <> 'offer' and created_at > coalesce(nullif(p_since->>'invoices','')::timestamptz, v_now)),
      'offers',       (select count(*) from invoices       where workspace_id = v_ws and kind = 'offer' and created_at > coalesce(nullif(p_since->>'offers','')::timestamptz, v_now)),
      'expenses',     (select count(*) from expenses       where workspace_id = v_ws and created_at > coalesce(nullif(p_since->>'expenses','')::timestamptz, v_now)),
      'transactions', (select count(*) from transactions   where workspace_id = v_ws and created_at > coalesce(nullif(p_since->>'transactions','')::timestamptz, v_now)),
      'issues',       (select count(*) from issues         where workspace_id = v_ws and created_at > coalesce(nullif(p_since->>'issues','')::timestamptz, v_now)),
      'docs',         (select count(*) from docs           where workspace_id = v_ws and created_at > coalesce(nullif(p_since->>'docs','')::timestamptz, v_now))
    );
  end if;

  if v_company is not null then
    out_j := out_j || jsonb_build_object(
      'candidates',   (select count(*) from candidates     where company_id = v_company and created_at > coalesce(nullif(p_since->>'candidates','')::timestamptz, v_now))
    );
  end if;

  return out_j;
end $$;
grant execute on function get_nav_activity(text, jsonb) to authenticated, anon;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0040_lock_rpcs.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter Platform Core — 0040_lock_rpcs.sql
-- THE security lockdown. Every authenticated RPC used to be EXECUTE-able by
-- the public anon key with a caller-supplied p_privy — so anyone who read the
-- client code could pass someone else's Privy DID and read that tenant's
-- data. The app now calls these through /api/rpc, which verifies the SIGNED
-- Privy token server-side and runs on the service-role key. This migration
-- revokes public/anon/authenticated EXECUTE on all of them (and on the
-- server-only automation/AI internals), leaving only service_role.
--
-- ⚠️ RUN ORDER MATTERS: deploy the app code that ships /api/rpc FIRST, then
-- run this. Running it against an older build breaks every dashboard read.
-- Rollback: re-run the older migrations' grant statements.
--
-- Kept PUBLIC on purpose (candidate-facing flows have no Privy session):
--   set_config, register_link_click, company_can_accept_candidate,
--   get_assessment_init_data, submit_assessment,
--   get_invoice_document_public, get_post_public, add_post_comment_public.
--
-- Idempotent & overload-safe (iterates pg_proc). Depends on 0001–0039.
-- ============================================================================

do $$
declare
  fn text;
  r record;
  locked text[] := array[
    -- workspace / CRM core
    'get_my_workspace','list_records','get_record','create_record','update_record',
    'delete_record','import_records','get_pipeline_by_kind','move_pipeline_record',
    'get_finance_summary','get_finance_analytics','get_project','get_roadmap',
    'get_members','set_member_role','get_invoice_document','save_invoice_items',
    'convert_offer_to_invoice','get_transactions_ledger','create_bank_account',
    'get_bank_accounts','delete_bank_account','reconcile_transaction',
    'suggest_transaction_matches','update_transactions_bulk','get_workspace_branding',
    'save_workspace_branding','get_nav_activity','get_treasury_dataset',
    -- marketing sites
    'create_site','delete_site','get_sites','get_site_stats','get_posts','get_post',
    'save_post','add_post_comment','set_post_comment_resolved',
    -- automations + integrations (client-facing)
    'get_automations','get_automation_by_id','save_automation','delete_automation',
    'set_automation_enabled','get_automation_runs','get_event_automations',
    'get_connections','get_connection','save_connection','delete_connection',
    'create_api_key','get_api_keys','revoke_api_key','get_webhook_endpoints',
    'upsert_webhook_endpoint','delete_webhook_endpoint','get_webhook_deliveries',
    -- docs + AI providers
    'get_docs','get_doc','save_doc','delete_doc','get_ai_providers',
    'store_ai_provider','delete_ai_provider','set_ai_provider_meta',
    -- HR / ATS
    'get_message_templates','upsert_message_template','delete_message_template',
    'get_tracking_links','get_source_attribution','create_tracking_link',
    'get_my_team','get_onboarding_tasks','set_onboarding_task','record_pulse',
    'get_candidates_for_recruiter','search_candidates_for_recruiter',
    'get_candidate_details','get_pipeline_board','log_candidate_message',
    -- server-only internals (dispatcher / MCP / cron) — never for browsers
    'claim_automation_events','complete_automation_event','retry_automation_event',
    'enqueue_webhook_event','enqueue_scheduled_automations','log_webhook_delivery',
    'log_automation_run','resolve_api_key','get_ai_secret',
    'automation_create_record','automation_update_record','anonymize_expired_candidates'
  ];
begin
  foreach fn in array locked loop
    for r in
      select p.oid::regprocedure as sig
      from pg_proc p
      join pg_namespace n on n.oid = p.pronamespace
      where n.nspname = 'public' and p.proname = fn
    loop
      execute format('revoke execute on function %s from public, anon, authenticated', r.sig);
      execute format('grant execute on function %s to service_role', r.sig);
    end loop;
  end loop;
end $$;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0041_hr_secure_rpcs.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0041_hr_secure_rpcs.sql
-- Phase B of the lockdown: the legacy ATS tables still had RLS policies that
-- resolve the tenant from current_setting('app.current_privy_user_id'), which
-- ANY holder of the public anon key can set to a victim's (non-secret) Privy
-- DID — so set_config(victim) + select * from candidates leaked cross-tenant
-- PII. Same spoof as the old p_privy pattern, via the GUC.
--
-- Fix: every remaining CLIENT read/write of the crown-jewel tables now goes
-- through a SECURITY DEFINER RPC. Recruiter RPCs (hr_*) resolve the company
-- from the caller's privy id and are granted to service_role ONLY — they are
-- reachable exclusively through /api/rpc, which injects the VERIFIED privy id
-- (a direct anon call can't reach them, so the spoof is gone). The public
-- apply flow (candidates have no login) gets two anon-callable DEFINER RPCs
-- that need no anon table privileges, so 0042 can revoke those entirely.
--
-- Additive & idempotent. Depends on 0001–0040. Pairs with 0042 (the revoke),
-- which must run AFTER this + the app deploy.
-- ============================================================================

-- ── helper: resolve legacy company from a privy id ──────────────────────────
create or replace function hr_company_id(p_privy text)
returns uuid language sql stable security definer set search_path = public as $$
  select company_id from company_users where privy_user_id = p_privy limit 1;
$$;

-- ── PUBLIC apply flow (anon; DEFINER so it needs no anon table grants) ───────
create or replace function apply_to_position(
  p_position_id uuid, p_full_name text, p_email text, p_phone text,
  p_linkedin text, p_source text, p_utm_source text, p_utm_medium text,
  p_utm_campaign text, p_referrer text, p_tracking_link_id uuid
) returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_company uuid; v_title text; v_id uuid; v_token uuid;
begin
  select company_id, title into v_company, v_title from positions where id = p_position_id;
  if v_company is null then raise exception 'Position not found'; end if;
  -- Honour the plan candidate cap, but fail OPEN (as the old client did) if the
  -- cap function is absent, so infra gaps never block a genuine applicant.
  begin
    if not company_can_accept_candidate(v_company) then
      raise exception 'This position is no longer accepting applications.';
    end if;
  exception
    when undefined_function then null;
  end;

  insert into candidates (
    company_id, position_id, full_name, email, phone, linkedin_url, status,
    source, utm_source, utm_medium, utm_campaign, referrer, tracking_link_id
  ) values (
    v_company, p_position_id, p_full_name, p_email, nullif(p_phone,''), nullif(p_linkedin,''),
    'applied', coalesce(nullif(p_source,''),'direct'), p_utm_source, p_utm_medium,
    p_utm_campaign, p_referrer, p_tracking_link_id
  ) returning id, access_token into v_id, v_token;

  insert into activity_log (company_id, candidate_id, action, details)
  values (v_company, v_id, 'application_submitted',
          jsonb_build_object('position_title', v_title, 'cv_uploaded', true));

  return jsonb_build_object('id', v_id, 'access_token', v_token);
end $$;

-- Applicant attaches their CV url; gated by the access_token just returned, so
-- only the person who created the row can set it (no login required).
create or replace function set_candidate_cv(p_candidate_id uuid, p_access_token uuid, p_cv_url text)
returns boolean language plpgsql security definer set search_path = public as $$
declare v_n int;
begin
  update candidates set cv_url = p_cv_url
   where id = p_candidate_id and access_token = p_access_token;
  get diagnostics v_n = row_count;
  return v_n > 0;
end $$;

-- ── RECRUITER RPCs (service_role only → only reachable via verified /api/rpc) ─

-- Home / HR overview aggregates.
create or replace function hr_overview_data(p_privy text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_c uuid; v_company jsonb; v_now timestamptz := now();
begin
  v_c := hr_company_id(p_privy);
  if v_c is null then return null; end if;
  select to_jsonb(c) into v_company from (select name, plan from companies where id = v_c) c;
  return jsonb_build_object(
    'company', v_company,
    'status_rows', coalesce((select jsonb_agg(jsonb_build_object('status', status, 'applied_at', applied_at))
                             from candidates where company_id = v_c), '[]'::jsonb),
    'active_positions', (select count(*) from positions where company_id = v_c and is_active),
    'upcoming_interviews', (select count(*) from interviews i join candidates ca on ca.id = i.candidate_id
                            where ca.company_id = v_c and i.status = 'scheduled' and i.scheduled_at >= v_now),
    'assessments_completed', (select count(*) from assessment_responses r join candidates ca on ca.id = r.candidate_id
                              where ca.company_id = v_c and r.is_completed),
    'recent', coalesce((select jsonb_agg(row) from (
        select jsonb_build_object('id', ca.id, 'full_name', ca.full_name, 'email', ca.email,
               'status', ca.status, 'applied_at', ca.applied_at,
               'position_title', p.title) as row
        from candidates ca left join positions p on p.id = ca.position_id
        where ca.company_id = v_c order by ca.applied_at desc limit 6) s), '[]'::jsonb)
  );
end $$;

-- Recruitment analytics raw rows.
create or replace function hr_analytics_data(p_privy text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_c uuid;
begin
  v_c := hr_company_id(p_privy);
  if v_c is null then return null; end if;
  return jsonb_build_object(
    'company', (select to_jsonb(c) from (select * from companies where id = v_c) c),
    'positions', coalesce((select jsonb_agg(jsonb_build_object('id', id, 'title', title, 'status', status))
                           from positions where company_id = v_c), '[]'::jsonb),
    'candidates', coalesce((select jsonb_agg(jsonb_build_object('id', id, 'status', status,
                            'source', source, 'position_id', position_id))
                            from candidates where company_id = v_c), '[]'::jsonb)
  );
end $$;

-- Activity log for one candidate (tenant-checked).
create or replace function hr_candidate_activity(p_privy text, p_candidate_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_c uuid;
begin
  v_c := hr_company_id(p_privy);
  if v_c is null then return '[]'::jsonb; end if;
  return coalesce((select jsonb_agg(to_jsonb(a) order by a.created_at desc)
    from activity_log a
    where a.candidate_id = p_candidate_id and a.company_id = v_c), '[]'::jsonb);
end $$;

-- Move a candidate's stage + audit it (tenant-checked).
create or replace function hr_update_candidate_status(p_privy text, p_candidate_id uuid, p_status text)
returns boolean language plpgsql security definer set search_path = public as $$
declare v_c uuid; v_old text; v_n int;
begin
  v_c := hr_company_id(p_privy);
  if v_c is null then return false; end if;
  select status into v_old from candidates where id = p_candidate_id and company_id = v_c;
  update candidates set status = p_status where id = p_candidate_id and company_id = v_c;
  get diagnostics v_n = row_count;
  if v_n = 0 then return false; end if;
  insert into activity_log (company_id, candidate_id, action, details)
  values (v_c, p_candidate_id, 'status_updated',
          jsonb_build_object('old_status', v_old, 'new_status', p_status));
  return true;
end $$;

-- "Generate demo data" helper on the candidate page (tenant-checked insert).
create or replace function hr_seed_demo_result(p_privy text, p_candidate_id uuid, p_results jsonb)
returns boolean language plpgsql security definer set search_path = public as $$
declare v_c uuid;
begin
  v_c := hr_company_id(p_privy);
  if v_c is null then return false; end if;
  if not exists (select 1 from candidates where id = p_candidate_id and company_id = v_c) then
    return false;
  end if;
  insert into assessment_results (candidate_id, overall_score, cognitive_score, personality_score,
    work_style_score, personality_data, work_style_data, cognitive_data, summary)
  values (p_candidate_id,
    (p_results->>'overall_score')::int, (p_results->>'cognitive_score')::int,
    (p_results->>'personality_score')::int, (p_results->>'work_style_score')::int,
    p_results->'personality_data', p_results->'work_style_data', p_results->'cognitive_data',
    p_results->>'summary');
  update candidates set status = 'assessment_completed' where id = p_candidate_id and company_id = v_c;
  return true;
end $$;

-- Is Google Calendar connected for this recruiter's workspace?
create or replace function hr_google_connected(p_privy text)
returns boolean language sql stable security definer set search_path = public as $$
  select exists(
    select 1 from integration_tokens t
    join company_users cu on cu.id = t.user_id
    where cu.privy_user_id = p_privy and t.provider = 'google');
$$;

-- ── grants ──────────────────────────────────────────────────────────────────
-- Public flow: anon may call these two (DEFINER, no table privileges needed).
grant execute on function apply_to_position(uuid,text,text,text,text,text,text,text,text,text,uuid) to anon, authenticated, service_role;
grant execute on function set_candidate_cv(uuid,uuid,text) to anon, authenticated, service_role;
-- Recruiter RPCs: service_role ONLY. Reached only through the verified proxy;
-- a direct anon call with a spoofed p_privy cannot execute them.
revoke all on function hr_company_id(text) from public, anon, authenticated;
grant execute on function hr_overview_data(text)                     to service_role;
grant execute on function hr_analytics_data(text)                    to service_role;
grant execute on function hr_candidate_activity(text,uuid)           to service_role;
grant execute on function hr_update_candidate_status(text,uuid,text) to service_role;
grant execute on function hr_seed_demo_result(text,uuid,jsonb)       to service_role;
grant execute on function hr_google_connected(text)                  to service_role;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0042_lock_legacy_tables.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0042_lock_legacy_tables.sql
-- The table-level half of Phase B. Revokes the public/anon/authenticated
-- roles' direct access to the crown-jewel ATS tables (candidate PII, resumes,
-- assessment scores, OAuth tokens). After 0041 routed every remaining client
-- read/write through SECURITY DEFINER RPCs, nothing in the browser touches
-- these tables directly anymore:
--   • recruiter access  → hr_* RPCs, service_role only, via verified /api/rpc
--   • public apply flow → apply_to_position / set_candidate_cv (DEFINER, anon)
--   • server routes     → service_role (bypasses this revoke)
-- so cutting the anon/authenticated key off closes the set_config spoof.
--
-- ⚠️ RUN ORDER: deploy the app (0041 RPCs + client changes) FIRST, then run
-- this. Running it against an older build breaks the HR dashboard reads.
-- Rollback: `grant select, insert, update, delete on <table> to anon, authenticated;`
--
-- NOT locked this pass (documented follow-up): companies, company_users,
-- positions, assessment_templates — lower-stakes metadata (names, titles,
-- member emails) still reachable via the GUC spoof until their client reads
-- are moved behind RPCs too.
--
-- Idempotent. Depends on 0041.
-- ============================================================================

do $$
declare t text;
begin
  foreach t in array array[
    'candidates', 'assessment_results', 'assessment_responses',
    'interviews', 'activity_log', 'integration_tokens'
  ] loop
    if to_regclass('public.' || t) is not null then
      execute format('revoke all on table public.%I from anon, authenticated', t);
      -- keep RLS enabled as belt-and-suspenders; service_role bypasses both
      execute format('alter table public.%I enable row level security', t);
    end if;
  end loop;
end $$;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0043_agents.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter Platform Core — 0043_agents.sql
-- AI Agents: users define agents (role + instructions + which BYO model +
-- which tools they may use + an autonomy level), then run them on a task. The
-- runner (server-side, /api/agents/run) executes a tool-use loop over the SAME
-- workspace tools the MCP server exposes, on the user's own AI key. Two safety
-- layers: (1) tools are scoped per agent, (2) 'suggest' agents only PROPOSE
-- writes — a human approves before anything is created/updated. 'auto' agents
-- write directly, bounded by a per-run step cap + the scoped tool list + a full
-- audit log. Agents always act inside the owner's workspace tenancy.
--
-- Additive, idempotent & prod-safe. Depends on 0001–0034. Run AFTER them.
-- ============================================================================

create table if not exists agents (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspaces(id) on delete cascade,
  name text not null default 'New agent',
  role text not null default '',                    -- short label, e.g. "Collections assistant"
  instructions text not null default '',            -- system prompt
  provider text not null default '',                -- '' = use workspace default AI key
  model text not null default '',
  allowed_tools text[] not null default '{list_objects,list_records,search_records,get_record}',
  allowed_objects text[] not null default '{}',     -- empty = all objects; else restrict
  autonomy text not null default 'suggest' check (autonomy in ('suggest','auto')),
  max_steps int not null default 12 check (max_steps between 1 and 40),
  enabled boolean not null default true,
  created_by_privy text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists idx_agents_ws on agents(workspace_id, updated_at desc);
drop trigger if exists trg_agents_upd on agents;
create trigger trg_agents_upd before update on agents for each row execute function set_updated_at();
alter table agents enable row level security;

-- One run of an agent against a task. `steps` is the audit log (each AI turn +
-- tool call + result). `proposed` holds writes awaiting approval (suggest mode).
create table if not exists agent_runs (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspaces(id) on delete cascade,
  agent_id uuid references agents(id) on delete set null,
  agent_name text not null default '',
  task text not null default '',
  status text not null default 'running'
    check (status in ('running','done','error','awaiting_approval')),
  steps jsonb not null default '[]'::jsonb,
  proposed jsonb not null default '[]'::jsonb,
  result text not null default '',
  created_by_privy text,
  created_at timestamptz not null default now(),
  finished_at timestamptz
);
create index if not exists idx_agent_runs_ws on agent_runs(workspace_id, created_at desc);
alter table agent_runs enable row level security;

-- ── Agent CRUD (client-facing, via /api/rpc verified proxy) ────────────────────
create or replace function get_agents(p_privy text, p_workspace uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((select jsonb_agg(to_jsonb(a) order by a.updated_at desc) from (
    select id, name, role, instructions, provider, model, allowed_tools, allowed_objects,
           autonomy, max_steps, enabled, updated_at
    from agents where workspace_id = p_workspace
  ) a), '[]'::jsonb);
end $$;
grant execute on function get_agents(text, uuid) to authenticated, anon;

create or replace function save_agent(
  p_privy text, p_workspace uuid, p_id uuid, p_name text, p_role text, p_instructions text,
  p_provider text, p_model text, p_allowed_tools text[], p_allowed_objects text[],
  p_autonomy text, p_max_steps int
) returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  if p_id is null then
    insert into agents (workspace_id, name, role, instructions, provider, model,
      allowed_tools, allowed_objects, autonomy, max_steps, created_by_privy)
    values (p_workspace, coalesce(nullif(p_name,''),'New agent'), p_role, p_instructions,
      coalesce(p_provider,''), coalesce(p_model,''),
      coalesce(p_allowed_tools, '{list_objects,list_records,search_records,get_record}'),
      coalesce(p_allowed_objects, '{}'),
      coalesce(nullif(p_autonomy,''),'suggest'), coalesce(p_max_steps,12), p_privy)
    returning id into v_id;
  else
    update agents set name = p_name, role = p_role, instructions = p_instructions,
      provider = coalesce(p_provider,''), model = coalesce(p_model,''),
      allowed_tools = coalesce(p_allowed_tools, allowed_tools),
      allowed_objects = coalesce(p_allowed_objects, allowed_objects),
      autonomy = coalesce(nullif(p_autonomy,''), autonomy), max_steps = coalesce(p_max_steps, max_steps)
    where id = p_id and workspace_id = p_workspace
    returning id into v_id;
  end if;
  return v_id;
end $$;
grant execute on function save_agent(text, uuid, uuid, text, text, text, text, text, text[], text[], text, int) to authenticated, anon;

create or replace function set_agent_enabled(p_privy text, p_workspace uuid, p_id uuid, p_enabled boolean)
returns boolean language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  update agents set enabled = p_enabled where id = p_id and workspace_id = p_workspace;
  return found;
end $$;
grant execute on function set_agent_enabled(text, uuid, uuid, boolean) to authenticated, anon;

create or replace function delete_agent(p_privy text, p_workspace uuid, p_id uuid)
returns boolean language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  delete from agents where id = p_id and workspace_id = p_workspace;
  return found;
end $$;
grant execute on function delete_agent(text, uuid, uuid) to authenticated, anon;

create or replace function get_agent_runs(p_privy text, p_workspace uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((select jsonb_agg(to_jsonb(r) order by r.created_at desc) from (
    select id, agent_id, agent_name, task, status, steps, proposed, result, created_at, finished_at
    from agent_runs where workspace_id = p_workspace order by created_at desc limit 50
  ) r), '[]'::jsonb);
end $$;
grant execute on function get_agent_runs(text, uuid) to authenticated, anon;

-- ── Runner-side writers (service_role only; the /api/agents routes call these) ─
-- get one agent's full definition (incl. its resolved run config).
create or replace function get_agent_full(p_workspace uuid, p_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  return (select to_jsonb(a) from agents a where a.id = p_id and a.workspace_id = p_workspace);
end $$;
revoke all on function get_agent_full(uuid, uuid) from public, authenticated, anon;
grant execute on function get_agent_full(uuid, uuid) to service_role;

create or replace function create_agent_run(p_workspace uuid, p_agent_id uuid, p_agent_name text, p_task text, p_privy text)
returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid;
begin
  insert into agent_runs (workspace_id, agent_id, agent_name, task, created_by_privy)
  values (p_workspace, p_agent_id, p_agent_name, p_task, p_privy) returning id into v_id;
  return v_id;
end $$;
revoke all on function create_agent_run(uuid, uuid, text, text, text) from public, authenticated, anon;
grant execute on function create_agent_run(uuid, uuid, text, text, text) to service_role;

create or replace function finish_agent_run(p_id uuid, p_status text, p_steps jsonb, p_proposed jsonb, p_result text)
returns void language plpgsql security definer set search_path = public as $$
begin
  update agent_runs set status = p_status, steps = coalesce(p_steps,'[]'::jsonb),
    proposed = coalesce(p_proposed,'[]'::jsonb), result = coalesce(p_result,''),
    finished_at = case when p_status in ('done','error') then now() else finished_at end
  where id = p_id;
end $$;
revoke all on function finish_agent_run(uuid, text, jsonb, jsonb, text) from public, authenticated, anon;
grant execute on function finish_agent_run(uuid, text, jsonb, jsonb, text) to service_role;

-- fetch a run for the approval step (service_role; approve route resolves tenancy).
create or replace function get_agent_run_row(p_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  return (select to_jsonb(r) from agent_runs r where r.id = p_id);
end $$;
revoke all on function get_agent_run_row(uuid) from public, authenticated, anon;
grant execute on function get_agent_run_row(uuid) to service_role;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0044_hr_manage.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0044_hr_manage.sql
-- HR add/delete management the UI was missing:
--   • Interviews were never actually stored — the schedule route only made a
--     Google Calendar event, so the Interviews page showed dummy data. These
--     RPCs list / create / cancel real rows in the `interviews` table, no
--     Google dependency (works on any plan; the Calendar sync stays a Pro
--     add-on on the candidate page).
--   • Candidates could only arrive via the public apply flow — recruiters had
--     no way to add one manually or delete one. Added both.
--
-- All are SECURITY DEFINER, tenant-checked via hr_company_id (0041), and
-- service_role-only so they are reachable only through the verified /api/rpc
-- proxy. Additive & idempotent. Depends on 0041.
-- ============================================================================

-- ── Interviews ────────────────────────────────────────────────────────────────
create or replace function hr_list_interviews(p_privy text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_c uuid;
begin
  v_c := hr_company_id(p_privy);
  if v_c is null then return '[]'::jsonb; end if;
  return coalesce((select jsonb_agg(row order by row->>'scheduled_at') from (
    select jsonb_build_object(
      'id', i.id, 'candidate_id', i.candidate_id, 'candidate_name', c.full_name,
      'candidate_email', c.email, 'position_title', p.title,
      'scheduled_at', i.scheduled_at, 'duration_minutes', i.duration_minutes,
      'status', i.status, 'notes', i.notes, 'meet_link', i.google_meet_link
    ) as row
    from interviews i
    join candidates c on c.id = i.candidate_id
    left join positions p on p.id = c.position_id
    where c.company_id = v_c and i.status = 'scheduled' and i.scheduled_at >= now() - interval '1 day'
  ) s), '[]'::jsonb);
end $$;
revoke all on function hr_list_interviews(text) from public, anon, authenticated;
grant execute on function hr_list_interviews(text) to service_role;

create or replace function hr_schedule_interview(
  p_privy text, p_candidate_id uuid, p_scheduled_at timestamptz, p_duration int, p_notes text
) returns uuid language plpgsql security definer set search_path = public as $$
declare v_c uuid; v_id uuid;
begin
  v_c := hr_company_id(p_privy);
  if v_c is null then raise exception 'NOT_A_MEMBER'; end if;
  if not exists (select 1 from candidates where id = p_candidate_id and company_id = v_c) then
    raise exception 'Candidate not in your workspace';
  end if;
  insert into interviews (candidate_id, scheduled_at, duration_minutes, status, notes)
  values (p_candidate_id, p_scheduled_at, coalesce(p_duration, 30), 'scheduled', nullif(p_notes,''))
  returning id into v_id;
  update candidates set status = 'interview_scheduled' where id = p_candidate_id and company_id = v_c;
  insert into activity_log (company_id, candidate_id, action, details)
  values (v_c, p_candidate_id, 'status_updated', jsonb_build_object('new_status', 'interview_scheduled', 'scheduled_at', p_scheduled_at));
  return v_id;
end $$;
revoke all on function hr_schedule_interview(text, uuid, timestamptz, int, text) from public, anon, authenticated;
grant execute on function hr_schedule_interview(text, uuid, timestamptz, int, text) to service_role;

create or replace function hr_cancel_interview(p_privy text, p_id uuid)
returns boolean language plpgsql security definer set search_path = public as $$
declare v_c uuid; v_n int;
begin
  v_c := hr_company_id(p_privy);
  if v_c is null then return false; end if;
  delete from interviews i using candidates c
   where i.id = p_id and i.candidate_id = c.id and c.company_id = v_c;
  get diagnostics v_n = row_count;
  return v_n > 0;
end $$;
revoke all on function hr_cancel_interview(text, uuid) from public, anon, authenticated;
grant execute on function hr_cancel_interview(text, uuid) to service_role;

-- ── Candidates (recruiter add / delete) ───────────────────────────────────────
create or replace function hr_create_candidate(
  p_privy text, p_full_name text, p_email text, p_phone text, p_linkedin text, p_position_id uuid
) returns uuid language plpgsql security definer set search_path = public as $$
declare v_c uuid; v_id uuid;
begin
  v_c := hr_company_id(p_privy);
  if v_c is null then raise exception 'NOT_A_MEMBER'; end if;
  if coalesce(trim(p_full_name),'') = '' or coalesce(trim(p_email),'') = '' then
    raise exception 'Name and email are required';
  end if;
  -- position (if given) must belong to the same company
  if p_position_id is not null and not exists (select 1 from positions where id = p_position_id and company_id = v_c) then
    raise exception 'Position not in your workspace';
  end if;
  insert into candidates (company_id, position_id, full_name, email, phone, linkedin_url, status, source)
  values (v_c, p_position_id, trim(p_full_name), trim(p_email), nullif(p_phone,''), nullif(p_linkedin,''), 'applied', 'manual')
  returning id into v_id;
  insert into activity_log (company_id, candidate_id, action, details)
  values (v_c, v_id, 'candidate_added', jsonb_build_object('source', 'manual'));
  return v_id;
end $$;
revoke all on function hr_create_candidate(text, text, text, text, text, uuid) from public, anon, authenticated;
grant execute on function hr_create_candidate(text, text, text, text, text, uuid) to service_role;

create or replace function hr_delete_candidate(p_privy text, p_id uuid)
returns boolean language plpgsql security definer set search_path = public as $$
declare v_c uuid; v_n int;
begin
  v_c := hr_company_id(p_privy);
  if v_c is null then return false; end if;
  delete from candidates where id = p_id and company_id = v_c;  -- cascades to assessments/interviews/activity
  get diagnostics v_n = row_count;
  return v_n > 0;
end $$;
revoke all on function hr_delete_candidate(text, uuid) from public, anon, authenticated;
grant execute on function hr_delete_candidate(text, uuid) to service_role;

-- also expose a lightweight position list for the "add candidate" picker
create or replace function hr_list_positions_min(p_privy text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_c uuid;
begin
  v_c := hr_company_id(p_privy);
  if v_c is null then return '[]'::jsonb; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('id', id, 'title', title) order by created_at desc)
                   from positions where company_id = v_c and is_active), '[]'::jsonb);
end $$;
revoke all on function hr_list_positions_min(text) from public, anon, authenticated;
grant execute on function hr_list_positions_min(text) to service_role;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0045_interviews_manage.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0045_interviews_manage.sql
-- Makes interview scheduling actually work end-to-end.
--
-- Background: two half-built flows existed. The Interviews page stored a bare
-- `interviews` row but created no Google Meet link and sent no email; the
-- candidate page created a Meet event but stored no row (so it never appeared
-- in the list). This migration reworks the RPCs so a single server route
-- (/api/hr/interviews) can: create the row WITH the Meet link + event id,
-- reschedule it, and cancel it — while the route handles the Google Calendar
-- call and the candidate email around them.
--
-- The `interviews` table itself ships in supabase-schema.sql (base setup). We
-- guard its existence + the columns we touch so this is safe on any live DB.
-- All RPCs are SECURITY DEFINER, tenant-checked via hr_company_id (0041), and
-- service_role-only (reached only through the verified server). Depends on 0041.
-- ============================================================================

-- ── Schema guard (no-op if base schema already created it) ────────────────────
create table if not exists interviews (
  id uuid primary key default gen_random_uuid(),
  candidate_id uuid references candidates(id) on delete cascade,
  interviewer_id uuid references company_users(id),
  scheduled_at timestamptz not null,
  duration_minutes integer default 60,
  google_calendar_event_id text,
  google_meet_link text,
  status text default 'scheduled',
  notes text,
  feedback jsonb,
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);
alter table interviews add column if not exists google_calendar_event_id text;
alter table interviews add column if not exists google_meet_link text;
alter table interviews add column if not exists duration_minutes integer default 60;
alter table interviews add column if not exists notes text;
alter table interviews add column if not exists status text default 'scheduled';
alter table interviews add column if not exists updated_at timestamptz default now();

-- Re-apply the 0042 lockdown. Normally a no-op, but if the `create table if not
-- exists` above actually created the table (fresh project, or a DB that predates
-- the base schema), it would otherwise pick up Supabase's default privileges for
-- anon/authenticated and sit there readable. The hr_* RPCs below are SECURITY
-- DEFINER and run as the owner, so RLS does not impede them.
revoke all on table public.interviews from anon, authenticated;
alter table public.interviews enable row level security;

-- ── Candidate contact card (for building the Meet event + the email) ──────────
create or replace function hr_candidate_contact(p_privy text, p_candidate_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_c uuid; v_row jsonb;
begin
  v_c := hr_company_id(p_privy);
  if v_c is null then raise exception 'NOT_A_MEMBER'; end if;
  select jsonb_build_object(
    'full_name', c.full_name, 'email', c.email,
    'position_title', p.title,
    'company_name', co.name, 'brand_color', co.brand_color
  ) into v_row
  from candidates c
  left join positions p on p.id = c.position_id
  left join companies co on co.id = c.company_id
  where c.id = p_candidate_id and c.company_id = v_c;
  if v_row is null then raise exception 'Candidate not in your workspace'; end if;
  return v_row;
end $$;
revoke all on function hr_candidate_contact(text, uuid) from public, anon, authenticated;
grant execute on function hr_candidate_contact(text, uuid) to service_role;

-- ── Schedule (now stores the Meet link + calendar event id) ───────────────────
-- Signature changed (added p_meet_link / p_event_id), so drop the 0044 version.
drop function if exists hr_schedule_interview(text, uuid, timestamptz, int, text);
create or replace function hr_schedule_interview(
  p_privy text, p_candidate_id uuid, p_scheduled_at timestamptz, p_duration int,
  p_notes text, p_meet_link text default null, p_event_id text default null
) returns uuid language plpgsql security definer set search_path = public as $$
declare v_c uuid; v_id uuid; v_interviewer uuid;
begin
  v_c := hr_company_id(p_privy);
  if v_c is null then raise exception 'NOT_A_MEMBER'; end if;
  if not exists (select 1 from candidates where id = p_candidate_id and company_id = v_c) then
    raise exception 'Candidate not in your workspace';
  end if;
  select id into v_interviewer from company_users
   where privy_user_id = p_privy and company_id = v_c limit 1;
  insert into interviews (candidate_id, interviewer_id, scheduled_at, duration_minutes,
                          status, notes, google_meet_link, google_calendar_event_id)
  values (p_candidate_id, v_interviewer, p_scheduled_at, coalesce(p_duration, 30),
          'scheduled', nullif(p_notes,''), nullif(p_meet_link,''), nullif(p_event_id,''))
  returning id into v_id;
  update candidates set status = 'interview_scheduled' where id = p_candidate_id and company_id = v_c;
  insert into activity_log (company_id, candidate_id, action, details)
  values (v_c, p_candidate_id, 'status_updated',
          jsonb_build_object('new_status', 'interview_scheduled', 'scheduled_at', p_scheduled_at,
                             'meet_link', nullif(p_meet_link,'')));
  return v_id;
end $$;
revoke all on function hr_schedule_interview(text, uuid, timestamptz, int, text, text, text) from public, anon, authenticated;
grant execute on function hr_schedule_interview(text, uuid, timestamptz, int, text, text, text) to service_role;

-- ── Reschedule / edit ─────────────────────────────────────────────────────────
create or replace function hr_update_interview(
  p_privy text, p_id uuid, p_scheduled_at timestamptz, p_duration int, p_notes text
) returns jsonb language plpgsql security definer set search_path = public as $$
declare v_c uuid; v_row jsonb;
begin
  v_c := hr_company_id(p_privy);
  if v_c is null then raise exception 'NOT_A_MEMBER'; end if;
  update interviews i
     set scheduled_at = p_scheduled_at,
         duration_minutes = coalesce(p_duration, i.duration_minutes),
         notes = nullif(p_notes,''),
         updated_at = now()
   from candidates c
   where i.id = p_id and i.candidate_id = c.id and c.company_id = v_c;
  if not found then raise exception 'Interview not in your workspace'; end if;
  select jsonb_build_object(
    'id', i.id, 'candidate_name', c.full_name, 'candidate_email', c.email,
    'position_title', p.title, 'company_name', co.name, 'brand_color', co.brand_color,
    'google_calendar_event_id', i.google_calendar_event_id, 'meet_link', i.google_meet_link,
    'scheduled_at', i.scheduled_at, 'duration_minutes', i.duration_minutes
  ) into v_row
  from interviews i
  join candidates c on c.id = i.candidate_id
  left join positions p on p.id = c.position_id
  left join companies co on co.id = c.company_id
  where i.id = p_id;
  return v_row;
end $$;
revoke all on function hr_update_interview(text, uuid, timestamptz, int, text) from public, anon, authenticated;
grant execute on function hr_update_interview(text, uuid, timestamptz, int, text) to service_role;

-- ── Cancel (returns the event id + contact so the route can clean up Google) ──
-- Return type changed boolean → jsonb, so drop the 0044 version first.
drop function if exists hr_cancel_interview(text, uuid);
create or replace function hr_cancel_interview(p_privy text, p_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_c uuid; v_event text; v_email text; v_name text; v_pos text;
        v_color text; v_company text; v_when timestamptz; v_dur int;
begin
  v_c := hr_company_id(p_privy);
  if v_c is null then return jsonb_build_object('ok', false); end if;
  select i.google_calendar_event_id, c.email, c.full_name, p.title,
         co.brand_color, co.name, i.scheduled_at, i.duration_minutes
    into v_event, v_email, v_name, v_pos, v_color, v_company, v_when, v_dur
  from interviews i
  join candidates c on c.id = i.candidate_id
  left join positions p on p.id = c.position_id
  left join companies co on co.id = c.company_id
  where i.id = p_id and c.company_id = v_c;
  if not found then return jsonb_build_object('ok', false); end if;
  delete from interviews where id = p_id;
  return jsonb_build_object(
    'ok', true, 'google_calendar_event_id', v_event,
    'candidate_email', v_email, 'candidate_name', v_name, 'position_title', v_pos,
    'brand_color', v_color, 'company_name', v_company,
    'scheduled_at', v_when, 'duration_minutes', v_dur
  );
end $$;
revoke all on function hr_cancel_interview(text, uuid) from public, anon, authenticated;
grant execute on function hr_cancel_interview(text, uuid) to service_role;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0046_revoke_public_execute.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0046_revoke_public_execute.sql
--
-- Closes the hole audit-security.sql surfaced: 29 SECURITY DEFINER functions
-- were executable by `anon`, including hr_overview_data(p_privy),
-- hr_update_candidate_status(p_privy, …), search_people(p_privy, …) and the
-- whole agents CRUD. DEFINER bypasses RLS, so anyone holding the public anon
-- key could call them straight against the Supabase REST endpoint with someone
-- else's Privy DID and read or modify that tenant's data — routing around the
-- /api/rpc proxy entirely. The proxy only ever protected the browser path.
--
-- Root cause: Postgres grants EXECUTE to PUBLIC on every new function. 0041 and
-- 0043 granted to service_role but never revoked that default, so the grant
-- stayed. 0044/0045 did revoke, which is why none of their functions were
-- exposed — this migration applies that same treatment retroactively, and by
-- iteration rather than by name so nothing is missed.
--
-- ⚠️ RUN ORDER — CHECK THIS FIRST OR THE APP GOES DOWN:
--   /api/rpc must be talking to Postgres as `service_role`. It falls back to the
--   anon key when SUPABASE_SERVICE_ROLE_KEY is unset (see app/api/rpc/route.ts),
--   and after this migration the anon key can no longer execute these functions
--   — every dashboard read would start failing. Confirm the env var is present
--   in Render (and locally) BEFORE running this. Same caveat 0042 carried.
--
-- Rollback if something breaks:
--   grant execute on function public.<name>(<args>) to anon, authenticated;
--
-- Idempotent and safe to re-run. Verify with supabase/audit-security.sql:
-- section B should afterwards list ONLY the keep_public functions below.
-- ============================================================================

do $$
declare
  r record;
  -- Genuinely public surfaces. Candidates and invoice/post recipients have no
  -- Privy session, so these must stay anon-callable. Each is either token-gated
  -- (a uuid/text secret the caller must already hold) or writes only its own row.
  keep_public text[] := array[
    'apply_to_position',            -- public job application
    'set_candidate_cv',             -- CV upload during apply (token-gated)
    'get_assessment_init_data',     -- assessment load (token-gated)
    'submit_assessment',            -- assessment submit (token-gated)
    'log_consent',                  -- GDPR consent during apply
    'register_link_click',          -- tracking-link click counter
    'company_can_accept_candidate', -- plan cap check in the apply flow
    'get_invoice_document_public',  -- shared invoice view (token-gated)
    'get_post_public',              -- shared post review (token-gated)
    'add_post_comment_public'       -- comment on a shared post (token-gated)
  ];
  n_revoked int := 0;
begin
  for r in
    select p.oid,
           p.proname,
           pg_get_function_identity_arguments(p.oid) as args
    from pg_proc p
    join pg_namespace ns on ns.oid = p.pronamespace
    where ns.nspname = 'public'
      and p.prosecdef                       -- DEFINER only: these bypass RLS
      and not (p.proname = any(keep_public))
      and (has_function_privilege('anon', p.oid, 'execute')
        or has_function_privilege('authenticated', p.oid, 'execute'))
  loop
    -- Trigger functions are included deliberately. PostgreSQL does not check
    -- EXECUTE on a trigger function when the trigger fires, so revoking here
    -- hardens them without breaking the triggers that call them.
    execute format('revoke all on function public.%I(%s) from public, anon, authenticated',
                   r.proname, r.args);
    execute format('grant execute on function public.%I(%s) to service_role',
                   r.proname, r.args);
    n_revoked := n_revoked + 1;
  end loop;
  raise notice 'revoked public EXECUTE on % SECURITY DEFINER function(s)', n_revoked;
end $$;

-- ── Table grants: second layer behind RLS ───────────────────────────────────
-- Most tables sit at "RLS on, 0 policies", which already denies anon everything.
-- But the GRANT is still there, so the day someone adds a permissive policy or
-- flips RLS off, the data is immediately public. Drop the grant too, but ONLY
-- where there are no policies — tables that intentionally serve anon through a
-- policy (positions, contact_messages, consent_logs, tracking_links,
-- assessment_templates …) need to keep theirs or the public flows break.
do $$
declare r record; n int := 0;
begin
  for r in
    select c.oid, c.relname
    from pg_class c
    join pg_namespace ns on ns.oid = c.relnamespace
    where ns.nspname = 'public'
      and c.relkind = 'r'
      and c.relrowsecurity
      and (select count(*) from pg_policies p
            where p.schemaname = 'public' and p.tablename = c.relname) = 0
      and (has_table_privilege('anon', c.oid, 'select')
        or has_table_privilege('authenticated', c.oid, 'select'))
  loop
    execute format('revoke all on table public.%I from anon, authenticated', r.relname);
    n := n + 1;
  end loop;
  raise notice 'revoked anon/authenticated grants on % zero-policy table(s)', n;
end $$;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0047_finance_math.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0047_finance_math.sql
-- Fixes the finance totals. Two independent bugs made Overview and Finance
-- disagree with each other and with reality.
--
-- BUG 1 — get_finance_summary never learned about `direction`.
--   It was written in 0004. 0015 then added invoices.direction ('income' |
--   'cost') so that supplier bills live in the same table as sales invoices.
--   The summary was never updated, so it did:
--       revenue     = sum(all paid invoices)      -> supplier bills counted AS INCOME
--       outstanding = sum(all sent/overdue)       -> money you OWE shown as money owed TO you
--       expenses    = sum(expenses table only)    -> cost invoices missed entirely
--   Net effect: revenue overstated, costs understated, and the same bill
--   inflating both sides. get_finance_analytics (0015) got this right, which is
--   why the dashboard and the finance page never matched.
--
-- BUG 2 — neither function excluded offers/quotes.
--   0016 added invoices.kind ('invoice' | 'offer'); offers share the table and
--   use statuses draft/sent/accepted/declined. Since `outstanding` matches
--   status in ('sent','overdue'), every quote you had merely SENT was being
--   counted as outstanding revenue. Both functions now require kind='invoice'.
--
-- Money only counts once here: revenue = paid income invoices; costs = the
-- expenses table PLUS paid cost invoices; nothing is summed from both sides.
--
-- Additive & idempotent — pure function redefinitions, no schema change.
-- ============================================================================

-- ── Summary (Finance overview cards) ────────────────────────────────────────
-- Keys revenue/outstanding/expenses/invoices are load-bearing for the UI
-- (lib/crm/data.ts loadFinance); net/payable are additive extras.
create or replace function get_finance_summary(p_privy text, p_workspace uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_revenue numeric; v_expenses numeric;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;

  select coalesce(sum(amount), 0) into v_revenue
    from invoices
   where workspace_id = p_workspace and status = 'paid'
     and direction = 'income' and kind = 'invoice';

  -- Costs come from two places and must not double-count: standalone expenses,
  -- plus invoices you received (direction='cost') that have been paid.
  select coalesce(sum(amount), 0) into v_expenses from (
    select amount from expenses
      where workspace_id = p_workspace and status in ('approved','paid')
    union all
    select amount from invoices
      where workspace_id = p_workspace and status = 'paid'
        and direction = 'cost' and kind = 'invoice'
  ) c;

  return jsonb_build_object(
    'revenue',     v_revenue,
    'expenses',    v_expenses,
    'net',         v_revenue - v_expenses,
    'outstanding', coalesce((select sum(amount) from invoices
                              where workspace_id = p_workspace
                                and status in ('sent','overdue')
                                and direction = 'income' and kind = 'invoice'), 0),
    'payable',     coalesce((select sum(amount) from invoices
                              where workspace_id = p_workspace
                                and status in ('sent','overdue')
                                and direction = 'cost' and kind = 'invoice'), 0),
    'invoices',    coalesce((select count(*) from invoices
                              where workspace_id = p_workspace and kind = 'invoice'), 0)
  );
end $$;

-- ── Analytics (dashboard chart + KPIs) ──────────────────────────────────────
-- Full redefinition of the 0015 version with kind='invoice' added to every
-- invoice predicate, so quotes stop inflating revenue and outstanding.
create or replace function get_finance_analytics(p_privy text, p_workspace uuid, p_months int default 12)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_months int := greatest(1, least(coalesce(p_months, 12), 36));
  v_start  date := (date_trunc('month', now()) - ((v_months - 1) || ' months')::interval)::date;
  v_series jsonb;
  v_revenue numeric;
  v_costs   numeric;
  v_outstanding numeric;
  v_payable numeric;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;

  with months as (
    select generate_series(date_trunc('month', v_start), date_trunc('month', now()), interval '1 month') as m
  ),
  rev as (
    select date_trunc('month', coalesce(issued_at, created_at::date)) as m, sum(amount) as total
    from invoices
    where workspace_id = p_workspace and status = 'paid'
      and direction = 'income' and kind = 'invoice'
      and coalesce(issued_at, created_at::date) >= v_start
    group by 1
  ),
  cost as (
    select m, sum(total) as total from (
      select date_trunc('month', coalesce(spent_at, created_at::date)) as m, sum(amount) as total
      from expenses
      where workspace_id = p_workspace and status in ('approved','paid')
        and coalesce(spent_at, created_at::date) >= v_start
      group by 1
      union all
      select date_trunc('month', coalesce(issued_at, created_at::date)) as m, sum(amount) as total
      from invoices
      where workspace_id = p_workspace and status = 'paid'
        and direction = 'cost' and kind = 'invoice'
        and coalesce(issued_at, created_at::date) >= v_start
      group by 1
    ) u group by m
  )
  select jsonb_agg(jsonb_build_object(
    'month',   to_char(months.m, 'YYYY-MM'),
    'label',   to_char(months.m, 'Mon'),
    'revenue', coalesce(rev.total, 0),
    'costs',   coalesce(cost.total, 0)
  ) order by months.m)
  into v_series
  from months
  left join rev  on rev.m  = months.m
  left join cost on cost.m = months.m;

  select coalesce(sum(amount), 0) into v_revenue from invoices
    where workspace_id = p_workspace and status = 'paid'
      and direction = 'income' and kind = 'invoice'
      and coalesce(issued_at, created_at::date) >= v_start;

  select coalesce(sum(amount), 0) into v_costs from (
    select amount from expenses
      where workspace_id = p_workspace and status in ('approved','paid')
        and coalesce(spent_at, created_at::date) >= v_start
    union all
    select amount from invoices
      where workspace_id = p_workspace and status = 'paid'
        and direction = 'cost' and kind = 'invoice'
        and coalesce(issued_at, created_at::date) >= v_start
  ) c;

  select coalesce(sum(amount), 0) into v_outstanding from invoices
    where workspace_id = p_workspace and status in ('sent','overdue')
      and direction = 'income' and kind = 'invoice';
  select coalesce(sum(amount), 0) into v_payable from invoices
    where workspace_id = p_workspace and status in ('sent','overdue')
      and direction = 'cost' and kind = 'invoice';

  return jsonb_build_object(
    'months',      v_months,
    'revenue',     v_revenue,
    'costs',       v_costs,
    'net',         v_revenue - v_costs,
    'outstanding', v_outstanding,
    'payable',     v_payable,
    'margin',      case when v_revenue > 0 then round(((v_revenue - v_costs) / v_revenue) * 100) else 0 end,
    'series',      coalesce(v_series, '[]'::jsonb)
  );
end $$;

-- Reachable only through the verified /api/rpc proxy (0040/0046 posture).
revoke all on function get_finance_summary(text, uuid)        from public, anon, authenticated;
revoke all on function get_finance_analytics(text, uuid, int) from public, anon, authenticated;
grant execute on function get_finance_summary(text, uuid)        to service_role;
grant execute on function get_finance_analytics(text, uuid, int) to service_role;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0048_team_invites.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0048_team_invites.sql
-- Gives team invites a real, unguessable token so accepting one proves you
-- were actually invited.
--
-- Before this, /api/team/claim matched a pending company_users row purely on
-- an email address supplied in the request body — with no auth on the endpoint
-- and no verification of the caller's identity. Anyone who guessed or knew an
-- invited address could POST {email, privyUserId} and bind their own Privy
-- account to that invite, joining the workspace with whatever role had been
-- assigned, up to and including owner. Email matching also failed whenever the
-- inviter typed a capital letter, since the row stored the address verbatim
-- while the claim lowercased it.
--
-- Now: the invite carries a random token, the accept link contains it, and the
-- claim looks the invite up BY TOKEN with a verified Privy session. The token
-- is single-use — cleared the moment it is redeemed.
--
-- Additive & idempotent. Existing pending invites have no token, so they can no
-- longer be claimed and should simply be re-sent.
-- ============================================================================

alter table company_users add column if not exists invite_token uuid;
alter table company_users add column if not exists invited_at   timestamptz;
alter table company_users add column if not exists invited_by    text;

-- Partial unique index: only unredeemed invites hold a token, and each is unique.
create unique index if not exists idx_company_users_invite_token
  on company_users (invite_token)
  where invite_token is not null;

-- Look up a pending invite by its token, for the accept screen. Returns only
-- what the page needs to render "You've been invited to <company> as <role>" —
-- deliberately no email or member list. The token IS the secret, so this stays
-- callable without a session; without a valid token it returns null.
create or replace function get_invite_by_token(p_token uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v jsonb;
begin
  if p_token is null then return null; end if;
  select jsonb_build_object(
    'company_name', c.name,
    'role',         cu.role,
    'full_name',    cu.full_name,
    'email',        cu.email
  ) into v
  from company_users cu
  join companies c on c.id = cu.company_id
  where cu.invite_token = p_token
    and cu.privy_user_id is null;          -- already redeemed => not an invite
  return v;   -- null when the token is unknown or spent
end $$;
revoke all on function get_invite_by_token(uuid) from public, anon, authenticated;
grant execute on function get_invite_by_token(uuid) to service_role;

-- Redeem an invite. p_privy comes from a verified Privy token in the route, so
-- the caller cannot claim on someone else's behalf. Single-use: the token is
-- cleared, and a second attempt finds nothing.
create or replace function redeem_invite(p_token uuid, p_privy text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_id uuid; v_company uuid; v_role text; v_name text;
begin
  if p_token is null or coalesce(trim(p_privy),'') = '' then
    return jsonb_build_object('ok', false, 'reason', 'missing_token');
  end if;

  select cu.id, cu.company_id, cu.role into v_id, v_company, v_role
  from company_users cu
  where cu.invite_token = p_token and cu.privy_user_id is null
  for update;

  if v_id is null then
    return jsonb_build_object('ok', false, 'reason', 'invalid_or_used');
  end if;

  -- Someone already in this company should not gain a second membership row.
  if exists (select 1 from company_users
              where company_id = v_company and privy_user_id = p_privy) then
    -- Burn the invite anyway so the link cannot be reused.
    update company_users set invite_token = null where id = v_id;
    return jsonb_build_object('ok', true, 'already_member', true);
  end if;

  update company_users
     set privy_user_id = p_privy,
         invite_token  = null          -- single use
   where id = v_id;

  select name into v_name from companies where id = v_company;
  return jsonb_build_object('ok', true, 'company_id', v_company,
                            'company_name', v_name, 'role', v_role);
end $$;
revoke all on function redeem_invite(uuid, text) from public, anon, authenticated;
grant execute on function redeem_invite(uuid, text) to service_role;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0049_remove_members.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0049_remove_members.sql
-- Adds member removal, and makes pending invites visible so they can be revoked.
--
-- Two gaps this closes:
--
--  1. get_members read only from `accounts`. The 0005 trigger copies a
--     company_users row into accounts ONLY when privy_user_id is set, and an
--     invite starts life with that null — so an invited-but-not-yet-joined
--     person appeared nowhere in the UI. You could not see who you had invited,
--     let alone cancel it. Pending invites are now returned alongside members
--     with pending=true.
--
--  2. There was no removal RPC at all. The legacy /dashboard/team page deleted
--     straight from company_users with the browser's key, which is exactly the
--     direct-table access 0040–0046 spent their time closing, and it only
--     touched company_users — leaving the `accounts` row behind, so the person
--     kept workspace access.
--
-- remove_member deletes BOTH rows. Membership lives in two tables (accounts for
-- the workspace, company_users for the legacy ATS side, sharing one id), and
-- removing only one leaves the person with half their access — HR data in
-- particular resolves through company_users.
--
-- Guards: owner/admin only; nobody can remove themselves (use a second admin,
-- so a workspace cannot be orphaned by accident); only an owner can remove
-- another owner; the last owner can never be removed.
--
-- Additive & idempotent. Depends on 0012 (workspace_role) and 0048.
-- ============================================================================

-- ── Members list now includes pending invites ───────────────────────────────
create or replace function get_members(p_privy text, p_workspace uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((
    select jsonb_agg(r order by sort, created_at)
    from (
      -- joined members
      select jsonb_build_object(
               'id', a.id,
               'name', coalesce(nullif(a.full_name,''), a.email),
               'email', a.email,
               'role', a.role,
               'privy_user_id', a.privy_user_id,
               'pending', false
             ) as r,
             case a.role when 'owner' then 0 when 'admin' then 1 else 2 end as sort,
             a.created_at
      from accounts a
      where a.workspace_id = p_workspace

      union all

      -- invited, not yet accepted (never reaches `accounts` until redeemed)
      select jsonb_build_object(
               'id', cu.id,
               'name', coalesce(nullif(cu.full_name,''), cu.email),
               'email', cu.email,
               'role', cu.role,
               'privy_user_id', null,
               'pending', true,
               'invited_at', cu.invited_at
             ) as r,
             3 as sort,
             cu.created_at
      from company_users cu
      where cu.company_id = p_workspace and cu.privy_user_id is null
    ) s
  ), '[]'::jsonb);
end $$;

-- ── Remove a member, or revoke a pending invite ─────────────────────────────
create or replace function remove_member(p_privy text, p_workspace uuid, p_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  my_role      text;
  v_privy      text;
  v_role       text;
  v_is_member  boolean;
  v_n          int;
begin
  my_role := workspace_role(p_privy, p_workspace);
  if my_role is null or my_role not in ('owner','admin') then
    raise exception 'FORBIDDEN';
  end if;

  -- p_id may be an accounts.id (the CRM members screen) or a company_users.id
  -- (the legacy HR team screen). Resolve either to the same person rather than
  -- forcing both callers onto one table's ids.
  select a.privy_user_id, a.role, true
    into v_privy, v_role, v_is_member
  from accounts a
  where a.id = p_id and a.workspace_id = p_workspace;

  if not coalesce(v_is_member, false) then
    select cu.privy_user_id, cu.role, cu.privy_user_id is not null
      into v_privy, v_role, v_is_member
    from company_users cu
    where cu.id = p_id and cu.company_id = p_workspace;
  end if;

  if coalesce(v_is_member, false) then
    -- Removing yourself is blocked: an admin who does it by accident locks the
    -- workspace's own team screen away from them. Have another admin do it.
    if v_privy = p_privy then raise exception 'CANNOT_REMOVE_SELF'; end if;

    if v_role = 'owner' then
      if my_role <> 'owner' then raise exception 'ONLY_OWNER_CAN_REMOVE_OWNER'; end if;
      if (select count(*) from accounts
           where workspace_id = p_workspace and role = 'owner') <= 1 then
        raise exception 'CANNOT_REMOVE_LAST_OWNER';
      end if;
    end if;

    -- Delete by privy id, not by p_id, so both halves go regardless of which
    -- table the caller identified them from.
    delete from accounts
     where workspace_id = p_workspace and privy_user_id = v_privy;
    -- The legacy half. Without this they keep HR/ATS access, which resolves
    -- through company_users rather than accounts.
    delete from company_users
     where company_id = p_workspace and privy_user_id = v_privy;

    return jsonb_build_object('ok', true, 'kind', 'member');
  end if;

  -- Otherwise: a pending invite, identified by its company_users id.
  delete from company_users
   where id = p_id and company_id = p_workspace and privy_user_id is null;
  get diagnostics v_n = row_count;
  if v_n > 0 then
    return jsonb_build_object('ok', true, 'kind', 'invite');
  end if;

  return jsonb_build_object('ok', false, 'reason', 'not_found');
end $$;

-- ── Grants (0046 posture: reachable only through the verified proxy) ────────
revoke all on function get_members(text, uuid)           from public, anon, authenticated;
revoke all on function remove_member(text, uuid, uuid)   from public, anon, authenticated;
grant execute on function get_members(text, uuid)         to service_role;
grant execute on function remove_member(text, uuid, uuid) to service_role;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0050_unify_roles.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0050_unify_roles.sql
-- Reconciles the two role vocabularies that had drifted apart.
--
-- company_users (the ATS side, from the base schema) allowed:
--     owner | admin | recruiter | viewer
-- accounts / set_member_role (the workspace side, 0012) allowed:
--     owner | admin | member
--
-- Nothing translated between them. The 0005 sync trigger copies the role
-- verbatim, so a 'recruiter' became a 'recruiter' in accounts even though
-- set_member_role would refuse to set that value — and inviting someone as
-- 'member' failed outright with
--     violates check constraint "company_users_role_check"
-- because the ATS table had never heard of 'member'.
--
-- Rather than translate in both directions forever, both sides now accept the
-- union. Existing rows stay valid (it is a widening), the trigger's verbatim
-- copy becomes correct by construction, and either screen can manage anyone.
--
--   owner     — full control, including billing
--   admin     — manage members, settings and all records
--   member    — general access (the workspace default)
--   recruiter — ATS-focused member; kept for existing HR teams
--   viewer    — read-only
--
-- Additive & idempotent.
-- ============================================================================

do $$
begin
  alter table company_users drop constraint if exists company_users_role_check;
  alter table company_users add constraint company_users_role_check
    check (role in ('owner','admin','member','recruiter','viewer'));
exception when others then
  raise notice 'company_users role check not updated: %', sqlerrm;
end $$;

-- accounts has no check constraint, but keep the default sane for new rows.
alter table accounts alter column role set default 'member';

-- set_member_role must accept the same set, or a recruiter/viewer could be
-- listed but never re-assigned.
create or replace function set_member_role(p_privy text, p_workspace uuid, p_account uuid, p_role text)
returns void language plpgsql security definer set search_path = public as $$
declare my_role text;
begin
  if p_role not in ('owner','admin','member','recruiter','viewer') then
    raise exception 'INVALID_ROLE';
  end if;
  my_role := workspace_role(p_privy, p_workspace);
  if my_role is null or my_role not in ('owner', 'admin') then raise exception 'FORBIDDEN'; end if;
  if p_role = 'owner' and my_role <> 'owner' then raise exception 'ONLY_OWNER_CAN_GRANT_OWNER'; end if;
  -- never demote the last remaining owner
  if exists (select 1 from accounts where id = p_account and workspace_id = p_workspace and role = 'owner')
     and p_role <> 'owner'
     and (select count(*) from accounts where workspace_id = p_workspace and role = 'owner') <= 1 then
    raise exception 'CANNOT_REMOVE_LAST_OWNER';
  end if;

  update accounts set role = p_role where id = p_account and workspace_id = p_workspace;

  -- Keep the ATS half in step, otherwise HR permissions silently diverge from
  -- what the members screen shows.
  update company_users cu
     set role = p_role
    from accounts a
   where a.id = p_account and a.workspace_id = p_workspace
     and cu.company_id = p_workspace and cu.privy_user_id = a.privy_user_id;
end $$;
revoke all on function set_member_role(text, uuid, uuid, text) from public, anon, authenticated;
grant execute on function set_member_role(text, uuid, uuid, text) to service_role;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0051_active_workspace.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0051_active_workspace.sql
-- Gives a person an *active* workspace, so belonging to more than one stops
-- being ambiguous.
--
-- The two resolvers disagreed. get_my_workspace (0012) took
--     order by a.created_at limit 1     -> always your OLDEST workspace
-- while hr_company_id (0041) took
--     limit 1                           -> no ORDER BY, so genuinely arbitrary
--
-- Accept an invite while already owning a workspace and you kept landing back
-- in your original one; worse, the CRM could resolve to workspace A in the same
-- session that HR resolved to workspace B, because nothing tied the two
-- together. Data looked wrong long before anyone suspected why.
--
-- Both now read one stored choice, falling back to the oldest membership (and
-- self-healing if the stored workspace is one you have since left).
--
-- Additive & idempotent.
-- ============================================================================

create table if not exists user_settings (
  privy_user_id    text primary key,
  active_workspace uuid references workspaces(id) on delete set null,
  updated_at       timestamptz default now()
);
alter table user_settings enable row level security;   -- definer RPCs only
revoke all on table user_settings from anon, authenticated;

-- ── Which workspaces can I see? (drives the switcher) ───────────────────────
create or replace function list_my_workspaces(p_privy text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_active uuid;
begin
  select active_workspace into v_active from user_settings where privy_user_id = p_privy;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', ws.id, 'name', ws.name, 'slug', ws.slug, 'plan', ws.plan,
      'role', a.role, 'active', (ws.id = v_active)
    ) order by a.created_at)
    from accounts a join workspaces ws on ws.id = a.workspace_id
    where a.privy_user_id = p_privy
  ), '[]'::jsonb);
end $$;

-- ── Switch ──────────────────────────────────────────────────────────────────
create or replace function set_active_workspace(p_privy text, p_workspace uuid)
returns boolean language plpgsql security definer set search_path = public as $$
begin
  -- You can only make active a workspace you actually belong to.
  if not exists (select 1 from accounts
                  where privy_user_id = p_privy and workspace_id = p_workspace) then
    return false;
  end if;
  insert into user_settings (privy_user_id, active_workspace, updated_at)
  values (p_privy, p_workspace, now())
  on conflict (privy_user_id)
    do update set active_workspace = excluded.active_workspace, updated_at = now();
  return true;
end $$;

-- ── Single source of truth for "which workspace am I in" ────────────────────
-- Stored choice when it is still a live membership, else the oldest. Used by
-- both resolvers below so they can never disagree again.
create or replace function effective_workspace(p_privy text)
returns uuid language sql stable security definer set search_path = public as $$
  select coalesce(
    (select us.active_workspace
       from user_settings us
       join accounts a on a.privy_user_id = us.privy_user_id
                      and a.workspace_id = us.active_workspace
      where us.privy_user_id = p_privy),
    (select a.workspace_id from accounts a
      where a.privy_user_id = p_privy
      order by a.created_at limit 1)
  );
$$;

create or replace function get_my_workspace(p_privy text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare rec record; v_ws uuid;
begin
  v_ws := effective_workspace(p_privy);
  if v_ws is null then return null; end if;
  select ws.id, ws.name, ws.slug, ws.plan, a.role into rec
  from accounts a join workspaces ws on ws.id = a.workspace_id
  where a.privy_user_id = p_privy and ws.id = v_ws;
  if rec.id is null then return null; end if;
  return jsonb_build_object('id', rec.id, 'name', rec.name, 'slug', rec.slug,
                            'plan', rec.plan, 'role', rec.role);
end $$;

-- The ATS half. workspace_id and company_id are the same uuid (see the 0005
-- sync trigger), so the same choice applies. Falls back to the oldest
-- membership — deterministically, unlike the bare `limit 1` it replaces.
create or replace function hr_company_id(p_privy text)
returns uuid language sql stable security definer set search_path = public as $$
  select coalesce(
    (select cu.company_id from company_users cu
      where cu.privy_user_id = p_privy
        and cu.company_id = effective_workspace(p_privy)),
    (select cu.company_id from company_users cu
      where cu.privy_user_id = p_privy
      order by cu.created_at limit 1)
  );
$$;

-- ── Accepting an invite should land you in the workspace you just joined ────
create or replace function redeem_invite(p_token uuid, p_privy text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_id uuid; v_company uuid; v_role text; v_name text;
begin
  if p_token is null or coalesce(trim(p_privy),'') = '' then
    return jsonb_build_object('ok', false, 'reason', 'missing_token');
  end if;

  select cu.id, cu.company_id, cu.role into v_id, v_company, v_role
  from company_users cu
  where cu.invite_token = p_token and cu.privy_user_id is null
  for update;

  if v_id is null then
    return jsonb_build_object('ok', false, 'reason', 'invalid_or_used');
  end if;

  if exists (select 1 from company_users
              where company_id = v_company and privy_user_id = p_privy) then
    update company_users set invite_token = null where id = v_id;
    perform set_active_workspace(p_privy, v_company);   -- take them there anyway
    return jsonb_build_object('ok', true, 'already_member', true);
  end if;

  update company_users
     set privy_user_id = p_privy, invite_token = null
   where id = v_id;

  -- Make the newly joined workspace active, so someone who already had their
  -- own does not get dropped back into it and wonder where the invite went.
  perform set_active_workspace(p_privy, v_company);

  select name into v_name from companies where id = v_company;
  return jsonb_build_object('ok', true, 'company_id', v_company,
                            'company_name', v_name, 'role', v_role);
end $$;

-- ── Grants (0046 posture) ───────────────────────────────────────────────────
revoke all on function list_my_workspaces(text)          from public, anon, authenticated;
revoke all on function set_active_workspace(text, uuid)  from public, anon, authenticated;
revoke all on function effective_workspace(text)         from public, anon, authenticated;
revoke all on function get_my_workspace(text)            from public, anon, authenticated;
revoke all on function hr_company_id(text)               from public, anon, authenticated;
revoke all on function redeem_invite(uuid, text)         from public, anon, authenticated;
grant execute on function list_my_workspaces(text)         to service_role;
grant execute on function set_active_workspace(text, uuid) to service_role;
grant execute on function get_my_workspace(text)           to service_role;
grant execute on function redeem_invite(uuid, text)        to service_role;
-- effective_workspace / hr_company_id are internal helpers: no role needs
-- EXECUTE, the DEFINER functions that call them run as the owner.

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0052_report_schedules.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0052_report_schedules.sql
-- Scheduled PDF reports: pick a cadence, a time, recipients and which sections.
--
-- The section list is stored as plain text ids matching lib/reports/registry.ts.
-- Deliberately not a foreign key or an enum: the whole point is that adding a
-- report section later means appending one registry entry in code, with no
-- migration. Unknown ids are skipped at render time rather than rejected here,
-- so a schedule keeps working if a section is renamed or retired.
--
-- Times are stored as a plain hour plus an IANA timezone rather than a
-- timestamp, because "every Monday at 08:00 in Europe/Warsaw" has to survive
-- daylight saving. due_report_schedules() resolves that at dispatch time.
--
-- Additive & idempotent. Depends on 0051 (workspaces/accounts).
-- ============================================================================

create table if not exists report_schedules (
  id           uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspaces(id) on delete cascade,
  name         text not null default 'Business report',
  frequency    text not null default 'weekly' check (frequency in ('weekly','monthly')),
  day_of_week  int  not null default 1 check (day_of_week between 0 and 6),   -- 0=Sun, weekly only
  day_of_month int  not null default 1 check (day_of_month between 1 and 28), -- monthly only; 28 keeps every month valid
  hour         int  not null default 8 check (hour between 0 and 23),
  timezone     text not null default 'UTC',
  recipients   text[] not null default '{}',
  sections     text[] not null default '{}',
  enabled      boolean not null default true,
  last_sent_at timestamptz,
  created_by   text,
  created_at   timestamptz default now(),
  updated_at   timestamptz default now()
);
create index if not exists idx_report_schedules_ws on report_schedules(workspace_id);
alter table report_schedules enable row level security;
revoke all on table report_schedules from anon, authenticated;

-- ── Read / write, workspace-scoped ──────────────────────────────────────────
create or replace function get_report_schedules(p_privy text, p_workspace uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
    'id', r.id, 'name', r.name, 'frequency', r.frequency,
    'day_of_week', r.day_of_week, 'day_of_month', r.day_of_month,
    'hour', r.hour, 'timezone', r.timezone,
    'recipients', r.recipients, 'sections', r.sections,
    'enabled', r.enabled, 'last_sent_at', r.last_sent_at
  ) order by r.created_at) from report_schedules r where r.workspace_id = p_workspace), '[]'::jsonb);
end $$;

create or replace function save_report_schedule(
  p_privy text, p_workspace uuid, p_id uuid, p_name text, p_frequency text,
  p_day_of_week int, p_day_of_month int, p_hour int, p_timezone text,
  p_recipients text[], p_sections text[], p_enabled boolean
) returns uuid language plpgsql security definer set search_path = public as $$
declare v_role text; v_id uuid;
begin
  v_role := workspace_role(p_privy, p_workspace);
  if v_role is null or v_role not in ('owner','admin') then raise exception 'FORBIDDEN'; end if;
  if p_frequency not in ('weekly','monthly') then raise exception 'INVALID_FREQUENCY'; end if;
  if coalesce(array_length(p_recipients, 1), 0) = 0 then raise exception 'NO_RECIPIENTS'; end if;
  if coalesce(array_length(p_sections, 1), 0) = 0 then raise exception 'NO_SECTIONS'; end if;

  if p_id is null then
    insert into report_schedules (workspace_id, name, frequency, day_of_week, day_of_month,
                                  hour, timezone, recipients, sections, enabled, created_by)
    values (p_workspace, coalesce(nullif(p_name,''),'Business report'), p_frequency,
            coalesce(p_day_of_week,1), coalesce(p_day_of_month,1), coalesce(p_hour,8),
            coalesce(nullif(p_timezone,''),'UTC'), p_recipients, p_sections,
            coalesce(p_enabled, true), p_privy)
    returning id into v_id;
  else
    update report_schedules set
      name = coalesce(nullif(p_name,''),'Business report'), frequency = p_frequency,
      day_of_week = coalesce(p_day_of_week,1), day_of_month = coalesce(p_day_of_month,1),
      hour = coalesce(p_hour,8), timezone = coalesce(nullif(p_timezone,''),'UTC'),
      recipients = p_recipients, sections = p_sections,
      enabled = coalesce(p_enabled, true), updated_at = now()
    where id = p_id and workspace_id = p_workspace
    returning id into v_id;
    if v_id is null then raise exception 'NOT_FOUND'; end if;
  end if;
  return v_id;
end $$;

create or replace function delete_report_schedule(p_privy text, p_workspace uuid, p_id uuid)
returns boolean language plpgsql security definer set search_path = public as $$
declare v_role text; v_n int;
begin
  v_role := workspace_role(p_privy, p_workspace);
  if v_role is null or v_role not in ('owner','admin') then raise exception 'FORBIDDEN'; end if;
  delete from report_schedules where id = p_id and workspace_id = p_workspace;
  get diagnostics v_n = row_count;
  return v_n > 0;
end $$;

-- ── Dispatcher support ──────────────────────────────────────────────────────
-- Which schedules are due right now, in their own timezone? A schedule fires
-- when local time has reached its hour on the right day and it has not already
-- gone out this period — so a cron ticking every 15 minutes, or one that missed
-- a few beats, still sends exactly once.
create or replace function due_report_schedules()
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', r.id, 'workspace_id', r.workspace_id, 'workspace_name', w.name,
      'name', r.name, 'frequency', r.frequency, 'sections', r.sections,
      'recipients', r.recipients,
      -- any member's DID: the report RPCs resolve tenancy from it
      'privy', (select a.privy_user_id from accounts a
                 where a.workspace_id = r.workspace_id
                 order by case a.role when 'owner' then 0 when 'admin' then 1 else 2 end
                 limit 1)
    ))
    from report_schedules r
    join workspaces w on w.id = r.workspace_id
    where r.enabled
      and extract(hour from (now() at time zone r.timezone)) >= r.hour
      and (
        (r.frequency = 'weekly'
          and extract(dow from (now() at time zone r.timezone)) = r.day_of_week
          and (r.last_sent_at is null or r.last_sent_at < now() - interval '6 days'))
        or
        (r.frequency = 'monthly'
          and extract(day from (now() at time zone r.timezone)) = r.day_of_month
          and (r.last_sent_at is null or r.last_sent_at < now() - interval '27 days'))
      )
  ), '[]'::jsonb);
end $$;

create or replace function mark_report_sent(p_id uuid)
returns void language sql security definer set search_path = public as $$
  update report_schedules set last_sent_at = now() where id = p_id;
$$;

-- ── Grants (0046 posture) ───────────────────────────────────────────────────
revoke all on function get_report_schedules(text, uuid)                                            from public, anon, authenticated;
revoke all on function save_report_schedule(text, uuid, uuid, text, text, int, int, int, text, text[], text[], boolean) from public, anon, authenticated;
revoke all on function delete_report_schedule(text, uuid, uuid)                                    from public, anon, authenticated;
revoke all on function due_report_schedules()                                                      from public, anon, authenticated;
revoke all on function mark_report_sent(uuid)                                                      from public, anon, authenticated;
grant execute on function get_report_schedules(text, uuid)                                            to service_role;
grant execute on function save_report_schedule(text, uuid, uuid, text, text, int, int, int, text, text[], text[], boolean) to service_role;
grant execute on function delete_report_schedule(text, uuid, uuid)                                    to service_role;
grant execute on function due_report_schedules()                                                      to service_role;
grant execute on function mark_report_sent(uuid)                                                      to service_role;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0053_sign.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0053_sign.sql
-- Lightweight e-signature ("DocSign"). Send a PDF to one or more people, each
-- signs via a single-use tokenised link, and once everyone has signed we stamp
-- a signature certificate onto the document and email the signed copy back.
--
-- Deliberately NOT a clone of Documenso / DocuSeal (both AGPL — incompatible
-- with this MIT repo). The PDF work uses pdf-lib (MIT) server-side and the
-- signature canvas uses signature_pad (MIT); everything else reuses primitives
-- we already have (private storage, Resend, tokenised public pages).
--
-- Not eIDAS "qualified" signatures — it is an advanced e-signature: identity by
-- emailed link, intent captured explicitly, plus an audit trail (who / when /
-- from what IP) and a SHA-256 of the final document for tamper evidence.
--
-- All RPCs SECURITY DEFINER + service_role-only (0046 posture). Recipient-facing
-- ones are gated by an unguessable token, not a session. Depends on 0012.
-- ============================================================================

create table if not exists sign_documents (
  id           uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspaces(id) on delete cascade,
  title        text not null default 'Document',
  storage_path text not null,                 -- original PDF, private 'documents' bucket
  signed_path  text,                          -- final stamped PDF once complete
  signed_hash  text,                          -- sha256 of the signed PDF (tamper evidence)
  status       text not null default 'sent' check (status in ('draft','sent','signed','declined','voided')),
  source_kind  text default 'upload',         -- upload | invoice | offer (future linking)
  source_id    uuid,
  created_by   text,
  created_at   timestamptz default now(),
  updated_at   timestamptz default now(),
  completed_at timestamptz
);
create index if not exists idx_sign_documents_ws on sign_documents(workspace_id);
alter table sign_documents enable row level security;
revoke all on table sign_documents from anon, authenticated;

create table if not exists sign_recipients (
  id             uuid primary key default gen_random_uuid(),
  document_id    uuid not null references sign_documents(id) on delete cascade,
  name           text not null,
  email          text not null,
  sign_token     uuid not null default gen_random_uuid(),
  status         text not null default 'pending' check (status in ('pending','signed','declined')),
  signature_type text,                         -- drawn | typed
  signature_data text,                         -- PNG data URL (drawn) or the typed name
  signed_at      timestamptz,
  ip             text,
  user_agent     text,
  sort           int default 0
);
create unique index if not exists idx_sign_recipients_token on sign_recipients(sign_token);
create index if not exists idx_sign_recipients_doc on sign_recipients(document_id);
alter table sign_recipients enable row level security;
revoke all on table sign_recipients from anon, authenticated;

-- ── Recruiter/owner side (workspace-scoped) ─────────────────────────────────
create or replace function get_sign_documents(p_privy text, p_workspace uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
    'id', d.id, 'title', d.title, 'status', d.status,
    'created_at', d.created_at, 'completed_at', d.completed_at,
    'signed', (select count(*) from sign_recipients r where r.document_id = d.id and r.status = 'signed'),
    'total', (select count(*) from sign_recipients r where r.document_id = d.id),
    'recipients', coalesce((select jsonb_agg(jsonb_build_object('name', r.name, 'email', r.email, 'status', r.status) order by r.sort)
                            from sign_recipients r where r.document_id = d.id), '[]'::jsonb)
  ) order by d.created_at desc) from sign_documents d where d.workspace_id = p_workspace), '[]'::jsonb);
end $$;

create or replace function create_sign_document(
  p_privy text, p_workspace uuid, p_title text, p_storage_path text,
  p_source_kind text, p_source_id uuid, p_recipients jsonb
) returns jsonb language plpgsql security definer set search_path = public as $$
declare v_role text; v_id uuid; v_rec jsonb; i int := 0; v_out jsonb := '[]'::jsonb; v_token uuid;
begin
  v_role := workspace_role(p_privy, p_workspace);
  if v_role is null or v_role not in ('owner','admin','member','recruiter') then raise exception 'FORBIDDEN'; end if;
  if coalesce(p_storage_path,'') = '' then raise exception 'NO_DOCUMENT'; end if;
  if jsonb_typeof(p_recipients) <> 'array' or jsonb_array_length(p_recipients) = 0 then raise exception 'NO_RECIPIENTS'; end if;

  insert into sign_documents (workspace_id, title, storage_path, source_kind, source_id, created_by, status)
  values (p_workspace, coalesce(nullif(p_title,''),'Document'), p_storage_path,
          coalesce(nullif(p_source_kind,''),'upload'), p_source_id, p_privy, 'sent')
  returning id into v_id;

  for v_rec in select * from jsonb_array_elements(p_recipients) loop
    if coalesce(v_rec->>'email','') = '' then continue; end if;
    v_token := gen_random_uuid();
    insert into sign_recipients (document_id, name, email, sign_token, sort)
    values (v_id, coalesce(nullif(v_rec->>'name',''), v_rec->>'email'),
            lower(trim(v_rec->>'email')), v_token, i);
    v_out := v_out || jsonb_build_object(
      'name', coalesce(nullif(v_rec->>'name',''), v_rec->>'email'),
      'email', lower(trim(v_rec->>'email')), 'token', v_token);
    i := i + 1;
  end loop;

  return jsonb_build_object('id', v_id, 'recipients', v_out);
end $$;

create or replace function void_sign_document(p_privy text, p_workspace uuid, p_id uuid)
returns boolean language plpgsql security definer set search_path = public as $$
declare v_role text; v_n int;
begin
  v_role := workspace_role(p_privy, p_workspace);
  if v_role is null or v_role not in ('owner','admin','member','recruiter') then raise exception 'FORBIDDEN'; end if;
  update sign_documents set status = 'voided', updated_at = now()
   where id = p_id and workspace_id = p_workspace and status <> 'signed';
  get diagnostics v_n = row_count;
  return v_n > 0;
end $$;

-- Paths for the authenticated download route.
create or replace function get_sign_document_file(p_privy text, p_workspace uuid, p_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v jsonb;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  select jsonb_build_object('title', d.title, 'status', d.status,
           'storage_path', d.storage_path, 'signed_path', d.signed_path)
    into v from sign_documents d where d.id = p_id and d.workspace_id = p_workspace;
  return v;
end $$;

-- ── Signer side (token-gated, no session) ───────────────────────────────────
create or replace function get_sign_request(p_token uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v jsonb;
begin
  if p_token is null then return null; end if;
  select jsonb_build_object(
    'document_id', d.id, 'title', d.title, 'storage_path', d.storage_path,
    'doc_status', d.status, 'signer_name', r.name, 'signer_email', r.email,
    'already_signed', (r.status = 'signed')
  ) into v
  from sign_recipients r join sign_documents d on d.id = r.document_id
  where r.sign_token = p_token;
  return v;  -- null for an unknown token
end $$;

-- Records one signature. When it completes the document, returns everything the
-- route needs to build the certificate page + notify everyone.
create or replace function record_signature(
  p_token uuid, p_type text, p_data text, p_ip text, p_ua text
) returns jsonb language plpgsql security definer set search_path = public as $$
declare v_doc uuid; v_status text; v_rid uuid; v_pending int;
begin
  select r.id, r.document_id, d.status into v_rid, v_doc, v_status
  from sign_recipients r join sign_documents d on d.id = r.document_id
  where r.sign_token = p_token and r.status = 'pending'
  for update;

  if v_rid is null then return jsonb_build_object('ok', false, 'reason', 'invalid_or_signed'); end if;
  if v_status in ('voided','declined') then return jsonb_build_object('ok', false, 'reason', 'no_longer_active'); end if;

  update sign_recipients
     set status = 'signed', signature_type = nullif(p_type,''), signature_data = p_data,
         signed_at = now(), ip = nullif(p_ip,''), user_agent = left(coalesce(p_ua,''), 400)
   where id = v_rid;

  select count(*) into v_pending from sign_recipients where document_id = v_doc and status = 'pending';

  if v_pending > 0 then
    return jsonb_build_object('ok', true, 'complete', false);
  end if;

  -- Everyone has signed: hand the route the full signature set + the original.
  return jsonb_build_object(
    'ok', true, 'complete', true, 'document_id', v_doc,
    'title', (select title from sign_documents where id = v_doc),
    'storage_path', (select storage_path from sign_documents where id = v_doc),
    'signers', (select jsonb_agg(jsonb_build_object(
        'name', name, 'email', email, 'type', signature_type,
        'data', signature_data, 'signed_at', signed_at, 'ip', ip) order by sort)
      from sign_recipients where document_id = v_doc)
  );
end $$;

-- Called by the route after it builds + stores the stamped PDF.
create or replace function finalize_sign_document(p_document_id uuid, p_signed_path text, p_signed_hash text)
returns void language sql security definer set search_path = public as $$
  update sign_documents
     set status = 'signed', signed_path = p_signed_path, signed_hash = p_signed_hash,
         completed_at = now(), updated_at = now()
   where id = p_document_id;
$$;

-- ── Grants (0046 posture) ───────────────────────────────────────────────────
revoke all on function get_sign_documents(text, uuid)                                   from public, anon, authenticated;
revoke all on function create_sign_document(text, uuid, text, text, text, uuid, jsonb)  from public, anon, authenticated;
revoke all on function void_sign_document(text, uuid, uuid)                             from public, anon, authenticated;
revoke all on function get_sign_document_file(text, uuid, uuid)                         from public, anon, authenticated;
revoke all on function get_sign_request(uuid)                                           from public, anon, authenticated;
revoke all on function record_signature(uuid, text, text, text, text)                   from public, anon, authenticated;
revoke all on function finalize_sign_document(uuid, text, text)                         from public, anon, authenticated;
grant execute on function get_sign_documents(text, uuid)                                   to service_role;
grant execute on function create_sign_document(text, uuid, text, text, text, uuid, jsonb)  to service_role;
grant execute on function void_sign_document(text, uuid, uuid)                             to service_role;
grant execute on function get_sign_document_file(text, uuid, uuid)                         to service_role;
grant execute on function get_sign_request(uuid)                                           to service_role;
grant execute on function record_signature(uuid, text, text, text, text)                   to service_role;
grant execute on function finalize_sign_document(uuid, text, text)                         to service_role;

