-- ══════════════════════════════════════════════════════════════════════════
-- 0054_forms.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0054_forms.sql
-- Custom Forms: a public form builder whose submissions land as CRM People
-- (leads). Generalises the existing public apply flow — same pattern (an anon
-- SECURITY DEFINER RPC writing one row it fully controls), now for arbitrary
-- lead-capture forms rather than only job applications.
--
-- A form's fields are a jsonb array of { key, label, type, required, options?,
-- map? }. `map` names a people column the field feeds (first_name, last_name,
-- email, phone, title, linkedin_url); unmapped answers go into people.custom_fields
-- and the raw submission. Adding a field type later is a UI concern — the schema
-- stores whatever the builder produces.
--
-- Workspace RPCs are SECURITY DEFINER + service_role-only (0046 posture). The
-- two public ones (get_public_form, submit_form) are anon-callable by design,
-- exactly like apply_to_position — they touch only their own rows.
-- Depends on 0001 (people) + 0012 (workspace_role).
-- ============================================================================

create table if not exists forms (
  id            uuid primary key default gen_random_uuid(),
  workspace_id  uuid not null references workspaces(id) on delete cascade,
  slug          text not null unique,             -- public id in /f/<slug>
  name          text not null default 'Untitled form',
  title         text not null default 'Get in touch',
  description   text,
  fields        jsonb not null default '[]',
  submit_message text not null default 'Thanks — we''ll be in touch.',
  enabled       boolean not null default true,
  created_by    text,
  created_at    timestamptz default now(),
  updated_at    timestamptz default now()
);
create index if not exists idx_forms_ws on forms(workspace_id);
alter table forms enable row level security;
revoke all on table forms from anon, authenticated;

create table if not exists form_submissions (
  id           uuid primary key default gen_random_uuid(),
  form_id      uuid not null references forms(id) on delete cascade,
  workspace_id uuid not null references workspaces(id) on delete cascade,
  data         jsonb not null default '{}',
  person_id    uuid,                               -- the lead created from it
  ip           text,
  created_at   timestamptz default now()
);
create index if not exists idx_form_submissions_form on form_submissions(form_id);
alter table form_submissions enable row level security;
revoke all on table form_submissions from anon, authenticated;

-- ── Owner side (workspace-scoped) ───────────────────────────────────────────
create or replace function get_forms(p_privy text, p_workspace uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
    'id', f.id, 'slug', f.slug, 'name', f.name, 'title', f.title,
    'enabled', f.enabled, 'fields', f.fields, 'created_at', f.created_at,
    'submissions', (select count(*) from form_submissions s where s.form_id = f.id)
  ) order by f.created_at desc) from forms f where f.workspace_id = p_workspace), '[]'::jsonb);
end $$;

create or replace function get_form(p_privy text, p_workspace uuid, p_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v jsonb;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  select jsonb_build_object('id', f.id, 'slug', f.slug, 'name', f.name, 'title', f.title,
           'description', f.description, 'fields', f.fields, 'submit_message', f.submit_message,
           'enabled', f.enabled)
    into v from forms f where f.id = p_id and f.workspace_id = p_workspace;
  return v;
end $$;

create or replace function save_form(
  p_privy text, p_workspace uuid, p_id uuid, p_name text, p_title text,
  p_description text, p_fields jsonb, p_submit_message text, p_enabled boolean
) returns jsonb language plpgsql security definer set search_path = public as $$
declare v_role text; v_id uuid; v_slug text;
begin
  v_role := workspace_role(p_privy, p_workspace);
  if v_role is null or v_role not in ('owner','admin','member','recruiter') then raise exception 'FORBIDDEN'; end if;
  if jsonb_typeof(p_fields) <> 'array' then raise exception 'INVALID_FIELDS'; end if;

  if p_id is null then
    v_slug := lower(substr(replace(gen_random_uuid()::text, '-', ''), 1, 10));
    insert into forms (workspace_id, slug, name, title, description, fields, submit_message, enabled, created_by)
    values (p_workspace, v_slug, coalesce(nullif(p_name,''),'Untitled form'),
            coalesce(nullif(p_title,''),'Get in touch'), p_description, coalesce(p_fields,'[]'::jsonb),
            coalesce(nullif(p_submit_message,''),'Thanks — we''ll be in touch.'), coalesce(p_enabled,true), p_privy)
    returning id, slug into v_id, v_slug;
  else
    update forms set name = coalesce(nullif(p_name,''),'Untitled form'),
      title = coalesce(nullif(p_title,''),'Get in touch'), description = p_description,
      fields = coalesce(p_fields,'[]'::jsonb),
      submit_message = coalesce(nullif(p_submit_message,''),'Thanks — we''ll be in touch.'),
      enabled = coalesce(p_enabled,true), updated_at = now()
    where id = p_id and workspace_id = p_workspace
    returning id, slug into v_id, v_slug;
    if v_id is null then raise exception 'NOT_FOUND'; end if;
  end if;
  return jsonb_build_object('id', v_id, 'slug', v_slug);
end $$;

create or replace function delete_form(p_privy text, p_workspace uuid, p_id uuid)
returns boolean language plpgsql security definer set search_path = public as $$
declare v_role text; v_n int;
begin
  v_role := workspace_role(p_privy, p_workspace);
  if v_role is null or v_role not in ('owner','admin','member','recruiter') then raise exception 'FORBIDDEN'; end if;
  delete from forms where id = p_id and workspace_id = p_workspace;
  get diagnostics v_n = row_count;
  return v_n > 0;
end $$;

create or replace function get_form_submissions(p_privy text, p_workspace uuid, p_form_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
    'id', s.id, 'data', s.data, 'person_id', s.person_id, 'created_at', s.created_at
  ) order by s.created_at desc) from form_submissions s
    where s.form_id = p_form_id and s.workspace_id = p_workspace), '[]'::jsonb);
end $$;

-- ── Public side (anon; touches only its own rows) ───────────────────────────
create or replace function get_public_form(p_slug text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v jsonb;
begin
  select jsonb_build_object('id', f.id, 'title', f.title, 'description', f.description,
           'fields', f.fields, 'enabled', f.enabled, 'workspace_name', w.name)
    into v from forms f join workspaces w on w.id = f.workspace_id
    where f.slug = lower(p_slug);
  return v;  -- null if unknown
end $$;

-- Creates a lead (people row) from a submission and logs the raw answers.
-- Standard fields map onto people columns via each field's `map`; everything
-- else is stashed in custom_fields + the submission.
create or replace function submit_form(p_slug text, p_data jsonb, p_ip text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_form forms; v_field jsonb; v_key text; v_map text; v_val text;
  v_first text; v_last text; v_email text; v_phone text; v_title text; v_linkedin text;
  v_custom jsonb := '{}'::jsonb; v_person uuid;
begin
  select * into v_form from forms where slug = lower(p_slug) and enabled;
  if v_form.id is null then return jsonb_build_object('ok', false, 'reason', 'not_found'); end if;
  if jsonb_typeof(p_data) <> 'object' then return jsonb_build_object('ok', false, 'reason', 'bad_data'); end if;

  for v_field in select * from jsonb_array_elements(v_form.fields) loop
    v_key := v_field->>'key';
    v_map := v_field->>'map';
    v_val := p_data->>v_key;
    if v_val is null or v_val = '' then continue; end if;
    if    v_map = 'first_name'   then v_first := left(v_val, 200);
    elsif v_map = 'last_name'    then v_last := left(v_val, 200);
    elsif v_map = 'email'        then v_email := left(v_val, 320);
    elsif v_map = 'phone'        then v_phone := left(v_val, 60);
    elsif v_map = 'title'        then v_title := left(v_val, 200);
    elsif v_map = 'linkedin_url' then v_linkedin := left(v_val, 400);
    else  v_custom := v_custom || jsonb_build_object(coalesce(v_field->>'label', v_key), left(v_val, 2000));
    end if;
  end loop;

  insert into people (workspace_id, first_name, last_name, email, phone, title, linkedin_url, source, custom_fields)
  values (v_form.workspace_id, v_first, v_last, v_email, v_phone, v_title, v_linkedin,
          'form:' || v_form.name, v_custom)
  returning id into v_person;

  insert into form_submissions (form_id, workspace_id, data, person_id, ip)
  values (v_form.id, v_form.workspace_id, p_data, v_person, nullif(p_ip,''));

  return jsonb_build_object('ok', true, 'message', v_form.submit_message);
end $$;

-- ── Grants ──────────────────────────────────────────────────────────────────
revoke all on function get_forms(text, uuid)                                          from public, anon, authenticated;
revoke all on function get_form(text, uuid, uuid)                                     from public, anon, authenticated;
revoke all on function save_form(text, uuid, uuid, text, text, text, jsonb, text, boolean) from public, anon, authenticated;
revoke all on function delete_form(text, uuid, uuid)                                  from public, anon, authenticated;
revoke all on function get_form_submissions(text, uuid, uuid)                         from public, anon, authenticated;
grant execute on function get_forms(text, uuid)                                          to service_role;
grant execute on function get_form(text, uuid, uuid)                                     to service_role;
grant execute on function save_form(text, uuid, uuid, text, text, text, jsonb, text, boolean) to service_role;
grant execute on function delete_form(text, uuid, uuid)                                  to service_role;
grant execute on function get_form_submissions(text, uuid, uuid)                         to service_role;
-- Public flow: anon may call these two (DEFINER; no anon table grants needed).
grant execute on function get_public_form(text)          to anon, authenticated, service_role;
grant execute on function submit_form(text, jsonb, text)  to anon, authenticated, service_role;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0055_short_links.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0055_short_links.sql
-- URL shortener: workspace-scoped short links with click counting and a public
-- /l/<code> redirect.
--
-- Note: this is intentionally NOT built on the legacy `tracking_links` table.
-- That one is company-scoped (the HR candidate source-attribution feature) and
-- predates the workspace model; reusing it would tangle general link-shortening
-- with recruiting attribution. short_links is workspace-scoped like everything
-- built since the CRM pivot. The two coexist.
--
-- register_short_click is anon SECURITY DEFINER (a public redirect must resolve
-- without a session) and only ever bumps a counter + returns the target of the
-- row matching the code — it cannot read or change anything else. Owner RPCs are
-- service_role-only (0046 posture). Depends on 0012.
-- ============================================================================

create table if not exists short_links (
  id           uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspaces(id) on delete cascade,
  code         text not null unique,
  target_url   text not null,
  title        text,
  clicks       bigint not null default 0,
  created_by   text,
  created_at   timestamptz default now()
);
create index if not exists idx_short_links_ws on short_links(workspace_id);
alter table short_links enable row level security;
revoke all on table short_links from anon, authenticated;

create or replace function get_short_links(p_privy text, p_workspace uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
    'id', l.id, 'code', l.code, 'target_url', l.target_url, 'title', l.title,
    'clicks', l.clicks, 'created_at', l.created_at
  ) order by l.created_at desc) from short_links l where l.workspace_id = p_workspace), '[]'::jsonb);
end $$;

create or replace function create_short_link(p_privy text, p_workspace uuid, p_target text, p_title text, p_code text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_role text; v_code text; v_id uuid; tries int := 0;
begin
  v_role := workspace_role(p_privy, p_workspace);
  if v_role is null or v_role not in ('owner','admin','member','recruiter') then raise exception 'FORBIDDEN'; end if;
  if p_target !~* '^https?://' then raise exception 'INVALID_URL'; end if;

  -- Custom code if given + valid + free; otherwise generate a unique short one.
  if coalesce(p_code,'') <> '' then
    if lower(p_code) !~ '^[a-z0-9-]{3,32}$' then raise exception 'BAD_CODE'; end if;
    v_code := lower(p_code);
    if exists (select 1 from short_links where code = v_code) then raise exception 'CODE_TAKEN'; end if;
  else
    loop
      v_code := lower(substr(replace(gen_random_uuid()::text,'-',''), 1, 7));
      exit when not exists (select 1 from short_links where code = v_code);
      tries := tries + 1; if tries > 5 then raise exception 'CODE_GEN_FAILED'; end if;
    end loop;
  end if;

  insert into short_links (workspace_id, code, target_url, title, created_by)
  values (p_workspace, v_code, p_target, nullif(p_title,''), p_privy)
  returning id into v_id;
  return jsonb_build_object('id', v_id, 'code', v_code);
end $$;

create or replace function delete_short_link(p_privy text, p_workspace uuid, p_id uuid)
returns boolean language plpgsql security definer set search_path = public as $$
declare v_role text; v_n int;
begin
  v_role := workspace_role(p_privy, p_workspace);
  if v_role is null or v_role not in ('owner','admin','member','recruiter') then raise exception 'FORBIDDEN'; end if;
  delete from short_links where id = p_id and workspace_id = p_workspace;
  get diagnostics v_n = row_count;
  return v_n > 0;
end $$;

-- Public: resolve a code to its target and count the click. Returns null for an
-- unknown code so the redirect route can 404 cleanly.
create or replace function register_short_click(p_code text)
returns text language plpgsql security definer set search_path = public as $$
declare v_target text;
begin
  update short_links set clicks = clicks + 1
   where code = lower(p_code)
  returning target_url into v_target;
  return v_target;
end $$;

revoke all on function get_short_links(text, uuid)                    from public, anon, authenticated;
revoke all on function create_short_link(text, uuid, text, text, text) from public, anon, authenticated;
revoke all on function delete_short_link(text, uuid, uuid)            from public, anon, authenticated;
grant execute on function get_short_links(text, uuid)                    to service_role;
grant execute on function create_short_link(text, uuid, text, text, text) to service_role;
grant execute on function delete_short_link(text, uuid, uuid)            to service_role;
-- Public redirect counter (anon; DEFINER, touches only the matched row).
grant execute on function register_short_click(text) to anon, authenticated, service_role;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0056_cal_meetings.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0056_cal_meetings.sql
-- Cal.com connector (connect-not-copy: Cal.com is AGPL, so we integrate over its
-- webhook API rather than embedding any of its code) + a `meetings` table.
--
-- A workspace stores its Cal.com booking link and a webhook signing secret.
-- Cal.com POSTs booking events to /api/integrations/cal/<token>; the route
-- verifies the HMAC signature and calls cal_log_meeting, which records the
-- meeting and — when the attendee email matches a candidate in this workspace —
-- also drops an interview row so it shows on the Interviews page.
--
-- cal_resolve_connection + cal_log_meeting are service_role-only and called by
-- the webhook route (which has already verified the signature). The webhook
-- token identifies the workspace but is NOT the credential — the HMAC secret is.
-- Depends on 0012 + the interviews/candidates tables (base schema).
-- ============================================================================

create table if not exists cal_connections (
  workspace_id   uuid primary key references workspaces(id) on delete cascade,
  booking_url    text,
  webhook_secret text,
  webhook_token  uuid not null default gen_random_uuid(),
  enabled        boolean not null default true,
  created_at     timestamptz default now(),
  updated_at     timestamptz default now()
);
create unique index if not exists idx_cal_connections_token on cal_connections(webhook_token);
alter table cal_connections enable row level security;
revoke all on table cal_connections from anon, authenticated;

create table if not exists meetings (
  id             uuid primary key default gen_random_uuid(),
  workspace_id   uuid not null references workspaces(id) on delete cascade,
  title          text,
  attendee_name  text,
  attendee_email text,
  starts_at      timestamptz,
  ends_at        timestamptz,
  join_url       text,
  source         text default 'cal.com',
  external_id    text,
  candidate_id   uuid,
  raw            jsonb,
  created_at     timestamptz default now()
);
-- Dedupe re-deliveries of the same Cal.com booking.
create unique index if not exists idx_meetings_ext on meetings(workspace_id, external_id) where external_id is not null;
create index if not exists idx_meetings_ws on meetings(workspace_id);
alter table meetings enable row level security;
revoke all on table meetings from anon, authenticated;

-- ── Owner side ──────────────────────────────────────────────────────────────
-- Never returns the secret in plaintext — only whether one is set.
create or replace function get_cal_connection(p_privy text, p_workspace uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v jsonb;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  select jsonb_build_object('booking_url', c.booking_url, 'webhook_token', c.webhook_token,
           'has_secret', (c.webhook_secret is not null and c.webhook_secret <> ''), 'enabled', c.enabled)
    into v from cal_connections c where c.workspace_id = p_workspace;
  if v is null then
    -- Create a row so the workspace has a stable webhook token to paste into Cal.
    insert into cal_connections (workspace_id) values (p_workspace)
      on conflict (workspace_id) do nothing;
    select jsonb_build_object('booking_url', c.booking_url, 'webhook_token', c.webhook_token,
             'has_secret', false, 'enabled', c.enabled)
      into v from cal_connections c where c.workspace_id = p_workspace;
  end if;
  return v;
end $$;

create or replace function save_cal_connection(p_privy text, p_workspace uuid, p_booking_url text, p_secret text, p_enabled boolean)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_role text; v_token uuid;
begin
  v_role := workspace_role(p_privy, p_workspace);
  if v_role is null or v_role not in ('owner','admin') then raise exception 'FORBIDDEN'; end if;
  insert into cal_connections (workspace_id, booking_url, webhook_secret, enabled, updated_at)
  values (p_workspace, nullif(p_booking_url,''), nullif(p_secret,''), coalesce(p_enabled,true), now())
  on conflict (workspace_id) do update set
    booking_url = nullif(p_booking_url,''),
    -- keep the existing secret when the field is left blank on save
    webhook_secret = coalesce(nullif(p_secret,''), cal_connections.webhook_secret),
    enabled = coalesce(p_enabled,true), updated_at = now()
  returning webhook_token into v_token;
  return jsonb_build_object('webhook_token', v_token);
end $$;

create or replace function get_meetings(p_privy text, p_workspace uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
    'id', m.id, 'title', m.title, 'attendee_name', m.attendee_name, 'attendee_email', m.attendee_email,
    'starts_at', m.starts_at, 'join_url', m.join_url, 'source', m.source, 'candidate_id', m.candidate_id
  ) order by m.starts_at desc nulls last) from meetings m
    where m.workspace_id = p_workspace order by 1), '[]'::jsonb);
end $$;

-- ── Webhook side (service_role; route has already verified the HMAC) ─────────
create or replace function cal_resolve_connection(p_token uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v jsonb;
begin
  select jsonb_build_object('workspace_id', workspace_id, 'secret', webhook_secret, 'enabled', enabled)
    into v from cal_connections where webhook_token = p_token;
  return v;   -- null for an unknown token
end $$;

create or replace function cal_log_meeting(
  p_workspace uuid, p_external_id text, p_title text, p_name text, p_email text,
  p_starts timestamptz, p_ends timestamptz, p_join_url text, p_raw jsonb
) returns jsonb language plpgsql security definer set search_path = public as $$
declare v_candidate uuid; v_meeting uuid;
begin
  -- Attendee → existing candidate in this workspace's company (same uuid).
  if p_email is not null and p_email <> '' then
    select id into v_candidate from candidates
     where company_id = p_workspace and lower(email) = lower(p_email)
     order by created_at desc limit 1;
  end if;

  insert into meetings (workspace_id, title, attendee_name, attendee_email, starts_at, ends_at,
                        join_url, source, external_id, candidate_id, raw)
  values (p_workspace, p_title, p_name, lower(nullif(p_email,'')), p_starts, p_ends,
          p_join_url, 'cal.com', nullif(p_external_id,''), v_candidate, p_raw)
  on conflict (workspace_id, external_id) where external_id is not null
    do update set starts_at = excluded.starts_at, ends_at = excluded.ends_at,
                  join_url = excluded.join_url, title = excluded.title, raw = excluded.raw
  returning id into v_meeting;

  -- If it matched a candidate, also log an interview so it shows in HR.
  if v_candidate is not null and p_starts is not null then
    insert into interviews (candidate_id, scheduled_at, duration_minutes, status, notes,
                            google_meet_link, google_calendar_event_id)
    values (v_candidate, p_starts,
            greatest(1, coalesce(extract(epoch from (p_ends - p_starts))/60, 30))::int,
            'scheduled', 'Booked via Cal.com', p_join_url, 'cal:' || coalesce(p_external_id,''))
    on conflict do nothing;
    update candidates set status = 'interview_scheduled'
     where id = v_candidate and status not in ('hired','rejected','interview_scheduled');
  end if;

  return jsonb_build_object('ok', true, 'meeting_id', v_meeting, 'matched_candidate', v_candidate is not null);
end $$;

-- ── Grants (0046 posture) ───────────────────────────────────────────────────
revoke all on function get_cal_connection(text, uuid)                              from public, anon, authenticated;
revoke all on function save_cal_connection(text, uuid, text, text, boolean)        from public, anon, authenticated;
revoke all on function get_meetings(text, uuid)                                    from public, anon, authenticated;
revoke all on function cal_resolve_connection(uuid)                                from public, anon, authenticated;
revoke all on function cal_log_meeting(uuid, text, text, text, text, timestamptz, timestamptz, text, jsonb) from public, anon, authenticated;
grant execute on function get_cal_connection(text, uuid)                              to service_role;
grant execute on function save_cal_connection(text, uuid, text, text, boolean)        to service_role;
grant execute on function get_meetings(text, uuid)                                    to service_role;
grant execute on function cal_resolve_connection(uuid)                                to service_role;
grant execute on function cal_log_meeting(uuid, text, text, text, text, timestamptz, timestamptz, text, jsonb) to service_role;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0057_assistant.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0057_assistant.sql
-- Chat assistant channels: connect a Telegram / Slack / WhatsApp bot and talk to
-- your workspace in natural language ("make an offer for Acme at 12k and show me
-- a preview"). Each inbound message runs the shared agent loop (lib/agents,
-- migration 0043) on the workspace's own AI key, and the reply goes back to the
-- chat. This migration is the channel storage + resolver; the per-platform
-- webhook routes live in /api/assistant/*.
--
-- Security model:
--   • allowed_senders is a strict allowlist of chat ids — an unlisted sender is
--     refused and told their id so the owner can add them. Without this, anyone
--     who found the bot could operate the workspace.
--   • bot_token / webhook_secret live in a service_role-only, RLS-denied table;
--     the webhook token in the URL only names the channel, it is not the secret.
--   • the agent acts as `acting_privy` (whoever connected the bot) and inherits
--     their autonomy setting — 'auto' executes writes, 'suggest' only proposes.
-- Depends on 0012 + 0043 (agents) + get_ai_secret (0034/0038).
-- ============================================================================

create table if not exists assistant_channels (
  id             uuid primary key default gen_random_uuid(),
  workspace_id   uuid not null references workspaces(id) on delete cascade,
  platform       text not null default 'telegram' check (platform in ('telegram','slack','whatsapp')),
  bot_token      text,                                                   -- secret
  webhook_token  uuid not null default gen_random_uuid(),               -- inbound URL id
  webhook_secret text not null default replace(gen_random_uuid()::text,'-',''),  -- Telegram secret_token header
  allowed_senders text[] not null default '{}',
  autonomy       text not null default 'auto' check (autonomy in ('suggest','auto')),
  acting_privy   text,                                                   -- whose AI key + identity the agent uses
  enabled        boolean not null default true,
  created_at     timestamptz default now(),
  updated_at     timestamptz default now()
);
create unique index if not exists idx_assistant_channels_token on assistant_channels(webhook_token);
create index if not exists idx_assistant_channels_ws on assistant_channels(workspace_id);
alter table assistant_channels enable row level security;
revoke all on table assistant_channels from anon, authenticated;

-- ── Owner side ──────────────────────────────────────────────────────────────
create or replace function get_assistant_channels(p_privy text, p_workspace uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
    'id', c.id, 'platform', c.platform, 'webhook_token', c.webhook_token,
    'has_token', (c.bot_token is not null and c.bot_token <> ''),
    'allowed_senders', c.allowed_senders, 'autonomy', c.autonomy, 'enabled', c.enabled
  ) order by c.created_at) from assistant_channels c where c.workspace_id = p_workspace), '[]'::jsonb);
end $$;

create or replace function save_assistant_channel(
  p_privy text, p_workspace uuid, p_id uuid, p_platform text, p_bot_token text,
  p_allowed_senders text[], p_autonomy text, p_enabled boolean
) returns jsonb language plpgsql security definer set search_path = public as $$
declare v_role text; v_id uuid; v_token uuid; v_secret text;
begin
  v_role := workspace_role(p_privy, p_workspace);
  if v_role is null or v_role not in ('owner','admin') then raise exception 'FORBIDDEN'; end if;
  if coalesce(p_platform,'telegram') not in ('telegram','slack','whatsapp') then raise exception 'BAD_PLATFORM'; end if;
  if coalesce(p_autonomy,'auto') not in ('suggest','auto') then raise exception 'BAD_AUTONOMY'; end if;

  if p_id is null then
    insert into assistant_channels (workspace_id, platform, bot_token, allowed_senders, autonomy, enabled, acting_privy)
    values (p_workspace, coalesce(p_platform,'telegram'), nullif(p_bot_token,''),
            coalesce(p_allowed_senders,'{}'), coalesce(p_autonomy,'auto'), coalesce(p_enabled,true), p_privy)
    returning id, webhook_token, webhook_secret into v_id, v_token, v_secret;
  else
    update assistant_channels set
      platform = coalesce(p_platform, platform),
      bot_token = coalesce(nullif(p_bot_token,''), bot_token),   -- keep when left blank
      allowed_senders = coalesce(p_allowed_senders, allowed_senders),
      autonomy = coalesce(p_autonomy, autonomy),
      enabled = coalesce(p_enabled, enabled),
      acting_privy = coalesce(acting_privy, p_privy),
      updated_at = now()
    where id = p_id and workspace_id = p_workspace
    returning id, webhook_token, webhook_secret into v_id, v_token, v_secret;
    if v_id is null then raise exception 'NOT_FOUND'; end if;
  end if;
  return jsonb_build_object('id', v_id, 'webhook_token', v_token, 'webhook_secret', v_secret);
end $$;

create or replace function delete_assistant_channel(p_privy text, p_workspace uuid, p_id uuid)
returns boolean language plpgsql security definer set search_path = public as $$
declare v_role text; v_n int;
begin
  v_role := workspace_role(p_privy, p_workspace);
  if v_role is null or v_role not in ('owner','admin') then raise exception 'FORBIDDEN'; end if;
  delete from assistant_channels where id = p_id and workspace_id = p_workspace;
  get diagnostics v_n = row_count;
  return v_n > 0;
end $$;

-- ── Webhook side (service_role; the routes have vetted the request) ─────────
create or replace function resolve_assistant_channel(p_token uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v jsonb;
begin
  select jsonb_build_object(
    'id', id, 'workspace_id', workspace_id, 'platform', platform, 'bot_token', bot_token,
    'webhook_secret', webhook_secret, 'allowed_senders', allowed_senders,
    'autonomy', autonomy, 'acting_privy', acting_privy, 'enabled', enabled
  ) into v from assistant_channels where webhook_token = p_token;
  return v;   -- null for an unknown token
end $$;

revoke all on function get_assistant_channels(text, uuid)                                       from public, anon, authenticated;
revoke all on function save_assistant_channel(text, uuid, uuid, text, text, text[], text, boolean) from public, anon, authenticated;
revoke all on function delete_assistant_channel(text, uuid, uuid)                               from public, anon, authenticated;
revoke all on function resolve_assistant_channel(uuid)                                          from public, anon, authenticated;
grant execute on function get_assistant_channels(text, uuid)                                       to service_role;
grant execute on function save_assistant_channel(text, uuid, uuid, text, text, text[], text, boolean) to service_role;
grant execute on function delete_assistant_channel(text, uuid, uuid)                               to service_role;
grant execute on function resolve_assistant_channel(uuid)                                          to service_role;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0058_sanctions.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0058_sanctions.sql
-- Sanctions screening: check a customer, vendor or contact against the official
-- OFAC lists before you invoice them or pay them.
--
-- WHY THIS SHAPE:
--   • The lists are US Treasury publications — public domain, freely
--     redistributable, no key and no per-query fee. We ingest the raw CSVs into
--     Postgres (see /api/sanctions/refresh) and match locally with pg_trgm.
--     Screening is therefore a local index lookup, not a metered API call, which
--     is what keeps this free at any volume. Hosted screening APIs charge per
--     query AND require a commercial data licence; that is the thing being
--     avoided here.
--   • sanctions_entities is REFERENCE DATA, deliberately not workspace-scoped —
--     it's the same public list for everyone, and one shared trigram index beats
--     N copies. Only the screening *results* are tenant data.
--   • Fuzzy, not exact. Real names arrive as "Acme Trading Sp. z o.o." against a
--     list entry of "ACME TRADING". sanctions_normalize() strips legal forms and
--     punctuation, and trigram similarity absorbs the rest.
--
-- WHAT THIS IS NOT: a compliance product. It screens against the OFAC lists we
-- have imported, at the freshness of the last refresh, and it cannot tell you
-- that a name match IS the listed party. Every hit needs a human decision —
-- which is why screen_sanctions writes an audit row every time it runs.
-- Depends on 0001 (workspaces) + is_workspace_member/workspace_role.
-- ============================================================================

create extension if not exists pg_trgm;

-- ── Reference data ──────────────────────────────────────────────────────────
create table if not exists sanctions_entities (
  id           bigserial primary key,
  source       text not null,                       -- 'ofac_sdn' | 'ofac_consolidated'
  source_uid   text not null,                       -- OFAC ent_num, stable across refreshes
  name         text not null,
  entity_type  text,                                -- individual | entity | vessel | aircraft
  programs     text[] not null default '{}',        -- e.g. {UKRAINE-EO13662,RUSSIA-EO14024}
  aliases      text[] not null default '{}',
  addresses    text[] not null default '{}',
  countries    text[] not null default '{}',
  remarks      text,
  -- All three are derived by trg_sanctions_search_text. norm_name/norm_aliases
  -- exist so scoring is a plain similarity() over stored text instead of
  -- re-normalising every candidate row on every screening.
  search_text  text not null default '',            -- normalised name + aliases, trigram target
  norm_name    text not null default '',
  norm_aliases text[] not null default '{}',
  updated_at   timestamptz not null default now(),
  unique (source, source_uid)
);
alter table sanctions_entities add column if not exists norm_name    text not null default '';
alter table sanctions_entities add column if not exists norm_aliases text[] not null default '{}';

-- Reference data, but there is no reason for a browser to page through 17k
-- sanctioned parties — reads go through screen_sanctions only.
alter table sanctions_entities enable row level security;
revoke all on table sanctions_entities from anon, authenticated;

create index if not exists idx_sanctions_entities_trgm on sanctions_entities using gin (search_text gin_trgm_ops);
create index if not exists idx_sanctions_entities_source on sanctions_entities(source);

-- Per-source freshness. The UI must be able to say "list last updated 3 days
-- ago" — a screening is only as good as its data, and silently screening
-- against a six-month-old list is worse than not screening.
create table if not exists sanctions_sources (
  source       text primary key,
  label        text not null,
  url          text,
  entity_count int not null default 0,
  synced_at    timestamptz,
  last_error   text
);
alter table sanctions_sources enable row level security;
revoke all on table sanctions_sources from anon, authenticated;

insert into sanctions_sources (source, label, url) values
  ('ofac_sdn',          'OFAC — Specially Designated Nationals', 'https://sanctionslistservice.ofac.treas.gov/api/PublicationPreview/exports/SDN.CSV'),
  ('ofac_consolidated', 'OFAC — Consolidated (non-SDN)',         'https://sanctionslistservice.ofac.treas.gov/api/PublicationPreview/exports/CONS_PRIM.CSV')
on conflict (source) do nothing;

-- ── Tenant data: the audit trail ────────────────────────────────────────────
-- Every screening is recorded. "We checked, on this date, and this is what came
-- back" is the entire evidentiary value of doing this at all.
create table if not exists sanctions_screenings (
  id           uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspaces(id) on delete cascade,
  object_type  text,                                 -- 'companies' | 'people' | null for ad-hoc
  record_id    uuid,
  query        text not null,
  match_count  int not null default 0,
  top_score    numeric(4,3),
  status       text not null default 'clear' check (status in ('clear','review','no_data')),
  matches      jsonb not null default '[]',
  screened_by  text,
  screened_at  timestamptz not null default now()
);
create index if not exists idx_sanctions_screenings_ws on sanctions_screenings(workspace_id, screened_at desc);
create index if not exists idx_sanctions_screenings_record on sanctions_screenings(workspace_id, record_id, screened_at desc);
alter table sanctions_screenings enable row level security;
revoke all on table sanctions_screenings from anon, authenticated;

-- ── Name normalisation ──────────────────────────────────────────────────────
-- Uppercase → transliterate → drop punctuation → strip legal forms, so
-- "Acme Trading, LLC", "Åcme Trading Sp. z o.o." and "O.O.O. ACME TRADING" all
-- reduce to "ACME TRADING". Only legal-form tokens are stripped — words like
-- TRADING or GROUP carry real distinguishing meaning, and removing them would
-- collapse unrelated companies onto each other.
--
-- Three details that were wrong in the obvious version and matter a lot:
--   • Transliteration must happen BEFORE the punctuation strip. Otherwise "Å"
--     is not in [A-Z], becomes a space, and "Åcme" screens as "CME" — silently
--     losing the first letter of every accented name.
--   • Periods are DELETED, not turned into spaces, so "O.O.O." collapses to
--     "OOO" (a legal form we can strip) instead of "O O O" (three tokens of
--     noise that wreck the trigram score).
--   • Legal forms appear as prefixes in Russian/Polish/Indonesian naming and as
--     suffixes in Anglo/German naming, so both ends are stripped.
-- unaccent() is deliberately not used: it is STABLE, not IMMUTABLE, so it
-- cannot back a deterministic stored key. translate() can.
-- IMMUTABLE so search_text is reproducible for the index.
create or replace function sanctions_normalize(p text)
returns text language sql immutable parallel safe as $$
  with tr as (
    -- Ligatures expand to two letters, so they can't ride along in translate().
    select translate(
      replace(replace(replace(replace(replace(upper(coalesce(p, '')),
        'Æ', 'AE'), 'Œ', 'OE'), 'ß', 'SS'), 'İ', 'I'), '.', ''),
      'ÀÁÂÃÄÅĀĂĄÇĆČĈĊĎĐÐÈÉÊËĒĔĖĘĚĜĞĠĢÌÍÎÏĨĪĮİŁĹĻĽÑŃŅŇÒÓÔÕÖØŌŎŐŔŖŘŚŜŞŠŢŤŦÙÚÛÜŨŪŬŮŰŲÝŸŶŹŻŽÞ',
      'AAAAAAAAACCCCCDDDEEEEEEEEEGGGGIIIIIIIILLLLNNNNOOOOOOOOORRRSSSSTTTUUUUUUUUUUYYYZZZP'
    ) as v
  ), base as (
    select trim(regexp_replace(regexp_replace(v, '[^A-Z0-9]+', ' ', 'g'), '\s+', ' ', 'g')) as v from tr
  ), no_prefix as (
    select trim(regexp_replace(v,
      '^((OOO|ZAO|OAO|PAO|AO|TOO|JSC|OJSC|PJSC|CJSC|LLC|PT|CV|UAB|SP Z OO|SIA) )+',
      '', 'g')) as v
    from base
  ), stripped as (
    select trim(regexp_replace(v,
      '( (LLC|LLP|LP|LTD|LTDA|LIMITED|INC|INCORPORATED|CORP|CORPORATION|COMPANY|CO|GMBH|MBH|AG|KG|SA|SAS|SARL|SL|SPA|SRL|BV|NV|PLC|OY|OYJ|AB|AS|ASA|APS|DOO|AD|JSC|OJSC|PJSC|CJSC|OOO|ZAO|PAO|OAO|PTE|PTY|BHD|SDN|SIA|UAB|SP Z OO|SPZOO|SPOLKA Z OGRANICZONA ODPOWIEDZIALNOSCIA|SA DE CV|DE CV))+$',
      '', 'g')) as v
    from no_prefix
  )
  -- A company genuinely named "CO" would normalise to nothing; fall back through
  -- the earlier forms rather than producing an empty search key.
  select coalesce(nullif(stripped.v, ''), nullif(no_prefix.v, ''), base.v)
  from base, no_prefix, stripped;
$$;

-- search_text is derived, never supplied by the caller: the ingest route would
-- otherwise have to reimplement sanctions_normalize in TypeScript, and any
-- drift between the two would silently degrade matching.
create or replace function sanctions_entities_search_text() returns trigger
language plpgsql set search_path = public as $$
begin
  new.norm_name    := sanctions_normalize(new.name);
  new.norm_aliases := coalesce((select array_agg(sanctions_normalize(a)) from unnest(new.aliases) a), '{}');
  new.search_text  := trim(new.norm_name || ' ' || array_to_string(new.norm_aliases, ' '));
  return new;
end $$;

drop trigger if exists trg_sanctions_search_text on sanctions_entities;
create trigger trg_sanctions_search_text
  before insert or update of name, aliases on sanctions_entities
  for each row execute function sanctions_entities_search_text();

-- ── Screening ───────────────────────────────────────────────────────────────
-- Returns the matches AND records the check. Named screen_* rather than get_*
-- on purpose: /lib/rpc only memoises get|list|search|suggest, and an audited
-- write must never be served from cache.
create or replace function screen_sanctions(
  p_privy text, p_workspace uuid, p_query text,
  p_object text default null, p_record uuid default null,
  p_threshold numeric default 0.45
) returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_q text; v_total bigint; v_matches jsonb; v_count int; v_top numeric; v_status text;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;

  v_q := sanctions_normalize(p_query);
  if length(v_q) < 3 then raise exception 'QUERY_TOO_SHORT'; end if;

  -- Prefilter with word_similarity (`<%`), NOT plain similarity (`%`).
  -- search_text concatenates a name with up to a dozen aliases, so whole-string
  -- similarity against a short query is tiny — an entity with 7 aliases scored
  -- 0.22 against its OWN name and was filtered out before scoring, i.e. the
  -- exact name of a sanctioned party came back "clear". word_similarity scores
  -- the best matching extent instead, which is the right question here.
  -- The prefilter is set strictly looser than the final score cut so it can
  -- never be the thing that hides a match.
  perform set_config('pg_trgm.word_similarity_threshold',
                     greatest(0.1, p_threshold * 0.8)::text, true);

  select count(*) into v_total from sanctions_entities;

  -- No list imported yet. Reporting "clear" here would be an actively harmful
  -- lie, so it gets its own status and no audit row claiming a clean result.
  if v_total = 0 then
    return jsonb_build_object(
      'status', 'no_data', 'query', p_query, 'normalized', v_q,
      'match_count', 0, 'top_score', null, 'matches', '[]'::jsonb,
      'screened_at', now()
    );
  end if;

  with scored as (
    select e.id, e.name, e.source, e.entity_type, e.programs, e.countries,
           e.aliases, e.addresses, e.remarks,
           greatest(
             similarity(e.norm_name, v_q),
             coalesce((select max(similarity(a, v_q)) from unnest(e.norm_aliases) a), 0)
           ) as score
    from sanctions_entities e
    where v_q <% e.search_text         -- trigram index does the heavy filtering
  )
  select coalesce(jsonb_agg(to_jsonb(s) order by s.score desc), '[]'::jsonb), count(*), max(s.score)
    into v_matches, v_count, v_top
  from (select * from scored where score >= p_threshold order by score desc limit 25) s;

  v_status := case when v_count > 0 then 'review' else 'clear' end;

  insert into sanctions_screenings (workspace_id, object_type, record_id, query, match_count, top_score, status, matches, screened_by)
  values (p_workspace, nullif(p_object, ''), p_record, p_query, v_count, round(coalesce(v_top, 0), 3), v_status, v_matches, p_privy);

  return jsonb_build_object(
    'status', v_status, 'query', p_query, 'normalized', v_q,
    'match_count', v_count, 'top_score', round(coalesce(v_top, 0), 3),
    'matches', v_matches, 'screened_at', now()
  );
end $$;

-- Latest screening per record, so a list can show badges without re-screening.
create or replace function get_sanctions_screenings(p_privy text, p_workspace uuid, p_record uuid default null)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((
    select jsonb_agg(to_jsonb(x) order by x.screened_at desc) from (
      select distinct on (s.record_id, s.query)
             s.id, s.object_type, s.record_id, s.query, s.match_count,
             s.top_score, s.status, s.matches, s.screened_at
      from sanctions_screenings s
      where s.workspace_id = p_workspace
        and (p_record is null or s.record_id = p_record)
      order by s.record_id, s.query, s.screened_at desc
    ) x
  ), '[]'::jsonb);
end $$;

-- List freshness + size, for the "last updated" line next to the button.
create or replace function get_sanctions_status(p_privy text, p_workspace uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  return jsonb_build_object(
    'total', (select count(*) from sanctions_entities),
    'sources', coalesce((select jsonb_agg(to_jsonb(s) order by s.source) from (
        select source, label, url, entity_count, synced_at, last_error from sanctions_sources
      ) s), '[]'::jsonb)
  );
end $$;

-- Called by /api/sanctions/refresh (service_role) after a successful ingest.
create or replace function record_sanctions_sync(p_source text, p_count int, p_error text default null)
returns void language sql security definer set search_path = public as $$
  insert into sanctions_sources (source, label, entity_count, synced_at, last_error)
  values (p_source, p_source, coalesce(p_count, 0), now(), nullif(p_error, ''))
  on conflict (source) do update set
    entity_count = excluded.entity_count,
    synced_at    = excluded.synced_at,
    last_error   = excluded.last_error;
$$;

revoke all on function sanctions_normalize(text)                                   from public, anon, authenticated;
revoke all on function screen_sanctions(text, uuid, text, text, uuid, numeric)     from public, anon, authenticated;
revoke all on function get_sanctions_screenings(text, uuid, uuid)                  from public, anon, authenticated;
revoke all on function get_sanctions_status(text, uuid)                            from public, anon, authenticated;
revoke all on function record_sanctions_sync(text, int, text)                      from public, anon, authenticated;
grant execute on function sanctions_normalize(text)                                to service_role;
grant execute on function screen_sanctions(text, uuid, text, text, uuid, numeric)  to service_role;
grant execute on function get_sanctions_screenings(text, uuid, uuid)               to service_role;
grant execute on function get_sanctions_status(text, uuid)                         to service_role;
grant execute on function record_sanctions_sync(text, int, text)                   to service_role;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0059_umami.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0059_umami.sql
-- Point web analytics at a self-hosted Umami instead of the built-in
-- site_events pipeline (0027/0029/0030).
--
-- WHY UMAMI AND NOT PLAUSIBLE: Umami is MIT, so white-labelling it inside an
-- MIT product is unambiguous — Plausible CE is AGPL-3.0, and any modification
-- we made to it would have to be published. Umami also runs on Postgres and a
-- single Node process (~512 MB) rather than Elixir + ClickHouse (~4 GB), which
-- is the difference between one small Render service and a real monthly bill.
--
-- NOTHING IS DELETED. sites/site_events and get_site_stats stay exactly as they
-- are: they hold real historical pageviews that Umami will not have, and the
-- app falls back to them for any site with no umami_website_id. The swap is
-- per-site and reversible — clear the column and that site reads from Postgres
-- again.
-- Depends on 0027 (sites) + 0030.
-- ============================================================================

-- The id Umami assigns its own website record. Text, not uuid: Umami's ids are
-- uuids today but that is its schema's business, not ours, and a format change
-- upstream should not need a migration here.
alter table sites add column if not exists umami_website_id text;
create index if not exists idx_sites_umami on sites(umami_website_id) where umami_website_id is not null;

-- Redefined in full (0027's version did not select the new column).
create or replace function get_sites(p_privy text, p_workspace uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
    'id', s.id, 'domain', s.domain, 'name', s.name, 'created_at', s.created_at,
    'umami_website_id', s.umami_website_id
  ) order by s.created_at) from sites s where s.workspace_id = p_workspace), '[]'::jsonb);
end $$;

-- Called by /api/analytics/site after Umami has created its website record.
-- Membership is re-checked here rather than trusted from the route, so a bug in
-- the route cannot relabel another tenant's site.
create or replace function link_site_umami(p_privy text, p_site uuid, p_umami_id text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_ws uuid;
begin
  select workspace_id into v_ws from sites where id = p_site;
  if v_ws is null or not is_workspace_member(v_ws, p_privy) then raise exception 'NOT_FOUND_OR_FORBIDDEN'; end if;
  update sites set umami_website_id = nullif(p_umami_id, '') where id = p_site;
  return jsonb_build_object('id', p_site, 'umami_website_id', nullif(p_umami_id, ''));
end $$;

-- Resolve a site to its Umami id for the stats route. Returns null rather than
-- raising when unlinked — an unlinked site is a normal state (it still has
-- Postgres analytics), not an error.
create or replace function get_site_umami(p_privy text, p_site uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_ws uuid; v_umami text; v_domain text;
begin
  select workspace_id, umami_website_id, domain into v_ws, v_umami, v_domain from sites where id = p_site;
  if v_ws is null or not is_workspace_member(v_ws, p_privy) then raise exception 'NOT_FOUND_OR_FORBIDDEN'; end if;
  return jsonb_build_object('site_id', p_site, 'domain', v_domain, 'umami_website_id', v_umami);
end $$;

revoke all on function link_site_umami(text, uuid, text) from public, anon, authenticated;
revoke all on function get_site_umami(text, uuid)        from public, anon, authenticated;
grant execute on function link_site_umami(text, uuid, text) to service_role;
grant execute on function get_site_umami(text, uuid)        to service_role;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0060_careers_page.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0060_careers_page.sql
-- A public, branded careers page per company: every open role in one place at
-- /careers/<slug>, instead of only the one-role-at-a-time /apply/<positionId>
-- links that exist today.
--
-- The slug is chosen here with SUBDOMAINS in mind. Once wildcard DNS is
-- pointed at the app, acme.runbutter.app rewrites to /careers/acme with no
-- schema change — so the slug has to obey DNS label rules from day one
-- (lowercase, alphanumeric + hyphen, no leading/trailing hyphen, <= 63 chars),
-- and reserved hostnames have to be refused NOW. Letting someone take "www",
-- "api" or "mail" before the DNS flip would silently break the flip.
--
-- Nothing becomes public implicitly: a company has no careers page until an
-- owner/admin sets a slug. Roles are then listed only when active AND
-- published, so an internal req can stay off the public page.
-- Depends on the legacy ATS tables (companies, positions) + workspaces (0024).
-- ============================================================================

alter table companies  add column if not exists careers_slug     text;
alter table companies  add column if not exists careers_headline text;
alter table companies  add column if not exists careers_about    text;
alter table positions  add column if not exists is_published     boolean not null default true;

-- Case-insensitive uniqueness: hostnames are case-insensitive, so "Acme" and
-- "acme" must not be two different careers pages.
create unique index if not exists idx_companies_careers_slug on companies (lower(careers_slug))
  where careers_slug is not null;

-- ── Slug rules ──────────────────────────────────────────────────────────────
-- Names that must never become a tenant subdomain, because they are either
-- already routed, conventionally reserved, or would be used to impersonate us.
create or replace function careers_slug_reserved(p text)
returns boolean language sql immutable parallel safe as $$
  select lower(coalesce(p, '')) = any (array[
    'www','api','app','admin','administrator','auth','login','signup','register',
    'mail','email','smtp','imap','pop','ftp','ns','ns1','ns2','dns','mx',
    'cdn','static','assets','img','images','media','files','download','downloads',
    'blog','docs','doc','help','support','status','dashboard','portal','account',
    'billing','pay','payments','checkout','stripe','webhook','webhooks','hooks',
    'staging','stage','dev','test','demo','sandbox','preview','beta','alpha',
    'runbutter','hirebtr','careers','jobs','apply','security','abuse','postmaster',
    'root','system','internal','private','public','null','undefined','me','my'
  ])
$$;

-- Valid DNS label AND valid URL segment. 2-40 chars keeps it typeable and well
-- inside the 63-char DNS limit.
create or replace function careers_slug_valid(p text)
returns boolean language sql immutable parallel safe as $$
  select coalesce(p, '') ~ '^[a-z0-9]([a-z0-9-]{0,38}[a-z0-9])?$'
     and length(coalesce(p, '')) between 2 and 40
     and coalesce(p, '') !~ '--'          -- xn-- is the IDN prefix; avoid the whole class
     and not careers_slug_reserved(p)
$$;

-- ── Public read ─────────────────────────────────────────────────────────────
-- Anon-callable BY DESIGN: candidates have no Privy session, exactly like the
-- existing apply flow. It returns only what a careers page shows — never
-- candidate data, never anything about the workspace's internal state.
create or replace function get_careers_page(p_slug text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_company uuid; v_out jsonb;
begin
  select id into v_company from companies where lower(careers_slug) = lower(trim(coalesce(p_slug, '')));
  if v_company is null then return null; end if;   -- caller renders 404

  select jsonb_build_object(
    'company', jsonb_build_object(
      'id', c.id,
      'name', coalesce(nullif(w.legal_name, ''), c.name),
      'slug', c.careers_slug,
      'headline', c.careers_headline,
      'about', c.careers_about,
      -- workspace_id == company_id (0005 sync trigger), so branding set in
      -- Settings → Branding drives the public page with no second place to edit.
      'logo_url', coalesce(nullif(w.logo_url, ''), c.logo_url),
      'accent_color', nullif(w.accent_color, ''),
      'website', nullif(w.address, '')
    ),
    'positions', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', p.id, 'title', p.title, 'department', p.department,
        'location', p.location, 'employment_type', p.employment_type,
        'created_at', p.created_at
      ) order by p.created_at desc)
      from positions p
      where p.company_id = v_company and p.is_active and p.is_published
    ), '[]'::jsonb)
  ) into v_out
  from companies c left join workspaces w on w.id = c.id
  where c.id = v_company;

  return v_out;
end $$;

-- ── Owner side ──────────────────────────────────────────────────────────────
create or replace function set_careers_page(
  p_privy text, p_company uuid, p_slug text, p_headline text default null, p_about text default null
) returns jsonb language plpgsql security definer set search_path = public as $$
declare v_slug text;
begin
  if not is_workspace_member(p_company, p_privy) then raise exception 'NOT_A_MEMBER'; end if;

  v_slug := lower(trim(coalesce(p_slug, '')));
  if v_slug = '' then
    -- Empty slug takes the page down. Deliberately allowed: unpublishing must
    -- not require deleting the company.
    update companies set careers_slug = null, careers_headline = p_headline, careers_about = p_about
    where id = p_company;
    return jsonb_build_object('slug', null);
  end if;

  if not careers_slug_valid(v_slug) then
    if careers_slug_reserved(v_slug) then raise exception 'SLUG_RESERVED';
    else raise exception 'SLUG_INVALID'; end if;
  end if;
  if exists (select 1 from companies where lower(careers_slug) = v_slug and id <> p_company) then
    raise exception 'SLUG_TAKEN';
  end if;

  update companies set careers_slug = v_slug, careers_headline = p_headline, careers_about = p_about
  where id = p_company;
  return jsonb_build_object('slug', v_slug);
end $$;

create or replace function get_careers_settings(p_privy text, p_company uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_company, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((select jsonb_build_object(
    'slug', careers_slug, 'headline', careers_headline, 'about', careers_about
  ) from companies where id = p_company), '{}'::jsonb);
end $$;

-- Publish/unpublish a single role without deactivating it internally.
create or replace function set_position_published(p_privy text, p_position uuid, p_published boolean)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_company uuid;
begin
  select company_id into v_company from positions where id = p_position;
  if v_company is null or not is_workspace_member(v_company, p_privy) then raise exception 'NOT_FOUND_OR_FORBIDDEN'; end if;
  update positions set is_published = coalesce(p_published, true) where id = p_position;
  return jsonb_build_object('id', p_position, 'is_published', coalesce(p_published, true));
end $$;

revoke all on function get_careers_page(text)                              from public, anon, authenticated;
revoke all on function set_careers_page(text, uuid, text, text, text)      from public, anon, authenticated;
revoke all on function get_careers_settings(text, uuid)                    from public, anon, authenticated;
revoke all on function set_position_published(text, uuid, boolean)         from public, anon, authenticated;
-- The public page is server-rendered through the service_role client, so anon
-- EXECUTE stays revoked here too — consistent with 0046.
grant execute on function get_careers_page(text)                           to service_role;
grant execute on function set_careers_page(text, uuid, text, text, text)   to service_role;
grant execute on function get_careers_settings(text, uuid)                 to service_role;
grant execute on function set_position_published(text, uuid, boolean)      to service_role;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0061_branding_expanded.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0061_branding_expanded.sql
-- Branding grows from "logo on an invoice" to every surface a customer's
-- audience actually sees: the careers page, the apply form, outbound email,
-- documents, and the link preview when any of those is shared.
--
-- All of it hangs off `workspaces`, which already holds logo_url/accent_color
-- (0024), so there stays exactly ONE place a brand is defined. The careers copy
-- added in 0060 lives on `companies` for the public read path; everything
-- visual belongs here.
--
-- get/save_workspace_branding are redefined IN FULL rather than patched — same
-- discipline as the CRUD monolith, so the newest migration is always the whole
-- truth for these two functions.
-- Depends on 0024 (identity columns) + 0060 (careers page).
-- ============================================================================

-- Careers + apply surfaces
alter table workspaces add column if not exists cover_image_url text;   -- careers hero
alter table workspaces add column if not exists apply_intro     text;   -- shown above the apply form
-- Link previews (careers page, public forms, apply pages)
alter table workspaces add column if not exists favicon_url     text;
alter table workspaces add column if not exists og_image_url    text;
-- Outbound email (candidate status mails, invoice mails)
alter table workspaces add column if not exists email_from_name text;
alter table workspaces add column if not exists email_footer    text;
-- Documents beyond the invoice footer that already exists
alter table workspaces add column if not exists document_footer text;

create or replace function get_workspace_branding(p_privy text, p_workspace uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((select jsonb_build_object(
    'logo_url', logo_url, 'legal_name', legal_name, 'address', address,
    'accent_color', accent_color, 'invoice_footer', invoice_footer,
    'tax_id', tax_id, 'country', country, 'vat_id', vat_id, 'reg_no', reg_no,
    'bdo', bdo, 'iban', iban, 'bank_name', bank_name,
    'cover_image_url', cover_image_url, 'apply_intro', apply_intro,
    'favicon_url', favicon_url, 'og_image_url', og_image_url,
    'email_from_name', email_from_name, 'email_footer', email_footer,
    'document_footer', document_footer
  ) from workspaces where id = p_workspace), '{}'::jsonb);
end $$;

create or replace function save_workspace_branding(p_privy text, p_workspace uuid, p_data jsonb)
returns void language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  update workspaces set
    logo_url        = nullif(p_data->>'logo_url',''),
    legal_name      = nullif(p_data->>'legal_name',''),
    address         = nullif(p_data->>'address',''),
    accent_color    = coalesce(nullif(p_data->>'accent_color',''), accent_color),
    invoice_footer  = nullif(p_data->>'invoice_footer',''),
    tax_id          = nullif(p_data->>'tax_id',''),
    country         = nullif(p_data->>'country',''),
    vat_id          = nullif(p_data->>'vat_id',''),
    reg_no          = nullif(p_data->>'reg_no',''),
    bdo             = nullif(p_data->>'bdo',''),
    iban            = nullif(p_data->>'iban',''),
    bank_name       = nullif(p_data->>'bank_name',''),
    -- `?` (key present) rather than a plain nullif: a caller that omits a key
    -- must leave it alone. Without this, any older client still posting the
    -- 0024 field set would blank every branding value added here.
    cover_image_url = case when p_data ? 'cover_image_url' then nullif(p_data->>'cover_image_url','') else cover_image_url end,
    apply_intro     = case when p_data ? 'apply_intro'     then nullif(p_data->>'apply_intro','')     else apply_intro end,
    favicon_url     = case when p_data ? 'favicon_url'     then nullif(p_data->>'favicon_url','')     else favicon_url end,
    og_image_url    = case when p_data ? 'og_image_url'    then nullif(p_data->>'og_image_url','')    else og_image_url end,
    email_from_name = case when p_data ? 'email_from_name' then nullif(p_data->>'email_from_name','') else email_from_name end,
    email_footer    = case when p_data ? 'email_footer'    then nullif(p_data->>'email_footer','')    else email_footer end,
    document_footer = case when p_data ? 'document_footer' then nullif(p_data->>'document_footer','') else document_footer end
  where id = p_workspace;
end $$;

-- Anon EXECUTE was granted in 0024, before the /api/rpc proxy existed (0046).
-- Revoke it here: branding is workspace data and must go through the proxy.
revoke all on function get_workspace_branding(text, uuid)          from public, anon, authenticated;
revoke all on function save_workspace_branding(text, uuid, jsonb)  from public, anon, authenticated;
grant execute on function get_workspace_branding(text, uuid)         to service_role;
grant execute on function save_workspace_branding(text, uuid, jsonb) to service_role;

-- ── Public read for the careers page ────────────────────────────────────────
-- Redefined from 0060 so the page can render the hero image, favicon and OG
-- image. Same contract otherwise.
create or replace function get_careers_page(p_slug text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_company uuid; v_out jsonb;
begin
  select id into v_company from companies where lower(careers_slug) = lower(trim(coalesce(p_slug, '')));
  if v_company is null then return null; end if;

  select jsonb_build_object(
    'company', jsonb_build_object(
      'id', c.id,
      'name', coalesce(nullif(w.legal_name, ''), c.name),
      'slug', c.careers_slug,
      'headline', c.careers_headline,
      'about', c.careers_about,
      'logo_url', coalesce(nullif(w.logo_url, ''), c.logo_url),
      'accent_color', nullif(w.accent_color, ''),
      'website', nullif(w.address, ''),
      'cover_image_url', nullif(w.cover_image_url, ''),
      'favicon_url', nullif(w.favicon_url, ''),
      'og_image_url', nullif(w.og_image_url, '')
    ),
    'positions', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', p.id, 'title', p.title, 'department', p.department,
        'location', p.location, 'employment_type', p.employment_type,
        'created_at', p.created_at
      ) order by p.created_at desc)
      from positions p
      where p.company_id = v_company and p.is_active and p.is_published
    ), '[]'::jsonb)
  ) into v_out
  from companies c left join workspaces w on w.id = c.id
  where c.id = v_company;

  return v_out;
end $$;

revoke all on function get_careers_page(text) from public, anon, authenticated;
grant execute on function get_careers_page(text) to service_role;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0062_analytics_geo.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0062_analytics_geo.sql
-- Countries, browsers, operating systems and campaign attribution on the
-- BUILT-IN analytics pipeline (0027/0029/0030) — no Umami required.
--
-- WHY HERE AND NOT VIA UMAMI: Umami supplies these too, but only once a Node
-- service and a second database are deployed and reachable. This works on the
-- pipeline that is already collecting, costs nothing, and keeps the data in the
-- same Postgres as leads/campaigns/deals — so a pageview can be joined to a
-- campaign, which no external analytics product can do.
--
-- GEO IS FREE OR ABSENT. There is no IP-geolocation call here: country/region/
-- city come from headers the edge already attaches (Cloudflare's cf-ipcountry,
-- Vercel's x-vercel-ip-*). If nothing sits in front of the app, they arrive null
-- and the UI says "Unknown" rather than guessing — a metered lookup API would
-- break the cost rule, and inventing a location would be worse than admitting
-- we don't have one.
--
-- Still cookieless: none of these columns identify a person. Country is
-- coarse-grained by construction, and the visitor id remains the daily-rotating
-- salted hash from /api/t.
-- Depends on 0027 (site_events) + 0029/0030 (get_site_stats).
-- ============================================================================

alter table site_events add column if not exists country      text;   -- ISO-3166 alpha-2
alter table site_events add column if not exists region       text;
alter table site_events add column if not exists city         text;
alter table site_events add column if not exists browser      text;
alter table site_events add column if not exists os           text;
alter table site_events add column if not exists utm_source   text;
alter table site_events add column if not exists utm_medium   text;
alter table site_events add column if not exists utm_campaign text;

-- Breakdown queries all filter site_id + ts and then group by one dimension.
-- The existing (site_id, ts desc) index already serves the filter; these are
-- narrow partial indexes for the group-bys that actually run.
create index if not exists idx_site_events_country on site_events(site_id, country) where country is not null;
create index if not exists idx_site_events_utm on site_events(site_id, utm_source) where utm_source is not null;

-- Redefined IN FULL (from 0029) — same discipline as the CRUD monolith, so the
-- newest migration is the whole truth for this function.
create or replace function get_site_stats(p_privy text, p_site uuid, p_days int default 30)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_ws uuid;
  v_days int := greatest(1, least(coalesce(p_days, 30), 365));
  v_start timestamptz := date_trunc('day', now()) - ((v_days - 1) || ' days')::interval;
begin
  select workspace_id into v_ws from sites where id = p_site;
  if v_ws is null or not is_workspace_member(v_ws, p_privy) then raise exception 'NOT_FOUND_OR_FORBIDDEN'; end if;

  return jsonb_build_object(
    'pageviews', (select count(*) from site_events where site_id = p_site and ts >= v_start),
    'visitors',  (select count(distinct visitor) from site_events where site_id = p_site and ts >= v_start),
    'live',      (select count(distinct visitor) from site_events where site_id = p_site and ts >= now() - interval '5 minutes'),
    'desktop',   (select count(*) from site_events where site_id = p_site and ts >= v_start and device = 'desktop'),
    'mobile',    (select count(*) from site_events where site_id = p_site and ts >= v_start and device = 'mobile'),
    'series', coalesce((
      select jsonb_agg(jsonb_build_object(
        'day', to_char(d.day, 'YYYY-MM-DD'), 'label', to_char(d.day, 'DD Mon'),
        'pageviews', coalesce(e.pv, 0), 'visitors', coalesce(e.uv, 0)
      ) order by d.day)
      from generate_series(date_trunc('day', v_start), date_trunc('day', now()), interval '1 day') d(day)
      left join (
        select date_trunc('day', ts) as day, count(*) as pv, count(distinct visitor) as uv
        from site_events where site_id = p_site and ts >= v_start group by 1
      ) e on e.day = d.day
    ), '[]'::jsonb),
    'top_pages', coalesce((
      select jsonb_agg(jsonb_build_object('path', t.path, 'count', t.c) order by t.c desc)
      from (select path, count(*) c from site_events where site_id = p_site and ts >= v_start
            group by path order by c desc limit 10) t
    ), '[]'::jsonb),
    'top_referrers', coalesce((
      select jsonb_agg(jsonb_build_object('ref', t.ref, 'count', t.c) order by t.c desc)
      from (select coalesce(nullif(referrer, ''), 'direct') as ref, count(*) c
            from site_events where site_id = p_site and ts >= v_start
            group by 1 order by c desc limit 10) t
    ), '[]'::jsonb),
    -- ── 0062 additions ───────────────────────────────────────────────────────
    -- Unknown is kept as its own bucket rather than dropped: "we have no
    -- location for 80% of traffic" is information, and silently omitting it
    -- would make the country list look authoritative when it isn't.
    'countries', coalesce((
      select jsonb_agg(jsonb_build_object('code', t.code, 'count', t.c) order by t.c desc)
      from (select coalesce(nullif(upper(country), ''), 'Unknown') as code, count(*) c
            from site_events where site_id = p_site and ts >= v_start
            group by 1 order by c desc limit 12) t
    ), '[]'::jsonb),
    'cities', coalesce((
      select jsonb_agg(jsonb_build_object('name', t.name, 'count', t.c) order by t.c desc)
      from (select city || case when country is not null then ', ' || upper(country) else '' end as name, count(*) c
            from site_events where site_id = p_site and ts >= v_start and nullif(city,'') is not null
            group by 1 order by c desc limit 10) t
    ), '[]'::jsonb),
    'browsers', coalesce((
      select jsonb_agg(jsonb_build_object('name', t.name, 'count', t.c) order by t.c desc)
      from (select coalesce(nullif(browser, ''), 'Unknown') as name, count(*) c
            from site_events where site_id = p_site and ts >= v_start
            group by 1 order by c desc limit 8) t
    ), '[]'::jsonb),
    'operating_systems', coalesce((
      select jsonb_agg(jsonb_build_object('name', t.name, 'count', t.c) order by t.c desc)
      from (select coalesce(nullif(os, ''), 'Unknown') as name, count(*) c
            from site_events where site_id = p_site and ts >= v_start
            group by 1 order by c desc limit 8) t
    ), '[]'::jsonb),
    -- Campaign attribution: only rows that actually carried a utm_source, so an
    -- empty list honestly means "no tagged traffic" rather than "all direct".
    'campaigns', coalesce((
      select jsonb_agg(jsonb_build_object(
        'source', t.src, 'medium', t.med, 'campaign', t.camp, 'count', t.c
      ) order by t.c desc)
      from (select utm_source as src, coalesce(nullif(utm_medium,''), '—') as med,
                   coalesce(nullif(utm_campaign,''), '—') as camp, count(*) c
            from site_events
            where site_id = p_site and ts >= v_start and nullif(utm_source,'') is not null
            group by 1,2,3 order by c desc limit 10) t
    ), '[]'::jsonb),
    -- Lets the UI distinguish "no geo data available" from "no traffic".
    'geo_coverage', (
      select case when count(*) = 0 then 0
             else round(100.0 * count(country) / count(*)) end
      from site_events where site_id = p_site and ts >= v_start
    )
  );
end $$;

-- Matches 0029: the tracker path is anon, and the dashboard reads through the
-- /api/rpc proxy.
grant execute on function get_site_stats(text, uuid, int) to authenticated, anon;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0063_careers_position.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0063_careers_position.sql
-- A public page per open role: /careers/<slug>/<positionId>.
--
-- Until now the careers list linked straight into the application form, so a
-- candidate never saw the job description — even though `description`,
-- `department`, `location` and `employment_type` are captured on every position.
-- People were applying blind to fields we already had.
--
-- Giving each role its own URL also makes it indexable, which is what allows
-- JobPosting structured data and therefore Google Jobs. That is free
-- distribution which is impossible while every role shares one page.
--
-- Same visibility contract as get_careers_page (0060/0061): the company must
-- have a careers slug, and the role must be active AND published. A hidden or
-- closed role 404s here rather than being reachable by guessing its id.
-- Depends on 0060 (careers_slug, is_published) + 0061 (branding columns).
-- ============================================================================

create or replace function get_careers_position(p_slug text, p_position uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_company uuid; v_out jsonb;
begin
  select id into v_company from companies where lower(careers_slug) = lower(trim(coalesce(p_slug, '')));
  if v_company is null then return null; end if;

  select jsonb_build_object(
    'company', jsonb_build_object(
      'id', c.id,
      'name', coalesce(nullif(w.legal_name, ''), c.name),
      'slug', c.careers_slug,
      'logo_url', coalesce(nullif(w.logo_url, ''), c.logo_url),
      'accent_color', nullif(w.accent_color, ''),
      'website', nullif(w.address, ''),
      'cover_image_url', nullif(w.cover_image_url, ''),
      'favicon_url', nullif(w.favicon_url, ''),
      'og_image_url', nullif(w.og_image_url, ''),
      -- Shown on the apply step; surfaced here so the job page can preview it.
      'apply_intro', nullif(w.apply_intro, '')
    ),
    'position', jsonb_build_object(
      'id', p.id, 'title', p.title, 'description', p.description,
      'department', p.department, 'location', p.location,
      'employment_type', p.employment_type, 'created_at', p.created_at
    ),
    -- Lets the page offer "3 other open roles" without a second round trip.
    'other_positions', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', o.id, 'title', o.title, 'department', o.department, 'location', o.location
      ) order by o.created_at desc)
      from positions o
      where o.company_id = v_company and o.is_active and o.is_published and o.id <> p.id
      limit 5
    ), '[]'::jsonb)
  ) into v_out
  from positions p
  join companies c on c.id = p.company_id
  left join workspaces w on w.id = c.id
  where p.id = p_position
    and p.company_id = v_company
    and p.is_active
    and p.is_published;

  return v_out;   -- null when hidden, closed, or not this company's role
end $$;

revoke all on function get_careers_position(text, uuid) from public, anon, authenticated;
grant execute on function get_careers_position(text, uuid) to service_role;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0064_invoice_reminders.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0064_invoice_reminders.sql
-- Mark invoices overdue, and chase them.
--
-- `overdue` has been a valid invoice status since 0015 and is read by
-- get_finance_summary — but nothing in the product ever SET it, and no reminder
-- was ever sent. An invoice went out and then sat there. This is the feature
-- that turns an invoicing screen into something that actually collects money.
--
-- SENDING EMAIL TO A CUSTOMER'S CUSTOMER IS THE RISK HERE, so the defaults are
-- deliberately timid:
--   • disabled per workspace until someone turns it on — nobody gets chased
--     because they upgraded
--   • every send is logged and the log is UNIQUE per (invoice, stage), so a
--     retried cron or a double-click cannot mail the same person twice
--   • only 'income' invoices are chased. Chasing a bill you owe would be
--     nonsense, and the direction column already distinguishes them
--   • a per-run cap, so a misconfigured schedule can't blast a whole ledger
-- Depends on 0015 (invoices) + 0025 (share links).
-- ============================================================================

-- ── Per-workspace configuration ─────────────────────────────────────────────
create table if not exists invoice_reminder_settings (
  workspace_id uuid primary key references workspaces(id) on delete cascade,
  enabled      boolean not null default false,
  -- Days relative to due_at. Negative = before due, positive = after.
  -- Default is one polite nudge before, then escalating chases.
  offsets      int[] not null default '{-3,1,7,14}',
  -- Null = use the built-in copy. Supports {{invoice_number}}, {{amount}},
  -- {{due_date}}, {{days_overdue}}, {{company}}, {{link}}.
  subject      text,
  body         text,
  reply_to     text,
  updated_at   timestamptz not null default now()
);
alter table invoice_reminder_settings enable row level security;
revoke all on table invoice_reminder_settings from anon, authenticated;

-- ── Send log ────────────────────────────────────────────────────────────────
-- The unique constraint is the whole safety mechanism: it makes "send reminder
-- for stage N" idempotent at the database level, so a cron that fires twice or
-- a route that retries cannot double-mail a client.
create table if not exists invoice_reminder_log (
  id           uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspaces(id) on delete cascade,
  invoice_id   uuid not null references invoices(id) on delete cascade,
  stage        int not null,                     -- the offset that triggered it
  sent_to      text,
  sent_at      timestamptz not null default now(),
  error        text,
  unique (invoice_id, stage)
);
create index if not exists idx_reminder_log_ws on invoice_reminder_log(workspace_id, sent_at desc);
alter table invoice_reminder_log enable row level security;
revoke all on table invoice_reminder_log from anon, authenticated;

-- ── Overdue marking ─────────────────────────────────────────────────────────
-- Separate from reminders on purpose: a workspace that never enables chasing
-- still wants its dashboard to say "overdue" instead of "sent" forever.
-- Only 'sent' moves to 'overdue' — a draft is not overdue, and paid/cancelled
-- must never be reopened.
create or replace function mark_invoices_overdue(p_workspace uuid default null)
returns int language plpgsql security definer set search_path = public as $$
declare v_n int;
begin
  update invoices
     set status = 'overdue'
   where status = 'sent'
     and due_at is not null
     and due_at < current_date
     and (p_workspace is null or workspace_id = p_workspace);
  get diagnostics v_n = row_count;
  return v_n;
end $$;

-- ── Which reminders are due right now ───────────────────────────────────────
/**
 * Returns unpaid income invoices whose due date has reached one of the
 * configured offsets and which have not already been mailed at that stage.
 *
 * The stage chosen is the LARGEST offset already reached, not the smallest, so
 * an invoice that has been sitting for 30 days sends the day-14 chase once —
 * rather than working through -3, 1, 7 and 14 on consecutive runs and looking
 * like a malfunction to the recipient.
 */
create or replace function due_invoice_reminders(p_workspace uuid, p_limit int default 50)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_out jsonb;
begin
  select coalesce(jsonb_agg(to_jsonb(x) order by x.due_at), '[]'::jsonb) into v_out
  from (
    select i.id, i.number, i.amount, i.due_at, i.status,
           c.name  as company_name,
           c.email as company_email,
           (current_date - i.due_at::date) as days_overdue,
           s.subject, s.body, s.reply_to,
           (select max(o) from unnest(s.offsets) o
             where i.due_at::date + o <= current_date) as stage
    from invoices i
    join invoice_reminder_settings s on s.workspace_id = i.workspace_id
    left join companies c on c.id = i.organization_id
    where i.workspace_id = p_workspace
      and s.enabled
      and i.direction = 'income'
      and i.status in ('sent', 'overdue')
      and i.due_at is not null
      and coalesce(i.kind, 'invoice') <> 'offer'
  ) x
  where x.stage is not null
    -- Idempotence: skip anything already logged at this stage.
    and not exists (
      select 1 from invoice_reminder_log l
      where l.invoice_id = x.id and l.stage = x.stage
    )
    -- No address, no reminder. Returning it would just produce a failed send.
    and nullif(x.company_email, '') is not null
  limit greatest(1, least(coalesce(p_limit, 50), 200));

  return v_out;
end $$;

-- Called by the send route after each attempt. Records failures too, so a
-- permanently bouncing address is visible rather than retried forever.
create or replace function log_invoice_reminder(
  p_workspace uuid, p_invoice uuid, p_stage int, p_to text, p_error text default null
) returns void language sql security definer set search_path = public as $$
  insert into invoice_reminder_log (workspace_id, invoice_id, stage, sent_to, error)
  values (p_workspace, p_invoice, p_stage, nullif(p_to, ''), nullif(p_error, ''))
  on conflict (invoice_id, stage) do nothing;
$$;

-- ── Owner side ──────────────────────────────────────────────────────────────
create or replace function get_invoice_reminder_settings(p_privy text, p_workspace uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((select jsonb_build_object(
    'enabled', enabled, 'offsets', offsets, 'subject', subject,
    'body', body, 'reply_to', reply_to
  ) from invoice_reminder_settings where workspace_id = p_workspace),
  -- Reflect the table defaults so the UI shows the same thing before first save.
  jsonb_build_object('enabled', false, 'offsets', jsonb_build_array(-3, 1, 7, 14),
                     'subject', null, 'body', null, 'reply_to', null));
end $$;

create or replace function save_invoice_reminder_settings(
  p_privy text, p_workspace uuid, p_enabled boolean, p_offsets int[],
  p_subject text default null, p_body text default null, p_reply_to text default null
) returns jsonb language plpgsql security definer set search_path = public as $$
declare v_role text; v_offsets int[];
begin
  v_role := workspace_role(p_privy, p_workspace);
  if v_role is null or v_role not in ('owner','admin') then raise exception 'FORBIDDEN'; end if;

  -- Clamp to a sane window and de-duplicate. Without this, a typo like 3650
  -- schedules a reminder ten years out, and duplicates would fight the
  -- unique(invoice, stage) constraint rather than being caught here.
  select coalesce(array_agg(distinct o order by o), '{}') into v_offsets
  from unnest(coalesce(p_offsets, '{-3,1,7,14}')) o
  where o between -60 and 365;

  if array_length(v_offsets, 1) is null then raise exception 'NO_VALID_OFFSETS'; end if;
  if array_length(v_offsets, 1) > 8 then raise exception 'TOO_MANY_OFFSETS'; end if;

  insert into invoice_reminder_settings (workspace_id, enabled, offsets, subject, body, reply_to, updated_at)
  values (p_workspace, coalesce(p_enabled, false), v_offsets,
          nullif(p_subject,''), nullif(p_body,''), nullif(p_reply_to,''), now())
  on conflict (workspace_id) do update set
    enabled = excluded.enabled, offsets = excluded.offsets,
    subject = excluded.subject, body = excluded.body,
    reply_to = excluded.reply_to, updated_at = now();

  return jsonb_build_object('enabled', coalesce(p_enabled,false), 'offsets', v_offsets);
end $$;

-- What was chased, and when — so "did we already hassle them?" is answerable.
create or replace function get_invoice_reminder_log(p_privy text, p_workspace uuid, p_limit int default 100)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((select jsonb_agg(to_jsonb(x) order by x.sent_at desc) from (
    select l.id, l.invoice_id, i.number as invoice_number, l.stage,
           l.sent_to, l.sent_at, l.error
    from invoice_reminder_log l
    left join invoices i on i.id = l.invoice_id
    where l.workspace_id = p_workspace
    order by l.sent_at desc
    limit greatest(1, least(coalesce(p_limit, 100), 500))
  ) x), '[]'::jsonb);
end $$;

revoke all on function mark_invoices_overdue(uuid)                                      from public, anon, authenticated;
revoke all on function due_invoice_reminders(uuid, int)                                 from public, anon, authenticated;
revoke all on function log_invoice_reminder(uuid, uuid, int, text, text)                from public, anon, authenticated;
revoke all on function get_invoice_reminder_settings(text, uuid)                        from public, anon, authenticated;
revoke all on function save_invoice_reminder_settings(text, uuid, boolean, int[], text, text, text) from public, anon, authenticated;
revoke all on function get_invoice_reminder_log(text, uuid, int)                         from public, anon, authenticated;
grant execute on function mark_invoices_overdue(uuid)                                    to service_role;
grant execute on function due_invoice_reminders(uuid, int)                               to service_role;
grant execute on function log_invoice_reminder(uuid, uuid, int, text, text)              to service_role;
grant execute on function get_invoice_reminder_settings(text, uuid)                      to service_role;
grant execute on function save_invoice_reminder_settings(text, uuid, boolean, int[], text, text, text) to service_role;
grant execute on function get_invoice_reminder_log(text, uuid, int)                      to service_role;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0065_files.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0065_files.sql
-- Company files that become DATA, not just storage.
--
-- The point is not a file manager — Dropbox exists. The point is that a contract
-- dropped here is extracted to text, indexed with Postgres FTS, and ATTACHED to
-- a record (a company, an invoice, a candidate). Because everything already
-- lives in one Postgres, "find every contract mentioning auto-renewal, for
-- clients who owe us money" becomes a single join. No external file service can
-- answer that, because it cannot see the ledger.
--
-- EXTRACTION IS PLUGGABLE AND OPTIONAL:
--   • PDFs with a text layer are handled locally by pdf-parse — free, no service.
--   • Scans and photos need OCR. That's MinerU (self-hosted, optional) or a
--     vision model on the workspace's own AI key. Neither is required to store
--     a file; `extract_status` records which path ran, or that none did.
-- Nothing here calls a metered API, consistent with the cost rule.
--
-- Text search is a stored tsvector kept by trigger rather than an expression
-- index, because extraction happens AFTER the row is created (upload first,
-- parse second) and a trigger updates the vector on that later write for free.
-- Depends on 0001 (workspaces).
-- ============================================================================

create table if not exists files (
  id             uuid primary key default gen_random_uuid(),
  workspace_id   uuid not null references workspaces(id) on delete cascade,
  name           text not null,
  -- Path inside the private storage bucket. Not a public URL: these are
  -- contracts and payroll, so they are served through a signed URL on demand.
  storage_path    text not null,
  mime_type      text,
  size_bytes     bigint,
  -- Optional attachment to any record, kept loose on purpose: the CRUD monolith
  -- spans a dozen tables and a real FK would need one column per object.
  -- Integrity is enforced by the RPCs, which resolve the record first.
  linked_object  text,
  linked_id      uuid,
  -- Extracted plain text / Markdown.
  content        text,
  extract_status text not null default 'pending'
                 check (extract_status in ('pending','text_layer','ocr','vision','failed','skipped')),
  extract_error  text,
  page_count     int,
  search_vector  tsvector,
  uploaded_by    text,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);

create index if not exists idx_files_ws on files(workspace_id, created_at desc);
create index if not exists idx_files_linked on files(workspace_id, linked_object, linked_id)
  where linked_id is not null;
create index if not exists idx_files_search on files using gin (search_vector);

alter table files enable row level security;
revoke all on table files from anon, authenticated;

-- 'simple' rather than 'english': these documents are Polish, German and English
-- in the same workspace, and an English stemmer mangles the others. Exact-ish
-- token matching across languages beats good stemming in one.
create or replace function files_search_vector() returns trigger
language plpgsql set search_path = public as $$
begin
  new.search_vector :=
    setweight(to_tsvector('simple', coalesce(new.name, '')), 'A') ||
    setweight(to_tsvector('simple', left(coalesce(new.content, ''), 900000)), 'B');
  new.updated_at := now();
  return new;
end $$;

drop trigger if exists trg_files_search on files;
create trigger trg_files_search
  before insert or update of name, content on files
  for each row execute function files_search_vector();

-- ── RPCs ────────────────────────────────────────────────────────────────────
create or replace function create_file(
  p_privy text, p_workspace uuid, p_name text, p_path text,
  p_mime text default null, p_size bigint default null,
  p_object text default null, p_linked uuid default null
) returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  if coalesce(trim(p_name), '') = '' or coalesce(trim(p_path), '') = '' then
    raise exception 'NAME_AND_PATH_REQUIRED';
  end if;
  insert into files (workspace_id, name, storage_path, mime_type, size_bytes,
                     linked_object, linked_id, uploaded_by)
  values (p_workspace, p_name, p_path, nullif(p_mime,''), p_size,
          nullif(p_object,''), p_linked, p_privy)
  returning id into v_id;
  return v_id;
end $$;

-- Called by the extraction route once text is available. Separate from creation
-- because upload succeeds immediately and parsing may take seconds (or fail).
create or replace function set_file_content(
  p_privy text, p_file uuid, p_content text, p_status text,
  p_pages int default null, p_error text default null
) returns boolean language plpgsql security definer set search_path = public as $$
declare v_ws uuid;
begin
  select workspace_id into v_ws from files where id = p_file;
  if v_ws is null or not is_workspace_member(v_ws, p_privy) then raise exception 'NOT_FOUND_OR_FORBIDDEN'; end if;
  if coalesce(p_status,'') not in ('pending','text_layer','ocr','vision','failed','skipped') then
    raise exception 'BAD_STATUS';
  end if;
  update files set
    content        = case when p_status = 'failed' then content else p_content end,
    extract_status = p_status,
    extract_error  = nullif(p_error, ''),
    page_count     = coalesce(p_pages, page_count)
  where id = p_file;
  return true;
end $$;

create or replace function get_files(
  p_privy text, p_workspace uuid, p_object text default null,
  p_linked uuid default null, p_limit int default 200
) returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at desc) from (
    select id, name, storage_path, mime_type, size_bytes, linked_object, linked_id,
           extract_status, extract_error, page_count, created_at,
           -- The body can be megabytes; a list view only needs to know whether
           -- there IS text and roughly how much.
           (content is not null and content <> '') as has_content,
           length(coalesce(content, '')) as content_length
    from files
    where workspace_id = p_workspace
      and (p_object is null or linked_object = p_object)
      and (p_linked is null or linked_id = p_linked)
    order by created_at desc
    limit greatest(1, least(coalesce(p_limit, 200), 500))
  ) x), '[]'::jsonb);
end $$;

create or replace function get_file(p_privy text, p_file uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_ws uuid; v_out jsonb;
begin
  select workspace_id into v_ws from files where id = p_file;
  if v_ws is null or not is_workspace_member(v_ws, p_privy) then raise exception 'NOT_FOUND_OR_FORBIDDEN'; end if;
  select to_jsonb(f) into v_out from (
    select id, workspace_id, name, storage_path, mime_type, size_bytes,
           linked_object, linked_id, content, extract_status, extract_error,
           page_count, created_at
    from files where id = p_file
  ) f;
  return v_out;
end $$;

/**
 * Full-text search across file contents.
 *
 * websearch_to_tsquery, not plainto_tsquery: it understands quoted phrases and
 * OR, which is what someone typing into a search box actually expects, and it
 * never throws on odd punctuation the way to_tsquery does.
 */
create or replace function search_files(p_privy text, p_workspace uuid, p_query text, p_limit int default 30)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_q tsquery;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  if coalesce(trim(p_query), '') = '' then return '[]'::jsonb; end if;
  v_q := websearch_to_tsquery('simple', p_query);

  return coalesce((select jsonb_agg(to_jsonb(x) order by x.rank desc) from (
    select f.id, f.name, f.linked_object, f.linked_id, f.extract_status, f.created_at,
           ts_rank(f.search_vector, v_q) as rank,
           ts_headline('simple', coalesce(f.content, ''), v_q,
                       'MaxFragments=2,MinWords=5,MaxWords=18,StartSel=«,StopSel=»') as snippet
    from files f
    where f.workspace_id = p_workspace and f.search_vector @@ v_q
    order by rank desc
    limit greatest(1, least(coalesce(p_limit, 30), 100))
  ) x), '[]'::jsonb);
end $$;

create or replace function delete_file(p_privy text, p_file uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_ws uuid; v_path text;
begin
  select workspace_id, storage_path into v_ws, v_path from files where id = p_file;
  if v_ws is null or not is_workspace_member(v_ws, p_privy) then raise exception 'NOT_FOUND_OR_FORBIDDEN'; end if;
  delete from files where id = p_file;
  -- Hand the path back so the caller can remove the object from storage too;
  -- deleting the row alone would orphan the blob and keep billing for it.
  return jsonb_build_object('ok', true, 'storage_path', v_path);
end $$;

revoke all on function create_file(text, uuid, text, text, text, bigint, text, uuid)  from public, anon, authenticated;
revoke all on function set_file_content(text, uuid, text, text, int, text)            from public, anon, authenticated;
revoke all on function get_files(text, uuid, text, uuid, int)                         from public, anon, authenticated;
revoke all on function get_file(text, uuid)                                           from public, anon, authenticated;
revoke all on function search_files(text, uuid, text, int)                            from public, anon, authenticated;
revoke all on function delete_file(text, uuid)                                        from public, anon, authenticated;
grant execute on function create_file(text, uuid, text, text, text, bigint, text, uuid) to service_role;
grant execute on function set_file_content(text, uuid, text, text, int, text)           to service_role;
grant execute on function get_files(text, uuid, text, uuid, int)                        to service_role;
grant execute on function get_file(text, uuid)                                          to service_role;
grant execute on function search_files(text, uuid, text, int)                           to service_role;
grant execute on function delete_file(text, uuid)                                       to service_role;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0066_post_schedule.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0066_post_schedule.sql
-- Give posts a date, so Post Studio can have a calendar.
--
-- `posts` (0028) has status draft|in_review|approved|published but NO date at
-- all, so "when does this go out" was never answerable and the list could only
-- ever sort by updated_at. A social calendar is the view people actually plan
-- in — you need to see the month, not a list ordered by whoever edited last.
--
-- scheduled_at is nullable ON PURPOSE. A post with no date is a draft sitting in
-- the backlog, which is a real and common state; forcing a date at creation
-- would make every rough idea require a decision it isn't ready for. The
-- calendar shows dated posts, and an "Unscheduled" tray holds the rest.
--
-- Redefines get_posts / save_post IN FULL per the CRUD convention, plus a
-- dedicated set_post_schedule for drag-to-reschedule: dragging a card should not
-- have to round-trip the whole post body (which can carry an image URL and a
-- few kB of copy) just to move it one day.
-- Depends on 0028 (posts).
-- ============================================================================

alter table posts add column if not exists scheduled_at timestamptz;

-- Partial: most rows are dated once the workspace starts planning, but the
-- backlog never is, and there is no reason to index nulls.
create index if not exists idx_posts_scheduled on posts(workspace_id, scheduled_at)
  where scheduled_at is not null;

-- ── Payload ─────────────────────────────────────────────────────────────────
create or replace function post_payload(p posts)
returns jsonb language sql stable as $$
  select jsonb_build_object(
    'id', p.id, 'platform', p.platform, 'handle', p.handle, 'content', p.content,
    'image_url', p.image_url, 'status', p.status, 'share_token', p.share_token,
    'campaign_id', p.campaign_id, 'updated_at', p.updated_at,
    'scheduled_at', p.scheduled_at,
    'comments', coalesce((select jsonb_agg(jsonb_build_object(
      'id', c.id, 'author', c.author, 'body', c.body, 'x', c.x, 'y', c.y,
      'resolved', c.resolved, 'created_at', c.created_at
    ) order by c.created_at) from post_comments c where c.post_id = p.id), '[]'::jsonb)
  );
$$;

-- ── List ────────────────────────────────────────────────────────────────────
-- Ordered by schedule, nulls last: the calendar wants chronological order, and
-- the undated backlog belongs at the end rather than interleaved.
create or replace function get_posts(p_privy text, p_workspace uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
    'id', p.id, 'platform', p.platform, 'handle', p.handle, 'content', p.content,
    'image_url', p.image_url, 'status', p.status, 'updated_at', p.updated_at,
    'scheduled_at', p.scheduled_at, 'campaign_id', p.campaign_id,
    'comment_count', (select count(*) from post_comments c where c.post_id = p.id and not c.resolved)
  ) order by p.scheduled_at asc nulls last, p.updated_at desc)
  from posts p where p.workspace_id = p_workspace), '[]'::jsonb);
end $$;

-- ── Save ────────────────────────────────────────────────────────────────────
-- scheduled_at follows the branded-save convention from 0061: written only when
-- the key is PRESENT in the payload, so an editor saving copy cannot silently
-- clear a date it never knew about. Passing an explicit null unschedules.
create or replace function save_post(p_privy text, p_workspace uuid, p_id uuid, p_data jsonb)
returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid := p_id;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  if v_id is null then
    insert into posts (workspace_id, platform, handle, content, image_url, status, campaign_id, scheduled_at)
    values (p_workspace,
      coalesce(nullif(p_data->>'platform',''), 'instagram'), nullif(p_data->>'handle',''),
      coalesce(p_data->>'content',''), nullif(p_data->>'image_url',''),
      coalesce(nullif(p_data->>'status',''), 'draft'), nullif(p_data->>'campaign_id','')::uuid,
      nullif(p_data->>'scheduled_at','')::timestamptz)
    returning id into v_id;
  else
    update posts set
      platform  = coalesce(nullif(p_data->>'platform',''), platform),
      handle    = nullif(p_data->>'handle',''),
      content   = coalesce(p_data->>'content', content),
      image_url = nullif(p_data->>'image_url',''),
      status    = coalesce(nullif(p_data->>'status',''), status),
      campaign_id = nullif(p_data->>'campaign_id','')::uuid,
      scheduled_at = case when p_data ? 'scheduled_at'
                          then nullif(p_data->>'scheduled_at','')::timestamptz
                          else scheduled_at end
    where id = v_id and workspace_id = p_workspace;
  end if;
  return v_id;
end $$;

-- ── Reschedule ──────────────────────────────────────────────────────────────
/**
 * Move one post to a date, or back to the backlog with null.
 *
 * Separate from save_post because dragging a card across a calendar should not
 * round-trip the post body — that is a few kB of copy and an image URL travelling
 * both ways per drag, and any concurrent edit in another tab would be clobbered
 * by whatever the dragging client last read.
 */
create or replace function set_post_schedule(p_privy text, p_id uuid, p_at timestamptz)
returns boolean language plpgsql security definer set search_path = public as $$
declare v_ws uuid;
begin
  select workspace_id into v_ws from posts where id = p_id;
  if v_ws is null or not is_workspace_member(v_ws, p_privy) then
    raise exception 'NOT_FOUND_OR_FORBIDDEN';
  end if;
  update posts set scheduled_at = p_at where id = p_id;
  return true;
end $$;

revoke all on function set_post_schedule(text, uuid, timestamptz) from public, anon, authenticated;
grant execute on function set_post_schedule(text, uuid, timestamptz) to service_role;
-- get_posts/save_post keep the grants 0040 settled on: reachable only through
-- the /api/rpc proxy, which proves identity before calling as service_role.
revoke all on function get_posts(text, uuid) from public, anon, authenticated;
revoke all on function save_post(text, uuid, uuid, jsonb) from public, anon, authenticated;
grant execute on function get_posts(text, uuid) to service_role;
grant execute on function save_post(text, uuid, uuid, jsonb) to service_role;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0067_mind_maps.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0067_mind_maps.sql
-- Free-form canvases: boxes you move, connected by edges.
--
-- WHY ONE JSONB COLUMN, NOT nodes + edges TABLES.
-- A canvas is always loaded and saved WHOLE — you open a map, drag things, and
-- the client holds the entire graph in memory the whole time. Nothing ever
-- queries "all nodes at x > 400" or joins an edge to another table. Normalising
-- would buy referential integrity we don't need and cost a multi-statement
-- write on every save, where a single jsonb assignment is atomic for free.
--
-- The shape is React Flow's own ({ nodes: [...], edges: [...] }) so the client
-- can hand it straight to the canvas and back without a translation layer that
-- would have to be kept in sync with the library.
--
-- Guarded, not trusted: the graph is client-authored, so save_mind_map checks
-- it is an object with array members and caps its size. Without that, one bad
-- client could write a 40 MB row that every subsequent open has to download.
-- Depends on 0001 (workspaces).
-- ============================================================================

create table if not exists mind_maps (
  id           uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspaces(id) on delete cascade,
  title        text not null default 'Untitled map',
  -- { nodes: [...], edges: [...] } — React Flow's own shape.
  graph        jsonb not null default '{"nodes":[],"edges":[]}'::jsonb,
  created_by   text,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);

create index if not exists idx_mind_maps_ws on mind_maps(workspace_id, updated_at desc);

alter table mind_maps enable row level security;
revoke all on table mind_maps from anon, authenticated;

-- ── List ────────────────────────────────────────────────────────────────────
-- Deliberately does NOT return `graph`: a list of ten maps would otherwise ship
-- ten full canvases to render ten titles. Counts come from jsonb_array_length,
-- so the card can say "12 boxes" without the payload.
create or replace function get_mind_maps(p_privy text, p_workspace uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((select jsonb_agg(to_jsonb(x) order by x.updated_at desc) from (
    select m.id, m.title, m.created_at, m.updated_at,
           coalesce(jsonb_array_length(m.graph->'nodes'), 0) as node_count,
           coalesce(jsonb_array_length(m.graph->'edges'), 0) as edge_count
    from mind_maps m
    where m.workspace_id = p_workspace
    order by m.updated_at desc
  ) x), '[]'::jsonb);
end $$;

create or replace function get_mind_map(p_privy text, p_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_ws uuid; v_out jsonb;
begin
  select workspace_id into v_ws from mind_maps where id = p_id;
  if v_ws is null or not is_workspace_member(v_ws, p_privy) then
    raise exception 'NOT_FOUND_OR_FORBIDDEN';
  end if;
  select jsonb_build_object('id', m.id, 'title', m.title, 'graph', m.graph,
                            'updated_at', m.updated_at)
    into v_out from mind_maps m where m.id = p_id;
  return v_out;
end $$;

create or replace function create_mind_map(p_privy text, p_workspace uuid, p_title text default null)
returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  insert into mind_maps (workspace_id, title, created_by)
  values (p_workspace, coalesce(nullif(trim(p_title), ''), 'Untitled map'), p_privy)
  returning id into v_id;
  return v_id;
end $$;

-- ── Save ────────────────────────────────────────────────────────────────────
/**
 * Persist the canvas.
 *
 * Title and graph are BOTH optional and each is written only when supplied, so
 * renaming a map does not have to send the graph and an autosaving canvas does
 * not have to send the title.
 *
 * The size cap is the real guard here. `graph` is written by the browser, so
 * without a ceiling a runaway client (or a paste of something enormous) writes a
 * row that every later open has to download. 2 MB is far beyond any hand-drawn
 * map and far below a problem.
 */
create or replace function save_mind_map(
  p_privy text, p_id uuid, p_graph jsonb default null, p_title text default null
) returns boolean language plpgsql security definer set search_path = public as $$
declare v_ws uuid;
begin
  select workspace_id into v_ws from mind_maps where id = p_id;
  if v_ws is null or not is_workspace_member(v_ws, p_privy) then
    raise exception 'NOT_FOUND_OR_FORBIDDEN';
  end if;

  if p_graph is not null then
    -- Shape check: the canvas reads graph.nodes / graph.edges and would break on
    -- anything else, so refuse it here rather than store a row that cannot open.
    if jsonb_typeof(p_graph) <> 'object'
       or jsonb_typeof(p_graph->'nodes') <> 'array'
       or jsonb_typeof(p_graph->'edges') <> 'array' then
      raise exception 'BAD_GRAPH';
    end if;
    if pg_column_size(p_graph) > 2 * 1024 * 1024 then raise exception 'GRAPH_TOO_LARGE'; end if;
  end if;

  update mind_maps set
    graph      = coalesce(p_graph, graph),
    title      = coalesce(nullif(trim(p_title), ''), title),
    updated_at = now()
  where id = p_id;
  return true;
end $$;

create or replace function delete_mind_map(p_privy text, p_id uuid)
returns boolean language plpgsql security definer set search_path = public as $$
declare v_ws uuid;
begin
  select workspace_id into v_ws from mind_maps where id = p_id;
  if v_ws is null or not is_workspace_member(v_ws, p_privy) then
    raise exception 'NOT_FOUND_OR_FORBIDDEN';
  end if;
  delete from mind_maps where id = p_id;
  return true;
end $$;

revoke all on function get_mind_maps(text, uuid)                       from public, anon, authenticated;
revoke all on function get_mind_map(text, uuid)                        from public, anon, authenticated;
revoke all on function create_mind_map(text, uuid, text)               from public, anon, authenticated;
revoke all on function save_mind_map(text, uuid, jsonb, text)          from public, anon, authenticated;
revoke all on function delete_mind_map(text, uuid)                     from public, anon, authenticated;
grant execute on function get_mind_maps(text, uuid)                    to service_role;
grant execute on function get_mind_map(text, uuid)                     to service_role;
grant execute on function create_mind_map(text, uuid, text)            to service_role;
grant execute on function save_mind_map(text, uuid, jsonb, text)       to service_role;
grant execute on function delete_mind_map(text, uuid)                  to service_role;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0068_skills.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter Platform Core — 0068_skills.sql
-- SKILLS: reusable instruction packs that can be attached to any agent.
--
-- An agent's `instructions` answer "who are you". A skill answers "how does
-- this company do X" — the invoice numbering scheme, the tone of a reminder,
-- which categories map to which cost centre. That knowledge is per-company,
-- outlives any one agent, and belongs to more than one of them, so it cannot
-- live inside a single agent's prompt.
--
-- Skills can be written in the app or imported from a public GitHub repository
-- (SKILL.md files with YAML frontmatter — the Anthropic skill format). An
-- imported skill is THIRD-PARTY TEXT that ends up in a system prompt, so:
--   • import writes nothing on its own — /api/skills/import returns a preview
--     and a human saves what they chose;
--   • `source`/`source_url` are kept so an imported skill stays identifiable;
--   • suggested_tools is a HINT for the builder UI, never a grant. The runner
--     intersects it with the agent's allowed_tools, so attaching a skill can
--     never widen what an agent may touch. See lib/agents/runner.ts.
--
-- Additive, idempotent & prod-safe. Depends on 0043 (agents). Run AFTER it.
-- ============================================================================

create table if not exists skills (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspaces(id) on delete cascade,
  name text not null default 'New skill',
  description text not null default '',          -- one line, shown in the picker
  instructions text not null default '',         -- the pack itself
  suggested_tools text[] not null default '{}',  -- a hint, never a grant
  source text not null default 'local' check (source in ('local', 'github')),
  source_url text not null default '',
  created_by_privy text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists idx_skills_ws on skills(workspace_id, updated_at desc);
drop trigger if exists trg_skills_upd on skills;
create trigger trg_skills_upd before update on skills for each row execute function set_updated_at();
alter table skills enable row level security;

-- Which skills an agent carries. An array rather than a join table: the list is
-- short, always read in full with the agent, and never queried from the skill
-- side. `on delete cascade` cannot reach into an array, so deleting a skill
-- prunes the references explicitly (see delete_skill below).
alter table agents add column if not exists skill_ids uuid[] not null default '{}';

-- ── Skill CRUD (client-facing, via the /api/rpc verified proxy) ───────────────
create or replace function get_skills(p_privy text, p_workspace uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((select jsonb_agg(to_jsonb(s) order by s.updated_at desc) from (
    select id, name, description, instructions, suggested_tools, source, source_url, updated_at
    from skills where workspace_id = p_workspace
  ) s), '[]'::jsonb);
end $$;
grant execute on function get_skills(text, uuid) to authenticated, anon;

create or replace function save_skill(
  p_privy text, p_workspace uuid, p_id uuid, p_name text, p_description text,
  p_instructions text, p_suggested_tools text[], p_source text, p_source_url text
) returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  -- A skill body becomes part of a system prompt; an unbounded one would blow
  -- the context window of every agent carrying it, so it is capped here rather
  -- than only in the UI (the RPC is reachable without the UI).
  if length(coalesce(p_instructions, '')) > 20000 then raise exception 'SKILL_TOO_LARGE'; end if;
  if p_id is null then
    insert into skills (workspace_id, name, description, instructions, suggested_tools,
                        source, source_url, created_by_privy)
    values (p_workspace, coalesce(nullif(p_name, ''), 'New skill'), coalesce(p_description, ''),
            coalesce(p_instructions, ''), coalesce(p_suggested_tools, '{}'),
            case when p_source in ('local', 'github') then p_source else 'local' end,
            coalesce(p_source_url, ''), p_privy)
    returning id into v_id;
  else
    update skills set
      name = coalesce(nullif(p_name, ''), name),
      description = coalesce(p_description, description),
      instructions = coalesce(p_instructions, instructions),
      suggested_tools = coalesce(p_suggested_tools, suggested_tools)
    where id = p_id and workspace_id = p_workspace
    returning id into v_id;
  end if;
  return v_id;
end $$;
grant execute on function save_skill(text, uuid, uuid, text, text, text, text[], text, text) to authenticated, anon;

create or replace function delete_skill(p_privy text, p_workspace uuid, p_id uuid)
returns boolean language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  delete from skills where id = p_id and workspace_id = p_workspace;
  if not found then return false; end if;
  -- Prune the dangling reference. Without this an agent keeps an id that
  -- resolves to nothing, and the runner would silently drop a skill the UI
  -- still shows as attached.
  update agents set skill_ids = array_remove(skill_ids, p_id)
   where workspace_id = p_workspace and p_id = any(skill_ids);
  return true;
end $$;
grant execute on function delete_skill(text, uuid, uuid) to authenticated, anon;

-- ── save_agent, extended with skill_ids ───────────────────────────────────────
-- Adding a parameter creates an OVERLOAD rather than replacing the function, so
-- the twelve-argument version is dropped first. Anon EXECUTE is revoked (0046)
-- and every caller goes through /api/rpc, so there is no third-party caller
-- pinned to the old signature.
drop function if exists save_agent(text, uuid, uuid, text, text, text, text, text, text[], text[], text, int);

create or replace function save_agent(
  p_privy text, p_workspace uuid, p_id uuid, p_name text, p_role text, p_instructions text,
  p_provider text, p_model text, p_allowed_tools text[], p_allowed_objects text[],
  p_autonomy text, p_max_steps int, p_skill_ids uuid[] default '{}'
) returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid; v_skills uuid[];
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  -- Only ids that are real skills IN THIS WORKSPACE survive. Otherwise a caller
  -- could staple another tenant's skill id onto their agent and have the runner
  -- read it back by id.
  select coalesce(array_agg(s.id), '{}') into v_skills
    from skills s where s.workspace_id = p_workspace and s.id = any(coalesce(p_skill_ids, '{}'));

  if p_id is null then
    insert into agents (workspace_id, name, role, instructions, provider, model,
      allowed_tools, allowed_objects, autonomy, max_steps, skill_ids, created_by_privy)
    values (p_workspace, coalesce(nullif(p_name,''),'New agent'), p_role, p_instructions,
      coalesce(p_provider,''), coalesce(p_model,''),
      coalesce(p_allowed_tools, '{list_objects,list_records,search_records,get_record}'),
      coalesce(p_allowed_objects, '{}'),
      coalesce(nullif(p_autonomy,''),'suggest'), coalesce(p_max_steps,12), v_skills, p_privy)
    returning id into v_id;
  else
    update agents set name = p_name, role = p_role, instructions = p_instructions,
      provider = coalesce(p_provider,''), model = coalesce(p_model,''),
      allowed_tools = coalesce(p_allowed_tools, allowed_tools),
      allowed_objects = coalesce(p_allowed_objects, allowed_objects),
      autonomy = coalesce(nullif(p_autonomy,''), autonomy), max_steps = coalesce(p_max_steps, max_steps),
      skill_ids = v_skills
    where id = p_id and workspace_id = p_workspace
    returning id into v_id;
  end if;
  return v_id;
end $$;
grant execute on function save_agent(text, uuid, uuid, text, text, text, text, text, text[], text[], text, int, uuid[]) to authenticated, anon;

-- get_agents must return skill_ids or the editor reopens with the skills blank
-- and the next save silently detaches every one of them.
create or replace function get_agents(p_privy text, p_workspace uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((select jsonb_agg(to_jsonb(a) order by a.updated_at desc) from (
    select id, name, role, instructions, provider, model, allowed_tools, allowed_objects,
           autonomy, max_steps, skill_ids, enabled, updated_at
    from agents where workspace_id = p_workspace
  ) a), '[]'::jsonb);
end $$;
grant execute on function get_agents(text, uuid) to authenticated, anon;

-- ── Runner-side read (service_role; /api/agents/run composes the prompt) ──────
create or replace function get_agent_skills(p_workspace uuid, p_ids uuid[])
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  return coalesce((select jsonb_agg(to_jsonb(s) order by s.name) from (
    select id, name, description, instructions, suggested_tools
    from skills where workspace_id = p_workspace and id = any(coalesce(p_ids, '{}'))
  ) s), '[]'::jsonb);
end $$;
revoke all on function get_agent_skills(uuid, uuid[]) from public, authenticated, anon;
grant execute on function get_agent_skills(uuid, uuid[]) to service_role;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0069_post_board.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0069_post_board.sql
-- Post Studio board: the whole content plan on one canvas, posts you drag and
-- connect. A campaign is a sequence — teaser, launch, follow-up — and neither
-- the calendar nor the grid can show that a post EXISTS BECAUSE of another one.
--
-- WHY POSITIONS, NOT NODES.
-- 0067 stores mind maps as React Flow's whole { nodes, edges } graph, because
-- there a node IS the content. Here a node is a POST — a real row that the
-- calendar, the grid and the share link all read. If the board stored nodes
-- too, every edit would have to be written twice and the two copies would drift
-- the first time someone renamed a post from the calendar.
--
-- So the board stores only what the posts themselves cannot: a position per
-- post id, plus the edges between them. Nodes are derived from the live post
-- list on every open. That makes the board self-healing — a post deleted
-- anywhere simply stops being drawn, and a post created anywhere shows up
-- needing a place — with no cleanup job and no possibility of a stale card.
--
-- One board per workspace: this is the marketing team's shared plan, not a
-- document you make several of.
-- Depends on 0001 (workspaces) and 0028 (posts).
-- ============================================================================

create table if not exists post_boards (
  workspace_id uuid primary key references workspaces(id) on delete cascade,
  -- { positions: { "<post_id>": { "x": 0, "y": 0 } }, edges: [ ...React Flow edges ] }
  graph        jsonb not null default '{"positions":{},"edges":[]}'::jsonb,
  updated_at   timestamptz not null default now(),
  updated_by   text
);

alter table post_boards enable row level security;
revoke all on table post_boards from anon, authenticated;

create or replace function get_post_board(p_privy text, p_workspace uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  -- A workspace that has never opened the board has no row; an empty graph is
  -- the correct answer, not an error, so the canvas opens with everything
  -- auto-placed instead of showing a failure.
  return coalesce(
    (select b.graph from post_boards b where b.workspace_id = p_workspace),
    '{"positions":{},"edges":[]}'::jsonb
  );
end $$;
grant execute on function get_post_board(text, uuid) to authenticated, anon;

create or replace function save_post_board(p_privy text, p_workspace uuid, p_graph jsonb)
returns boolean language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;

  -- Client-authored, so guarded rather than trusted — same reasoning as
  -- save_mind_map (0067). Without the cap one bad client could write a row that
  -- every subsequent open has to download.
  if p_graph is null
     or jsonb_typeof(p_graph) <> 'object'
     or jsonb_typeof(coalesce(p_graph->'positions', '{}'::jsonb)) <> 'object'
     or jsonb_typeof(coalesce(p_graph->'edges', '[]'::jsonb)) <> 'array'
  then raise exception 'BAD_GRAPH'; end if;
  if pg_column_size(p_graph) > 1048576 then raise exception 'GRAPH_TOO_LARGE'; end if;

  insert into post_boards (workspace_id, graph, updated_at, updated_by)
  values (p_workspace, p_graph, now(), p_privy)
  on conflict (workspace_id) do update
    set graph = excluded.graph, updated_at = now(), updated_by = excluded.updated_by;
  return true;
end $$;
grant execute on function save_post_board(text, uuid, jsonb) to authenticated, anon;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0070_newsletters.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0070_newsletters.sql
-- Newsletters: lists, subscribers, campaigns, and per-recipient delivery.
--
-- A native implementation of ideas listmonk proved out. NOT a port: listmonk is
-- AGPL-3.0, so copying its code would oblige us to relicense this whole product
-- away from MIT. Schema concepts are not copyrightable; the code is.
--
-- FOUR DECISIONS THAT SHAPE EVERYTHING BELOW
--
-- 1. A subscriber is an EMAIL ADDRESS, not a person. `people` holds humans in
--    the CRM; one human can hold two addresses, and a newsletter signup must not
--    silently manufacture a CRM contact. So subscribers key on
--    (workspace_id, email) and carry a nullable person_id to join the two when
--    they really are the same party.
--
-- 2. Consent is a RECORD, not a boolean. Under GDPR the obligation is to
--    demonstrate consent, and `subscribed = true` proves nothing about where it
--    came from. consent_source / consent_at / consent_ip are that proof.
--
-- 3. ONE DELIVERY ROW PER (newsletter, subscriber), UNIQUE. This is the most
--    important constraint in the file. It makes a send resumable after a crash
--    and makes double-sending structurally impossible rather than merely
--    unlikely — the worst failure a mailing tool has, because it is public,
--    irreversible, and lands in every customer's inbox at once.
--
-- 4. Unsubscribe needs no login. An unguessable per-subscriber token, because
--    Gmail and Yahoo require one-click unsubscribe from bulk senders and
--    deliverability collapses without it.
--
-- Additive, idempotent & prod-safe. Depends on 0001 (workspaces) and the
-- `people` table. Run AFTER 0069.
-- ============================================================================

create extension if not exists pgcrypto;

-- ── Lists ────────────────────────────────────────────────────────────────────
create table if not exists newsletter_lists (
  id           uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspaces(id) on delete cascade,
  name         text not null default 'New list',
  description  text not null default '',
  -- 'single' = subscribed on submit. 'double' = must click a confirmation link.
  opt_in       text not null default 'single' check (opt_in in ('single', 'double')),
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);
create index if not exists idx_nl_lists_ws on newsletter_lists(workspace_id, updated_at desc);
drop trigger if exists trg_nl_lists_upd on newsletter_lists;
create trigger trg_nl_lists_upd before update on newsletter_lists for each row execute function set_updated_at();
alter table newsletter_lists enable row level security;
revoke all on table newsletter_lists from anon, authenticated;

-- ── Subscribers ──────────────────────────────────────────────────────────────
create table if not exists newsletter_subscribers (
  id            uuid primary key default gen_random_uuid(),
  workspace_id  uuid not null references workspaces(id) on delete cascade,
  email         text not null,
  name          text not null default '',
  -- Nullable on purpose: a subscriber need not be in the CRM. set null on
  -- delete so removing a contact does not silently drop them off a mailing list
  -- they consented to — that would be a compliance problem, not a tidy-up.
  person_id     uuid references people(id) on delete set null,

  -- enabled  → mailable
  -- unconfirmed → double opt-in pending; NEVER mailed a campaign
  -- unsubscribed → they asked to stop
  -- bounced / complained → the provider told us to stop; treated as permanent
  status        text not null default 'enabled'
                check (status in ('enabled', 'unconfirmed', 'unsubscribed', 'bounced', 'complained')),

  -- Proof of consent, not just its existence.
  consent_source text not null default '',      -- 'form:<id>' | 'import' | 'manual' | 'api'
  consent_at     timestamptz,
  consent_ip     text,

  -- Unguessable. Used for one-click unsubscribe and double opt-in confirmation,
  -- so it must never be derivable from the email address.
  token         text not null default replace(gen_random_uuid()::text, '-', '') ,

  attribs       jsonb not null default '{}'::jsonb,   -- merge fields for templates
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

-- Case-insensitive uniqueness per workspace: "A@x.com" and "a@x.com" are the
-- same inbox, and importing a CSV twice with different casing must not create a
-- second subscriber who then receives everything twice.
create unique index if not exists uq_nl_subs_ws_email on newsletter_subscribers(workspace_id, lower(email));
create unique index if not exists uq_nl_subs_token on newsletter_subscribers(token);
create index if not exists idx_nl_subs_ws on newsletter_subscribers(workspace_id, status);
drop trigger if exists trg_nl_subs_upd on newsletter_subscribers;
create trigger trg_nl_subs_upd before update on newsletter_subscribers for each row execute function set_updated_at();
alter table newsletter_subscribers enable row level security;
revoke all on table newsletter_subscribers from anon, authenticated;

-- ── Membership ───────────────────────────────────────────────────────────────
create table if not exists newsletter_list_subscribers (
  list_id       uuid not null references newsletter_lists(id) on delete cascade,
  subscriber_id uuid not null references newsletter_subscribers(id) on delete cascade,
  created_at    timestamptz not null default now(),
  primary key (list_id, subscriber_id)
);
create index if not exists idx_nl_ls_sub on newsletter_list_subscribers(subscriber_id);
alter table newsletter_list_subscribers enable row level security;
revoke all on table newsletter_list_subscribers from anon, authenticated;

-- ── Newsletters (the campaigns) ──────────────────────────────────────────────
create table if not exists newsletters (
  id           uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspaces(id) on delete cascade,
  subject      text not null default '',
  -- Shown after the subject in most clients. Its own field because leaving it
  -- unset makes the client scrape the first body line, which is usually
  -- "View in browser".
  preheader    text not null default '',
  template     text not null default 'plain' check (template in ('plain', 'announcement', 'digest')),
  content      jsonb not null default '{}'::jsonb,   -- template-shaped blocks
  from_name    text not null default '',
  reply_to     text not null default '',

  status       text not null default 'draft'
               check (status in ('draft', 'scheduled', 'sending', 'sent', 'paused', 'cancelled')),
  scheduled_at timestamptz,
  started_at   timestamptz,
  finished_at  timestamptz,

  created_by_privy text,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);
create index if not exists idx_newsletters_ws on newsletters(workspace_id, updated_at desc);
-- The send cron's lookup: what is due right now.
create index if not exists idx_newsletters_due on newsletters(status, scheduled_at)
  where status in ('scheduled', 'sending');
drop trigger if exists trg_newsletters_upd on newsletters;
create trigger trg_newsletters_upd before update on newsletters for each row execute function set_updated_at();
alter table newsletters enable row level security;
revoke all on table newsletters from anon, authenticated;

create table if not exists newsletter_targets (
  newsletter_id uuid not null references newsletters(id) on delete cascade,
  list_id       uuid not null references newsletter_lists(id) on delete cascade,
  primary key (newsletter_id, list_id)
);
alter table newsletter_targets enable row level security;
revoke all on table newsletter_targets from anon, authenticated;

-- ── Deliveries — the table that makes sends safe ─────────────────────────────
create table if not exists newsletter_deliveries (
  id            uuid primary key default gen_random_uuid(),
  workspace_id  uuid not null references workspaces(id) on delete cascade,
  newsletter_id uuid not null references newsletters(id) on delete cascade,
  subscriber_id uuid not null references newsletter_subscribers(id) on delete cascade,
  -- Snapshotted, not joined. If a subscriber later changes their address, the
  -- record of where this send actually WENT must not change with it.
  email         text not null,
  status        text not null default 'pending'
                check (status in ('pending', 'sent', 'failed', 'skipped')),
  provider_id   text,          -- Resend's id, for reconciling bounces later
  error         text,
  sent_at       timestamptz,
  created_at    timestamptz not null default now()
);
-- THE constraint. One row per recipient per newsletter — a retry after a crash
-- can only ever update a row, never create a second send.
create unique index if not exists uq_nl_deliveries on newsletter_deliveries(newsletter_id, subscriber_id);
create index if not exists idx_nl_deliveries_claim on newsletter_deliveries(newsletter_id, status);
alter table newsletter_deliveries enable row level security;
revoke all on table newsletter_deliveries from anon, authenticated;

-- ── Events (opens / clicks / unsubscribes) ───────────────────────────────────
create table if not exists newsletter_events (
  id            uuid primary key default gen_random_uuid(),
  workspace_id  uuid not null references workspaces(id) on delete cascade,
  newsletter_id uuid references newsletters(id) on delete cascade,
  subscriber_id uuid references newsletter_subscribers(id) on delete set null,
  kind          text not null check (kind in ('open', 'click', 'unsubscribe', 'bounce', 'complaint')),
  url           text,
  created_at    timestamptz not null default now()
);
create index if not exists idx_nl_events_nl on newsletter_events(newsletter_id, kind);
create index if not exists idx_nl_events_ws on newsletter_events(workspace_id, created_at desc);
alter table newsletter_events enable row level security;
revoke all on table newsletter_events from anon, authenticated;

-- ============================================================================
-- RPCs (client-facing, through the /api/rpc verified proxy)
-- ============================================================================

create or replace function get_newsletter_lists(p_privy text, p_workspace uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((select jsonb_agg(to_jsonb(x) order by x.name) from (
    select l.id, l.name, l.description, l.opt_in, l.updated_at,
           -- Only mailable members are counted. Showing a total that includes
           -- unsubscribed and bounced addresses would overstate reach on the
           -- exact screen someone uses to decide whether a send is worth it.
           (select count(*) from newsletter_list_subscribers ls
              join newsletter_subscribers s on s.id = ls.subscriber_id
             where ls.list_id = l.id and s.status = 'enabled') as subscriber_count
    from newsletter_lists l where l.workspace_id = p_workspace
  ) x), '[]'::jsonb);
end $$;
grant execute on function get_newsletter_lists(text, uuid) to authenticated, anon;

create or replace function save_newsletter_list(
  p_privy text, p_workspace uuid, p_id uuid, p_name text, p_description text, p_opt_in text
) returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  if p_id is null then
    insert into newsletter_lists (workspace_id, name, description, opt_in)
    values (p_workspace, coalesce(nullif(p_name,''),'New list'), coalesce(p_description,''),
            case when p_opt_in in ('single','double') then p_opt_in else 'single' end)
    returning id into v_id;
  else
    update newsletter_lists set
      name = coalesce(nullif(p_name,''), name),
      description = coalesce(p_description, description),
      opt_in = case when p_opt_in in ('single','double') then p_opt_in else opt_in end
    where id = p_id and workspace_id = p_workspace
    returning id into v_id;
  end if;
  return v_id;
end $$;
grant execute on function save_newsletter_list(text, uuid, uuid, text, text, text) to authenticated, anon;

create or replace function delete_newsletter_list(p_privy text, p_workspace uuid, p_id uuid)
returns boolean language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  delete from newsletter_lists where id = p_id and workspace_id = p_workspace;
  return found;
end $$;
grant execute on function delete_newsletter_list(text, uuid, uuid) to authenticated, anon;

-- Paged: a list can hold six figures of addresses, and get_* returning all of
-- them would build one enormous jsonb per screen render.
create or replace function get_newsletter_subscribers(
  p_privy text, p_workspace uuid, p_list uuid default null,
  p_query text default null, p_limit int default 50, p_offset int default 0
) returns jsonb language plpgsql security definer set search_path = public as $$
declare v_rows jsonb; v_total bigint; v_lim int; v_off int;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  v_lim := greatest(1, least(coalesce(p_limit, 50), 200));
  v_off := greatest(0, coalesce(p_offset, 0));

  select count(*) into v_total
    from newsletter_subscribers s
   where s.workspace_id = p_workspace
     and (p_list is null or exists (select 1 from newsletter_list_subscribers ls
                                     where ls.subscriber_id = s.id and ls.list_id = p_list))
     and (p_query is null or p_query = '' or s.email ilike '%'||p_query||'%' or s.name ilike '%'||p_query||'%');

  select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc), '[]'::jsonb) into v_rows from (
    select s.id, s.email, s.name, s.status, s.person_id, s.consent_source, s.consent_at, s.created_at
      from newsletter_subscribers s
     where s.workspace_id = p_workspace
       and (p_list is null or exists (select 1 from newsletter_list_subscribers ls
                                       where ls.subscriber_id = s.id and ls.list_id = p_list))
       and (p_query is null or p_query = '' or s.email ilike '%'||p_query||'%' or s.name ilike '%'||p_query||'%')
     order by s.created_at desc
     limit v_lim offset v_off
  ) x;

  return jsonb_build_object('rows', v_rows, 'total', v_total);
end $$;
grant execute on function get_newsletter_subscribers(text, uuid, uuid, text, int, int) to authenticated, anon;

/**
 * Add or update one subscriber and put them on a list.
 *
 * Idempotent by (workspace, lower(email)), which is what makes a re-imported CSV
 * safe. Two rules that look like edge cases and are not:
 *   • An existing UNSUBSCRIBED/BOUNCED/COMPLAINED subscriber is NEVER silently
 *     re-enabled by an import. Someone who opted out must not be opted back in
 *     by uploading an old spreadsheet — that is the mechanism by which mailing
 *     tools generate complaints and get their domain blocked.
 *   • Consent fields are only written when the row is created, so a later import
 *     cannot overwrite the original proof of where consent came from.
 */
create or replace function upsert_newsletter_subscriber(
  p_privy text, p_workspace uuid, p_email text, p_name text default '',
  p_list uuid default null, p_source text default 'manual', p_ip text default null,
  p_status text default 'enabled'
) returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid; v_existing text;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  if coalesce(p_email,'') !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then
    raise exception 'BAD_EMAIL';
  end if;

  select id, status into v_id, v_existing
    from newsletter_subscribers
   where workspace_id = p_workspace and lower(email) = lower(p_email);

  if v_id is null then
    insert into newsletter_subscribers (workspace_id, email, name, status, consent_source, consent_at, consent_ip)
    values (p_workspace, p_email, coalesce(p_name,''),
            case when p_status in ('enabled','unconfirmed') then p_status else 'enabled' end,
            coalesce(p_source,'manual'), now(), p_ip)
    returning id into v_id;
  else
    update newsletter_subscribers
       set name = case when coalesce(p_name,'') <> '' then p_name else name end
     where id = v_id;
    -- deliberately no status change here; see the note above.
  end if;

  if p_list is not null then
    insert into newsletter_list_subscribers (list_id, subscriber_id)
    values (p_list, v_id) on conflict do nothing;
  end if;
  return v_id;
end $$;
grant execute on function upsert_newsletter_subscriber(text, uuid, text, text, uuid, text, text, text) to authenticated, anon;

create or replace function set_newsletter_subscriber_status(
  p_privy text, p_workspace uuid, p_id uuid, p_status text
) returns boolean language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  if p_status not in ('enabled','unconfirmed','unsubscribed','bounced','complained') then
    raise exception 'BAD_STATUS';
  end if;
  update newsletter_subscribers set status = p_status
   where id = p_id and workspace_id = p_workspace;
  return found;
end $$;
grant execute on function set_newsletter_subscriber_status(text, uuid, uuid, text) to authenticated, anon;

create or replace function delete_newsletter_subscriber(p_privy text, p_workspace uuid, p_id uuid)
returns boolean language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  delete from newsletter_subscribers where id = p_id and workspace_id = p_workspace;
  return found;
end $$;
grant execute on function delete_newsletter_subscriber(text, uuid, uuid) to authenticated, anon;

-- ── Newsletters ──────────────────────────────────────────────────────────────
create or replace function get_newsletters(p_privy text, p_workspace uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((select jsonb_agg(to_jsonb(x) order by x.updated_at desc) from (
    select n.id, n.subject, n.preheader, n.template, n.status, n.scheduled_at,
           n.started_at, n.finished_at, n.updated_at,
           (select count(*) from newsletter_deliveries d where d.newsletter_id = n.id and d.status = 'sent') as sent_count,
           (select count(distinct e.subscriber_id) from newsletter_events e
             where e.newsletter_id = n.id and e.kind = 'open') as open_count,
           (select count(distinct e.subscriber_id) from newsletter_events e
             where e.newsletter_id = n.id and e.kind = 'click') as click_count,
           coalesce((select jsonb_agg(t.list_id) from newsletter_targets t where t.newsletter_id = n.id), '[]'::jsonb) as list_ids
    from newsletters n where n.workspace_id = p_workspace
  ) x), '[]'::jsonb);
end $$;
grant execute on function get_newsletters(text, uuid) to authenticated, anon;

create or replace function get_newsletter(p_privy text, p_workspace uuid, p_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v jsonb;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  select to_jsonb(n) || jsonb_build_object(
    'list_ids', coalesce((select jsonb_agg(t.list_id) from newsletter_targets t where t.newsletter_id = n.id), '[]'::jsonb)
  ) into v from newsletters n where n.id = p_id and n.workspace_id = p_workspace;
  return v;
end $$;
grant execute on function get_newsletter(text, uuid, uuid) to authenticated, anon;

/**
 * Save a draft. Refuses to edit a newsletter that is already sending or sent —
 * changing the subject of a half-delivered send would mean two different emails
 * going out under one record, and the audit trail would describe neither.
 */
create or replace function save_newsletter(
  p_privy text, p_workspace uuid, p_id uuid, p_subject text, p_preheader text,
  p_template text, p_content jsonb, p_from_name text, p_reply_to text, p_list_ids uuid[]
) returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid; v_status text;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  if pg_column_size(coalesce(p_content, '{}'::jsonb)) > 524288 then raise exception 'CONTENT_TOO_LARGE'; end if;

  if p_id is null then
    insert into newsletters (workspace_id, subject, preheader, template, content, from_name, reply_to, created_by_privy)
    values (p_workspace, coalesce(p_subject,''), coalesce(p_preheader,''),
            case when p_template in ('plain','announcement','digest') then p_template else 'plain' end,
            coalesce(p_content,'{}'::jsonb), coalesce(p_from_name,''), coalesce(p_reply_to,''), p_privy)
    returning id into v_id;
  else
    select status into v_status from newsletters where id = p_id and workspace_id = p_workspace;
    if v_status is null then return null; end if;
    if v_status in ('sending','sent') then raise exception 'ALREADY_SENT'; end if;
    update newsletters set
      subject = coalesce(p_subject, subject), preheader = coalesce(p_preheader, preheader),
      template = case when p_template in ('plain','announcement','digest') then p_template else template end,
      content = coalesce(p_content, content),
      from_name = coalesce(p_from_name, from_name), reply_to = coalesce(p_reply_to, reply_to)
    where id = p_id and workspace_id = p_workspace
    returning id into v_id;
  end if;

  if p_list_ids is not null then
    delete from newsletter_targets where newsletter_id = v_id;
    -- Only lists in THIS workspace survive, so a foreign list id cannot be
    -- stapled on to make a send reach another tenant's subscribers.
    insert into newsletter_targets (newsletter_id, list_id)
    select v_id, l.id from newsletter_lists l
     where l.workspace_id = p_workspace and l.id = any(p_list_ids)
    on conflict do nothing;
  end if;
  return v_id;
end $$;
grant execute on function save_newsletter(text, uuid, uuid, text, text, text, jsonb, text, text, uuid[]) to authenticated, anon;

create or replace function delete_newsletter(p_privy text, p_workspace uuid, p_id uuid)
returns boolean language plpgsql security definer set search_path = public as $$
declare v_status text;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  select status into v_status from newsletters where id = p_id and workspace_id = p_workspace;
  if v_status is null then return false; end if;
  -- A sent newsletter is a record of something that reached real inboxes. It is
  -- kept so the delivery and event history stays explicable.
  if v_status in ('sending','sent') then raise exception 'ALREADY_SENT'; end if;
  delete from newsletters where id = p_id and workspace_id = p_workspace;
  return true;
end $$;
grant execute on function delete_newsletter(text, uuid, uuid) to authenticated, anon;

/**
 * Queue a send: materialise one delivery row per mailable recipient, then mark
 * the newsletter scheduled.
 *
 * Materialising up front rather than resolving recipients at send time is what
 * makes the audience a FACT about this send. If it were resolved per batch, a
 * subscriber added halfway through would get an email from a campaign that had
 * already "finished", and the sent count would never agree with the list count.
 *
 * Only 'enabled' subscribers are queued — unconfirmed (double opt-in pending),
 * unsubscribed, bounced and complained are all excluded here rather than being
 * filtered later, so the queue itself is the audience.
 */
create or replace function queue_newsletter(
  p_privy text, p_workspace uuid, p_id uuid, p_when timestamptz default null
) returns jsonb language plpgsql security definer set search_path = public as $$
declare v_status text; v_n int;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  select status into v_status from newsletters where id = p_id and workspace_id = p_workspace;
  if v_status is null then raise exception 'NOT_FOUND'; end if;
  if v_status in ('sending','sent') then raise exception 'ALREADY_SENT'; end if;
  if not exists (select 1 from newsletter_targets where newsletter_id = p_id) then raise exception 'NO_LISTS'; end if;

  insert into newsletter_deliveries (workspace_id, newsletter_id, subscriber_id, email)
  select distinct p_workspace, p_id, s.id, s.email
    from newsletter_targets t
    join newsletter_list_subscribers ls on ls.list_id = t.list_id
    join newsletter_subscribers s on s.id = ls.subscriber_id
   where t.newsletter_id = p_id
     and s.workspace_id = p_workspace
     and s.status = 'enabled'
  on conflict (newsletter_id, subscriber_id) do nothing;

  get diagnostics v_n = row_count;

  update newsletters
     set status = 'scheduled', scheduled_at = coalesce(p_when, now())
   where id = p_id and workspace_id = p_workspace;

  return jsonb_build_object('queued', v_n);
end $$;
grant execute on function queue_newsletter(text, uuid, uuid, timestamptz) to authenticated, anon;

create or replace function cancel_newsletter(p_privy text, p_workspace uuid, p_id uuid)
returns boolean language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  -- Cancelling mid-send is allowed and stops future batches; already-delivered
  -- rows stay 'sent' because those emails are in real inboxes and pretending
  -- otherwise would make the stats lie.
  update newsletters set status = 'cancelled'
   where id = p_id and workspace_id = p_workspace and status in ('scheduled','sending','paused');
  if not found then return false; end if;
  delete from newsletter_deliveries where newsletter_id = p_id and status = 'pending';
  return true;
end $$;
grant execute on function cancel_newsletter(text, uuid, uuid) to authenticated, anon;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0071_newsletter_send.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0071_newsletter_send.sql
-- The send pipeline: batch claiming, delivery marking, and the public
-- token-addressed endpoints (unsubscribe, confirm, open, click).
--
-- AT-MOST-ONCE, ON PURPOSE.
-- A delivery is claimed by moving it to 'sending' BEFORE the provider call. If
-- the process dies between the claim and the result, that row is stranded — and
-- it is deliberately NOT returned to 'pending' by anything automatic.
--
-- This is the at-least-once / at-most-once fork, and for bulk email the answer
-- is not the usual one. Retrying a row that may already have been accepted by
-- Resend sends a duplicate to a real customer; leaving it stranded sends nothing
-- to one person. A missed email is a support question. A duplicate send to a
-- whole list is a public incident and cannot be undone. So stale claims are
-- swept to 'failed' with a reason, and re-sending is an explicit human act.
--
-- The claim itself uses FOR UPDATE SKIP LOCKED: two overlapping cron ticks must
-- never be handed the same delivery row, and SKIP LOCKED is what makes the
-- second tick take different work instead of blocking on the first.
--
-- Everything here is service_role only. These run from /api/newsletters/* which
-- holds the Resend key; none of it is reachable through the /api/rpc proxy.
-- Depends on 0070.
-- ============================================================================

-- 'sending' is the claimed state. Added to the existing check constraint rather
-- than tracked in a second column so a delivery has exactly one status.
alter table newsletter_deliveries drop constraint if exists newsletter_deliveries_status_check;
alter table newsletter_deliveries add constraint newsletter_deliveries_status_check
  check (status in ('pending', 'sending', 'sent', 'failed', 'skipped'));

alter table newsletter_deliveries add column if not exists claimed_at timestamptz;
create index if not exists idx_nl_deliveries_stale on newsletter_deliveries(status, claimed_at)
  where status = 'sending';

-- ── What is due ──────────────────────────────────────────────────────────────
create or replace function due_newsletters(p_limit int default 5)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  return coalesce((select jsonb_agg(to_jsonb(x)) from (
    select n.id, n.workspace_id, n.subject, n.preheader, n.template, n.content,
           n.from_name, n.reply_to, n.status
      from newsletters n
     where (n.status = 'scheduled' and n.scheduled_at <= now())
        or n.status = 'sending'
     order by n.scheduled_at nulls first
     limit greatest(1, least(coalesce(p_limit, 5), 20))
  ) x), '[]'::jsonb);
end $$;
revoke all on function due_newsletters(int) from public, authenticated, anon;
grant execute on function due_newsletters(int) to service_role;

/**
 * Claim up to p_limit pending deliveries for one newsletter and flip the
 * newsletter to 'sending'.
 *
 * SKIP LOCKED is the whole point: without it a second cron tick overlapping the
 * first would block on the same rows and then send them again once the lock
 * cleared. With it, the second tick simply takes the next unclaimed slice.
 */
create or replace function claim_newsletter_batch(p_newsletter uuid, p_limit int default 50)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_rows jsonb;
begin
  update newsletters
     set status = 'sending', started_at = coalesce(started_at, now())
   where id = p_newsletter and status in ('scheduled', 'sending');
  if not found then return '[]'::jsonb; end if;

  -- One statement, three stages. `candidate` takes the lock, `claimed` flips
  -- the rows and RETURNS them, and the final SELECT aggregates.
  --
  -- This was previously `UPDATE ... RETURNING jsonb_build_object(...) INTO
  -- v_rows`, which raises "query returned more than one row" the moment a batch
  -- holds more than one delivery — so every real batch failed and only a
  -- batch of exactly one worked. RETURNING INTO takes a single row; aggregating
  -- in a data-modifying CTE is what actually collects the set.
  with candidate as (
    select d.id
      from newsletter_deliveries d
     where d.newsletter_id = p_newsletter and d.status = 'pending'
     order by d.created_at
     limit greatest(1, least(coalesce(p_limit, 50), 200))
     for update skip locked
  ), claimed as (
    update newsletter_deliveries d
       set status = 'sending', claimed_at = now()
      from candidate c
     where d.id = c.id
    returning d.id, d.email, d.subscriber_id
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', cl.id, 'email', cl.email, 'subscriber_id', cl.subscriber_id,
           'token', s.token, 'name', s.name, 'attribs', s.attribs)), '[]'::jsonb)
    into v_rows
    from claimed cl
    join newsletter_subscribers s on s.id = cl.subscriber_id;

  return v_rows;
end $$;
revoke all on function claim_newsletter_batch(uuid, int) from public, authenticated, anon;
grant execute on function claim_newsletter_batch(uuid, int) to service_role;

create or replace function mark_newsletter_delivery(
  p_id uuid, p_status text, p_provider_id text default null, p_error text default null
) returns boolean language plpgsql security definer set search_path = public as $$
begin
  if p_status not in ('sent', 'failed', 'skipped') then raise exception 'BAD_STATUS'; end if;
  update newsletter_deliveries
     set status = p_status,
         provider_id = coalesce(p_provider_id, provider_id),
         error = p_error,
         sent_at = case when p_status = 'sent' then now() else sent_at end
   where id = p_id and status = 'sending';
  return found;
end $$;
revoke all on function mark_newsletter_delivery(uuid, text, text, text) from public, authenticated, anon;
grant execute on function mark_newsletter_delivery(uuid, text, text, text) to service_role;

/**
 * Close a newsletter once nothing is left to do, and sweep stale claims.
 *
 * A claim older than p_stale_minutes belonged to a process that died. It is
 * marked FAILED, never returned to pending — see the header. The operator sees
 * the count and decides; the system never silently risks a duplicate.
 */
create or replace function finish_newsletter(p_id uuid, p_stale_minutes int default 15)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_stale int; v_left int;
begin
  update newsletter_deliveries
     set status = 'failed',
         error = 'Interrupted mid-send. Not retried automatically: the message may already have been accepted by the provider, and a duplicate to a real subscriber is worse than a miss.'
   where newsletter_id = p_id and status = 'sending'
     and claimed_at < now() - make_interval(mins => greatest(1, coalesce(p_stale_minutes, 15)));
  get diagnostics v_stale = row_count;

  select count(*) into v_left from newsletter_deliveries
   where newsletter_id = p_id and status in ('pending', 'sending');

  if v_left = 0 then
    update newsletters set status = 'sent', finished_at = now()
     where id = p_id and status = 'sending';
  end if;

  return jsonb_build_object('swept', v_stale, 'remaining', v_left);
end $$;
revoke all on function finish_newsletter(uuid, int) from public, authenticated, anon;
grant execute on function finish_newsletter(uuid, int) to service_role;

-- ── Public, token-addressed ──────────────────────────────────────────────────
/**
 * One-click unsubscribe. Addressed by the subscriber's unguessable token, so it
 * works from an email client with no session — which is the requirement, not a
 * shortcut: Gmail and Yahoo demand one-click unsubscribe from bulk senders and
 * deliverability collapses without it.
 *
 * Idempotent. A mail client that pre-fetches the link (several do) and then the
 * human clicking it must not produce an error the second time.
 */
create or replace function newsletter_unsubscribe(p_token text, p_newsletter uuid default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_id uuid; v_ws uuid; v_email text;
begin
  select id, workspace_id, email into v_id, v_ws, v_email
    from newsletter_subscribers where token = p_token;
  if v_id is null then return jsonb_build_object('ok', false); end if;

  update newsletter_subscribers set status = 'unsubscribed'
   where id = v_id and status <> 'unsubscribed';

  if found then
    insert into newsletter_events (workspace_id, newsletter_id, subscriber_id, kind)
    values (v_ws, p_newsletter, v_id, 'unsubscribe');
  end if;

  -- Any queued sends for this person stop now. Without this, unsubscribing
  -- during a large send still delivers whatever was already materialised.
  update newsletter_deliveries set status = 'skipped', error = 'unsubscribed'
   where subscriber_id = v_id and status = 'pending';

  return jsonb_build_object('ok', true, 'email', v_email);
end $$;
revoke all on function newsletter_unsubscribe(text, uuid) from public, authenticated, anon;
grant execute on function newsletter_unsubscribe(text, uuid) to service_role;

create or replace function newsletter_confirm(p_token text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_id uuid; v_email text;
begin
  select id, email into v_id, v_email from newsletter_subscribers where token = p_token;
  if v_id is null then return jsonb_build_object('ok', false); end if;
  -- Only lifts 'unconfirmed'. A confirmation link must never revive someone who
  -- has since unsubscribed or hard-bounced.
  update newsletter_subscribers set status = 'enabled'
   where id = v_id and status = 'unconfirmed';
  return jsonb_build_object('ok', true, 'email', v_email);
end $$;
revoke all on function newsletter_confirm(text) from public, authenticated, anon;
grant execute on function newsletter_confirm(text) to service_role;

/**
 * Record an open or a click, addressed by DELIVERY id — which ties the event to
 * a specific send rather than just to a person, and is unguessable.
 *
 * Opens are deduplicated per (delivery, kind) for the same url: clients prefetch
 * images and some proxy them repeatedly, so counting every pixel hit would
 * report open rates well above 100%.
 */
create or replace function record_newsletter_event(
  p_delivery uuid, p_kind text, p_url text default null
) returns boolean language plpgsql security definer set search_path = public as $$
declare v_ws uuid; v_nl uuid; v_sub uuid;
begin
  if p_kind not in ('open', 'click') then raise exception 'BAD_KIND'; end if;
  select workspace_id, newsletter_id, subscriber_id into v_ws, v_nl, v_sub
    from newsletter_deliveries where id = p_delivery;
  if v_ws is null then return false; end if;

  if exists (select 1 from newsletter_events e
              where e.newsletter_id = v_nl and e.subscriber_id = v_sub
                and e.kind = p_kind and coalesce(e.url,'') = coalesce(p_url,'')) then
    return true;
  end if;

  insert into newsletter_events (workspace_id, newsletter_id, subscriber_id, kind, url)
  values (v_ws, v_nl, v_sub, p_kind, p_url);
  return true;
end $$;
revoke all on function record_newsletter_event(uuid, text, text) from public, authenticated, anon;
grant execute on function record_newsletter_event(uuid, text, text) to service_role;

/**
 * Provider feedback (Resend webhook). A bounce or complaint is the mail system
 * telling us to stop; it is stored as a permanent status, not a counter, because
 * continuing to mail a hard-bounced address is what destroys a sending domain's
 * reputation.
 */
create or replace function record_newsletter_feedback(p_email text, p_workspace uuid, p_kind text)
returns boolean language plpgsql security definer set search_path = public as $$
declare v_id uuid;
begin
  if p_kind not in ('bounce', 'complaint') then raise exception 'BAD_KIND'; end if;
  select id into v_id from newsletter_subscribers
   where workspace_id = p_workspace and lower(email) = lower(p_email);
  if v_id is null then return false; end if;

  update newsletter_subscribers
     set status = case when p_kind = 'bounce' then 'bounced' else 'complained' end
   where id = v_id;

  insert into newsletter_events (workspace_id, subscriber_id, kind)
  values (p_workspace, v_id, p_kind);

  update newsletter_deliveries set status = 'skipped', error = p_kind
   where subscriber_id = v_id and status = 'pending';
  return true;
end $$;
revoke all on function record_newsletter_feedback(text, uuid, text) from public, authenticated, anon;
grant execute on function record_newsletter_feedback(text, uuid, text) to service_role;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0072_segments.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0072_segments.sql
-- Segments: a saved, LIVE filter over subscribers.
--
-- Mautic's real lesson is that segments, not campaigns, are the primitive. A
-- list is who you added; a segment is who currently matches — "opened nothing in
-- 90 days", "joined via the pricing form", "on the newsletter but never
-- clicked". Sequences and scoring both build on this, which is why it comes
-- first.
--
-- NO DYNAMIC SQL. The obvious way to build a filter engine is format() +
-- quote_literal into an EXECUTE. Inside a SECURITY DEFINER function that runs as
-- service_role, that is one escaping mistake away from arbitrary SQL against
-- every tenant's data. Instead `segment_match` is an ordinary STABLE function
-- with a CASE over a WHITELIST of fields — an unknown field or operator returns
-- false rather than being interpolated anywhere. The cost is that we support a
-- bounded predicate set instead of arbitrary expressions, which is the correct
-- trade for a filter builder driven by a UI.
--
-- PERFORMANCE, HONESTLY: the engagement predicates run an EXISTS per row, so
-- this is linear in list size and is not meant for millions of subscribers.
-- Results are capped and paged. If a workspace outgrows it, the fix is a
-- materialised engagement summary per subscriber, not dynamic SQL.
--
-- Depends on 0070/0071. Additive, idempotent & prod-safe.
-- ============================================================================

create table if not exists segments (
  id           uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspaces(id) on delete cascade,
  name         text not null default 'New segment',
  description  text not null default '',
  -- [{ field, op, value }] — ALL must match (AND). Deliberately not a nested
  -- boolean tree: an AND list covers the segments people actually build, and a
  -- tree needs a query builder UI that nobody uses correctly.
  filters      jsonb not null default '[]'::jsonb,
  created_by_privy text,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);
create index if not exists idx_segments_ws on segments(workspace_id, updated_at desc);
drop trigger if exists trg_segments_upd on segments;
create trigger trg_segments_upd before update on segments for each row execute function set_updated_at();
alter table segments enable row level security;
revoke all on table segments from anon, authenticated;

/**
 * Does one subscriber match one condition?
 *
 * STABLE, not IMMUTABLE: the engagement predicates read newsletter_events and
 * the date predicates read now(), so the planner must not cache results across
 * statements.
 *
 * An unrecognised field or operator returns FALSE. Returning true would make a
 * typo in a saved filter silently widen the audience of a send — the failure
 * mode that mails people who should never have received it.
 */
create or replace function segment_match(p_sub newsletter_subscribers, p_cond jsonb)
returns boolean language plpgsql stable set search_path = public as $$
declare
  f text := p_cond->>'field';
  o text := coalesce(p_cond->>'op', 'eq');
  v text := p_cond->>'value';
  -- The numeric operand for the day/count predicates. It must be parsed
  -- STRICTLY, not by stripping non-digits: the value for on_list is a UUID, and
  -- stripping its dashes leaves a 32-digit number that overflows int and raises
  -- — crashing the whole evaluation instead of failing closed. A whole-string
  -- match of at most six digits is non-numeric-safe and cannot overflow.
  n int  := case when coalesce(v, '') ~ '^\d{1,6}$' then v::int else null end;
begin
  if f is null then return false; end if;

  case f
    when 'status' then
      return case o
        when 'eq'  then p_sub.status = v
        when 'neq' then p_sub.status <> v
        else false end;

    when 'email' then
      return case o
        when 'contains'    then p_sub.email ilike '%'||coalesce(v,'')||'%'
        when 'not_contains'then p_sub.email not ilike '%'||coalesce(v,'')||'%'
        when 'ends_with'   then p_sub.email ilike '%'||coalesce(v,'')
        else false end;

    when 'name' then
      return case o
        when 'contains' then p_sub.name ilike '%'||coalesce(v,'')||'%'
        when 'is_set'   then coalesce(p_sub.name,'') <> ''
        when 'is_empty' then coalesce(p_sub.name,'') = ''
        else false end;

    when 'consent_source' then
      return case o
        when 'eq'       then p_sub.consent_source = v
        when 'contains' then p_sub.consent_source ilike '%'||coalesce(v,'')||'%'
        else false end;

    when 'created_at' then
      return case o
        when 'within_days' then n is not null and p_sub.created_at >= now() - make_interval(days => n)
        when 'before_days' then n is not null and p_sub.created_at <  now() - make_interval(days => n)
        else false end;

    -- Membership. Only lists in the SAME workspace are considered, so a foreign
    -- list id in a saved filter matches nothing rather than reaching across.
    when 'on_list' then
      return case o
        when 'eq' then exists (
          select 1 from newsletter_list_subscribers ls
            join newsletter_lists l on l.id = ls.list_id
           where ls.subscriber_id = p_sub.id and l.workspace_id = p_sub.workspace_id
             and l.id::text = v)
        when 'neq' then not exists (
          select 1 from newsletter_list_subscribers ls
            join newsletter_lists l on l.id = ls.list_id
           where ls.subscriber_id = p_sub.id and l.workspace_id = p_sub.workspace_id
             and l.id::text = v)
        else false end;

    -- Engagement. This is the reason segments exist at all: "opened nothing in
    -- 90 days" is not expressible as a column comparison.
    when 'opened' then
      return case o
        when 'within_days' then n is not null and exists (
          select 1 from newsletter_events e where e.subscriber_id = p_sub.id
            and e.kind = 'open' and e.created_at >= now() - make_interval(days => n))
        when 'not_within_days' then n is not null and not exists (
          select 1 from newsletter_events e where e.subscriber_id = p_sub.id
            and e.kind = 'open' and e.created_at >= now() - make_interval(days => n))
        when 'never' then not exists (
          select 1 from newsletter_events e where e.subscriber_id = p_sub.id and e.kind = 'open')
        else false end;

    when 'clicked' then
      return case o
        when 'within_days' then n is not null and exists (
          select 1 from newsletter_events e where e.subscriber_id = p_sub.id
            and e.kind = 'click' and e.created_at >= now() - make_interval(days => n))
        when 'not_within_days' then n is not null and not exists (
          select 1 from newsletter_events e where e.subscriber_id = p_sub.id
            and e.kind = 'click' and e.created_at >= now() - make_interval(days => n))
        when 'never' then not exists (
          select 1 from newsletter_events e where e.subscriber_id = p_sub.id and e.kind = 'click')
        else false end;

    when 'received' then
      return case o
        when 'never' then not exists (
          select 1 from newsletter_deliveries d where d.subscriber_id = p_sub.id and d.status = 'sent')
        when 'at_least' then n is not null and (
          select count(*) from newsletter_deliveries d
           where d.subscriber_id = p_sub.id and d.status = 'sent') >= n
        else false end;

    else return false;
  end case;
end $$;

/**
 * Evaluate a filter set live.
 *
 * bool_and over an EMPTY condition array returns NULL, which would make an empty
 * segment match nobody. coalesce(..., true) makes it match everyone instead —
 * "no filters" means "all subscribers", which is what someone building a segment
 * sees before they add their first condition.
 */
create or replace function evaluate_segment_filters(
  p_privy text, p_workspace uuid, p_filters jsonb,
  p_limit int default 25, p_offset int default 0
) returns jsonb language plpgsql security definer set search_path = public as $$
declare v_rows jsonb; v_total bigint; v_lim int; v_off int;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  if jsonb_typeof(coalesce(p_filters, '[]'::jsonb)) <> 'array' then raise exception 'BAD_FILTERS'; end if;
  v_lim := greatest(1, least(coalesce(p_limit, 25), 200));
  v_off := greatest(0, coalesce(p_offset, 0));

  select count(*) into v_total
    from newsletter_subscribers s
   where s.workspace_id = p_workspace
     and coalesce((select bool_and(segment_match(s, c))
                     from jsonb_array_elements(coalesce(p_filters,'[]'::jsonb)) c), true);

  select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc), '[]'::jsonb) into v_rows from (
    select s.id, s.email, s.name, s.status, s.consent_source, s.created_at
      from newsletter_subscribers s
     where s.workspace_id = p_workspace
       and coalesce((select bool_and(segment_match(s, c))
                       from jsonb_array_elements(coalesce(p_filters,'[]'::jsonb)) c), true)
     order by s.created_at desc
     limit v_lim offset v_off
  ) x;

  return jsonb_build_object('rows', v_rows, 'total', v_total);
end $$;
grant execute on function evaluate_segment_filters(text, uuid, jsonb, int, int) to authenticated, anon;

-- ── CRUD ─────────────────────────────────────────────────────────────────────
create or replace function get_segments(p_privy text, p_workspace uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  -- Deliberately does NOT compute each segment's size: that would run the full
  -- predicate set for every segment on every page load. The count is fetched
  -- when a segment is opened.
  return coalesce((select jsonb_agg(to_jsonb(x) order by x.updated_at desc) from (
    select g.id, g.name, g.description, g.filters, g.updated_at
      from segments g where g.workspace_id = p_workspace
  ) x), '[]'::jsonb);
end $$;
grant execute on function get_segments(text, uuid) to authenticated, anon;

create or replace function save_segment(
  p_privy text, p_workspace uuid, p_id uuid, p_name text, p_description text, p_filters jsonb
) returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  if jsonb_typeof(coalesce(p_filters, '[]'::jsonb)) <> 'array' then raise exception 'BAD_FILTERS'; end if;
  if jsonb_array_length(coalesce(p_filters, '[]'::jsonb)) > 20 then raise exception 'TOO_MANY_FILTERS'; end if;

  if p_id is null then
    insert into segments (workspace_id, name, description, filters, created_by_privy)
    values (p_workspace, coalesce(nullif(p_name,''),'New segment'), coalesce(p_description,''),
            coalesce(p_filters,'[]'::jsonb), p_privy)
    returning id into v_id;
  else
    update segments set
      name = coalesce(nullif(p_name,''), name),
      description = coalesce(p_description, description),
      filters = coalesce(p_filters, filters)
    where id = p_id and workspace_id = p_workspace
    returning id into v_id;
  end if;
  return v_id;
end $$;
grant execute on function save_segment(text, uuid, uuid, text, text, jsonb) to authenticated, anon;

create or replace function delete_segment(p_privy text, p_workspace uuid, p_id uuid)
returns boolean language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  delete from segments where id = p_id and workspace_id = p_workspace;
  return found;
end $$;
grant execute on function delete_segment(text, uuid, uuid) to authenticated, anon;

/**
 * Materialise a segment onto a list, so a newsletter can target it.
 *
 * A COPY, not a live link, and that is the honest behaviour: a send's audience
 * is fixed when it is queued (0070), so pretending a segment stays live inside a
 * send would be a lie. The user syncs, sees the number, then sends.
 *
 * Only ADDS. It never removes anyone the segment no longer matches, because
 * someone may have been added to that list by other means and silently dropping
 * them is not something a "sync" button should do.
 */
create or replace function sync_segment_to_list(
  p_privy text, p_workspace uuid, p_segment uuid, p_list uuid
) returns jsonb language plpgsql security definer set search_path = public as $$
declare v_filters jsonb; v_added int;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  select filters into v_filters from segments where id = p_segment and workspace_id = p_workspace;
  if v_filters is null then raise exception 'NOT_FOUND'; end if;
  if not exists (select 1 from newsletter_lists where id = p_list and workspace_id = p_workspace) then
    raise exception 'NOT_FOUND';
  end if;

  insert into newsletter_list_subscribers (list_id, subscriber_id)
  select p_list, s.id
    from newsletter_subscribers s
   where s.workspace_id = p_workspace
     and coalesce((select bool_and(segment_match(s, c))
                     from jsonb_array_elements(v_filters) c), true)
  on conflict do nothing;
  get diagnostics v_added = row_count;

  return jsonb_build_object('added', v_added);
end $$;
grant execute on function sync_segment_to_list(text, uuid, uuid, uuid) to authenticated, anon;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0073_sequences.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0073_sequences.sql
-- Drip sequences: an ordered list of steps with WAITS, run per subscriber.
--
-- This is the actual gap between "automations" (0032/0033) and marketing
-- automation. Our automations fire once, on an event. A sequence has a CURSOR
-- per person — which step they are on and when the next one is due — so "day 0
-- welcome, day 3 case study, day 7 ask for a call" is expressible at all.
--
-- SEQUENCE EMAILS REUSE THE NEWSLETTER MACHINERY, deliberately. A step points at
-- a `newsletters` row that is never queued; sending creates an ordinary
-- newsletter_deliveries row for that (newsletter, subscriber). Four things come
-- free and correct as a result:
--   • the unique (newsletter_id, subscriber_id) index means a re-enrolled
--     subscriber CANNOT receive the same step twice — the single worst bug a
--     drip tool can have;
--   • open and click tracking already key off a delivery id;
--   • one-click unsubscribe already works, because the token is the
--     subscriber's, not the campaign's;
--   • per-step stats roll up through the existing newsletter counters.
-- Writing a parallel delivery table would have meant reimplementing all four,
-- each with its own chance of being subtly wrong.
--
-- Depends on 0070/0071/0072. Additive, idempotent & prod-safe.
-- ============================================================================

create table if not exists sequences (
  id           uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspaces(id) on delete cascade,
  name         text not null default 'New sequence',
  description  text not null default '',
  enabled      boolean not null default false,   -- off until someone turns it on
  -- Who enters. Exactly one of these; a segment is re-evaluated on every
  -- enrolment sweep, which is the point of segments existing.
  entry_list    uuid references newsletter_lists(id) on delete set null,
  entry_segment uuid references segments(id) on delete set null,
  -- [{ kind:'wait', days:N } | { kind:'email', newsletter_id:'uuid' }]
  steps        jsonb not null default '[]'::jsonb,
  created_by_privy text,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);
create index if not exists idx_sequences_ws on sequences(workspace_id, updated_at desc);
create index if not exists idx_sequences_enabled on sequences(enabled) where enabled;
drop trigger if exists trg_sequences_upd on sequences;
create trigger trg_sequences_upd before update on sequences for each row execute function set_updated_at();
alter table sequences enable row level security;
revoke all on table sequences from anon, authenticated;

-- One cursor per (sequence, subscriber). The unique constraint is what makes
-- enrolment idempotent: an enrolment sweep runs repeatedly and must never
-- restart someone who is already partway through.
create table if not exists sequence_enrollments (
  id            uuid primary key default gen_random_uuid(),
  workspace_id  uuid not null references workspaces(id) on delete cascade,
  sequence_id   uuid not null references sequences(id) on delete cascade,
  subscriber_id uuid not null references newsletter_subscribers(id) on delete cascade,
  step_index    int  not null default 0,
  due_at        timestamptz not null default now(),
  status        text not null default 'active'
                check (status in ('active', 'running', 'completed', 'cancelled', 'failed')),
  last_error    text,
  enrolled_at   timestamptz not null default now(),
  finished_at   timestamptz
);
create unique index if not exists uq_seq_enroll on sequence_enrollments(sequence_id, subscriber_id);
-- The dispatcher's lookup: what is due right now.
create index if not exists idx_seq_enroll_due on sequence_enrollments(status, due_at)
  where status = 'active';
alter table sequence_enrollments enable row level security;
revoke all on table sequence_enrollments from anon, authenticated;

-- ── CRUD ─────────────────────────────────────────────────────────────────────
create or replace function get_sequences(p_privy text, p_workspace uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((select jsonb_agg(to_jsonb(x) order by x.updated_at desc) from (
    select s.id, s.name, s.description, s.enabled, s.entry_list, s.entry_segment,
           s.steps, s.updated_at,
           (select count(*) from sequence_enrollments e
             where e.sequence_id = s.id and e.status = 'active')    as active_count,
           (select count(*) from sequence_enrollments e
             where e.sequence_id = s.id and e.status = 'completed') as completed_count
      from sequences s where s.workspace_id = p_workspace
  ) x), '[]'::jsonb);
end $$;
grant execute on function get_sequences(text, uuid) to authenticated, anon;

/**
 * Save a sequence. Steps are shape-checked here rather than trusted, because
 * the dispatcher reads them as instructions: an email step naming a newsletter
 * from another workspace would otherwise send that workspace's content.
 */
create or replace function save_sequence(
  p_privy text, p_workspace uuid, p_id uuid, p_name text, p_description text,
  p_entry_list uuid, p_entry_segment uuid, p_steps jsonb
) returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid; v_step jsonb; v_kind text; v_days int; v_nl uuid;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  if jsonb_typeof(coalesce(p_steps, '[]'::jsonb)) <> 'array' then raise exception 'BAD_STEPS'; end if;
  if jsonb_array_length(coalesce(p_steps, '[]'::jsonb)) > 30 then raise exception 'TOO_MANY_STEPS'; end if;

  for v_step in select * from jsonb_array_elements(coalesce(p_steps, '[]'::jsonb)) loop
    v_kind := v_step->>'kind';
    if v_kind = 'wait' then
      -- Strict whole-string match, not trim-then-cast. Casting "abc" raises a
      -- raw "invalid input syntax for type integer" instead of BAD_WAIT, which
      -- reaches the user as a database error rather than a validation message —
      -- and a 4-digit-plus value would overflow before the range check ran.
      v_days := case when coalesce(v_step->>'days', '') ~ '^\d{1,3}$'
                     then (v_step->>'days')::int else null end;
      if v_days is null or v_days > 365 then raise exception 'BAD_WAIT'; end if;
    elsif v_kind = 'email' then
      begin v_nl := (v_step->>'newsletter_id')::uuid; exception when others then raise exception 'BAD_EMAIL_STEP'; end;
      -- Same-workspace only. This is the check that stops a crafted step from
      -- mailing another tenant's newsletter to this tenant's subscribers.
      if not exists (select 1 from newsletters n where n.id = v_nl and n.workspace_id = p_workspace) then
        raise exception 'BAD_EMAIL_STEP';
      end if;
    else
      raise exception 'BAD_STEP_KIND';
    end if;
  end loop;

  -- Entry references are validated the same way.
  if p_entry_list is not null and not exists (
      select 1 from newsletter_lists where id = p_entry_list and workspace_id = p_workspace) then
    raise exception 'BAD_ENTRY';
  end if;
  if p_entry_segment is not null and not exists (
      select 1 from segments where id = p_entry_segment and workspace_id = p_workspace) then
    raise exception 'BAD_ENTRY';
  end if;

  if p_id is null then
    insert into sequences (workspace_id, name, description, entry_list, entry_segment, steps, created_by_privy)
    values (p_workspace, coalesce(nullif(p_name,''),'New sequence'), coalesce(p_description,''),
            p_entry_list, p_entry_segment, coalesce(p_steps,'[]'::jsonb), p_privy)
    returning id into v_id;
  else
    update sequences set
      name = coalesce(nullif(p_name,''), name), description = coalesce(p_description, description),
      entry_list = p_entry_list, entry_segment = p_entry_segment,
      steps = coalesce(p_steps, steps)
    where id = p_id and workspace_id = p_workspace
    returning id into v_id;
  end if;
  return v_id;
end $$;
grant execute on function save_sequence(text, uuid, uuid, text, text, uuid, uuid, jsonb) to authenticated, anon;

create or replace function set_sequence_enabled(p_privy text, p_workspace uuid, p_id uuid, p_enabled boolean)
returns boolean language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  update sequences set enabled = p_enabled where id = p_id and workspace_id = p_workspace;
  return found;
end $$;
grant execute on function set_sequence_enabled(text, uuid, uuid, boolean) to authenticated, anon;

create or replace function delete_sequence(p_privy text, p_workspace uuid, p_id uuid)
returns boolean language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  delete from sequences where id = p_id and workspace_id = p_workspace;
  return found;
end $$;
grant execute on function delete_sequence(text, uuid, uuid) to authenticated, anon;

-- ── Enrolment ────────────────────────────────────────────────────────────────
/**
 * Enrol everyone who currently qualifies and is not already enrolled.
 *
 * Idempotent by the unique (sequence, subscriber) index — this runs on every
 * sweep, and restarting someone who is halfway through would re-send steps they
 * have already had.
 *
 * ONLY 'enabled' SUBSCRIBERS. Unconfirmed (double opt-in pending), unsubscribed,
 * bounced and complained are excluded at enrolment rather than filtered later,
 * so an enrolment IS a commitment to mail that person.
 *
 * ONCE ENROLLED, ALWAYS ENROLLED — leaving the segment does NOT eject someone
 * mid-drip. A welcome series that stops halfway because a contact's score
 * changed is worse than one that finishes.
 */
create or replace function enroll_sequence(p_sequence uuid, p_limit int default 500)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_ws uuid; v_list uuid; v_seg uuid; v_filters jsonb; v_n int;
begin
  select workspace_id, entry_list, entry_segment into v_ws, v_list, v_seg
    from sequences where id = p_sequence and enabled;
  if v_ws is null then return jsonb_build_object('enrolled', 0, 'skipped', 'not enabled'); end if;
  if v_list is null and v_seg is null then return jsonb_build_object('enrolled', 0, 'skipped', 'no entry'); end if;

  if v_seg is not null then
    select filters into v_filters from segments where id = v_seg and workspace_id = v_ws;
  end if;

  insert into sequence_enrollments (workspace_id, sequence_id, subscriber_id)
  select v_ws, p_sequence, s.id
    from newsletter_subscribers s
   where s.workspace_id = v_ws
     and s.status = 'enabled'
     and (v_list is null or exists (
           select 1 from newsletter_list_subscribers ls
            where ls.subscriber_id = s.id and ls.list_id = v_list))
     and (v_filters is null or coalesce(
           (select bool_and(segment_match(s, c)) from jsonb_array_elements(v_filters) c), true))
   limit greatest(1, least(coalesce(p_limit, 500), 5000))
  on conflict (sequence_id, subscriber_id) do nothing;
  get diagnostics v_n = row_count;

  return jsonb_build_object('enrolled', v_n);
end $$;
revoke all on function enroll_sequence(uuid, int) from public, authenticated, anon;
grant execute on function enroll_sequence(uuid, int) to service_role;

-- ── Dispatch ─────────────────────────────────────────────────────────────────
create or replace function enabled_sequences()
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  return coalesce((select jsonb_agg(jsonb_build_object('id', s.id, 'workspace_id', s.workspace_id))
                     from sequences s where s.enabled), '[]'::jsonb);
end $$;
revoke all on function enabled_sequences() from public, authenticated, anon;
grant execute on function enabled_sequences() to service_role;

/**
 * Claim due enrolments and return what each one needs next.
 *
 * SKIP LOCKED for the same reason as the newsletter sender: two overlapping
 * cron ticks must take different work rather than blocking and then doing it
 * twice.
 *
 * A claimed row goes to 'running'. Like newsletter deliveries this is
 * at-most-once — a crash strands the row for the sweeper rather than risking a
 * duplicate email.
 */
create or replace function claim_sequence_steps(p_limit int default 50)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_rows jsonb;
begin
  with candidate as (
    select e.id from sequence_enrollments e
      join sequences s on s.id = e.sequence_id and s.enabled
     where e.status = 'active' and e.due_at <= now()
     order by e.due_at
     limit greatest(1, least(coalesce(p_limit, 50), 200))
     for update of e skip locked
  ), claimed as (
    update sequence_enrollments e set status = 'running'
      from candidate c where e.id = c.id
    returning e.id, e.workspace_id, e.sequence_id, e.subscriber_id, e.step_index
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'enrollment_id', cl.id, 'workspace_id', cl.workspace_id,
           'sequence_id', cl.sequence_id, 'subscriber_id', cl.subscriber_id,
           'step_index', cl.step_index,
           'step', s.steps -> cl.step_index,
           'steps_total', jsonb_array_length(s.steps),
           'email', sub.email, 'name', sub.name, 'token', sub.token,
           'subscriber_status', sub.status)), '[]'::jsonb)
    into v_rows
    from claimed cl
    join sequences s on s.id = cl.sequence_id
    join newsletter_subscribers sub on sub.id = cl.subscriber_id;

  return v_rows;
end $$;
revoke all on function claim_sequence_steps(int) from public, authenticated, anon;
grant execute on function claim_sequence_steps(int) to service_role;

/**
 * Move an enrolment on.
 *
 * p_wait_days null = advance immediately (the step was an email that has been
 * sent). Otherwise the next step is due that many days out.
 *
 * Completing when step_index runs past the end is decided HERE rather than by
 * the caller, so a dispatcher bug cannot leave enrolments active forever
 * re-running a step that does not exist.
 */
create or replace function advance_enrollment(
  p_id uuid, p_wait_days int default null, p_error text default null
) returns boolean language plpgsql security definer set search_path = public as $$
declare v_next int; v_total int;
begin
  if p_error is not null then
    update sequence_enrollments
       set status = 'failed', last_error = left(p_error, 500), finished_at = now()
     where id = p_id and status = 'running';
    return found;
  end if;

  select e.step_index + 1, jsonb_array_length(s.steps) into v_next, v_total
    from sequence_enrollments e join sequences s on s.id = e.sequence_id
   where e.id = p_id;
  if v_next is null then return false; end if;

  if v_next >= coalesce(v_total, 0) then
    update sequence_enrollments
       set status = 'completed', step_index = v_next, finished_at = now()
     where id = p_id and status = 'running';
  else
    update sequence_enrollments
       set status = 'active', step_index = v_next,
           due_at = now() + make_interval(days => greatest(0, coalesce(p_wait_days, 0)))
     where id = p_id and status = 'running';
  end if;
  return found;
end $$;
revoke all on function advance_enrollment(uuid, int, text) from public, authenticated, anon;
grant execute on function advance_enrollment(uuid, int, text) to service_role;

/**
 * Stop mailing someone the moment they opt out.
 *
 * Called by the dispatcher before each step and after unsubscribes. Without it,
 * unsubscribing during a drip keeps delivering the remaining steps — which is
 * both the most annoying possible bug and a compliance problem.
 */
create or replace function cancel_enrollments_for_subscriber(p_subscriber uuid)
returns int language plpgsql security definer set search_path = public as $$
declare v_n int;
begin
  update sequence_enrollments
     set status = 'cancelled', finished_at = now()
   where subscriber_id = p_subscriber and status in ('active', 'running');
  get diagnostics v_n = row_count;
  return v_n;
end $$;
revoke all on function cancel_enrollments_for_subscriber(uuid) from public, authenticated, anon;
grant execute on function cancel_enrollments_for_subscriber(uuid) to service_role;

/** Sweep claims left by a dead process. Failed, never retried — see 0071. */
create or replace function sweep_stale_enrollments(p_minutes int default 15)
returns int language plpgsql security definer set search_path = public as $$
declare v_n int;
begin
  update sequence_enrollments
     set status = 'failed',
         last_error = 'Interrupted mid-step. Not retried automatically: the email may already have been accepted by the provider.',
         finished_at = now()
   where status = 'running'
     and enrolled_at < now() - make_interval(mins => greatest(1, coalesce(p_minutes, 15)));
  get diagnostics v_n = row_count;
  return v_n;
end $$;
revoke all on function sweep_stale_enrollments(int) from public, authenticated, anon;
grant execute on function sweep_stale_enrollments(int) to service_role;

/**
 * Record a sequence email as an ordinary newsletter delivery.
 *
 * Returns the delivery id, or NULL when one already exists — which is how a
 * re-enrolled or double-claimed subscriber is prevented from receiving the same
 * step twice. The caller must treat NULL as "already sent, skip".
 */
create or replace function create_sequence_delivery(
  p_workspace uuid, p_newsletter uuid, p_subscriber uuid
) returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid; v_email text;
begin
  select email into v_email from newsletter_subscribers
   where id = p_subscriber and workspace_id = p_workspace and status = 'enabled';
  if v_email is null then return null; end if;
  if not exists (select 1 from newsletters where id = p_newsletter and workspace_id = p_workspace) then
    return null;
  end if;

  insert into newsletter_deliveries (workspace_id, newsletter_id, subscriber_id, email, status, claimed_at)
  values (p_workspace, p_newsletter, p_subscriber, v_email, 'sending', now())
  on conflict (newsletter_id, subscriber_id) do nothing
  returning id into v_id;

  return v_id;   -- null when the row already existed
end $$;
revoke all on function create_sequence_delivery(uuid, uuid, uuid) from public, authenticated, anon;
grant execute on function create_sequence_delivery(uuid, uuid, uuid) to service_role;

-- Enrolment counts for one sequence, for the UI.
create or replace function get_sequence_stats(p_privy text, p_workspace uuid, p_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((select jsonb_object_agg(status, n) from (
    select status, count(*) as n from sequence_enrollments
     where sequence_id = p_id and workspace_id = p_workspace group by status
  ) x), '{}'::jsonb);
end $$;
grant execute on function get_sequence_stats(text, uuid, uuid) to authenticated, anon;

-- ── Unsubscribe must also stop the drip ──────────────────────────────────────
-- 0071 predates sequences, so its newsletter_unsubscribe stops queued NEWSLETTER
-- deliveries but leaves sequence enrolments running — someone who unsubscribed
-- would keep receiving the rest of a drip. Redefined here IN FULL (rather than
-- patched from the dispatcher) so the guarantee lives at the point of
-- unsubscribing and cannot be missed by a future caller.
create or replace function newsletter_unsubscribe(p_token text, p_newsletter uuid default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_id uuid; v_ws uuid; v_email text;
begin
  select id, workspace_id, email into v_id, v_ws, v_email
    from newsletter_subscribers where token = p_token;
  if v_id is null then return jsonb_build_object('ok', false); end if;

  update newsletter_subscribers set status = 'unsubscribed'
   where id = v_id and status <> 'unsubscribed';

  if found then
    insert into newsletter_events (workspace_id, newsletter_id, subscriber_id, kind)
    values (v_ws, p_newsletter, v_id, 'unsubscribe');
  end if;

  update newsletter_deliveries set status = 'skipped', error = 'unsubscribed'
   where subscriber_id = v_id and status = 'pending';

  -- The addition: stop every drip this person is partway through.
  update sequence_enrollments set status = 'cancelled', finished_at = now()
   where subscriber_id = v_id and status in ('active', 'running');

  return jsonb_build_object('ok', true, 'email', v_email);
end $$;
revoke all on function newsletter_unsubscribe(text, uuid) from public, authenticated, anon;
grant execute on function newsletter_unsubscribe(text, uuid) to service_role;

-- Same for a bounce or complaint: the mail system said stop, so the drip stops.
create or replace function record_newsletter_feedback(p_email text, p_workspace uuid, p_kind text)
returns boolean language plpgsql security definer set search_path = public as $$
declare v_id uuid;
begin
  if p_kind not in ('bounce', 'complaint') then raise exception 'BAD_KIND'; end if;
  select id into v_id from newsletter_subscribers
   where workspace_id = p_workspace and lower(email) = lower(p_email);
  if v_id is null then return false; end if;

  update newsletter_subscribers
     set status = case when p_kind = 'bounce' then 'bounced' else 'complained' end
   where id = v_id;

  insert into newsletter_events (workspace_id, subscriber_id, kind)
  values (p_workspace, v_id, p_kind);

  update newsletter_deliveries set status = 'skipped', error = p_kind
   where subscriber_id = v_id and status = 'pending';

  update sequence_enrollments set status = 'cancelled', finished_at = now()
   where subscriber_id = v_id and status in ('active', 'running');
  return true;
end $$;
revoke all on function record_newsletter_feedback(text, uuid, text) from public, authenticated, anon;
grant execute on function record_newsletter_feedback(text, uuid, text) to service_role;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0074_lead_scoring.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0074_lead_scoring.sql
-- Engagement scoring: points per action, decaying with age, stored per
-- subscriber so segments can filter on it cheaply.
--
-- WHY A STORED COLUMN AND NOT A COMPUTED ONE. Score's whole purpose is to be
-- filtered on ("score above 20"), and 0072's engagement predicates already run
-- an EXISTS per row. Computing a decayed sum per row inside a segment filter
-- would multiply that cost by the number of events each person has. A column
-- refreshed in batches by the cron makes score comparisons a plain integer
-- scan, and the staleness it buys is at most one cron tick — irrelevant for a
-- number whose inputs decay over weeks.
--
-- WHY DECAY AT ALL. Without it, score is a lifetime total: someone who read
-- everything two years ago and nothing since outranks someone reading you now.
-- That inverts the one question the score exists to answer — who is warm TODAY.
-- Half-life is configurable per workspace; at the 30-day default a click is
-- worth half as much after a month and a sixteenth after four.
--
-- SCOPE, STATED: v1 scores newsletter engagement only (opens, clicks, and
-- negative signals). Form submissions and page views are deliberately out —
-- both would need matching an anonymous visitor to a subscriber, which is a
-- guess, and a scoring model built on a guess is worse than a narrower one that
-- is right.
--
-- Depends on 0070-0073. Additive, idempotent & prod-safe.
-- ============================================================================

create table if not exists scoring_settings (
  workspace_id   uuid primary key references workspaces(id) on delete cascade,
  enabled        boolean not null default false,
  -- Days after which a signal is worth half. 0 disables decay entirely.
  half_life_days int not null default 30 check (half_life_days between 0 and 3650),
  updated_at     timestamptz not null default now()
);
alter table scoring_settings enable row level security;
revoke all on table scoring_settings from anon, authenticated;

create table if not exists scoring_rules (
  workspace_id uuid not null references workspaces(id) on delete cascade,
  kind         text not null check (kind in ('open', 'click', 'unsubscribe', 'bounce', 'complaint')),
  points       int  not null default 0 check (points between -100 and 100),
  primary key (workspace_id, kind)
);
alter table scoring_rules enable row level security;
revoke all on table scoring_rules from anon, authenticated;

alter table newsletter_subscribers add column if not exists score int not null default 0;
alter table newsletter_subscribers add column if not exists score_updated_at timestamptz;
-- Partial index on the mailable population: nobody segments on the score of a
-- bounced address.
create index if not exists idx_nl_subs_score on newsletter_subscribers(workspace_id, score desc)
  where status = 'enabled';

-- ── Settings + rules ─────────────────────────────────────────────────────────
create or replace function get_scoring_config(p_privy text, p_workspace uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v jsonb;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  select jsonb_build_object(
    'enabled', coalesce(s.enabled, false),
    'half_life_days', coalesce(s.half_life_days, 30),
    'rules', coalesce((select jsonb_object_agg(r.kind, r.points)
                         from scoring_rules r where r.workspace_id = p_workspace), '{}'::jsonb)
  ) into v from (select 1) z
  left join scoring_settings s on s.workspace_id = p_workspace;
  return v;
end $$;
grant execute on function get_scoring_config(text, uuid) to authenticated, anon;

create or replace function save_scoring_config(
  p_privy text, p_workspace uuid, p_enabled boolean, p_half_life int, p_rules jsonb
) returns boolean language plpgsql security definer set search_path = public as $$
declare k text; v int;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  if p_half_life is null or p_half_life < 0 or p_half_life > 3650 then raise exception 'BAD_HALF_LIFE'; end if;
  if jsonb_typeof(coalesce(p_rules, '{}'::jsonb)) <> 'object' then raise exception 'BAD_RULES'; end if;

  insert into scoring_settings (workspace_id, enabled, half_life_days, updated_at)
  values (p_workspace, coalesce(p_enabled, false), p_half_life, now())
  on conflict (workspace_id) do update
    set enabled = excluded.enabled, half_life_days = excluded.half_life_days, updated_at = now();

  for k, v in select key, value::text::int from jsonb_each(coalesce(p_rules, '{}'::jsonb)) loop
    if k not in ('open', 'click', 'unsubscribe', 'bounce', 'complaint') then raise exception 'BAD_RULE_KIND'; end if;
    if v < -100 or v > 100 then raise exception 'BAD_POINTS'; end if;
    insert into scoring_rules (workspace_id, kind, points) values (p_workspace, k, v)
    on conflict (workspace_id, kind) do update set points = excluded.points;
  end loop;
  return true;
end $$;
grant execute on function save_scoring_config(text, uuid, boolean, int, jsonb) to authenticated, anon;

-- ── Recompute ────────────────────────────────────────────────────────────────
/**
 * Recompute scores for one workspace, oldest-first, in batches.
 *
 * decay = 0.5 ^ (age_days / half_life). At half_life = 0 there is no decay and
 * the score is a lifetime total — offered because some workspaces genuinely
 * want that, but not the default, for the reason in the header.
 *
 * Events older than ten half-lives contribute under 0.1% and are excluded, so a
 * subscriber with years of history does not cost proportionally more to score.
 *
 * Oldest-first by score_updated_at means the batch always advances: with a
 * fixed limit and a nulls-first ordering, everyone gets scored before anyone is
 * scored twice.
 */
create or replace function recompute_subscriber_scores(p_workspace uuid, p_limit int default 500)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_hl int; v_enabled boolean; v_n int; v_cutoff interval;
begin
  select enabled, half_life_days into v_enabled, v_hl
    from scoring_settings where workspace_id = p_workspace;
  if not coalesce(v_enabled, false) then return jsonb_build_object('scored', 0, 'skipped', 'disabled'); end if;
  v_hl := coalesce(v_hl, 30);
  v_cutoff := make_interval(days => case when v_hl = 0 then 36500 else least(v_hl * 10, 36500) end);

  with target as (
    select s.id from newsletter_subscribers s
     where s.workspace_id = p_workspace
     order by s.score_updated_at asc nulls first
     limit greatest(1, least(coalesce(p_limit, 500), 5000))
  ), scored as (
    select t.id,
           coalesce(round(sum(
             r.points * case when v_hl = 0 then 1.0
                             else power(0.5, extract(epoch from (now() - e.created_at)) / 86400.0 / v_hl)
                        end
           )), 0)::int as score
      from target t
      left join newsletter_events e
             on e.subscriber_id = t.id
            and e.created_at >= now() - v_cutoff
      left join scoring_rules r
             on r.workspace_id = p_workspace and r.kind = e.kind
     group by t.id
  )
  update newsletter_subscribers s
     set score = sc.score, score_updated_at = now()
    from scored sc where s.id = sc.id;
  get diagnostics v_n = row_count;

  return jsonb_build_object('scored', v_n, 'half_life_days', v_hl);
end $$;
revoke all on function recompute_subscriber_scores(uuid, int) from public, authenticated, anon;
grant execute on function recompute_subscriber_scores(uuid, int) to service_role;

create or replace function scoring_workspaces()
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  return coalesce((select jsonb_agg(workspace_id) from scoring_settings where enabled), '[]'::jsonb);
end $$;
revoke all on function scoring_workspaces() from public, authenticated, anon;
grant execute on function scoring_workspaces() to service_role;

-- ── segment_match, redefined IN FULL with the score field ────────────────────
-- Per the project convention: extend the latest definition rather than adding a
-- parallel one. Only the new `score` branch differs from 0072.
create or replace function segment_match(p_sub newsletter_subscribers, p_cond jsonb)
returns boolean language plpgsql stable set search_path = public as $$
declare
  f text := p_cond->>'field';
  o text := coalesce(p_cond->>'op', 'eq');
  v text := p_cond->>'value';
  n int  := case when coalesce(v, '') ~ '^-?\d{1,6}$' then v::int else null end;
begin
  if f is null then return false; end if;

  case f
    when 'status' then
      return case o when 'eq' then p_sub.status = v when 'neq' then p_sub.status <> v else false end;

    when 'email' then
      return case o
        when 'contains'     then p_sub.email ilike '%'||coalesce(v,'')||'%'
        when 'not_contains' then p_sub.email not ilike '%'||coalesce(v,'')||'%'
        when 'ends_with'    then p_sub.email ilike '%'||coalesce(v,'')
        else false end;

    when 'name' then
      return case o
        when 'contains' then p_sub.name ilike '%'||coalesce(v,'')||'%'
        when 'is_set'   then coalesce(p_sub.name,'') <> ''
        when 'is_empty' then coalesce(p_sub.name,'') = ''
        else false end;

    when 'consent_source' then
      return case o
        when 'eq'       then p_sub.consent_source = v
        when 'contains' then p_sub.consent_source ilike '%'||coalesce(v,'')||'%'
        else false end;

    when 'created_at' then
      return case o
        when 'within_days' then n is not null and n >= 0 and p_sub.created_at >= now() - make_interval(days => n)
        when 'before_days' then n is not null and n >= 0 and p_sub.created_at <  now() - make_interval(days => n)
        else false end;

    -- NEW in 0074. A plain integer comparison, which is exactly why score is a
    -- stored column rather than computed per row inside this function.
    when 'score' then
      return case o
        when 'gte' then n is not null and p_sub.score >= n
        when 'lte' then n is not null and p_sub.score <= n
        else false end;

    when 'on_list' then
      return case o
        when 'eq' then exists (
          select 1 from newsletter_list_subscribers ls join newsletter_lists l on l.id = ls.list_id
           where ls.subscriber_id = p_sub.id and l.workspace_id = p_sub.workspace_id and l.id::text = v)
        when 'neq' then not exists (
          select 1 from newsletter_list_subscribers ls join newsletter_lists l on l.id = ls.list_id
           where ls.subscriber_id = p_sub.id and l.workspace_id = p_sub.workspace_id and l.id::text = v)
        else false end;

    when 'opened' then
      return case o
        when 'within_days' then n is not null and exists (
          select 1 from newsletter_events e where e.subscriber_id = p_sub.id
            and e.kind = 'open' and e.created_at >= now() - make_interval(days => n))
        when 'not_within_days' then n is not null and not exists (
          select 1 from newsletter_events e where e.subscriber_id = p_sub.id
            and e.kind = 'open' and e.created_at >= now() - make_interval(days => n))
        when 'never' then not exists (
          select 1 from newsletter_events e where e.subscriber_id = p_sub.id and e.kind = 'open')
        else false end;

    when 'clicked' then
      return case o
        when 'within_days' then n is not null and exists (
          select 1 from newsletter_events e where e.subscriber_id = p_sub.id
            and e.kind = 'click' and e.created_at >= now() - make_interval(days => n))
        when 'not_within_days' then n is not null and not exists (
          select 1 from newsletter_events e where e.subscriber_id = p_sub.id
            and e.kind = 'click' and e.created_at >= now() - make_interval(days => n))
        when 'never' then not exists (
          select 1 from newsletter_events e where e.subscriber_id = p_sub.id and e.kind = 'click')
        else false end;

    when 'received' then
      return case o
        when 'never' then not exists (
          select 1 from newsletter_deliveries d where d.subscriber_id = p_sub.id and d.status = 'sent')
        when 'at_least' then n is not null and (
          select count(*) from newsletter_deliveries d
           where d.subscriber_id = p_sub.id and d.status = 'sent') >= n
        else false end;

    else return false;
  end case;
end $$;

-- Score is shown in the subscriber list, so it must be selected there.
create or replace function get_newsletter_subscribers(
  p_privy text, p_workspace uuid, p_list uuid default null,
  p_query text default null, p_limit int default 50, p_offset int default 0
) returns jsonb language plpgsql security definer set search_path = public as $$
declare v_rows jsonb; v_total bigint; v_lim int; v_off int;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  v_lim := greatest(1, least(coalesce(p_limit, 50), 200));
  v_off := greatest(0, coalesce(p_offset, 0));

  select count(*) into v_total
    from newsletter_subscribers s
   where s.workspace_id = p_workspace
     and (p_list is null or exists (select 1 from newsletter_list_subscribers ls
                                     where ls.subscriber_id = s.id and ls.list_id = p_list))
     and (p_query is null or p_query = '' or s.email ilike '%'||p_query||'%' or s.name ilike '%'||p_query||'%');

  select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc), '[]'::jsonb) into v_rows from (
    select s.id, s.email, s.name, s.status, s.person_id, s.consent_source, s.consent_at,
           s.score, s.created_at
      from newsletter_subscribers s
     where s.workspace_id = p_workspace
       and (p_list is null or exists (select 1 from newsletter_list_subscribers ls
                                       where ls.subscriber_id = s.id and ls.list_id = p_list))
       and (p_query is null or p_query = '' or s.email ilike '%'||p_query||'%' or s.name ilike '%'||p_query||'%')
     order by s.created_at desc
     limit v_lim offset v_off
  ) x;

  return jsonb_build_object('rows', v_rows, 'total', v_total);
end $$;
grant execute on function get_newsletter_subscribers(text, uuid, uuid, text, int, int) to authenticated, anon;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0075_chat.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0075_chat.sql
-- Team chat: channels, messages, and unread state.
--
-- WHY BUILD THIS RATHER THAN INTEGRATE SLACK. The value is not chat — it is chat
-- ATTACHED TO RECORDS. A thread on an invoice, a candidate, a deal, sitting in
-- the same database as the thing it is about. Slack structurally cannot do that
-- because it does not know what an invoice is. That also bounds the scope: the
-- hard parts of a chat product (presence, infinite history, mobile push,
-- threading depth) are not where the value is, so v1 leaves them out.
--
-- VISIBILITY IS DECIDED IN SQL, ONCE. `can_read_channel` is the single predicate
-- every read and write goes through. A public channel is readable by any
-- workspace member; a private one only by its members. Scattering that rule
-- across a dozen RPCs is how a private channel eventually leaks — so it is one
-- function, and every other function calls it.
--
-- NO REALTIME SUBSCRIPTION IN V1, DELIBERATELY. Supabase Realtime delivers
-- Postgres changes to the BROWSER using the anon key and RLS policies. This
-- project revokes anon/authenticated on everything and routes reads through the
-- verified /api/rpc proxy (0040/0046). Opening RLS policies on messages purely
-- to get a websocket would reintroduce exactly the hole that proxy closed. The
-- client polls instead; the cost is a few seconds of latency, and the honest
-- upgrade path is a server-side SSE endpoint, not loosened RLS.
--
-- Depends on 0001 (workspaces). Additive, idempotent & prod-safe.
-- ============================================================================

create table if not exists channels (
  id            uuid primary key default gen_random_uuid(),
  workspace_id  uuid not null references workspaces(id) on delete cascade,
  name          text not null default 'general',
  topic         text not null default '',
  is_private    boolean not null default false,
  -- The differentiator: a channel that belongs to a record. Free-text object
  -- name rather than a FK, matching how files and automations already reference
  -- objects across a schema where each lives in its own table.
  linked_object text,
  linked_id     uuid,
  created_by_privy text,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);
create index if not exists idx_channels_ws on channels(workspace_id, updated_at desc);
create index if not exists idx_channels_linked on channels(workspace_id, linked_object, linked_id)
  where linked_object is not null;
drop trigger if exists trg_channels_upd on channels;
create trigger trg_channels_upd before update on channels for each row execute function set_updated_at();
alter table channels enable row level security;
revoke all on table channels from anon, authenticated;

create table if not exists channel_members (
  channel_id   uuid not null references channels(id) on delete cascade,
  privy_user_id text not null,
  -- Where this person has read up to. Nullable = never opened it, which is
  -- distinct from "read nothing since the epoch".
  last_read_at timestamptz,
  joined_at    timestamptz not null default now(),
  primary key (channel_id, privy_user_id)
);
create index if not exists idx_channel_members_user on channel_members(privy_user_id);
alter table channel_members enable row level security;
revoke all on table channel_members from anon, authenticated;

create table if not exists messages (
  id           uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspaces(id) on delete cascade,
  channel_id   uuid not null references channels(id) on delete cascade,
  author_privy text not null,
  -- Snapshotted. Resolving a display name at read time would mean a join per
  -- message against a directory that may no longer hold the author, and a
  -- message from someone who has left should still say who wrote it.
  author_name  text not null default '',
  -- 'user' | 'agent' | 'system'. Agents post as themselves rather than
  -- impersonating a person; a reader must always be able to tell.
  author_kind  text not null default 'user' check (author_kind in ('user', 'agent', 'system')),
  body         text not null default '',
  -- Soft delete: a hole in a conversation is more confusing than a tombstone,
  -- and replies above and below stop making sense without one.
  deleted_at   timestamptz,
  edited_at    timestamptz,
  created_at   timestamptz not null default now()
);
create index if not exists idx_messages_channel on messages(channel_id, created_at desc);
alter table messages enable row level security;
revoke all on table messages from anon, authenticated;

-- ── The one visibility predicate ─────────────────────────────────────────────
create or replace function can_read_channel(p_channel uuid, p_privy text)
returns boolean language sql stable set search_path = public as $$
  select exists (
    select 1 from channels c
     where c.id = p_channel
       and is_workspace_member(c.workspace_id, p_privy)
       and (
         not c.is_private
         or exists (select 1 from channel_members m
                     where m.channel_id = c.id and m.privy_user_id = p_privy)
       )
  );
$$;

-- ── Channels ─────────────────────────────────────────────────────────────────
create or replace function get_channels(p_privy text, p_workspace uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((select jsonb_agg(to_jsonb(x) order by x.name) from (
    select c.id, c.name, c.topic, c.is_private, c.linked_object, c.linked_id, c.updated_at,
           exists (select 1 from channel_members m
                    where m.channel_id = c.id and m.privy_user_id = p_privy) as joined,
           -- Unread count. A channel never opened counts everything, which is
           -- why last_read_at is nullable rather than defaulted to now().
           (select count(*) from messages msg
             where msg.channel_id = c.id and msg.deleted_at is null
               and msg.author_privy <> p_privy
               and (msg.created_at > (select m.last_read_at from channel_members m
                                       where m.channel_id = c.id and m.privy_user_id = p_privy)
                    or (select m.last_read_at from channel_members m
                         where m.channel_id = c.id and m.privy_user_id = p_privy) is null)
           ) as unread
      from channels c
     where c.workspace_id = p_workspace
       and (not c.is_private
            or exists (select 1 from channel_members m
                        where m.channel_id = c.id and m.privy_user_id = p_privy))
  ) x), '[]'::jsonb);
end $$;
grant execute on function get_channels(text, uuid) to authenticated, anon;

create or replace function create_channel(
  p_privy text, p_workspace uuid, p_name text, p_topic text default '',
  p_private boolean default false, p_object text default null, p_id uuid default null
) returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid; v_name text;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  -- Slack-ish normalisation, so #Sales and #sales are not two channels.
  v_name := lower(trim(regexp_replace(coalesce(nullif(p_name,''),'general'), '[^a-zA-Z0-9 _-]', '', 'g')));
  v_name := regexp_replace(v_name, '\s+', '-', 'g');
  if v_name = '' then v_name := 'general'; end if;
  if length(v_name) > 60 then v_name := left(v_name, 60); end if;

  insert into channels (workspace_id, name, topic, is_private, linked_object, linked_id, created_by_privy)
  values (p_workspace, v_name, coalesce(p_topic,''), coalesce(p_private,false), p_object, p_id, p_privy)
  returning id into v_id;

  -- The creator is always a member, private or not — otherwise creating a
  -- private channel would immediately lock its author out of it.
  insert into channel_members (channel_id, privy_user_id) values (v_id, p_privy)
  on conflict do nothing;
  return v_id;
end $$;
grant execute on function create_channel(text, uuid, text, text, boolean, text, uuid) to authenticated, anon;

create or replace function delete_channel(p_privy text, p_workspace uuid, p_id uuid)
returns boolean language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  if not can_read_channel(p_id, p_privy) then raise exception 'NO_ACCESS'; end if;
  delete from channels where id = p_id and workspace_id = p_workspace;
  return found;
end $$;
grant execute on function delete_channel(text, uuid, uuid) to authenticated, anon;

create or replace function join_channel(p_privy text, p_id uuid)
returns boolean language plpgsql security definer set search_path = public as $$
begin
  -- can_read_channel already excludes a private channel you are not in, so this
  -- cannot be used to add yourself to one.
  if not can_read_channel(p_id, p_privy) then raise exception 'NO_ACCESS'; end if;
  insert into channel_members (channel_id, privy_user_id) values (p_id, p_privy)
  on conflict do nothing;
  return true;
end $$;
grant execute on function join_channel(text, uuid) to authenticated, anon;

create or replace function add_channel_member(p_privy text, p_id uuid, p_member text)
returns boolean language plpgsql security definer set search_path = public as $$
declare v_ws uuid;
begin
  if not can_read_channel(p_id, p_privy) then raise exception 'NO_ACCESS'; end if;
  select workspace_id into v_ws from channels where id = p_id;
  -- The invitee must already be in the workspace. Without this check a private
  -- channel becomes a way to expose workspace data to an arbitrary Privy id.
  if not is_workspace_member(v_ws, p_member) then raise exception 'NOT_A_MEMBER'; end if;
  insert into channel_members (channel_id, privy_user_id) values (p_id, p_member)
  on conflict do nothing;
  return true;
end $$;
grant execute on function add_channel_member(text, uuid, text) to authenticated, anon;

create or replace function leave_channel(p_privy text, p_id uuid)
returns boolean language plpgsql security definer set search_path = public as $$
begin
  delete from channel_members where channel_id = p_id and privy_user_id = p_privy;
  return found;
end $$;
grant execute on function leave_channel(text, uuid) to authenticated, anon;

-- ── Messages ─────────────────────────────────────────────────────────────────
/**
 * Newest-first with a `before` cursor, not offset paging. A conversation grows
 * at the end someone is reading, so offsets shift under the reader and produce
 * duplicated or skipped messages while they scroll.
 */
create or replace function get_messages(
  p_privy text, p_channel uuid, p_before timestamptz default null, p_limit int default 50
) returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not can_read_channel(p_channel, p_privy) then raise exception 'NO_ACCESS'; end if;
  return coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at asc) from (
    select m.id, m.author_privy, m.author_name, m.author_kind,
           -- The body of a deleted message is never returned, not even to the
           -- author: a tombstone that still carries its text is not a deletion.
           case when m.deleted_at is null then m.body else '' end as body,
           m.deleted_at is not null as deleted, m.edited_at, m.created_at
      from messages m
     where m.channel_id = p_channel
       and (p_before is null or m.created_at < p_before)
     order by m.created_at desc
     limit greatest(1, least(coalesce(p_limit, 50), 200))
  ) x), '[]'::jsonb);
end $$;
grant execute on function get_messages(text, uuid, timestamptz, int) to authenticated, anon;

create or replace function post_message(
  p_privy text, p_channel uuid, p_body text, p_author_name text default ''
) returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid; v_ws uuid; v_body text;
begin
  if not can_read_channel(p_channel, p_privy) then raise exception 'NO_ACCESS'; end if;
  v_body := left(trim(coalesce(p_body, '')), 8000);
  if v_body = '' then raise exception 'EMPTY_MESSAGE'; end if;
  select workspace_id into v_ws from channels where id = p_channel;

  insert into messages (workspace_id, channel_id, author_privy, author_name, body)
  values (v_ws, p_channel, p_privy, left(coalesce(p_author_name,''), 80), v_body)
  returning id into v_id;

  -- Posting implies membership and implies you have read up to now — otherwise
  -- your own message shows as unread to you.
  insert into channel_members (channel_id, privy_user_id, last_read_at)
  values (p_channel, p_privy, now())
  on conflict (channel_id, privy_user_id) do update set last_read_at = now();

  update channels set updated_at = now() where id = p_channel;
  return v_id;
end $$;
grant execute on function post_message(text, uuid, text, text) to authenticated, anon;

create or replace function edit_message(p_privy text, p_id uuid, p_body text)
returns boolean language plpgsql security definer set search_path = public as $$
declare v_body text;
begin
  v_body := left(trim(coalesce(p_body, '')), 8000);
  if v_body = '' then raise exception 'EMPTY_MESSAGE'; end if;
  -- Author only. Channel access is not enough to rewrite someone else's words.
  update messages set body = v_body, edited_at = now()
   where id = p_id and author_privy = p_privy and deleted_at is null;
  return found;
end $$;
grant execute on function edit_message(text, uuid, text) to authenticated, anon;

create or replace function delete_message(p_privy text, p_id uuid)
returns boolean language plpgsql security definer set search_path = public as $$
begin
  update messages set deleted_at = now(), body = ''
   where id = p_id and author_privy = p_privy and deleted_at is null;
  return found;
end $$;
grant execute on function delete_message(text, uuid) to authenticated, anon;

create or replace function mark_channel_read(p_privy text, p_channel uuid)
returns boolean language plpgsql security definer set search_path = public as $$
begin
  if not can_read_channel(p_channel, p_privy) then raise exception 'NO_ACCESS'; end if;
  insert into channel_members (channel_id, privy_user_id, last_read_at)
  values (p_channel, p_privy, now())
  on conflict (channel_id, privy_user_id) do update set last_read_at = now();
  return true;
end $$;
grant execute on function mark_channel_read(text, uuid) to authenticated, anon;

-- ── Agents post here ─────────────────────────────────────────────────────────
/**
 * Service-role only, so an agent's run summary can land in a channel instead of
 * a runs table nobody opens. author_kind is forced to 'agent' — an agent must
 * never be able to post as a person, and the reader must always be able to
 * tell which is which.
 */
create or replace function post_agent_message(
  p_workspace uuid, p_channel uuid, p_agent_name text, p_body text
) returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid;
begin
  if not exists (select 1 from channels where id = p_channel and workspace_id = p_workspace) then
    return null;
  end if;
  insert into messages (workspace_id, channel_id, author_privy, author_name, author_kind, body)
  values (p_workspace, p_channel, 'agent', left(coalesce(p_agent_name,'Agent'), 80), 'agent',
          left(trim(coalesce(p_body,'')), 8000))
  returning id into v_id;
  update channels set updated_at = now() where id = p_channel;
  return v_id;
end $$;
revoke all on function post_agent_message(uuid, uuid, text, text) from public, authenticated, anon;
grant execute on function post_agent_message(uuid, uuid, text, text) to service_role;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0076_provision_and_harden.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0076_provision_and_harden.sql
-- Closes the tenant-isolation bypass on the HR half, in the only order that
-- works: give the browser server-side replacements FIRST. The actual table lock
-- is 0077, run after the app carrying these changes is deployed.
--
-- THE BYPASS, precisely, because it is worth writing down:
--   1. `companies` is anon-readable  → anyone gets any company's id
--   2. `company_users` is anon-WRITABLE → insert (privy_user_id = mine,
--      company_id = theirs)
--   3. hr_company_id(p_privy) resolves PURELY from company_users (0051)
--   4. hr_overview_data / hr_analytics_data / candidate reads all call
--      hr_company_id() and then serve that company's candidates, CVs,
--      assessment results and messages
-- The anon key ships in the browser bundle by design, so steps 1-2 need nothing
-- but a fetch. The CRM half was never affected: is_workspace_member reads
-- `accounts`, which has always been locked.
--
-- This migration does three things:
--   A. ensure_workspace()   — server-side, Privy-verified provisioning, so
--      onboarding stops needing anon INSERT on companies/company_users.
--   B. get_my_hr_companies()— the read the browser needs for login/plans/team.
--   C. hr_company_id()      — hardened to cross-check `accounts`, so a stray
--      company_users row grants nothing even if one is ever written again.
--
-- C is the important one. A and B remove the *need* for the open policies; C
-- means the exploit fails even while they are still open, and keeps failing if
-- a policy is ever re-added by mistake. Defence in depth, not belt-and-braces:
-- 0077 is a policy change, and policies are exactly the thing that gets
-- reinstated by an unrelated migration a year from now.
--
-- Additive, idempotent & prod-safe. Safe to run BEFORE deploying the app.
-- ============================================================================

-- ── A. Server-side provisioning ──────────────────────────────────────────────
/**
 * Create a company + owner membership + default assessment template, atomically.
 *
 * Replaces three separate client-side anon INSERTs in app/auth/register. Beyond
 * closing the write path, this fixes the silent-failure mode that made
 * onboarding fragile: the old flow could create the company, fail on the
 * membership, and leave someone signed in with no workspace and no error worth
 * showing. One function in one transaction cannot half-succeed.
 *
 * Idempotent by design: if this Privy user already has a company, return it
 * rather than making a second one. A double-submitted registration form used to
 * produce two companies.
 */
create or replace function ensure_workspace(
  p_privy text, p_company_name text, p_subdomain text, p_email text, p_full_name text
) returns jsonb language plpgsql security definer set search_path = public as $$
declare v_company uuid; v_sub text; v_existing uuid;
begin
  if coalesce(trim(p_privy), '') = '' then raise exception 'NO_IDENTITY'; end if;

  -- Already provisioned? Hand back what they have. ORDER BY created_at, not
  -- limit(1) alone: someone in two companies must get a STABLE answer, and an
  -- unordered limit returns an arbitrary row (the bug 0051 documents).
  select cu.company_id into v_existing
    from company_users cu where cu.privy_user_id = p_privy
   order by cu.created_at limit 1;
  if v_existing is not null then
    return jsonb_build_object('company_id', v_existing, 'created', false);
  end if;

  v_sub := lower(regexp_replace(coalesce(p_subdomain, ''), '[^a-zA-Z0-9-]', '', 'g'));
  if length(v_sub) < 2 then raise exception 'BAD_SUBDOMAIN'; end if;
  if exists (select 1 from companies where subdomain = v_sub) then raise exception 'SUBDOMAIN_TAKEN'; end if;

  insert into companies (name, subdomain, plan)
  values (coalesce(nullif(trim(p_company_name), ''), 'My company'), v_sub, 'free')
  returning id into v_company;

  insert into company_users (company_id, email, full_name, role, privy_user_id)
  values (v_company, coalesce(p_email, ''), coalesce(nullif(trim(p_full_name), ''), 'User'), 'owner', p_privy);

  insert into assessment_templates (company_id, name, description, questions, is_default)
  values (v_company, 'Default Assessment',
          'Standard personality and work style assessment',
          '[{"id":"1","category":"personality","trait":"Extraversion","text":"I enjoy being the center of attention","type":"scale","options":["Strongly Disagree","Disagree","Neutral","Agree","Strongly Agree"]},
            {"id":"2","category":"work_style","text":"I prefer to:","type":"choice","options":["Work independently","Work in teams","Mix of both"]}]'::jsonb,
          true);

  -- The 0005 trigger mirrors companies -> workspaces and creates the accounts
  -- row. It is exception-safe, so verify rather than assume: without an accounts
  -- row the CRM half sees no workspace at all, which is the silent failure this
  -- function exists to end.
  if not exists (select 1 from accounts where workspace_id = v_company and privy_user_id = p_privy) then
    insert into accounts (workspace_id, privy_user_id, role)
    values (v_company, p_privy, 'owner')
    on conflict do nothing;
  end if;

  return jsonb_build_object('company_id', v_company, 'created', true);
end $$;
revoke all on function ensure_workspace(text, text, text, text, text) from public, anon, authenticated;
grant execute on function ensure_workspace(text, text, text, text, text) to service_role;

/** Is this subdomain free? Read-only, so the register form can check as you type. */
create or replace function subdomain_available(p_subdomain text)
returns boolean language sql stable security definer set search_path = public as $$
  select not exists (
    select 1 from companies
     where subdomain = lower(regexp_replace(coalesce(p_subdomain,''), '[^a-zA-Z0-9-]', '', 'g'))
  );
$$;
revoke all on function subdomain_available(text) from public, anon, authenticated;
grant execute on function subdomain_available(text) to service_role;

-- ── B. The read the browser still needs ──────────────────────────────────────
/**
 * Which HR companies does this user belong to? Replaces four direct
 * `.from('company_users')` reads in the browser (login, plans, team, register).
 *
 * Returns only the caller's OWN memberships — p_privy is overwritten by the
 * /api/rpc proxy from the verified token, so it cannot be used to enumerate
 * anyone else's.
 */
create or replace function get_my_hr_companies(p_privy text)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if coalesce(trim(p_privy), '') = '' then return '[]'::jsonb; end if;
  return coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at) from (
    select cu.company_id, cu.role, cu.full_name, cu.email, cu.created_at,
           c.name as company_name, c.plan, c.subdomain
      from company_users cu
      join companies c on c.id = cu.company_id
     where cu.privy_user_id = p_privy
  ) x), '[]'::jsonb);
end $$;
grant execute on function get_my_hr_companies(text) to authenticated, anon;

-- ── C. Harden the resolver ───────────────────────────────────────────────────
/**
 * hr_company_id, redefined IN FULL with an `accounts` cross-check.
 *
 * 0051's version trusted company_users alone. That is what turned an anon INSERT
 * into full read access over another tenant's candidates. Requiring a matching
 * `accounts` row — a table that has always been locked and is only written by
 * the 0005 trigger and ensure_workspace — means a forged company_users row
 * resolves to NULL and every HR RPC returns nothing.
 *
 * Same resolution ORDER as before, so behaviour is unchanged for real members:
 * the active workspace first, else the OLDEST membership.
 */
create or replace function hr_company_id(p_privy text)
returns uuid language sql stable security definer set search_path = public as $$
  select coalesce(
    (select cu.company_id from company_users cu
      where cu.privy_user_id = p_privy
        and cu.company_id = effective_workspace(p_privy)
        and exists (select 1 from accounts a
                     where a.workspace_id = cu.company_id and a.privy_user_id = p_privy)),
    (select cu.company_id from company_users cu
      where cu.privy_user_id = p_privy
        and exists (select 1 from accounts a
                     where a.workspace_id = cu.company_id and a.privy_user_id = p_privy)
      order by cu.created_at limit 1)
  );
$$;

/**
 * redeem_invite, redefined IN FULL to also create the accounts row.
 *
 * This is a latent bug the hardening above exposed: 0051's version sets
 * company_users.privy_user_id and calls set_active_workspace (which writes
 * user_settings), but never touches `accounts`. So every INVITED team member
 * has had a company_users row with no accounts row — and the hardened resolver
 * would have locked all of them out.
 *
 * Fixing it here rather than only backfilling matters: a backfill closes the
 * gap for people who joined before today, and this closes it for everyone who
 * joins after.
 */
create or replace function redeem_invite(p_token uuid, p_privy text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_id uuid; v_company uuid; v_role text; v_name text;
begin
  if p_token is null or coalesce(trim(p_privy),'') = '' then
    return jsonb_build_object('ok', false, 'reason', 'missing_token');
  end if;

  select cu.id, cu.company_id, cu.role into v_id, v_company, v_role
    from company_users cu
   where cu.invite_token = p_token
   limit 1;
  if v_id is null then
    return jsonb_build_object('ok', false, 'reason', 'invalid_or_used');
  end if;

  if exists (select 1 from company_users
              where company_id = v_company and privy_user_id = p_privy) then
    update company_users set invite_token = null where id = v_id;
    perform set_active_workspace(p_privy, v_company);
    -- Even the already-a-member path repairs the accounts row, so an invite
    -- re-clicked by an existing member fixes them rather than doing nothing.
    insert into accounts (workspace_id, privy_user_id, role)
    values (v_company, p_privy, case when v_role in ('owner','admin') then v_role else 'member' end)
    on conflict do nothing;
    return jsonb_build_object('ok', true, 'already_member', true);
  end if;

  update company_users
     set privy_user_id = p_privy, invite_token = null
   where id = v_id;

  -- THE ADDITION. Without this the invitee has no accounts row, so the CRM half
  -- sees no workspace for them and the hardened hr_company_id returns null.
  insert into accounts (workspace_id, privy_user_id, role)
  values (v_company, p_privy, case when v_role in ('owner','admin') then v_role else 'member' end)
  on conflict do nothing;

  perform set_active_workspace(p_privy, v_company);

  select name into v_name from companies where id = v_company;
  return jsonb_build_object('ok', true, 'company_id', v_company,
                            'company_name', v_name, 'role', v_role);
end $$;
revoke all on function redeem_invite(uuid, text) from public, anon, authenticated;
grant execute on function redeem_invite(uuid, text) to service_role;

/**
 * Backfill, and REPORT what it did.
 *
 * Every legitimate member who predates the fix above needs an accounts row, or
 * the hardened resolver locks them out — a real customer losing access is a far
 * worse outcome than the bypass this migration closes.
 *
 * But there is no way to tell a legitimate historical row from a FORGED one:
 * company_users has been anon-writable for the life of the product, and a forged
 * row looks exactly like an invited one. Backfilling grants both.
 *
 * So this does not pretend to decide. It backfills (nobody is locked out) and
 * RAISES A NOTICE naming every workspace/user pair it touched. Read that list:
 * a privy_user_id you do not recognise against a company you own is an intruder
 * who was already inside, and the fix is to delete that company_users row —
 * which 0077 then makes impossible to recreate.
 */
do $$
declare r record; n int := 0;
begin
  for r in
    select cu.company_id, cu.privy_user_id, cu.email, cu.role, cu.created_at
      from company_users cu
      join workspaces w on w.id = cu.company_id
     where cu.privy_user_id is not null
       and not exists (select 1 from accounts a
                        where a.workspace_id = cu.company_id and a.privy_user_id = cu.privy_user_id)
     order by cu.company_id, cu.created_at
  loop
    insert into accounts (workspace_id, privy_user_id, role)
    values (r.company_id, r.privy_user_id,
            case when r.role in ('owner','admin') then r.role else 'member' end)
    on conflict do nothing;
    raise notice 'BACKFILLED workspace=% privy=% email=% role=% joined=%',
      r.company_id, r.privy_user_id, r.email, r.role, r.created_at;
    n := n + 1;
  end loop;
  raise notice '--- backfilled % account row(s). REVIEW the list above for identities you do not recognise.', n;
end $$;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0077_lock_hr_tables.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0077_lock_hr_tables.sql
-- Closes the anon read/write policies on the legacy ATS tables.
--
-- ⚠️ RUN ORDER — THIS ONE BREAKS THINGS IF RUN EARLY.
--   Run 0076 FIRST, and deploy the app carrying its client changes BEFORE
--   running this. Until that deploy is live, the browser still reads
--   `company_users` directly on the login, register, plans and team screens,
--   and this migration makes every one of those return nothing:
--     • login sends existing customers back through onboarding
--     • register cannot check a subdomain or create a company
--     • plans and team render empty
--   0076 is safe on its own and can sit in production indefinitely. This one is
--   the point of no return.
--
-- WHAT IT CLOSES. `company_users` was anon-WRITABLE. hr_company_id() resolved
-- from it alone, so inserting one row with your own Privy DID and someone
-- else's company id handed you their candidates, CVs, assessment results and
-- messages. `companies` being anon-readable supplied the ids. The anon key
-- ships in the browser bundle, so the whole chain needed nothing but a fetch.
--
-- 0076 already hardened hr_company_id to cross-check `accounts`, so the bypass
-- is dead either way. This removes the write primitive as well — defence in
-- depth, because a resolver is code and a policy is configuration, and the two
-- fail independently.
--
-- Same shape as 0042, which did this for the other legacy tables.
--
-- Rollback if something breaks:
--   create policy "tmp_anon_read" on public.<table> for select to anon using (true);
-- …then fix forward. Do not leave that policy in place.
-- ============================================================================

do $$
declare
  t text;
  p record;
  n_dropped int := 0;
  -- Every table the audit found with anon read+write. `positions` is included:
  -- the public job page reads it, but through get_careers_position /
  -- hr_list_positions_min server-side, never from the browser.
  targets text[] := array[
    'companies',
    'company_users',
    'assessment_templates',
    'candidate_messages',
    'consent_logs',
    'contact_messages',
    'message_templates',
    'positions',
    'tracking_links'
  ];
begin
  foreach t in array targets loop
    if to_regclass('public.' || t) is null then
      raise notice 'skip % (table not present)', t;
      continue;
    end if;

    -- Drop policies by iteration rather than by name: these were created across
    -- several migrations and by hand in the dashboard, so no fixed list of
    -- names is trustworthy.
    for p in
      select policyname from pg_policies
       where schemaname = 'public' and tablename = t
    loop
      execute format('drop policy if exists %I on public.%I', p.policyname, t);
      n_dropped := n_dropped + 1;
    end loop;

    -- RLS on with zero policies = nothing reaches it except service_role, which
    -- bypasses RLS entirely. That is what every other table in this schema does.
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on table public.%I from anon, authenticated', t);

    raise notice 'locked %', t;
  end loop;

  raise notice '--- dropped % policy(ies) across % table(s)', n_dropped, array_length(targets, 1);
end $$;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0078_api_key_scopes.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0078_api_key_scopes.sql
-- Read-only API keys, so a spreadsheet feed URL cannot write.
--
-- WHY THIS EXISTS. Excel's built-in "Get Data → From Web" (Power Query) cannot
-- send an Authorization header from its basic dialog — custom headers need
-- hand-written M code, and Excel Online cannot do them at all. So a feed a
-- non-technical person can actually use has to carry its key in the URL.
--
-- A key in a URL is a bearer credential that ends up in browser history,
-- forwarded emails, screen shares and server logs. That is acceptable for a
-- read-only credential and NOT acceptable for one that can create records. So:
--
--   • keys gain a scope: 'full' (existing behaviour) or 'read'
--   • the feed route accepts a key from the QUERY STRING only when its scope is
--     'read', and never allows a write with a query-string key at all
--
-- The second rule is the important one, and it lives in the route rather than
-- here: even a 'full' key pasted into a URL cannot write, because the transport
-- itself is treated as untrusted. That bounds URL leakage structurally instead
-- of relying on the user to have picked the right key type.
--
-- Existing keys default to 'full', so nothing changes for current integrations.
-- Additive, idempotent & prod-safe.
-- ============================================================================

alter table api_keys add column if not exists scope text not null default 'full';
do $$ begin
  alter table api_keys add constraint api_keys_scope_check check (scope in ('full', 'read'));
exception when duplicate_object then null; end $$;

-- ── Create, with a scope ─────────────────────────────────────────────────────
-- Adding a parameter would create an OVERLOAD rather than replace the function,
-- so the three-argument version is dropped first. Anon EXECUTE is revoked (0046)
-- and every caller goes through /api/rpc, so nothing is pinned to the old shape.
drop function if exists create_api_key(text, uuid, text);

create or replace function create_api_key(
  p_privy text, p_workspace uuid, p_name text, p_scope text default 'full'
) returns text language plpgsql security definer set search_path = public as $$
declare v_key text; v_prefix text; v_scope text;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  -- Anything unrecognised becomes 'read', not 'full'. A typo in a scope must
  -- never widen a credential.
  v_scope := case when p_scope = 'full' then 'full' else 'read' end;
  v_key := 'hb_' || replace(gen_random_uuid()::text, '-', '') || replace(gen_random_uuid()::text, '-', '');
  v_prefix := left(v_key, 11);
  insert into api_keys (workspace_id, name, prefix, key_hash, scope, created_by_privy)
  values (p_workspace, coalesce(nullif(p_name,''),'API key'), v_prefix,
          encode(sha256(v_key::bytea), 'hex'), v_scope, p_privy);
  return v_key;   -- shown once, never stored in plaintext
end $$;
grant execute on function create_api_key(text, uuid, text, text) to authenticated, anon;

-- ── Resolve, returning the scope ─────────────────────────────────────────────
create or replace function resolve_api_key(p_hash text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_row api_keys;
begin
  select * into v_row from api_keys where key_hash = p_hash and revoked = false limit 1;
  if v_row.id is null then return null; end if;
  update api_keys set last_used_at = now() where id = v_row.id;
  return jsonb_build_object(
    'id', v_row.id, 'workspace_id', v_row.workspace_id,
    'owner_privy', v_row.created_by_privy,
    -- coalesce, not v_row.scope alone: a key created before this migration has
    -- the column default, but being explicit means a future nullable column
    -- cannot silently resolve to an empty scope the route then mis-reads.
    'scope', coalesce(v_row.scope, 'full')
  );
end $$;
revoke all on function resolve_api_key(text) from public, authenticated, anon;
grant execute on function resolve_api_key(text) to service_role;

-- ── List, showing the scope ──────────────────────────────────────────────────
create or replace function get_api_keys(p_privy text, p_workspace uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
    'id', k.id, 'name', k.name, 'prefix', k.prefix, 'scope', coalesce(k.scope, 'full'),
    'last_used_at', k.last_used_at, 'revoked', k.revoked, 'created_at', k.created_at
  ) order by k.created_at desc) from api_keys k where k.workspace_id = p_workspace), '[]'::jsonb);
end $$;
grant execute on function get_api_keys(text, uuid) to authenticated, anon;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0079_excel_sync.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0079_excel_sync.sql
-- Two-way Excel sync over Microsoft Graph: someone edits the workbook, the
-- workspace sees it; someone edits the workspace, the workbook sees it.
--
-- WHY THIS EXISTS ALONGSIDE 0078.
-- 0078's feed is a URL you paste into Excel: zero setup, works for anyone, and
-- strictly one-way (Excel reads, never writes). That covers "I want these
-- numbers in my sheet". It does NOT cover "my team works IN the sheet" — the
-- actual situation in most companies, where the spreadsheet is where the edits
-- happen and the app is downstream. That needs write access to the workbook,
-- which needs OAuth, which is what this migration stores.
--
-- The two are complementary and both stay: the feed for people who just want
-- data, this for people whose workbook is the source of truth.
--
-- THE HARD PART IS NOT THE API, IT IS THE CONFLICT RULE.
-- Graph gives no per-cell change timestamps, so a real three-way merge is not
-- available at any price. Rather than fake one, the rule is stated plainly and
-- enforced in one place (lib/excel/sync.ts):
--
--   • inbound runs FIRST — a person editing a cell is the most recent intent
--   • then outbound rewrites the sheet from the database, so both agree
--   • a sheet row with no id is a NEW record
--   • a row DELETED from the sheet never deletes the record
--
-- That last rule is the one that matters. A filtered view, a sort that pushed
-- rows below the table range, or someone clearing a few lines all look exactly
-- like deletion over the API, and a sync that honoured them would silently
-- destroy data with no undo. Deleting is done in the app, on purpose.
--
-- TOKENS ARE ENCRYPTED AT REST (lib/crypto/secrets.ts), unlike the older
-- integration_tokens rows. A Files.ReadWrite token opens every workbook the
-- person can open, including ones that have nothing to do with us, so a leaked
-- database dump must not be a leaked OneDrive.
--
-- Depends on 0001 (workspaces, is_workspace_member).
-- Idempotent & prod-safe.
-- ============================================================================

-- ── The OAuth connection ─────────────────────────────────────────────────────
-- Per (workspace, person): the grant is personal — it is that person's OneDrive
-- or SharePoint access — but it is used on behalf of a workspace, and both have
-- to match before any sync runs.
create table if not exists ms_connections (
  id             uuid primary key default gen_random_uuid(),
  workspace_id   uuid not null references workspaces(id) on delete cascade,
  privy_user_id  text not null,
  account_email  text,
  -- Sealed with SECRETS_MASTER_KEY (AES-256-GCM). Never selected by the RPCs
  -- below — only the service-role sync path reads them.
  access_cipher  text, access_iv text, access_tag text,
  refresh_cipher text, refresh_iv text, refresh_tag text,
  expires_at     timestamptz,
  scope          text,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  unique (workspace_id, privy_user_id)
);

alter table ms_connections enable row level security;
revoke all on table ms_connections from anon, authenticated;

-- ── A linked table inside a workbook ─────────────────────────────────────────
create table if not exists excel_links (
  id             uuid primary key default gen_random_uuid(),
  workspace_id   uuid not null references workspaces(id) on delete cascade,
  connection_id  uuid not null references ms_connections(id) on delete cascade,
  -- Which RunButter object this sheet mirrors ('people', 'invoices', …).
  object         text not null,
  -- Graph coordinates. drive_id + item_id identify the workbook wherever it
  -- lives (personal OneDrive or a SharePoint document library).
  drive_id       text not null,
  item_id        text not null,
  file_name      text,
  worksheet      text not null default 'RunButter',
  -- Graph's *table* name, not the sheet name. Rows are read and written through
  -- a real Excel table so a user can sort, filter and add columns beside it
  -- without the sync overwriting their work.
  table_name     text,
  direction      text not null default 'out',
  enabled        boolean not null default true,
  last_sync_at   timestamptz,
  last_status    text,
  last_error     text,
  last_rows_out  int not null default 0,
  last_rows_in   int not null default 0,
  created_by_privy text,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  -- One link per sheet. Two links writing the same worksheet would each undo
  -- the other on every run.
  unique (workspace_id, item_id, worksheet)
);

do $$ begin
  alter table excel_links add constraint excel_links_direction_check
    check (direction in ('out', 'in', 'both'));
exception when duplicate_object then null; end $$;

create index if not exists idx_excel_links_ws on excel_links(workspace_id);
-- The sweep the cron runs: enabled links, oldest sync first.
create index if not exists idx_excel_links_due on excel_links(enabled, last_sync_at);

alter table excel_links enable row level security;
revoke all on table excel_links from anon, authenticated;

-- ── Reads ────────────────────────────────────────────────────────────────────
create or replace function get_ms_connection(p_privy text, p_workspace uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v jsonb;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  -- Deliberately no token columns: this answers "is it connected, and as whom",
  -- which is all the UI needs. Nothing that returns to a browser can widen.
  select jsonb_build_object(
    'id', c.id, 'account_email', c.account_email,
    'expires_at', c.expires_at, 'created_at', c.created_at,
    'connected_by_me', (c.privy_user_id = p_privy)
  ) into v
  from ms_connections c
  where c.workspace_id = p_workspace
  order by (c.privy_user_id = p_privy) desc, c.created_at
  limit 1;
  return v;   -- null when nothing is connected
end $$;
grant execute on function get_ms_connection(text, uuid) to authenticated, anon;

create or replace function get_excel_links(p_privy text, p_workspace uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
    'id', l.id, 'object', l.object, 'file_name', l.file_name,
    'worksheet', l.worksheet, 'table_name', l.table_name,
    'direction', l.direction, 'enabled', l.enabled,
    'last_sync_at', l.last_sync_at, 'last_status', l.last_status, 'last_error', l.last_error,
    'last_rows_out', l.last_rows_out, 'last_rows_in', l.last_rows_in,
    'created_at', l.created_at
  ) order by l.created_at desc) from excel_links l where l.workspace_id = p_workspace), '[]'::jsonb);
end $$;
grant execute on function get_excel_links(text, uuid) to authenticated, anon;

-- ── Writes ───────────────────────────────────────────────────────────────────
create or replace function save_excel_link(
  p_privy text, p_workspace uuid, p_id uuid,
  p_object text, p_drive_id text, p_item_id text, p_file_name text,
  p_worksheet text, p_direction text
) returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid; v_conn uuid; v_dir text; v_sheet text;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;

  -- A link is worthless without a connection to sync through, and creating one
  -- anyway would leave a row that fails on every cron tick forever.
  select c.id into v_conn from ms_connections c
   where c.workspace_id = p_workspace
   order by (c.privy_user_id = p_privy) desc, c.created_at limit 1;
  if v_conn is null then raise exception 'NOT_CONNECTED'; end if;

  -- Anything unrecognised becomes the read-only direction. As with API key
  -- scopes (0078), a typo must never grant more than was asked for — and here
  -- "more" means writing into someone's workbook.
  v_dir := case when p_direction in ('out', 'in', 'both') then p_direction else 'out' end;
  v_sheet := coalesce(nullif(trim(p_worksheet), ''), 'RunButter');

  if p_id is null then
    insert into excel_links (workspace_id, connection_id, object, drive_id, item_id,
                             file_name, worksheet, direction, created_by_privy)
    values (p_workspace, v_conn, p_object, p_drive_id, p_item_id,
            p_file_name, v_sheet, v_dir, p_privy)
    -- Re-linking a sheet already linked is an update, not a duplicate-key error
    -- the user has no way to interpret.
    on conflict (workspace_id, item_id, worksheet) do update
      set object = excluded.object, direction = excluded.direction,
          file_name = excluded.file_name, connection_id = excluded.connection_id,
          enabled = true, updated_at = now()
    returning id into v_id;
  else
    update excel_links set
      object = p_object, direction = v_dir, worksheet = v_sheet,
      file_name = coalesce(p_file_name, file_name), updated_at = now()
    where id = p_id and workspace_id = p_workspace
    returning id into v_id;
    if v_id is null then raise exception 'NOT_FOUND'; end if;
  end if;

  return v_id;
end $$;
grant execute on function save_excel_link(text, uuid, uuid, text, text, text, text, text, text) to authenticated, anon;

create or replace function set_excel_link_enabled(p_privy text, p_workspace uuid, p_id uuid, p_enabled boolean)
returns boolean language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  update excel_links set enabled = p_enabled, updated_at = now()
   where id = p_id and workspace_id = p_workspace;
  return found;
end $$;
grant execute on function set_excel_link_enabled(text, uuid, uuid, boolean) to authenticated, anon;

create or replace function delete_excel_link(p_privy text, p_workspace uuid, p_id uuid)
returns boolean language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  -- Unlinking never touches the workbook. The user's file is theirs; we stop
  -- syncing, we do not tidy up after ourselves in their document.
  delete from excel_links where id = p_id and workspace_id = p_workspace;
  return found;
end $$;
grant execute on function delete_excel_link(text, uuid, uuid) to authenticated, anon;

create or replace function disconnect_microsoft(p_privy text, p_workspace uuid)
returns boolean language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  -- Cascades to excel_links: a link without a token cannot sync, and leaving
  -- the rows behind would show "connected" sheets that silently never run.
  delete from ms_connections where workspace_id = p_workspace;
  return found;
end $$;
grant execute on function disconnect_microsoft(text, uuid) to authenticated, anon;

-- ── Sync bookkeeping (service_role only) ─────────────────────────────────────
-- Called by the sync route after each run. Anon/authenticated are revoked
-- because a client that could write last_status could hide a failing sync.
create or replace function record_excel_sync(
  p_id uuid, p_status text, p_error text, p_out int, p_in int
) returns boolean language plpgsql security definer set search_path = public as $$
begin
  update excel_links set
    last_sync_at = now(),
    last_status = left(coalesce(p_status, 'error'), 40),
    last_error = left(nullif(p_error, ''), 500),
    last_rows_out = coalesce(p_out, 0),
    last_rows_in = coalesce(p_in, 0),
    updated_at = now()
  where id = p_id;
  return found;
end $$;
revoke all on function record_excel_sync(uuid, text, text, int, int) from public, authenticated, anon;
grant execute on function record_excel_sync(uuid, text, text, int, int) to service_role;

-- Claim the links a sweep should run, oldest first. FOR UPDATE SKIP LOCKED so
-- two overlapping cron ticks cannot both pick up the same sheet and race each
-- other's writes into the same workbook.
create or replace function claim_excel_links(p_limit int default 20)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v jsonb;
begin
  with candidate as (
    select l.id from excel_links l
     where l.enabled = true
     order by l.last_sync_at nulls first
     limit greatest(1, least(coalesce(p_limit, 20), 100))
     for update skip locked
  ), claimed as (
    update excel_links l set last_sync_at = now()
      from candidate c where l.id = c.id
    returning l.id, l.workspace_id, l.connection_id, l.object,
              l.drive_id, l.item_id, l.worksheet, l.table_name, l.direction
  )
  select coalesce(jsonb_agg(to_jsonb(cl)), '[]'::jsonb) into v from claimed cl;
  return v;
end $$;
revoke all on function claim_excel_links(int) from public, authenticated, anon;
grant execute on function claim_excel_links(int) to service_role;

-- The sync route learns the table name it created; it has no user session.
create or replace function set_excel_table_name(p_id uuid, p_table text)
returns boolean language plpgsql security definer set search_path = public as $$
begin
  update excel_links set table_name = p_table, updated_at = now() where id = p_id;
  return found;
end $$;
revoke all on function set_excel_table_name(uuid, text) from public, authenticated, anon;
grant execute on function set_excel_table_name(uuid, text) to service_role;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0080_brand_the_funnel.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0080_brand_the_funnel.sql
-- Carry the company's brand colour through the whole hiring funnel.
--
-- THE BUG THIS FIXES. The careers page is brand-coloured (0060 hands it
-- `accent_color`), but the apply form and the assessment are not — they render
-- RunButter's emerald. So a candidate crosses from the company's colours into
-- ours halfway through applying, on the two screens where they are doing actual
-- work and most need to feel they are still dealing with that employer.
--
-- The cause is small: `accent_color` lives on `workspaces`, and neither of
-- those screens ever reads it. `get_assessment_init_data` selects only
-- name + logo_url, and the apply form queries `companies` straight from the
-- browser, where `workspaces` is not readable at all.
--
-- So this does two things:
--   1. redefines `get_assessment_init_data` to include the brand colour
--   2. adds `get_apply_branding(position_id)` — one public, minimal read for
--      the apply form, instead of widening anon access to `workspaces`
--
-- WHY 1 IS A FULL REDEFINITION. That function lives in supabase/legacy/ and in
-- no numbered migration. Redefining it here brings it under version control;
-- the body below is the original plus the colour, so re-running the legacy file
-- afterwards would silently REMOVE branding again. Treat this as the current
-- definition (see the freshness probe in verify-migrations.sql).
--
-- `workspace_id == company_id` (same uuid, 0005 sync trigger), which is why the
-- join below is on `w.id = <company id>` and not through a foreign key.
--
-- Idempotent & prod-safe.
-- ============================================================================

-- ── Assessment: same payload, plus the brand colour ──────────────────────────
create or replace function get_assessment_init_data(p_candidate_id uuid, p_token uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_candidate_rec record;
  v_company_rec   record;
  v_template_rec  record;
begin
  -- 1. Candidate, gated on the single-use access token exactly as before.
  select * into v_candidate_rec
    from candidates
   where id = p_candidate_id and access_token = p_token;
  if v_candidate_rec.id is null then return null; end if;

  -- 2. Company + brand, with the SAME precedence as get_careers_position (0063)
  --    and get_apply_branding below: workspace branding wins over the legacy
  --    company row. Selecting c.name/c.logo_url plainly here is what made the
  --    logo and company name change between the apply form and the assessment
  --    — the same inconsistency this migration exists to remove, one screen
  --    further along.
  --
  --    LEFT JOIN, so a company whose workspace row is missing still loads the
  --    assessment with the default accent rather than failing: a candidate must
  --    never be blocked by our branding data.
  select coalesce(nullif(w.legal_name, ''), c.name)      as name,
         coalesce(nullif(w.logo_url, ''),   c.logo_url)  as logo_url,
         nullif(w.accent_color, '')                      as accent_color
    into v_company_rec
    from companies c
    left join workspaces w on w.id = c.id
   where c.id = v_candidate_rec.company_id;

  -- 3. Template
  select * into v_template_rec
    from assessment_templates
   where position_id = v_candidate_rec.position_id and is_default = true
   limit 1;

  return jsonb_build_object(
    'candidate', row_to_json(v_candidate_rec),
    'company',   row_to_json(v_company_rec),
    'template',  row_to_json(v_template_rec)
  );
end $$;

-- Same grants the legacy definition carried: this is reached by a candidate who
-- has no account, holding a token. Anon EXECUTE is intentional here, unlike the
-- recruiter-side RPCs 0046 revoked.
grant execute on function get_assessment_init_data(uuid, uuid) to authenticated, anon;

-- ── Apply form: the minimum needed to render it in the company's colours ─────
-- A dedicated function rather than opening `workspaces` to anon. It returns
-- the public-facing fields and nothing else — no counts, no contact details,
-- no position list — so it cannot become a workspace enumeration tool.
--
-- `apply_intro` is included because Settings → Branding offers a field labelled
-- "Apply form intro" ("One line candidates see above the application form")
-- that the apply form never rendered. An owner could write it, save it, and see
-- it nowhere. It reaches the form now.
create or replace function get_apply_branding(p_position_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v jsonb;
begin
  select jsonb_build_object(
           'title', p.title,
           -- Same precedence as get_careers_position (0063): the workspace's
           -- branding wins over the legacy company row. Anything else and the
           -- logo can change between the careers page and the apply form,
           -- which is the very inconsistency this migration exists to remove.
           'company_name', coalesce(nullif(w.legal_name, ''), c.name),
           'logo_url', coalesce(nullif(w.logo_url, ''), c.logo_url),
           'accent_color', nullif(w.accent_color, ''),
           'apply_intro', nullif(w.apply_intro, '')
         )
    into v
    from positions p
    join companies c on c.id = p.company_id
    left join workspaces w on w.id = c.id
   where p.id = p_position_id
     -- Same visibility rule as the careers index and get_careers_position: a
     -- role that is closed or unpublished must not be reachable by guessing an
     -- id. Branding is harmless on its own, but an endpoint that confirms a
     -- hidden role exists is not.
     and p.is_active and p.is_published;

  return v;   -- null when the position is missing or not public
end $$;

revoke all on function get_apply_branding(uuid) from public;
grant execute on function get_apply_branding(uuid) to authenticated, anon;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0081_doc_kinds_and_attachments.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0081_doc_kinds_and_attachments.sql
-- Docs get a kind, and both docs and chat get images.
--
-- TWO SMALL SCHEMA CHANGES, ONE IDEA. Everything needed to put a picture in a
-- document or a message already exists — 0065 built a private bucket, an upload
-- route that records a `files` row, a membership-checked signed-URL reader, and
-- full-text indexing over the result. What was missing was a way to REFER to
-- one of those files from somewhere other than the Files screen.
--
-- So nothing here uploads, stores or serves an image. An attachment is a
-- `files.id`, and reading it goes down the same path a contract does. Three
-- consequences fall out for free rather than being built:
--   · an image dropped into a channel is already in FTS-indexed storage
--   · deleting the file deletes the attachment's target, everywhere at once
--   · a private bucket stays private — no public URL is ever minted
--
-- WHY NOT STORE A URL. A signed URL expires, so a document written today would
-- show broken images next week. The id is stable; the URL is minted per render.
--
-- ── docs.kind ───────────────────────────────────────────────────────────────
-- `doc` is the existing rich document. `note` is the light one — a quick note
-- with checkboxes, the thing people currently keep in a text file next to the
-- app. Two values, not four: a kind the editor cannot render is a bug waiting,
-- and `sheet`/`canvas` already exist elsewhere in the product (Excel sync,
-- Maps). The CHECK is what stops a third appearing by accident.
--
-- ── messages.attachments ────────────────────────────────────────────────────
-- A jsonb array of {file_id, name, mime, size}. Denormalised on purpose: the
-- name and size are snapshotted the same way `author_name` is, so a message
-- still reads sensibly after the file is deleted, and rendering a channel does
-- not need a join per message.
--
-- `post_message` is DROPPED and recreated rather than replaced, because adding
-- a parameter creates an overload and every existing 4-argument call then fails
-- as ambiguous. Same reasoning as 0068's `save_agent` and 0078's
-- `create_api_key`. `save_doc` below, for the same reason.
--
-- Depends on 0034 (docs), 0065 (files), 0075 (chat). Idempotent & prod-safe.
-- ============================================================================

-- ── Docs: a kind ────────────────────────────────────────────────────────────
alter table docs add column if not exists kind text not null default 'doc';

do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'docs_kind_check') then
    alter table docs add constraint docs_kind_check check (kind in ('doc', 'note'));
  end if;
end $$;

-- Listing filters by kind, so it belongs in the index the list already uses.
create index if not exists idx_docs_ws_kind on docs(workspace_id, kind, updated_at desc);

-- Same shape as 0034's, plus `kind`. Signature unchanged, so a plain replace.
create or replace function get_docs(p_privy text, p_workspace uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
    'id', d.id, 'title', d.title, 'snippet', left(d.body, 140),
    'kind', d.kind, 'updated_at', d.updated_at
  ) order by d.updated_at desc) from docs d where d.workspace_id = p_workspace), '[]'::jsonb);
end $$;
grant execute on function get_docs(text, uuid) to authenticated, anon;

create or replace function get_doc(p_privy text, p_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare my uuid[] := (select array_agg(workspace_id) from accounts where privy_user_id = p_privy);
begin
  return (select to_jsonb(t) from (
    select id, title, body, kind, updated_at from docs where id = p_id and workspace_id = any(my)
  ) t);
end $$;
grant execute on function get_doc(text, uuid) to authenticated, anon;

-- Dropped, not replaced — see the header. The old four-argument form goes with
-- it, so nothing is left to be ambiguous against.
drop function if exists save_doc(text, uuid, uuid, text, text);
create or replace function save_doc(
  p_privy text, p_workspace uuid, p_id uuid, p_title text, p_body text,
  p_kind text default 'doc'
) returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid; v_kind text;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  -- Fail to the existing kind rather than to an error: an old client that does
  -- not send one must keep working, and a bad value must never widen the CHECK.
  v_kind := case when p_kind in ('doc', 'note') then p_kind else null end;

  if p_id is null then
    insert into docs (workspace_id, title, body, kind, created_by_privy)
    values (p_workspace, coalesce(nullif(p_title, ''), 'Untitled'), coalesce(p_body, ''),
            coalesce(v_kind, 'doc'), p_privy)
    returning id into v_id;
  else
    update docs
       set title = coalesce(nullif(p_title, ''), title),
           body  = coalesce(p_body, body),
           kind  = coalesce(v_kind, kind)
     where id = p_id and workspace_id = p_workspace
    returning id into v_id;
  end if;
  return v_id;
end $$;
grant execute on function save_doc(text, uuid, uuid, text, text, text) to authenticated, anon;

-- ── Chat: attachments ───────────────────────────────────────────────────────
alter table messages add column if not exists attachments jsonb not null default '[]'::jsonb;

-- A message is now non-empty if it has EITHER text or an attachment. Before
-- this, `post_message` raised EMPTY_MESSAGE on a blank body, which is exactly
-- what "here, look at this picture" looks like.
--
-- Sanitising in SQL rather than trusting the client, because this is the only
-- place both the caller's identity and the file's workspace are known at once.
-- Every attachment must name a file in the SAME workspace as the channel:
-- reading the bytes is separately gated, but a foreign id would still leak that
-- file's NAME and SIZE into a channel that has no business seeing them.
create or replace function sanitize_attachments(p_workspace uuid, p_att jsonb)
returns jsonb language sql stable set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'file_id', f.id,
           -- Snapshotted, like author_name: the message should still read
           -- sensibly after the file itself is gone.
           'name',    f.name,
           'mime',    coalesce(f.mime_type, ''),
           'size',    coalesce(f.size_bytes, 0)
         ) order by a.ord), '[]'::jsonb)
    from jsonb_array_elements(case when jsonb_typeof(p_att) = 'array' then p_att else '[]'::jsonb end)
           with ordinality as a(el, ord)
    join files f
      on f.id = (a.el ->> 'file_id')::uuid
     and f.workspace_id = p_workspace
   -- Ten is a message, not a folder. An unbounded array is a way to make one
   -- row expensive to render for everyone in the channel, forever.
   where a.ord <= 10
     and (a.el ->> 'file_id') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
$$;
revoke all on function sanitize_attachments(uuid, jsonb) from public, anon, authenticated;

create or replace function get_messages(
  p_privy text, p_channel uuid, p_before timestamptz default null, p_limit int default 50
) returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not can_read_channel(p_channel, p_privy) then raise exception 'NO_ACCESS'; end if;
  return coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at asc) from (
    select m.id, m.author_privy, m.author_name, m.author_kind,
           case when m.deleted_at is null then m.body else '' end as body,
           -- A deleted message drops its attachments with its text. Leaving the
           -- pictures behind is not a deletion either.
           case when m.deleted_at is null then m.attachments else '[]'::jsonb end as attachments,
           m.deleted_at is not null as deleted, m.edited_at, m.created_at
      from messages m
     where m.channel_id = p_channel
       and (p_before is null or m.created_at < p_before)
     order by m.created_at desc
     limit greatest(1, least(coalesce(p_limit, 50), 200))
  ) x), '[]'::jsonb);
end $$;
grant execute on function get_messages(text, uuid, timestamptz, int) to authenticated, anon;

drop function if exists post_message(text, uuid, text, text);
create or replace function post_message(
  p_privy text, p_channel uuid, p_body text, p_author_name text default '',
  p_attachments jsonb default '[]'::jsonb
) returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid; v_ws uuid; v_body text; v_att jsonb;
begin
  if not can_read_channel(p_channel, p_privy) then raise exception 'NO_ACCESS'; end if;
  select workspace_id into v_ws from channels where id = p_channel;

  v_body := left(trim(coalesce(p_body, '')), 8000);
  v_att  := sanitize_attachments(v_ws, p_attachments);
  -- Either one is enough. An image with no caption is a perfectly ordinary
  -- message; a blank one with no attachment is still nothing.
  if v_body = '' and v_att = '[]'::jsonb then raise exception 'EMPTY_MESSAGE'; end if;

  insert into messages (workspace_id, channel_id, author_privy, author_name, body, attachments)
  values (v_ws, p_channel, p_privy, left(coalesce(p_author_name, ''), 80), v_body, v_att)
  returning id into v_id;

  insert into channel_members (channel_id, privy_user_id, last_read_at)
  values (p_channel, p_privy, now())
  on conflict (channel_id, privy_user_id) do update set last_read_at = now();

  update channels set updated_at = now() where id = p_channel;
  return v_id;
end $$;
grant execute on function post_message(text, uuid, text, text, jsonb) to authenticated, anon;

-- `edit_message` is deliberately untouched: editing text is a different act
-- from re-attaching files, and letting an edit swap the attachments would mean
-- the picture everyone replied to could be changed after the fact.

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0082_social_accounts.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0082_social_accounts.sql
-- OAuth grants for publishing to social platforms.
--
-- WHY THIS IS BUILT AND NOT BORROWED. Postiz solves exactly this problem and
-- solves it well, but it is AGPL-3.0 — copying a provider adapter, a schema or
-- a scheduler out of it would relicense this repository. So Postiz is read as a
-- feature specification and nothing else. Concepts are not copyrightable; its
-- source is.
--
-- WHY NATIVE RATHER THAN RUNNING POSTIZ ALONGSIDE. Aggregating it as a separate
-- service is legal and was the obvious shortcut, but it means every self-hoster
-- deploys a second app, a second Postgres and a second set of OAuth apps — the
-- opposite of the one-relational-core pitch. A post is already a row here.
--
-- TOKENS ARE SEALED AT REST, like 0079's `ms_connections` and unlike the older
-- `integration_tokens` rows. The reasoning is the same and it is not paranoia:
-- a leaked posting grant lets someone post AS the company, to that company's
-- real audience, and there is no undo for that.
--
-- THE RPCs BELOW NEVER RETURN A TOKEN. `get_social_accounts` selects the
-- display fields only; the cipher columns are readable exactly once, by
-- `get_social_token`, which is service_role and deliberately absent from
-- /api/rpc's ALLOWED — same rule as `claim_excel_links`. A browser that could
-- read a token could post from anywhere.
--
-- Depends on 0001 (workspaces). Additive, idempotent & prod-safe.
-- ============================================================================

create table if not exists social_accounts (
  id             uuid primary key default gen_random_uuid(),
  workspace_id   uuid not null references workspaces(id) on delete cascade,
  -- 'linkedin' | 'x'. Free text with a CHECK rather than an enum: adding a
  -- provider should be one migration line, not an ALTER TYPE.
  provider       text not null,
  -- The platform's own id for the page/profile being posted to. Part of the
  -- uniqueness key, because one person may connect a personal profile AND a
  -- company page from the same login.
  external_id    text not null,
  display_name   text not null default '',
  avatar_url     text,

  -- Sealed with SECRETS_MASTER_KEY (AES-256-GCM). Never selected by any RPC a
  -- browser can reach.
  access_cipher  text, access_iv text, access_tag text,
  refresh_cipher text, refresh_iv text, refresh_tag text,
  expires_at     timestamptz,
  scope          text,

  -- Who authorised it. Kept for the audit trail: "who connected this account"
  -- is the first question asked when something unexpected gets posted.
  connected_by_privy text,
  enabled        boolean not null default true,
  -- Set when the platform rejects the token, so the UI can say "reconnect"
  -- rather than failing every scheduled post in silence.
  last_error     text,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  unique (workspace_id, provider, external_id)
);

do $$ begin
  alter table social_accounts add constraint social_accounts_provider_check
    check (provider in ('linkedin', 'x'));
exception when duplicate_object then null; end $$;

create index if not exists idx_social_accounts_ws on social_accounts(workspace_id, provider);

drop trigger if exists trg_social_accounts_upd on social_accounts;
create trigger trg_social_accounts_upd before update on social_accounts
  for each row execute function set_updated_at();

alter table social_accounts enable row level security;
revoke all on table social_accounts from anon, authenticated;

-- ── Reads a browser may make ────────────────────────────────────────────────
-- Display fields only. Adding a token column to this SELECT is the single
-- change that would turn a workspace member into someone who can post from
-- anywhere, so it is called out here rather than left to review.
create or replace function get_social_accounts(p_privy text, p_workspace uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
    'id', a.id, 'provider', a.provider, 'display_name', a.display_name,
    'avatar_url', a.avatar_url, 'enabled', a.enabled,
    -- An expired token is not an error yet — it is refreshed on use. Surfaced
    -- so the UI can distinguish "needs reconnecting" from "never worked".
    'expired', a.expires_at is not null and a.expires_at < now(),
    'last_error', a.last_error, 'created_at', a.created_at
  ) order by a.provider, a.display_name) from social_accounts a
   where a.workspace_id = p_workspace), '[]'::jsonb);
end $$;
grant execute on function get_social_accounts(text, uuid) to authenticated, anon;

create or replace function set_social_account_enabled(
  p_privy text, p_workspace uuid, p_id uuid, p_enabled boolean
) returns boolean language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  update social_accounts set enabled = coalesce(p_enabled, enabled)
   where id = p_id and workspace_id = p_workspace;
  return found;
end $$;
grant execute on function set_social_account_enabled(text, uuid, uuid, boolean) to authenticated, anon;

-- Disconnecting deletes the grant rather than disabling it. A revoked token
-- kept "just in case" is a credential nobody is watching any more.
create or replace function delete_social_account(p_privy text, p_workspace uuid, p_id uuid)
returns boolean language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  delete from social_accounts where id = p_id and workspace_id = p_workspace;
  return found;
end $$;
grant execute on function delete_social_account(text, uuid, uuid) to authenticated, anon;

-- ── service_role only: the OAuth callback and the dispatcher ────────────────
-- Upsert on (workspace, provider, external_id): re-authorising the same page
-- must REPLACE the token, not accumulate a second row that then races the
-- first. `last_error` clears on a successful reconnect — that is what makes
-- "reconnect" a fix rather than a second broken row.
create or replace function save_social_account(
  p_workspace uuid, p_provider text, p_external_id text, p_display_name text,
  p_avatar_url text,
  p_access_cipher text, p_access_iv text, p_access_tag text,
  p_refresh_cipher text, p_refresh_iv text, p_refresh_tag text,
  p_expires_at timestamptz, p_scope text, p_privy text
) returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid;
begin
  insert into social_accounts (
    workspace_id, provider, external_id, display_name, avatar_url,
    access_cipher, access_iv, access_tag,
    refresh_cipher, refresh_iv, refresh_tag,
    expires_at, scope, connected_by_privy, enabled, last_error
  ) values (
    p_workspace, p_provider, p_external_id, coalesce(p_display_name, ''), p_avatar_url,
    p_access_cipher, p_access_iv, p_access_tag,
    p_refresh_cipher, p_refresh_iv, p_refresh_tag,
    p_expires_at, p_scope, p_privy, true, null
  )
  on conflict (workspace_id, provider, external_id) do update
     set display_name   = excluded.display_name,
         avatar_url     = excluded.avatar_url,
         access_cipher  = excluded.access_cipher,
         access_iv      = excluded.access_iv,
         access_tag     = excluded.access_tag,
         -- A provider that does not re-issue a refresh token on reconnect must
         -- not blank the one we already hold, or the account silently becomes
         -- unrefreshable at the next expiry.
         refresh_cipher = coalesce(excluded.refresh_cipher, social_accounts.refresh_cipher),
         refresh_iv     = coalesce(excluded.refresh_iv,     social_accounts.refresh_iv),
         refresh_tag    = coalesce(excluded.refresh_tag,    social_accounts.refresh_tag),
         expires_at     = excluded.expires_at,
         scope          = excluded.scope,
         enabled        = true,
         last_error     = null
  returning id into v_id;
  return v_id;
end $$;
revoke all on function save_social_account(uuid, text, text, text, text, text, text, text, text, text, text, timestamptz, text, text)
  from public, authenticated, anon;
grant execute on function save_social_account(uuid, text, text, text, text, text, text, text, text, text, text, timestamptz, text, text)
  to service_role;

create or replace function get_social_token(p_account uuid)
returns jsonb language sql security definer set search_path = public as $$
  select jsonb_build_object(
    'id', a.id, 'workspace_id', a.workspace_id, 'provider', a.provider,
    'external_id', a.external_id,
    'access_cipher', a.access_cipher, 'access_iv', a.access_iv, 'access_tag', a.access_tag,
    'refresh_cipher', a.refresh_cipher, 'refresh_iv', a.refresh_iv, 'refresh_tag', a.refresh_tag,
    'expires_at', a.expires_at
  ) from social_accounts a where a.id = p_account and a.enabled;
$$;
revoke all on function get_social_token(uuid) from public, authenticated, anon;
grant execute on function get_social_token(uuid) to service_role;

-- Written by the dispatcher when a platform rejects the grant. Separate from
-- `save_social_account` so a failure never touches the token itself: the fix
-- for "expired" is a reconnect, and clobbering the row here would lose the
-- refresh token that might still work.
create or replace function record_social_account_error(p_account uuid, p_error text)
returns boolean language plpgsql security definer set search_path = public as $$
begin
  update social_accounts set last_error = left(coalesce(p_error, ''), 500)
   where id = p_account;
  return found;
end $$;
revoke all on function record_social_account_error(uuid, text) from public, authenticated, anon;
grant execute on function record_social_account_error(uuid, text) to service_role;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0083_post_targets.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0083_post_targets.sql
-- One authored post, N accounts it goes out to, and an at-most-once sender.
--
-- SENDING IS AT-MOST-ONCE, ON PURPOSE. This is the newsletter rule (0070/0071)
-- applied to social, for the same reason and with the same shape:
--   · a target moves to 'sending' BEFORE the provider call
--   · a stale claim is swept to 'failed', NEVER back to 'pending'
--   · unique (post_id, account_id) makes a duplicate structurally impossible
-- A post published twice to a company's real audience is a public incident that
-- cannot be taken back; a post that did not go out is a support question. Do
-- not "fix" this into a retry — a retry is the bug.
--
-- WHY A SEPARATE TABLE AND NOT COLUMNS ON `posts`. A post is authored once and
-- fans out to several accounts, each of which succeeds or fails on its own: X
-- rejecting a post is not a reason to mark the LinkedIn one failed. Status per
-- target is the only shape that can say "went out on LinkedIn, failed on X",
-- which is exactly what a person needs to know.
--
-- Depends on 0028 (posts) and 0082 (social_accounts). Idempotent & prod-safe.
-- ============================================================================

-- When the post should go out. Null = "when told to", which is what the manual
-- Publish button uses; the scheduler only ever looks at rows that have one.
alter table posts add column if not exists scheduled_at timestamptz;

create table if not exists post_targets (
  id            uuid primary key default gen_random_uuid(),
  workspace_id  uuid not null references workspaces(id) on delete cascade,
  post_id       uuid not null references posts(id) on delete cascade,
  account_id    uuid not null references social_accounts(id) on delete cascade,
  -- pending → sending → sent | failed. 'skipped' exists for a target whose
  -- account was disabled between scheduling and sending: not an error, and not
  -- something to retry either.
  status        text not null default 'pending',
  scheduled_at  timestamptz,
  claimed_at    timestamptz,
  sent_at       timestamptz,
  -- The platform's id for the published post. This is what makes "sent" a
  -- verifiable claim rather than our own assertion.
  provider_post_id text,
  provider_url  text,
  error         text,
  created_at    timestamptz not null default now(),
  -- THE constraint. Everything above is bookkeeping; this is what makes
  -- double-publishing impossible rather than merely unlikely.
  unique (post_id, account_id)
);

do $$ begin
  alter table post_targets add constraint post_targets_status_check
    check (status in ('pending', 'sending', 'sent', 'failed', 'skipped'));
exception when duplicate_object then null; end $$;

create index if not exists idx_post_targets_post on post_targets(post_id);
-- The sweep the cron runs: due, unsent, oldest first. Partial, because sent
-- rows are the overwhelming majority after a week and none of them are due.
create index if not exists idx_post_targets_due on post_targets(scheduled_at)
  where status = 'pending';
-- Stale-claim sweep reads this one.
create index if not exists idx_post_targets_claimed on post_targets(claimed_at)
  where status = 'sending';

alter table post_targets enable row level security;
revoke all on table post_targets from anon, authenticated;

-- ── Reads and writes a browser may make ─────────────────────────────────────
create or replace function get_post_targets(p_privy text, p_post uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare my uuid[] := (select array_agg(workspace_id) from accounts where privy_user_id = p_privy);
begin
  return coalesce((select jsonb_agg(jsonb_build_object(
    'id', t.id, 'account_id', t.account_id, 'provider', a.provider,
    'display_name', a.display_name, 'status', t.status,
    'scheduled_at', t.scheduled_at, 'sent_at', t.sent_at,
    'provider_url', t.provider_url, 'error', t.error
  ) order by a.provider, a.display_name)
    from post_targets t
    join social_accounts a on a.id = t.account_id
   where t.post_id = p_post and t.workspace_id = any(my)), '[]'::jsonb);
end $$;
grant execute on function get_post_targets(text, uuid) to authenticated, anon;

/**
 * Set which accounts a post goes to, and when.
 *
 * Replaces the whole set, but ONLY the parts that are still changeable. A
 * target that is sending or already sent is left exactly as it is: unselecting
 * an account cannot un-publish a post, and pretending otherwise would let the
 * UI show a post as unsent while it is live on someone's feed. Reselecting an
 * already-sent account is a no-op for the same reason — that is what the unique
 * constraint plus this DO NOTHING buys.
 */
create or replace function set_post_targets(
  p_privy text, p_workspace uuid, p_post uuid, p_accounts uuid[],
  p_scheduled_at timestamptz default null
) returns jsonb language plpgsql security definer set search_path = public as $$
declare v_ok boolean;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  select exists (select 1 from posts where id = p_post and workspace_id = p_workspace) into v_ok;
  if not v_ok then raise exception 'NO_SUCH_POST'; end if;

  -- Drop the targets that are still safe to drop.
  delete from post_targets
   where post_id = p_post
     and status in ('pending', 'failed', 'skipped')
     and (p_accounts is null or account_id <> all(p_accounts));

  -- Add the new ones. The join against social_accounts is the tenancy check:
  -- an account id from another workspace simply matches no row, so a forged id
  -- adds nothing rather than posting somewhere it should not.
  insert into post_targets (workspace_id, post_id, account_id, scheduled_at)
  select p_workspace, p_post, a.id, p_scheduled_at
    from unnest(coalesce(p_accounts, '{}'::uuid[])) as sel(id)
    join social_accounts a on a.id = sel.id and a.workspace_id = p_workspace and a.enabled
  on conflict (post_id, account_id) do nothing;

  -- Keep a still-pending target's schedule in step with the post's.
  update post_targets set scheduled_at = p_scheduled_at
   where post_id = p_post and status = 'pending';
  update posts set scheduled_at = p_scheduled_at where id = p_post and workspace_id = p_workspace;

  return get_post_targets(p_privy, p_post);
end $$;
grant execute on function set_post_targets(text, uuid, uuid, uuid[], timestamptz) to authenticated, anon;

/**
 * "Publish now" — mark this post's pending targets due immediately.
 *
 * Deliberately does NOT send. Publishing goes through the same claim path as a
 * scheduled post, so there is exactly one code path that can talk to a
 * provider and exactly one place the at-most-once rule has to hold.
 */
create or replace function publish_post_now(p_privy text, p_workspace uuid, p_post uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  update post_targets set scheduled_at = now()
   where post_id = p_post and workspace_id = p_workspace and status = 'pending';
  if not found then raise exception 'NOTHING_TO_PUBLISH'; end if;
  update posts set scheduled_at = now() where id = p_post and workspace_id = p_workspace;
  return get_post_targets(p_privy, p_post);
end $$;
grant execute on function publish_post_now(text, uuid, uuid) to authenticated, anon;

-- ── service_role only: the dispatcher ───────────────────────────────────────
/**
 * Claim up to p_limit due targets.
 *
 * FOR UPDATE SKIP LOCKED for the same reason as the newsletter sender: two
 * overlapping cron ticks must never be handed the same row, or the second sends
 * it again once the first releases its lock.
 *
 * The claim is a data-modifying CTE aggregated by a final SELECT, not
 * `UPDATE … RETURNING … INTO`. That form takes a single row and raises
 * "query returned more than one row" on any batch bigger than one — the exact
 * bug 0071 had to fix, so it is not repeated here.
 *
 * A target whose account was disabled after scheduling is claimed and marked
 * 'skipped' by the caller rather than left pending forever.
 */
create or replace function claim_post_targets(p_limit int default 25)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_rows jsonb;
begin
  with candidate as (
    select t.id
      from post_targets t
      join social_accounts a on a.id = t.account_id
     where t.status = 'pending'
       and t.scheduled_at is not null
       and t.scheduled_at <= now()
     order by t.scheduled_at
     limit greatest(1, least(coalesce(p_limit, 25), 100))
     for update skip locked
  ), claimed as (
    update post_targets t
       set status = 'sending', claimed_at = now()
      from candidate c
     where t.id = c.id
    returning t.id, t.post_id, t.account_id, t.workspace_id
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', cl.id, 'post_id', cl.post_id, 'account_id', cl.account_id,
           'workspace_id', cl.workspace_id,
           'provider', a.provider, 'account_enabled', a.enabled,
           'content', p.content, 'image_url', p.image_url
         )), '[]'::jsonb)
    into v_rows
    from claimed cl
    join social_accounts a on a.id = cl.account_id
    join posts p on p.id = cl.post_id;

  return v_rows;
end $$;
revoke all on function claim_post_targets(int) from public, authenticated, anon;
grant execute on function claim_post_targets(int) to service_role;

-- Only a claimed row can be resolved (`status = 'sending'` in the WHERE), which
-- is what stops a late reply from a previous run overwriting a newer attempt.
create or replace function mark_post_target(
  p_id uuid, p_status text, p_provider_post_id text default null,
  p_provider_url text default null, p_error text default null
) returns boolean language plpgsql security definer set search_path = public as $$
begin
  if p_status not in ('sent', 'failed', 'skipped') then raise exception 'BAD_STATUS'; end if;
  update post_targets
     set status = p_status,
         provider_post_id = coalesce(p_provider_post_id, provider_post_id),
         provider_url = coalesce(p_provider_url, provider_url),
         error = left(p_error, 500),
         sent_at = case when p_status = 'sent' then now() else sent_at end
   where id = p_id and status = 'sending';
  if not found then return false; end if;

  -- A post counts as published once ANY target lands. Requiring all of them
  -- would leave a post that went out on LinkedIn showing as a draft because X
  -- rejected it.
  if p_status = 'sent' then
    update posts p set status = 'published'
     where p.id = (select post_id from post_targets where id = p_id)
       and p.status <> 'published';
  end if;
  return true;
end $$;
revoke all on function mark_post_target(uuid, text, text, text, text) from public, authenticated, anon;
grant execute on function mark_post_target(uuid, text, text, text, text) to service_role;

/**
 * Sweep claims that never resolved — a crashed dispatcher, a timed-out request.
 *
 * They go to 'failed', NEVER back to 'pending'. A claim that has been sitting
 * in 'sending' for ten minutes may well have reached the platform; we cannot
 * tell, and the one thing worse than a post that did not go out is the same
 * post going out twice. A person can look at the feed and re-publish. The
 * machine must not guess.
 */
create or replace function sweep_stale_post_targets(p_minutes int default 10)
returns int language plpgsql security definer set search_path = public as $$
declare n int;
begin
  update post_targets
     set status = 'failed',
         error = 'Timed out while sending — check the platform before publishing again.'
   where status = 'sending'
     and claimed_at < now() - make_interval(mins => greatest(1, coalesce(p_minutes, 10)));
  get diagnostics n = row_count;
  return n;
end $$;
revoke all on function sweep_stale_post_targets(int) from public, authenticated, anon;
grant execute on function sweep_stale_post_targets(int) to service_role;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0084_agentic.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0084_agentic.sql
-- Two things that turn "we have agents" into an agentic CRM: a place for an
-- agent to keep its notes, and permission to work without being asked.
--
-- THE GAP THIS CLOSES. The tool executor (lib/agents/tools.ts) has been
-- tenancy-safe and shared with /api/mcp since it was written, so capability was
-- never the problem. Two things were:
--   1. an agent could only act when a human opened a page and typed a task
--   2. anything it found out went into a run transcript nobody reads again
-- An agent that researches a company and then forgets is a chat window. An
-- agent that writes what it found onto the company, with a source, is a
-- colleague.
--
-- OBSERVED FACTS, WITH A SOURCE, AND NO CONFIDENCE SCORES. `source` is NOT NULL
-- and there is no `confidence` column, deliberately. A percentage next to a
-- guess is how a hallucination gets trusted — it converts "the model said so"
-- into something that looks measured. A URL or a tool name is checkable; 0.87
-- is not. If an agent cannot say where a claim came from, it does not get to
-- record the claim.
--
-- SCHEDULES ARE COARSE ON PURPOSE. hourly / daily / weekly plus an hour, not a
-- cron expression. A cron field means validating cron, explaining cron, and
-- debugging someone's `*/5 9-17 * * 1-5` — for a feature whose entire value is
-- "it ran without me". Autonomy is unchanged by this: a `suggest` agent still
-- only proposes, it just proposes unprompted.
--
-- Depends on 0043 (agents), 0068 (skills). Idempotent & prod-safe.
-- ============================================================================

-- ── What the agent found out ────────────────────────────────────────────────
create table if not exists record_notes (
  id           uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspaces(id) on delete cascade,
  -- Free-text object name + id, matching how files, chat channels and
  -- automations already reference records across a schema where each object
  -- lives in its own table. A FK is impossible here for the same reason.
  object       text not null,
  record_id    uuid not null,

  -- Who wrote it. `agent_name` is snapshotted like `messages.author_name`: a
  -- note should still say who made it after the agent is renamed or deleted.
  agent_id     uuid references agents(id) on delete set null,
  agent_name   text not null default '',
  run_id       uuid references agent_runs(id) on delete set null,

  -- 'observation' — something found out. 'action' — something done.
  -- Kept apart because "I emailed them" and "they raised $4M" are different
  -- kinds of claim and a reader needs to tell them apart at a glance.
  kind         text not null default 'observation',
  body         text not null,

  -- NOT NULL, and there is no confidence column. See the header.
  source       text not null,
  source_url   text,
  -- When the FACT was true, which is not when we wrote it down: a funding
  -- round from March recorded today is March's news.
  observed_at  timestamptz,
  created_at   timestamptz not null default now()
);

do $$ begin
  alter table record_notes add constraint record_notes_kind_check
    check (kind in ('observation', 'action'));
exception when duplicate_object then null; end $$;

do $$ begin
  -- An empty string would defeat NOT NULL, which is the entire point of the
  -- column. Cheap to enforce, impossible to retrofit once rows exist.
  alter table record_notes add constraint record_notes_source_not_blank
    check (length(btrim(source)) > 0);
exception when duplicate_object then null; end $$;

create index if not exists idx_record_notes_rec
  on record_notes(workspace_id, object, record_id, created_at desc);

alter table record_notes enable row level security;
revoke all on table record_notes from anon, authenticated;

create or replace function get_record_notes(p_privy text, p_object text, p_record uuid, p_limit int default 50)
returns jsonb language plpgsql security definer set search_path = public as $$
declare my uuid[] := (select array_agg(workspace_id) from accounts where privy_user_id = p_privy);
begin
  return coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at desc) from (
    select n.id, n.object, n.record_id, n.agent_id, n.agent_name, n.run_id,
           n.kind, n.body, n.source, n.source_url, n.observed_at, n.created_at
      from record_notes n
     where n.object = p_object and n.record_id = p_record and n.workspace_id = any(my)
     order by n.created_at desc
     limit greatest(1, least(coalesce(p_limit, 50), 200))
  ) x), '[]'::jsonb);
end $$;
grant execute on function get_record_notes(text, text, uuid, int) to authenticated, anon;

/**
 * Write a note.
 *
 * Reachable by an agent through the tool executor and by a person through
 * /api/rpc — the same function either way, because a note a human cannot
 * correct is a note nobody will trust. `p_agent` is scoped to the workspace in
 * SQL, so an agent id from another tenant resolves to null rather than
 * attributing the note to a stranger's agent.
 */
create or replace function add_record_note(
  p_privy text, p_workspace uuid, p_object text, p_record uuid,
  p_body text, p_source text, p_kind text default 'observation',
  p_source_url text default null, p_observed_at timestamptz default null,
  p_agent uuid default null, p_agent_name text default '', p_run uuid default null
) returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid; v_agent uuid; v_source text; v_body text;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;

  v_body   := left(btrim(coalesce(p_body, '')), 4000);
  v_source := left(btrim(coalesce(p_source, '')), 200);
  if v_body = ''   then raise exception 'EMPTY_NOTE'; end if;
  -- Refused rather than defaulted. "unknown" as a source is worse than no note:
  -- it looks like provenance and carries none.
  if v_source = '' then raise exception 'SOURCE_REQUIRED'; end if;

  select a.id into v_agent from agents a where a.id = p_agent and a.workspace_id = p_workspace;

  insert into record_notes (workspace_id, object, record_id, agent_id, agent_name, run_id,
                            kind, body, source, source_url, observed_at)
  values (p_workspace, p_object, p_record, v_agent, left(coalesce(p_agent_name, ''), 80), p_run,
          case when p_kind in ('observation', 'action') then p_kind else 'observation' end,
          v_body, v_source, p_source_url, p_observed_at)
  returning id into v_id;
  return v_id;
end $$;
grant execute on function add_record_note(text, uuid, text, uuid, text, text, text, text, timestamptz, uuid, text, uuid)
  to authenticated, anon;

create or replace function delete_record_note(p_privy text, p_workspace uuid, p_id uuid)
returns boolean language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  delete from record_notes where id = p_id and workspace_id = p_workspace;
  return found;
end $$;
grant execute on function delete_record_note(text, uuid, uuid) to authenticated, anon;

-- ── Agents that run without being asked ─────────────────────────────────────
alter table agents add column if not exists schedule text not null default 'off';
alter table agents add column if not exists schedule_hour int not null default 9;
alter table agents add column if not exists schedule_task text not null default '';
alter table agents add column if not exists last_run_at timestamptz;

do $$ begin
  alter table agents add constraint agents_schedule_check
    check (schedule in ('off', 'hourly', 'daily', 'weekly'));
exception when duplicate_object then null; end $$;

do $$ begin
  -- UTC, because a workspace has no timezone and guessing one silently is worse
  -- than an explicit hour that the UI can label.
  alter table agents add constraint agents_schedule_hour_check
    check (schedule_hour between 0 and 23);
exception when duplicate_object then null; end $$;

create index if not exists idx_agents_scheduled on agents(schedule, last_run_at)
  where schedule <> 'off' and enabled;

-- Adding parameters creates an OVERLOAD rather than replacing, so the
-- thirteen-argument version from 0068 is dropped first — same reasoning, and
-- anon EXECUTE is revoked so every caller comes through /api/rpc.
drop function if exists save_agent(text, uuid, uuid, text, text, text, text, text, text[], text[], text, int, uuid[]);

create or replace function save_agent(
  p_privy text, p_workspace uuid, p_id uuid, p_name text, p_role text, p_instructions text,
  p_provider text, p_model text, p_allowed_tools text[], p_allowed_objects text[],
  p_autonomy text, p_max_steps int, p_skill_ids uuid[] default '{}',
  p_schedule text default 'off', p_schedule_hour int default 9, p_schedule_task text default ''
) returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid; v_skills uuid[]; v_schedule text; v_hour int;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  select coalesce(array_agg(s.id), '{}') into v_skills
    from skills s where s.workspace_id = p_workspace and s.id = any(coalesce(p_skill_ids, '{}'));

  -- Unknown values fall back to 'off' rather than raising: a bad schedule must
  -- never mean an agent runs on a cadence nobody chose.
  v_schedule := case when p_schedule in ('off','hourly','daily','weekly') then p_schedule else 'off' end;
  v_hour     := least(23, greatest(0, coalesce(p_schedule_hour, 9)));

  -- A schedule with no task is 'off'. There is nothing for an unattended run to
  -- do, and storing it as scheduled would show a cadence in the UI that never
  -- produces a run.
  if coalesce(btrim(p_schedule_task), '') = '' then v_schedule := 'off'; end if;

  if p_id is null then
    insert into agents (workspace_id, name, role, instructions, provider, model,
      allowed_tools, allowed_objects, autonomy, max_steps, skill_ids, created_by_privy,
      schedule, schedule_hour, schedule_task)
    values (p_workspace, coalesce(nullif(p_name,''),'New agent'), p_role, p_instructions,
      coalesce(p_provider,''), coalesce(p_model,''),
      coalesce(p_allowed_tools, '{list_objects,list_records,search_records,get_record}'),
      coalesce(p_allowed_objects, '{}'),
      coalesce(nullif(p_autonomy,''),'suggest'), coalesce(p_max_steps,12), v_skills, p_privy,
      v_schedule, v_hour, left(coalesce(p_schedule_task, ''), 2000))
    returning id into v_id;
  else
    update agents set name = p_name, role = p_role, instructions = p_instructions,
      provider = coalesce(p_provider,''), model = coalesce(p_model,''),
      allowed_tools = coalesce(p_allowed_tools, allowed_tools),
      allowed_objects = coalesce(p_allowed_objects, allowed_objects),
      autonomy = coalesce(nullif(p_autonomy,''), autonomy), max_steps = coalesce(p_max_steps, max_steps),
      skill_ids = v_skills,
      schedule = v_schedule, schedule_hour = v_hour,
      schedule_task = left(coalesce(p_schedule_task, ''), 2000)
    where id = p_id and workspace_id = p_workspace
    returning id into v_id;
  end if;
  return v_id;
end $$;
grant execute on function save_agent(text, uuid, uuid, text, text, text, text, text, text[], text[], text, int, uuid[], text, int, text)
  to authenticated, anon;

-- Must return the new columns, or the editor reopens with the schedule blank
-- and the next save silently turns it off — the same failure 0068 called out
-- for skill_ids.
create or replace function get_agents(p_privy text, p_workspace uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((select jsonb_agg(to_jsonb(a) order by a.updated_at desc) from (
    select id, name, role, instructions, provider, model, allowed_tools, allowed_objects,
           autonomy, max_steps, skill_ids, enabled,
           schedule, schedule_hour, schedule_task, last_run_at, updated_at
    from agents where workspace_id = p_workspace
  ) a), '[]'::jsonb);
end $$;
grant execute on function get_agents(text, uuid) to authenticated, anon;

/**
 * Claim the agents that are due, marking them run in the same statement.
 *
 * FOR UPDATE SKIP LOCKED and a claim-before-work shape, for the reason every
 * other dispatcher in this codebase uses it: two overlapping cron ticks must
 * never be handed the same agent. Here a double-claim would mean two unattended
 * runs spending the customer's own AI credit twice on the same task.
 *
 * `last_run_at` is stamped at CLAIM time, not on completion. A run that crashes
 * must not become a hot loop that retries every minute for the rest of the day
 * — waiting for the next slot is the correct recovery for a scheduled job.
 *
 * Due-ness is deliberately loose (a full interval since the last run, and for
 * daily/weekly the hour must match). An agent that misses its 09:00 slot
 * because the cron was down runs at 10:00 the same day rather than being
 * skipped until tomorrow.
 */
create or replace function claim_due_agents(p_limit int default 5)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_rows jsonb;
begin
  with candidate as (
    select a.id
      from agents a
     where a.enabled
       and a.schedule <> 'off'
       and btrim(a.schedule_task) <> ''
       and case a.schedule
             when 'hourly' then a.last_run_at is null or a.last_run_at < now() - interval '1 hour'
             when 'daily'  then (a.last_run_at is null or a.last_run_at < now() - interval '23 hours')
                                and extract(hour from now() at time zone 'UTC') >= a.schedule_hour
             when 'weekly' then (a.last_run_at is null or a.last_run_at < now() - interval '6 days 23 hours')
                                and extract(hour from now() at time zone 'UTC') >= a.schedule_hour
             else false
           end
     order by a.last_run_at nulls first
     limit greatest(1, least(coalesce(p_limit, 5), 25))
     for update skip locked
  ), claimed as (
    update agents a set last_run_at = now()
      from candidate c
     where a.id = c.id
    returning a.id, a.workspace_id, a.name, a.schedule_task
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', cl.id, 'workspace_id', cl.workspace_id,
           'name', cl.name, 'task', cl.schedule_task)), '[]'::jsonb)
    into v_rows
    from claimed cl;

  return v_rows;
end $$;
revoke all on function claim_due_agents(int) from public, authenticated, anon;
grant execute on function claim_due_agents(int) to service_role;

/**
 * Who an unattended run acts as.
 *
 * There is no such thing as an unattributed actor here: every tool derives its
 * tenancy from `p_privy` in SQL, so a run with no identity would either see
 * nothing or need a bypass — and a bypass is exactly how one tenant's agent
 * ends up reading another's data.
 *
 * So the run is attributed to the member who added the AI key being spent. That
 * is the honest choice on both counts: it is their credit, and their
 * permissions are the ones the workspace already agreed the agent may use.
 * Falls back to the oldest workspace member when the key row predates
 * `created_by_privy`, and returns null when the workspace has no key at all —
 * which the dispatcher treats as "nothing to do", not as an error.
 */
create or replace function get_workspace_ai_owner(p_workspace uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_privy text;
begin
  select nullif(a.created_by_privy, '') into v_privy
    from ai_providers a
   where a.workspace_id = p_workspace and a.enabled
   order by a.is_default desc, a.created_at
   limit 1;

  if v_privy is null then
    -- No key at all → no owner. Distinct from "key exists but has no author".
    if not exists (select 1 from ai_providers a where a.workspace_id = p_workspace and a.enabled) then
      return null;
    end if;
    select ac.privy_user_id into v_privy
      from accounts ac where ac.workspace_id = p_workspace
     order by ac.created_at nulls last limit 1;
  end if;

  -- The author may have left the workspace since. Acting as someone who is no
  -- longer a member would be a privilege that outlives their membership.
  if v_privy is null or not is_workspace_member(p_workspace, v_privy) then
    select ac.privy_user_id into v_privy
      from accounts ac where ac.workspace_id = p_workspace
     order by ac.created_at nulls last limit 1;
  end if;

  if v_privy is null then return null; end if;
  return jsonb_build_object('privy_user_id', v_privy);
end $$;
revoke all on function get_workspace_ai_owner(uuid) from public, authenticated, anon;
grant execute on function get_workspace_ai_owner(uuid) to service_role;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0085_doc_kinds_wider.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0085_doc_kinds_wider.sql
-- Two more document kinds: a checklist and a table.
--
-- 0081 shipped `doc | note` and said so out loud: a kind the editor cannot
-- render is a bug waiting. Both of these now have an editor, so the CHECK
-- widens to match — which is the whole reason it was a CHECK and not a free
-- text column.
--
--   todo  — a real checklist. Not "a note that happens to contain checkboxes":
--           it has its own editor, its own progress count, and reordering.
--   sheet — a small table. NOT a spreadsheet: no formulas, no cell references,
--           no recalculation. Anyone who needs those already has the Excel
--           feed (0078) and two-way sync (0079) pointing at real records, and
--           reimplementing a formula engine here would be a worse version of
--           a thing this product already integrates with properly.
--
-- BOTH STORE MARKDOWN, in the same `body` column as everything else. A todo is
-- `- [ ] …` lines; a sheet is a markdown table. That is what keeps every kind
-- openable in every editor, exportable by one code path, and searchable by the
-- same query — and it is why adding a kind is a CHECK change rather than a
-- schema change.
--
-- Depends on 0081. Idempotent & prod-safe.
-- ============================================================================

-- `drop constraint if exists` then re-add: a CHECK cannot be widened in place,
-- and dropping first is what makes re-running this safe.
alter table docs drop constraint if exists docs_kind_check;
alter table docs add constraint docs_kind_check
  check (kind in ('doc', 'note', 'todo', 'sheet'));

-- The validator in save_doc has to widen with it, or a `todo` would be silently
-- stored as whatever the row already was — which is exactly the fallback's job
-- for BAD values, and the wrong answer for good ones. Full redefinition rather
-- than a parallel function; the signature is unchanged from 0081, so this is a
-- plain replace and no overload appears.
-- NOTE THE DEFAULT: null, not 'doc'. 0081 defaulted it to 'doc', which meant a
-- caller that omitted the argument was indistinguishable from one asking for a
-- document — so any five-argument save silently converted a table back into a
-- document. Null is the only value that can mean "I am not saying", which is
-- what an omitted argument actually means.
create or replace function save_doc(
  p_privy text, p_workspace uuid, p_id uuid, p_title text, p_body text,
  p_kind text default null
) returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid; v_kind text;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  -- Unknown or absent → null → keep the existing kind on update, default to
  -- 'doc' on insert. A bad value must never widen the CHECK by the back door.
  v_kind := case when p_kind in ('doc', 'note', 'todo', 'sheet') then p_kind else null end;

  if p_id is null then
    insert into docs (workspace_id, title, body, kind, created_by_privy)
    values (p_workspace, coalesce(nullif(p_title, ''), 'Untitled'), coalesce(p_body, ''),
            coalesce(v_kind, 'doc'), p_privy)
    returning id into v_id;
  else
    update docs
       set title = coalesce(nullif(p_title, ''), title),
           body  = coalesce(p_body, body),
           kind  = coalesce(v_kind, kind)
     where id = p_id and workspace_id = p_workspace
    returning id into v_id;
  end if;
  return v_id;
end $$;
grant execute on function save_doc(text, uuid, uuid, text, text, text) to authenticated, anon;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0086_doc_cards.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0086_doc_cards.sql
-- Notes and to-do lists become live cards: tags, and ticking without opening.
--
-- WHAT CHANGES AND WHY. The Docs index showed a 140-character snippet, which
-- for a checklist is a wall of "- [ ] " and tells you nothing. A list is a
-- thing you glance at and tick — opening a document to check one box off is
-- the whole friction. So the index needs two things it did not have: enough of
-- the body to render the list, and a way to flip one item.
--
-- TICKING GOES THROUGH ITS OWN RPC, not save_doc. Sending the whole body back
-- to toggle one checkbox means the client has to HOLD the whole body — and the
-- index only ever receives a preview, so a save from there would truncate the
-- document to whatever the card happened to be showing. `toggle_doc_item` flips
-- the Nth checklist line in SQL and never transports the body at all.
--
-- TAGS ARE A text[] ON THE ROW, not a table. There is no tag CRUD, no colour
-- picker and no join: a colour is derived from the tag's name in the client, so
-- "Personal" is the same green in every workspace and nobody has to administer
-- a palette. A tags table earns its place when tags need renaming, merging or
-- permissions — none of which is being asked for.
--
-- Depends on 0081 + 0085. Idempotent & prod-safe.
-- ============================================================================

alter table docs add column if not exists tags text[] not null default '{}';

-- Filtering by tag is the point of having them.
create index if not exists idx_docs_tags on docs using gin (tags);

/**
 * Normalise a tag list: trimmed, de-duplicated case-insensitively, capped.
 *
 * Cheap to enforce here and impossible to enforce anywhere else — every caller
 * would otherwise need the same three rules, and "Personal" and "personal"
 * rendering as two different pills is the kind of thing nobody reports and
 * everybody notices.
 */
create or replace function normalize_doc_tags(p_tags text[])
returns text[] language sql immutable as $$
  select coalesce(array_agg(t order by t), '{}')
    from (
      select distinct on (lower(btrim(x))) left(btrim(x), 24) as t
        from unnest(coalesce(p_tags, '{}')) as x
       where btrim(x) <> ''
       order by lower(btrim(x))
       limit 8
    ) s;
$$;

-- ── The index read ──────────────────────────────────────────────────────────
/**
 * Same shape as before plus `tags`, a longer `preview`, and the counts.
 *
 * The counts are computed in SQL rather than by the client parsing `preview`,
 * because the preview is TRUNCATED — counting from it would quietly under-report
 * a long list, and "3/7" that is actually "3/19" is worse than no number.
 */
create or replace function get_docs(p_privy text, p_workspace uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
    'id', d.id, 'title', d.title,
    'snippet', left(d.body, 140),
    -- Enough to render a card, nowhere near enough to be a document transfer.
    -- A card caps what it shows anyway, so this is a display budget.
    'preview', left(d.body, 1200),
    'kind', d.kind, 'tags', d.tags,
    'item_count', (select count(*) from regexp_matches(d.body, '^\s*[-*]\s+\[[ xX]\]', 'gn') m),
    'done_count', (select count(*) from regexp_matches(d.body, '^\s*[-*]\s+\[[xX]\]',  'gn') m),
    'updated_at', d.updated_at
  ) order by d.updated_at desc) from docs d where d.workspace_id = p_workspace), '[]'::jsonb);
end $$;
grant execute on function get_docs(text, uuid) to authenticated, anon;

create or replace function get_doc(p_privy text, p_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare my uuid[] := (select array_agg(workspace_id) from accounts where privy_user_id = p_privy);
begin
  return (select to_jsonb(t) from (
    select id, title, body, kind, tags, updated_at from docs where id = p_id and workspace_id = any(my)
  ) t);
end $$;
grant execute on function get_doc(text, uuid) to authenticated, anon;

-- ── Writes ──────────────────────────────────────────────────────────────────
-- Dropped and recreated: adding `p_tags` creates an overload, and every
-- six-argument call would then be ambiguous. Same reasoning as 0068 and 0085.
drop function if exists save_doc(text, uuid, uuid, text, text, text);

create or replace function save_doc(
  p_privy text, p_workspace uuid, p_id uuid, p_title text, p_body text,
  p_kind text default null, p_tags text[] default null
) returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid; v_kind text;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  -- Null = "I am not saying", which is what an omitted argument means. 0081
  -- defaulted this to 'doc' and so silently converted a table back into a
  -- document on any save that did not mention the kind.
  v_kind := case when p_kind in ('doc', 'note', 'todo', 'sheet') then p_kind else null end;

  if p_id is null then
    insert into docs (workspace_id, title, body, kind, tags, created_by_privy)
    values (p_workspace, coalesce(nullif(p_title, ''), 'Untitled'), coalesce(p_body, ''),
            coalesce(v_kind, 'doc'), normalize_doc_tags(p_tags), p_privy)
    returning id into v_id;
  else
    update docs
       set title = coalesce(nullif(p_title, ''), title),
           body  = coalesce(p_body, body),
           kind  = coalesce(v_kind, kind),
           -- Same rule as the kind: null means "leave them", which is what an
           -- older client that knows nothing about tags is saying.
           tags  = case when p_tags is null then tags else normalize_doc_tags(p_tags) end
     where id = p_id and workspace_id = p_workspace
    returning id into v_id;
  end if;
  return v_id;
end $$;
grant execute on function save_doc(text, uuid, uuid, text, text, text, text[]) to authenticated, anon;

/**
 * Flip the Nth checklist item (0-based), in place.
 *
 * The body never leaves the database. That is the point: the index holds a
 * TRUNCATED preview, so a round trip through the client would save whatever the
 * card was showing and throw away the rest of the document.
 *
 * `p_done` is explicit rather than a toggle so a double-tap, a slow network or
 * two people on the same list all converge on the state the person actually
 * chose, instead of racing to the opposite of whatever they last saw.
 *
 * Out-of-range and non-checklist documents return false rather than raising:
 * the caller is a checkbox on a card, and an exception there is a red banner
 * over a list that simply has no such item any more.
 */
create or replace function toggle_doc_item(p_privy text, p_id uuid, p_index int, p_done boolean)
returns boolean language plpgsql security definer set search_path = public as $$
declare
  my uuid[] := (select array_agg(workspace_id) from accounts where privy_user_id = p_privy);
  v_body text; v_lines text[]; v_out text[] := '{}'; v_n int := 0; v_hit boolean := false;
  v_line text;
begin
  select body into v_body from docs where id = p_id and workspace_id = any(my);
  if v_body is null then return false; end if;

  v_lines := string_to_array(v_body, E'\n');
  foreach v_line in array v_lines loop
    if v_line ~ '^\s*[-*]\s+\[[ xX]\]' then
      if v_n = p_index then
        -- Only the marker is rewritten; the indent, bullet character and text
        -- are left exactly as they were, so a round trip through here is not a
        -- reformat of somebody's list.
        v_line := regexp_replace(v_line, '^(\s*[-*]\s+\[)[ xX](\])',
                                 '\1' || case when p_done then 'x' else ' ' end || '\2');
        v_hit := true;
      end if;
      v_n := v_n + 1;
    end if;
    v_out := v_out || v_line;
  end loop;

  if not v_hit then return false; end if;
  update docs set body = array_to_string(v_out, E'\n') where id = p_id and workspace_id = any(my);
  return true;
end $$;
grant execute on function toggle_doc_item(text, uuid, int, boolean) to authenticated, anon;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0087_custom_objects.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0087_custom_objects.sql
-- Workspaces can define their own objects and fields.
--
-- WHY THIS MATTERS MORE THAN ANY FEATURE SO FAR. Every object in this product
-- is hardcoded. A transport company cannot add a Vehicle with a plate number
-- and an MOT date; a clinic cannot add a Patient; a factory cannot add a
-- Machine. "One core across Sales, Finance, Marketing, Projects and HR" is
-- only true for the five verticals we happened to build, and the honest
-- version of a general tool is one that BENDS. This is what lets a vertical be
-- a template rather than a fork.
--
-- ── JSONB, NOT DDL ──────────────────────────────────────────────────────────
-- A custom object could create a real table each. It must not. A SECURITY
-- DEFINER function running CREATE TABLE built from user input is one escaping
-- mistake from arbitrary DDL across every tenant — the same reasoning that
-- keeps segment_match (0072) a whitelist CASE and never dynamic SQL. Rows live
-- in ONE table with a `data jsonb` column: no runtime DDL, no migration per
-- object, no schema explosion, and one GIN index serves every workspace.
--
-- ── THE CRUD MONOLITH IS EXTENDED, NOT FORKED ───────────────────────────────
-- list/get/create/update/delete_record gain ONE branch each, at the END, after
-- every built-in has had its say. That ordering is the safety property: a
-- custom object can never shadow a built-in, whatever it is called.
--
-- Everything downstream — the agent tools, /api/mcp, the CSV feed, Excel sync,
-- imports, the record table — goes through those five functions, so a custom
-- object becomes a first-class citizen everywhere the moment this runs. That is
-- the whole reason for extending the monolith instead of adding a parallel one.
--
-- ── VALUES ARE COERCED, AND FAIL CLOSED ─────────────────────────────────────
-- coerce_custom_value types each value against its field. A number that is not
-- a number, and a select option that is not in the list, are REJECTED rather
-- than silently stored: a field definition nobody enforces is a comment, and
-- every consumer downstream trusts the declared type.
--
-- Depends on 0001 and 0031. Idempotent & prod-safe.
-- ============================================================================

-- ── The object ──────────────────────────────────────────────────────────────
create table if not exists custom_objects (
  id           uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspaces(id) on delete cascade,
  -- URL segment, and the `p_object` value the CRUD functions receive.
  slug         text not null,
  singular     text not null default 'Record',
  plural       text not null default 'Records',
  icon         text not null default 'Table2',
  -- Which nav group it appears under. Free text, so a workspace can invent one.
  group_key    text not null default 'Workspace',
  description  text not null default '',
  position     int  not null default 0,
  enabled      boolean not null default true,
  created_by_privy text,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  unique (workspace_id, slug)
);
alter table custom_objects enable row level security;
revoke all on table custom_objects from anon, authenticated;
drop trigger if exists trg_custom_objects_upd on custom_objects;
create trigger trg_custom_objects_upd before update on custom_objects
  for each row execute function set_updated_at();

-- ── The fields ──────────────────────────────────────────────────────────────
create table if not exists custom_fields (
  id           uuid primary key default gen_random_uuid(),
  object_id    uuid not null references custom_objects(id) on delete cascade,
  workspace_id uuid not null references workspaces(id) on delete cascade,
  key          text not null,
  label        text not null default '',
  -- Deliberately small. Every type here has a real editor, a real renderer and
  -- real coercion; a type with none of those is a promise the product breaks.
  type         text not null default 'text',
  options      text[] not null default '{}',
  -- For `relation`: which object this points at. A built-in slug or another
  -- custom one — both resolve through the same CRUD functions.
  relation_to  text,
  required     boolean not null default false,
  -- The headline column: what the row is called. Exactly one per object.
  is_primary   boolean not null default false,
  position     int not null default 0,
  created_at   timestamptz not null default now(),
  unique (object_id, key)
);
alter table custom_fields enable row level security;
revoke all on table custom_fields from anon, authenticated;
create index if not exists idx_custom_fields_obj on custom_fields(object_id, position);

do $$ begin
  alter table custom_fields add constraint custom_fields_type_check
    check (type in ('text','long_text','number','currency','date','checkbox',
                    'select','email','url','phone','relation'));
exception when duplicate_object then null; end $$;

-- ── The rows ────────────────────────────────────────────────────────────────
create table if not exists custom_records (
  id           uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspaces(id) on delete cascade,
  object_id    uuid not null references custom_objects(id) on delete cascade,
  data         jsonb not null default '{}'::jsonb,
  created_by_privy text,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);
alter table custom_records enable row level security;
revoke all on table custom_records from anon, authenticated;
create index if not exists idx_custom_records_obj on custom_records(object_id, created_at desc);
-- Filtering and searching inside `data` without a table scan.
create index if not exists idx_custom_records_data on custom_records using gin (data);
drop trigger if exists trg_custom_records_upd on custom_records;
create trigger trg_custom_records_upd before update on custom_records
  for each row execute function set_updated_at();

-- ── Guards ──────────────────────────────────────────────────────────────────
/**
 * Slugs the CRUD monolith already answers to.
 *
 * A custom object named `people` could never win — the built-in branch matches
 * first — so it would silently do nothing, which is worse than being refused.
 * Refusing at creation makes the collision impossible instead of merely lost.
 */
create or replace function reserved_object_slug(p_slug text)
returns boolean language sql immutable as $$
  select lower(coalesce(p_slug, '')) in (
    'people','companies','organizations','invoices','offers','expenses','transactions',
    'products','campaigns','projects','issues','assets','candidates','positions',
    'documents','docs','files','posts','newsletters','forms','sites','agents','skills'
  );
$$;

/**
 * Coerce one value to its field's type, or raise.
 *
 * Fails CLOSED. A number that is not a number and a select option outside the
 * list are refused rather than stored as text — the CSV feed, Excel sync and
 * any agent reading a "number" all trust the declared type, so a field
 * definition nobody enforces would break all three quietly.
 *
 * Null and empty pass through as JSON null unless the field is required, so
 * clearing a value is always possible.
 */
create or replace function coerce_custom_value(p_field custom_fields, p_value jsonb)
returns jsonb language plpgsql immutable as $$
declare v_text text;
begin
  if p_value is null or jsonb_typeof(p_value) = 'null' then
    if p_field.required then raise exception 'REQUIRED_FIELD: %', p_field.key; end if;
    return 'null'::jsonb;
  end if;

  -- Everything arrives as a JSON scalar; normalise to text once, then branch.
  v_text := btrim(case when jsonb_typeof(p_value) = 'string' then p_value #>> '{}' else p_value::text end);

  if v_text = '' then
    if p_field.required then raise exception 'REQUIRED_FIELD: %', p_field.key; end if;
    return 'null'::jsonb;
  end if;

  case p_field.type
    when 'number', 'currency' then
      if v_text !~ '^-?[0-9]+(\.[0-9]+)?$' then
        raise exception 'NOT_A_NUMBER: % (%)', p_field.key, v_text;
      end if;
      return to_jsonb(v_text::numeric);

    when 'checkbox' then
      return to_jsonb(lower(v_text) in ('true','t','yes','y','1'));

    when 'date' then
      -- An ISO date string, not a timestamp: these are calendar days (a due
      -- date, an MOT expiry), and giving them a timezone invents an hour that
      -- shifts the day for half the world.
      begin
        return to_jsonb(to_char(v_text::date, 'YYYY-MM-DD'));
      exception when others then raise exception 'NOT_A_DATE: % (%)', p_field.key, v_text;
      end;

    when 'select' then
      if cardinality(p_field.options) > 0 and not (v_text = any(p_field.options)) then
        raise exception 'BAD_OPTION: % (%)', p_field.key, v_text;
      end if;
      return to_jsonb(v_text);

    when 'relation' then
      if v_text !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' then
        raise exception 'NOT_A_RECORD_ID: %', p_field.key;
      end if;
      return to_jsonb(v_text);

    when 'email' then
      if v_text !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then
        raise exception 'NOT_AN_EMAIL: %', p_field.key;
      end if;
      return to_jsonb(lower(v_text));

    when 'url' then
      -- http/https only. A `javascript:` value stored here is rendered as a
      -- link somewhere eventually, and that is an XSS with a long fuse.
      if v_text !~* '^https?://' then raise exception 'NOT_A_URL: %', p_field.key; end if;
      return to_jsonb(left(v_text, 2000));

    else
      return to_jsonb(left(v_text, case when p_field.type = 'long_text' then 20000 else 1000 end));
  end case;
end $$;

/**
 * Build a validated `data` object from a client payload.
 *
 * Only DECLARED fields survive. An undeclared key is dropped rather than
 * stored: otherwise the row's shape drifts away from the field list, and every
 * reader — the table, the CSV feed, an agent — is looking at a schema that no
 * longer describes the data.
 */
create or replace function build_custom_data(p_object uuid, p_data jsonb, p_existing jsonb default null)
returns jsonb language plpgsql as $$
declare f custom_fields; v_out jsonb := coalesce(p_existing, '{}'::jsonb);
begin
  for f in select * from custom_fields where object_id = p_object order by position loop
    -- An absent key means "leave it alone" on update, and "empty" on insert
    -- (p_existing is null there). Present-but-null means "clear it".
    if p_data ? f.key then
      v_out := jsonb_set(v_out, array[f.key], coerce_custom_value(f, p_data -> f.key));
    elsif p_existing is null and f.required then
      raise exception 'REQUIRED_FIELD: %', f.key;
    end if;
  end loop;
  return v_out;
end $$;

/** The row's headline, for lists and anything else that shows a name. */
create or replace function custom_record_label(p_object uuid, p_data jsonb)
returns text language sql stable as $$
  select coalesce(
    nullif(p_data ->> (select key from custom_fields
                        where object_id = p_object and is_primary order by position limit 1), ''),
    nullif(p_data ->> (select key from custom_fields
                        where object_id = p_object order by position limit 1), ''),
    'Untitled');
$$;

-- ── Object + field management (browser-reachable) ───────────────────────────
create or replace function get_custom_objects(p_privy text, p_workspace uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
    'id', o.id, 'slug', o.slug, 'singular', o.singular, 'plural', o.plural,
    'icon', o.icon, 'group_key', o.group_key, 'description', o.description,
    'position', o.position, 'enabled', o.enabled,
    'record_count', (select count(*) from custom_records r where r.object_id = o.id),
    'fields', coalesce((select jsonb_agg(jsonb_build_object(
      'id', f.id, 'key', f.key, 'label', f.label, 'type', f.type, 'options', f.options,
      'relation_to', f.relation_to, 'required', f.required, 'is_primary', f.is_primary,
      'position', f.position
    ) order by f.position) from custom_fields f where f.object_id = o.id), '[]'::jsonb)
  ) order by o.position, o.plural) from custom_objects o where o.workspace_id = p_workspace), '[]'::jsonb);
end $$;
grant execute on function get_custom_objects(text, uuid) to authenticated, anon;

create or replace function save_custom_object(
  p_privy text, p_workspace uuid, p_id uuid, p_slug text, p_singular text, p_plural text,
  p_icon text default 'Table2', p_group text default 'Workspace', p_description text default ''
) returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid; v_slug text;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  -- Defining an object is a schema change, so it is an owner/admin act — the
  -- same bar delete_record already sets for destroying one row.
  if workspace_role(p_privy, p_workspace) not in ('owner','admin') then
    raise exception 'FORBIDDEN: only an owner or admin can change objects';
  end if;

  v_slug := lower(btrim(coalesce(p_slug, '')));
  if v_slug !~ '^[a-z][a-z0-9_]{1,30}$' then
    raise exception 'BAD_SLUG: use lowercase letters, numbers and underscores';
  end if;
  if reserved_object_slug(v_slug) then raise exception 'RESERVED_SLUG: % is a built-in object', v_slug; end if;

  if p_id is null then
    insert into custom_objects (workspace_id, slug, singular, plural, icon, group_key, description,
                                position, created_by_privy)
    values (p_workspace, v_slug,
            coalesce(nullif(btrim(p_singular), ''), 'Record'),
            coalesce(nullif(btrim(p_plural), ''), 'Records'),
            coalesce(nullif(p_icon, ''), 'Table2'),
            coalesce(nullif(btrim(p_group), ''), 'Workspace'),
            coalesce(p_description, ''),
            (select coalesce(max(position), 0) + 1 from custom_objects where workspace_id = p_workspace),
            p_privy)
    returning id into v_id;
  else
    update custom_objects
       set slug = v_slug,
           singular = coalesce(nullif(btrim(p_singular), ''), singular),
           plural = coalesce(nullif(btrim(p_plural), ''), plural),
           icon = coalesce(nullif(p_icon, ''), icon),
           group_key = coalesce(nullif(btrim(p_group), ''), group_key),
           description = coalesce(p_description, description)
     where id = p_id and workspace_id = p_workspace
    returning id into v_id;
    if v_id is null then raise exception 'NO_SUCH_OBJECT'; end if;
  end if;
  return v_id;
end $$;
grant execute on function save_custom_object(text, uuid, uuid, text, text, text, text, text, text) to authenticated, anon;

create or replace function save_custom_field(
  p_privy text, p_workspace uuid, p_object uuid, p_id uuid,
  p_key text, p_label text, p_type text,
  p_options text[] default '{}', p_relation_to text default null,
  p_required boolean default false, p_primary boolean default false, p_position int default null
) returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid; v_key text;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  if workspace_role(p_privy, p_workspace) not in ('owner','admin') then
    raise exception 'FORBIDDEN: only an owner or admin can change fields';
  end if;
  if not exists (select 1 from custom_objects where id = p_object and workspace_id = p_workspace) then
    raise exception 'NO_SUCH_OBJECT';
  end if;

  v_key := lower(btrim(coalesce(p_key, '')));
  if v_key !~ '^[a-z][a-z0-9_]{0,30}$' then
    raise exception 'BAD_FIELD_KEY: use lowercase letters, numbers and underscores';
  end if;
  -- `id` is the row's own column, not a field. Declaring one would shadow the
  -- record id in every payload the CRUD functions return.
  if v_key in ('id', 'created_at', 'updated_at') then raise exception 'RESERVED_FIELD_KEY: %', v_key; end if;
  if p_type not in ('text','long_text','number','currency','date','checkbox',
                    'select','email','url','phone','relation') then
    raise exception 'BAD_FIELD_TYPE: %', p_type;
  end if;

  if p_id is null then
    insert into custom_fields (object_id, workspace_id, key, label, type, options, relation_to,
                               required, is_primary, position)
    values (p_object, p_workspace, v_key,
            coalesce(nullif(btrim(p_label), ''), initcap(replace(v_key, '_', ' '))),
            p_type, coalesce(p_options, '{}'), nullif(p_relation_to, ''),
            coalesce(p_required, false), coalesce(p_primary, false),
            coalesce(p_position, (select coalesce(max(position), 0) + 1 from custom_fields where object_id = p_object)))
    returning id into v_id;
  else
    update custom_fields
       set key = v_key,
           label = coalesce(nullif(btrim(p_label), ''), label),
           type = p_type, options = coalesce(p_options, options),
           relation_to = nullif(p_relation_to, ''),
           required = coalesce(p_required, required),
           is_primary = coalesce(p_primary, is_primary),
           position = coalesce(p_position, position)
     where id = p_id and object_id = p_object
    returning id into v_id;
    if v_id is null then raise exception 'NO_SUCH_FIELD'; end if;
  end if;

  -- Exactly one primary, enforced by demoting the others rather than by a
  -- constraint — so setting a new primary is one call and never a failed one.
  if coalesce(p_primary, false) then
    update custom_fields set is_primary = false where object_id = p_object and id <> v_id;
  end if;
  return v_id;
end $$;
grant execute on function save_custom_field(text, uuid, uuid, uuid, text, text, text, text[], text, boolean, boolean, int) to authenticated, anon;

create or replace function delete_custom_field(p_privy text, p_workspace uuid, p_id uuid)
returns boolean language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  if workspace_role(p_privy, p_workspace) not in ('owner','admin') then
    raise exception 'FORBIDDEN: only an owner or admin can change fields';
  end if;
  delete from custom_fields where id = p_id and workspace_id = p_workspace;
  -- The VALUES stay in `data`. Dropping a field changes the shape, and quietly
  -- deleting the contents of a column across every row is not a click-sized
  -- act — re-adding the field brings the data back.
  return found;
end $$;
grant execute on function delete_custom_field(text, uuid, uuid) to authenticated, anon;

create or replace function delete_custom_object(p_privy text, p_workspace uuid, p_id uuid)
returns boolean language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  if workspace_role(p_privy, p_workspace) not in ('owner','admin') then
    raise exception 'FORBIDDEN: only an owner or admin can delete an object';
  end if;
  -- Cascades to its fields AND its rows. That is a real deletion of real data,
  -- which is why it is admin-only and why the UI asks for the name back.
  delete from custom_objects where id = p_id and workspace_id = p_workspace;
  return found;
end $$;
grant execute on function delete_custom_object(text, uuid, uuid) to authenticated, anon;

-- ── The CRUD monolith, extended ─────────────────────────────────────────────
-- Reproduced IN FULL from 0031 — the convention is to extend the latest
-- definition, never to add a parallel one — with exactly one branch added to
-- each, at the END so no built-in can be shadowed.

create or replace function list_records(p_privy text, p_workspace uuid, p_object text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_obj uuid;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;

  if p_object = 'people' then
    return coalesce((select jsonb_agg(jsonb_build_object(
      'id', pe.id, 'name', trim(coalesce(pe.first_name,'')||' '||coalesce(pe.last_name,'')),
      'title', pe.title, 'company', co.name, 'email', pe.email, 'source', pe.source,
      'synergy', (select ps.overall from psychometrics ps where ps.person_id=pe.id order by ps.assessed_at desc limit 1)
    ) order by pe.created_at desc)
    from people pe left join organizations co on co.id = pe.primary_company_id
    where pe.workspace_id=p_workspace), '[]'::jsonb);

  elsif p_object in ('companies','organizations') then
    return coalesce((select jsonb_agg(jsonb_build_object(
      'id', o.id, 'name', o.name, 'domain', o.domain, 'industry', o.industry, 'employee_count', o.employee_count,
      'tax_id', o.tax_id, 'address', o.address, 'country', o.country
    ) order by o.created_at desc) from organizations o where o.workspace_id=p_workspace), '[]'::jsonb);

  elsif p_object = 'invoices' then
    return coalesce((select jsonb_agg(jsonb_build_object(
      'id', i.id, 'number', i.number, 'company', o.name, 'kind', i.kind, 'direction', i.direction,
      'category', i.category, 'amount', i.amount, 'status', i.status, 'due_at', i.due_at
    ) order by i.created_at desc)
    from invoices i left join organizations o on o.id = i.organization_id
    where i.workspace_id=p_workspace), '[]'::jsonb);

  elsif p_object = 'expenses' then
    return coalesce((select jsonb_agg(jsonb_build_object(
      'id', e.id, 'vendor', e.vendor, 'category', e.category, 'amount', e.amount, 'status', e.status, 'spent_at', e.spent_at
    ) order by e.created_at desc) from expenses e where e.workspace_id=p_workspace), '[]'::jsonb);

  elsif p_object = 'transactions' then
    return coalesce((select jsonb_agg(jsonb_build_object(
      'id', t.id, 'txn_date', t.txn_date, 'description', t.description, 'amount', t.amount, 'currency', t.currency,
      'category', t.category, 'method', t.method, 'status', t.status, 'tax_rate', t.tax_rate,
      'account', ba.name, 'bank_account_id', t.bank_account_id,
      'matched_invoice_id', t.matched_invoice_id, 'matched_expense_id', t.matched_expense_id
    ) order by t.txn_date desc, t.created_at desc)
    from transactions t left join bank_accounts ba on ba.id = t.bank_account_id
    where t.workspace_id=p_workspace), '[]'::jsonb);

  elsif p_object = 'products' then
    return coalesce((select jsonb_agg(jsonb_build_object(
      'id', p.id, 'name', p.name, 'image', p.image_url, 'sku', p.sku, 'category', p.category, 'unit_price', p.unit_price, 'unit', p.unit
    ) order by p.created_at desc) from products p where p.workspace_id=p_workspace), '[]'::jsonb);

  elsif p_object = 'campaigns' then
    return coalesce((select jsonb_agg(jsonb_build_object(
      'id', c.id, 'name', c.name, 'channel', c.channel, 'status', c.status,
      'budget', c.budget, 'spend', c.spend, 'leads', c.leads, 'starts_on', c.starts_on, 'ends_on', c.ends_on
    ) order by c.created_at desc) from campaigns c where c.workspace_id=p_workspace), '[]'::jsonb);

  elsif p_object = 'projects' then
    return coalesce((select jsonb_agg(jsonb_build_object(
      'id', pr.id, 'name', pr.name, 'identifier', pr.identifier, 'status', pr.status,
      'issues', (select count(*) from issues i where i.project_id = pr.id)
    ) order by pr.created_at desc) from projects pr where pr.workspace_id=p_workspace), '[]'::jsonb);

  elsif p_object = 'issues' then
    return coalesce((select jsonb_agg(jsonb_build_object(
      'id', i.id, 'name', i.title, 'project', pr.name, 'status', i.status,
      'priority', i.priority, 'due_date', i.due_date,
      'assignee', (select a.full_name from accounts a where a.id = i.assignee_account_id)
    ) order by i.sort_order)
    from issues i left join projects pr on pr.id = i.project_id
    where i.workspace_id=p_workspace), '[]'::jsonb);

  elsif p_object = 'assets' then
    return coalesce((select jsonb_agg(jsonb_build_object(
      'id', a.id, 'name', a.name, 'category', a.category, 'serial_number', a.serial_number, 'status', a.status,
      'assigned_to', (select trim(coalesce(pe.first_name,'')||' '||coalesce(pe.last_name,'')) from people pe where pe.id=a.assigned_to_person_id)
    ) order by a.created_at desc) from assets a where a.workspace_id=p_workspace), '[]'::jsonb);
  end if;

  -- ── Custom objects (0087) ──────────────────────────────────────────────────
  -- LAST, after every built-in has matched. That ordering is the safety
  -- property: a custom object can never shadow a built-in one, whatever it is
  -- called. reserved_object_slug refuses the name at creation too, so the
  -- collision is impossible rather than merely lost.
  v_obj := (select id from custom_objects
             where workspace_id = p_workspace and slug = p_object and enabled);
  if v_obj is not null then
    return coalesce((select jsonb_agg(
      -- id and name are spliced on top of the row's own data, so a custom
      -- object presents the same shape as a built-in one and every consumer
      -- (the table, the CSV feed, the agent tools) works unchanged.
      r.data || jsonb_build_object('id', r.id, 'name', custom_record_label(v_obj, r.data))
      order by r.created_at desc
    ) from custom_records r where r.object_id = v_obj), '[]'::jsonb);
  end if;

  return '[]'::jsonb;
end $$;
grant execute on function list_records(text, uuid, text) to authenticated, anon;

create or replace function get_record(p_privy text, p_object text, p_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare my uuid[] := (select array_agg(workspace_id) from accounts where privy_user_id = p_privy);
begin
  if p_object in ('companies','organizations') then
    return (select to_jsonb(t) from (select id, name, domain, industry, employee_count, tax_id, address, country from organizations where id=p_id and workspace_id = any(my)) t);
  elsif p_object = 'people' then
    return (select to_jsonb(t) from (select id, first_name, last_name, email, phone, title, source from people where id=p_id and workspace_id = any(my)) t);
  elsif p_object = 'invoices' then
    return (select to_jsonb(t) from (select id, number, organization_id, kind, direction, amount, status, category, issued_at, due_at, notes from invoices where id=p_id and workspace_id = any(my)) t);
  elsif p_object = 'expenses' then
    return (select to_jsonb(t) from (select id, vendor, category, amount, status, spent_at, notes from expenses where id=p_id and workspace_id = any(my)) t);
  elsif p_object = 'transactions' then
    return (select to_jsonb(t) from (select id, txn_date, description, amount, currency, category, method, status, tax_rate, bank_account_id, notes from transactions where id=p_id and workspace_id = any(my)) t);
  elsif p_object = 'products' then
    return (select to_jsonb(t) from (select id, name, sku, description, unit_price, unit, category, image_url from products where id=p_id and workspace_id = any(my)) t);
  elsif p_object = 'campaigns' then
    return (select to_jsonb(t) from (select id, name, channel, status, budget, spend, leads, starts_on, ends_on, notes from campaigns where id=p_id and workspace_id = any(my)) t);
  elsif p_object = 'projects' then
    return (select to_jsonb(t) from (select id, name, identifier, status, description from projects where id=p_id and workspace_id = any(my)) t);
  elsif p_object = 'issues' then
    return (select to_jsonb(t) from (select id, title, status, priority, due_date, description from issues where id=p_id and workspace_id = any(my)) t);
  end if;

  -- ── Custom objects (0087) ──────────────────────────────────────────────────
  -- Tenancy comes from `my` in SQL, exactly like every branch above: a foreign
  -- record id resolves to no row rather than to someone else's data.
  return (select r.data || jsonb_build_object('id', r.id,
                   'name', custom_record_label(r.object_id, r.data))
            from custom_records r
            join custom_objects o on o.id = r.object_id
           where r.id = p_id and o.slug = p_object and r.workspace_id = any(my));
end $$;
grant execute on function get_record(text, text, uuid) to authenticated, anon;

create or replace function create_record(p_privy text, p_workspace uuid, p_object text, p_data jsonb)
returns uuid language plpgsql security definer set search_path = public as $$
declare v_obj uuid; v_id uuid;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  if p_object in ('companies','organizations') then
    insert into organizations (workspace_id, name, domain, industry, employee_count, tax_id, address, country)
    values (p_workspace, p_data->>'name', nullif(p_data->>'domain',''), nullif(p_data->>'industry',''), nullif(p_data->>'employee_count','')::int,
            nullif(p_data->>'tax_id',''), nullif(p_data->>'address',''), nullif(p_data->>'country',''))
    returning id into v_id;
  elsif p_object = 'people' then
    insert into people (workspace_id, first_name, last_name, email, phone, title, source)
    values (p_workspace, p_data->>'first_name', nullif(p_data->>'last_name',''), nullif(p_data->>'email',''), nullif(p_data->>'phone',''), nullif(p_data->>'title',''), nullif(p_data->>'source',''))
    returning id into v_id;
  elsif p_object = 'invoices' then
    insert into invoices (workspace_id, number, organization_id, kind, direction, amount, status, category, issued_at, due_at, notes)
    values (p_workspace, nullif(p_data->>'number',''), nullif(p_data->>'organization_id','')::uuid, coalesce(nullif(p_data->>'kind',''),'invoice'), coalesce(nullif(p_data->>'direction',''),'income'),
            coalesce(nullif(p_data->>'amount','')::numeric,0), coalesce(nullif(p_data->>'status',''),'draft'), nullif(p_data->>'category',''),
            nullif(p_data->>'issued_at','')::date, nullif(p_data->>'due_at','')::date, nullif(p_data->>'notes',''))
    returning id into v_id;
  elsif p_object = 'expenses' then
    insert into expenses (workspace_id, vendor, category, amount, status, spent_at, notes)
    values (p_workspace, nullif(p_data->>'vendor',''), coalesce(nullif(p_data->>'category',''),'other'), coalesce(nullif(p_data->>'amount','')::numeric,0), coalesce(nullif(p_data->>'status',''),'pending'), nullif(p_data->>'spent_at','')::date, nullif(p_data->>'notes',''))
    returning id into v_id;
  elsif p_object = 'transactions' then
    insert into transactions (workspace_id, bank_account_id, txn_date, description, amount, currency, category, method, status, tax_rate, tags, notes)
    values (p_workspace, nullif(p_data->>'bank_account_id','')::uuid,
            coalesce(nullif(p_data->>'txn_date','')::date, now()::date), nullif(p_data->>'description',''),
            coalesce(nullif(regexp_replace(coalesce(p_data->>'amount',''), '[^0-9.-]', '', 'g'),'')::numeric, 0),
            coalesce(nullif(p_data->>'currency',''),'USD'), nullif(p_data->>'category',''),
            coalesce(nullif(p_data->>'method',''),'transfer'), coalesce(nullif(p_data->>'status',''),'posted'),
            nullif(p_data->>'tax_rate','')::numeric,
            case when nullif(p_data->>'tags','') is not null then string_to_array(p_data->>'tags', ',') else '{}'::text[] end,
            nullif(p_data->>'notes',''))
    returning id into v_id;
  elsif p_object = 'products' then
    insert into products (workspace_id, name, sku, description, unit_price, unit, category, image_url)
    values (p_workspace, p_data->>'name', nullif(p_data->>'sku',''), nullif(p_data->>'description',''), coalesce(nullif(p_data->>'unit_price','')::numeric,0), nullif(p_data->>'unit',''), nullif(p_data->>'category',''), nullif(p_data->>'image_url',''))
    returning id into v_id;
  elsif p_object = 'campaigns' then
    insert into campaigns (workspace_id, name, channel, status, budget, spend, leads, starts_on, ends_on, notes)
    values (p_workspace, p_data->>'name', coalesce(nullif(p_data->>'channel',''),'email'), coalesce(nullif(p_data->>'status',''),'planned'),
            coalesce(nullif(p_data->>'budget','')::numeric,0), coalesce(nullif(p_data->>'spend','')::numeric,0), coalesce(nullif(p_data->>'leads','')::int,0),
            nullif(p_data->>'starts_on','')::date, nullif(p_data->>'ends_on','')::date, nullif(p_data->>'notes',''))
    returning id into v_id;
  elsif p_object = 'projects' then
    insert into projects (workspace_id, name, identifier, status, description)
    values (p_workspace, p_data->>'name', nullif(p_data->>'identifier',''), coalesce(nullif(p_data->>'status',''),'active'), nullif(p_data->>'description',''))
    returning id into v_id;
  elsif p_object = 'issues' then
    insert into issues (workspace_id, title, status, priority, due_date, description)
    values (p_workspace, p_data->>'title', coalesce(nullif(p_data->>'status',''),'backlog'), coalesce(nullif(p_data->>'priority',''),'none'), nullif(p_data->>'due_date','')::date, nullif(p_data->>'description',''))
    returning id into v_id;
  else
    -- ── Custom objects (0087) ────────────────────────────────────────────────
    v_obj := (select id from custom_objects
               where workspace_id = p_workspace and slug = p_object and enabled);
    if v_obj is null then raise exception 'UNKNOWN_OBJECT: %', p_object; end if;
    -- build_custom_data validates every value against its field and drops
    -- anything undeclared, so a payload cannot widen the row's shape.
    insert into custom_records (workspace_id, object_id, data, created_by_privy)
    values (p_workspace, v_obj, build_custom_data(v_obj, coalesce(p_data, '{}'::jsonb)), p_privy)
    returning id into v_id;
  end if;
  return v_id;
end $$;
grant execute on function create_record(text, uuid, text, jsonb) to authenticated, anon;

create or replace function update_record(p_privy text, p_object text, p_id uuid, p_data jsonb)
returns void language plpgsql security definer set search_path = public as $$
declare v_id uuid; v_obj uuid; v_existing jsonb; my uuid[] := (select array_agg(workspace_id) from accounts where privy_user_id = p_privy);
begin
  if p_object in ('companies','organizations') then
    update organizations set name=coalesce(nullif(p_data->>'name',''),name), domain=nullif(p_data->>'domain',''), industry=nullif(p_data->>'industry',''), employee_count=nullif(p_data->>'employee_count','')::int,
      tax_id=nullif(p_data->>'tax_id',''), address=nullif(p_data->>'address',''), country=nullif(p_data->>'country','')
    where id=p_id and workspace_id = any(my);
  elsif p_object = 'people' then
    update people set first_name=nullif(p_data->>'first_name',''), last_name=nullif(p_data->>'last_name',''), email=nullif(p_data->>'email',''), phone=nullif(p_data->>'phone',''), title=nullif(p_data->>'title',''), source=nullif(p_data->>'source','')
    where id=p_id and workspace_id = any(my);
  elsif p_object = 'invoices' then
    update invoices set number=nullif(p_data->>'number',''), organization_id=nullif(p_data->>'organization_id','')::uuid,
      kind=coalesce(nullif(p_data->>'kind',''),kind), direction=coalesce(nullif(p_data->>'direction',''),direction),
      amount=coalesce(nullif(p_data->>'amount','')::numeric,amount),
      status=coalesce(nullif(p_data->>'status',''),status), category=nullif(p_data->>'category',''),
      issued_at=nullif(p_data->>'issued_at','')::date, due_at=nullif(p_data->>'due_at','')::date, notes=nullif(p_data->>'notes','')
    where id=p_id and workspace_id = any(my);
  elsif p_object = 'expenses' then
    update expenses set vendor=nullif(p_data->>'vendor',''), category=coalesce(nullif(p_data->>'category',''),category), amount=coalesce(nullif(p_data->>'amount','')::numeric,amount), status=coalesce(nullif(p_data->>'status',''),status), spent_at=nullif(p_data->>'spent_at','')::date, notes=nullif(p_data->>'notes','')
    where id=p_id and workspace_id = any(my);
  elsif p_object = 'transactions' then
    update transactions set
      bank_account_id = case when p_data ? 'bank_account_id' then nullif(p_data->>'bank_account_id','')::uuid else bank_account_id end,
      txn_date = coalesce(nullif(p_data->>'txn_date','')::date, txn_date),
      description = case when p_data ? 'description' then nullif(p_data->>'description','') else description end,
      amount = coalesce(nullif(regexp_replace(coalesce(p_data->>'amount',''), '[^0-9.-]', '', 'g'),'')::numeric, amount),
      category = case when p_data ? 'category' then nullif(p_data->>'category','') else category end,
      method = coalesce(nullif(p_data->>'method',''), method),
      status = coalesce(nullif(p_data->>'status',''), status),
      tax_rate = case when p_data ? 'tax_rate' then nullif(p_data->>'tax_rate','')::numeric else tax_rate end,
      notes = case when p_data ? 'notes' then nullif(p_data->>'notes','') else notes end
    where id=p_id and workspace_id = any(my);
  elsif p_object = 'products' then
    update products set name=coalesce(nullif(p_data->>'name',''),name), sku=nullif(p_data->>'sku',''), description=nullif(p_data->>'description',''), unit_price=coalesce(nullif(p_data->>'unit_price','')::numeric,unit_price), unit=nullif(p_data->>'unit',''), category=nullif(p_data->>'category',''), image_url=nullif(p_data->>'image_url','')
    where id=p_id and workspace_id = any(my);
  elsif p_object = 'campaigns' then
    update campaigns set name=coalesce(nullif(p_data->>'name',''),name), channel=coalesce(nullif(p_data->>'channel',''),channel), status=coalesce(nullif(p_data->>'status',''),status),
      budget=coalesce(nullif(p_data->>'budget','')::numeric,budget), spend=coalesce(nullif(p_data->>'spend','')::numeric,spend), leads=coalesce(nullif(p_data->>'leads','')::int,leads),
      starts_on=nullif(p_data->>'starts_on','')::date, ends_on=nullif(p_data->>'ends_on','')::date, notes=nullif(p_data->>'notes','')
    where id=p_id and workspace_id = any(my);
  elsif p_object = 'projects' then
    update projects set name=coalesce(nullif(p_data->>'name',''),name), identifier=nullif(p_data->>'identifier',''), status=coalesce(nullif(p_data->>'status',''),status), description=nullif(p_data->>'description','')
    where id=p_id and workspace_id = any(my);
  elsif p_object = 'issues' then
    update issues set title=coalesce(nullif(p_data->>'title',''),title), status=coalesce(nullif(p_data->>'status',''),status), priority=coalesce(nullif(p_data->>'priority',''),priority), due_date=nullif(p_data->>'due_date','')::date, description=nullif(p_data->>'description','')
    where id=p_id and workspace_id = any(my);
  else
    -- ── Custom objects (0087) ────────────────────────────────────────────────
    select r.id, r.object_id, r.data into v_id, v_obj, v_existing
      from custom_records r join custom_objects o on o.id = r.object_id
     where r.id = p_id and o.slug = p_object and r.workspace_id = any(my);
    if v_id is null then raise exception 'UNKNOWN_OBJECT: %', p_object; end if;
    -- Merged onto the EXISTING data, so an absent key means "leave it alone"
    -- and a partial save never blanks the fields it does not mention — the
    -- same rule save_workspace_branding follows.
    update custom_records set data = build_custom_data(v_obj, coalesce(p_data, '{}'::jsonb), v_existing)
     where id = v_id;
  end if;
end $$;
grant execute on function update_record(text, text, uuid, jsonb) to authenticated, anon;

create or replace function delete_record(p_privy text, p_object text, p_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare tbl text; v_ws uuid;
begin
  tbl := case p_object
    when 'companies' then 'organizations' when 'organizations' then 'organizations'
    when 'people' then 'people' when 'invoices' then 'invoices' when 'expenses' then 'expenses'
    when 'transactions' then 'transactions'
    when 'products' then 'products' when 'campaigns' then 'campaigns'
    when 'projects' then 'projects' when 'issues' then 'issues' when 'assets' then 'assets'
    else null end;
  -- ── Custom objects (0087) ────────────────────────────────────────────────
  -- Same admin bar and the same membership check as a built-in, just against
  -- custom_records instead of a named table.
  if tbl is null then
    select r.workspace_id into v_ws
      from custom_records r join custom_objects o on o.id = r.object_id
     where r.id = p_id and o.slug = p_object;
    if v_ws is null then return; end if;
    if not is_workspace_member(v_ws, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
    if workspace_role(p_privy, v_ws) not in ('owner', 'admin') then
      raise exception 'FORBIDDEN: delete requires admin';
    end if;
    delete from custom_records where id = p_id and workspace_id = v_ws;
    return;
  end if;
  execute format('select workspace_id from %I where id = $1', tbl) into v_ws using p_id;
  if v_ws is null then return; end if;
  if not is_workspace_member(v_ws, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  if workspace_role(p_privy, v_ws) not in ('owner', 'admin') then raise exception 'FORBIDDEN: delete requires admin'; end if;
  execute format('delete from %I where id = $1 and workspace_id = $2', tbl) using p_id, v_ws;
end $$;
grant execute on function delete_record(text, text, uuid) to authenticated, anon;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0088_partial_update_fix.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0088_partial_update_fix.sql
-- A partial update no longer blanks the fields it does not mention.
--
-- ── THE BUG ─────────────────────────────────────────────────────────────────
-- Every branch of `update_record` except `transactions` assigned each column
-- with a bare `nullif(p_data->>'field','')`. An absent key therefore evaluated
-- to NULL and WROTE it. So this:
--
--     update_record(privy, 'invoices', id, '{"organization_id":"…"}')
--
-- linked the invoice to a company and, in the same statement, erased its
-- number, category, dates and notes. Reproduced on a real database: INV-1
-- became an invoice with no number, and a person updated the same way lost
-- their first name and email.
--
-- ── WHY IT SURVIVED THIS LONG ───────────────────────────────────────────────
-- The record form always posts every field, so the UI never triggered it. What
-- does trigger it is anything that updates a SUBSET, and the product has been
-- growing those: the agent `update_record` tool (whose description invites a
-- model to send only what changed), the REST API, Excel sync, and the demo
-- seeder that found this. An agent tidying one field would silently destroy the
-- rest of the row.
--
-- ── THE RULE, NOW UNIFORM ───────────────────────────────────────────────────
--   key absent   → leave the column exactly as it is
--   key present  → write it, including writing NULL to clear it
--
-- `p_data ? 'field'` is the test. It is not a new idea here: the `transactions`
-- branch has always done exactly this, and 0087's custom-object branch and
-- `save_workspace_branding` both follow the same rule. This makes the other
-- nine branches agree with them.
--
-- NOT-NULL columns keep a `coalesce(…, existing)` INSIDE the present-branch, so
-- sending `""` for a name is still "no change" rather than a constraint
-- violation — that is the pre-existing behaviour and forms rely on it.
--
-- Also: `assets` had NO create or update branch at all, while appearing in
-- list_records, in delete_record's table map, and in the nav with its own page.
-- The Add button on Team → Assets raised UNKNOWN_OBJECT. Both branches are
-- added here, which is why create_record is redefined in full below too.
--
-- Also adds two relation columns that were simply missing from the update path,
-- so they could be set at creation and never afterwards:
--   people.primary_company_id, issues.project_id, assets.assigned_to_person_id
--
-- Redefines `update_record` IN FULL per the convention. Depends on 0087.
-- Idempotent & prod-safe.
-- ============================================================================

create or replace function update_record(p_privy text, p_object text, p_id uuid, p_data jsonb)
returns void language plpgsql security definer set search_path = public as $$
declare v_id uuid; v_obj uuid; v_existing jsonb; my uuid[] := (select array_agg(workspace_id) from accounts where privy_user_id = p_privy);
begin
  if p_object in ('companies','organizations') then
    update organizations set
      name           = case when p_data ? 'name' then coalesce(nullif(p_data->>'name',''), name) else name end,
      domain         = case when p_data ? 'domain' then nullif(p_data->>'domain','') else domain end,
      industry       = case when p_data ? 'industry' then nullif(p_data->>'industry','') else industry end,
      employee_count = case when p_data ? 'employee_count' then nullif(p_data->>'employee_count','')::int else employee_count end,
      tax_id         = case when p_data ? 'tax_id' then nullif(p_data->>'tax_id','') else tax_id end,
      address        = case when p_data ? 'address' then nullif(p_data->>'address','') else address end,
      country        = case when p_data ? 'country' then nullif(p_data->>'country','') else country end
    where id=p_id and workspace_id = any(my);

  elsif p_object = 'people' then
    update people set
      first_name = case when p_data ? 'first_name' then nullif(p_data->>'first_name','') else first_name end,
      last_name  = case when p_data ? 'last_name' then nullif(p_data->>'last_name','') else last_name end,
      email      = case when p_data ? 'email' then nullif(p_data->>'email','') else email end,
      phone      = case when p_data ? 'phone' then nullif(p_data->>'phone','') else phone end,
      title      = case when p_data ? 'title' then nullif(p_data->>'title','') else title end,
      source     = case when p_data ? 'source' then nullif(p_data->>'source','') else source end,
      -- New here: a person could be attached to a company at creation and never
      -- moved afterwards, because this column was absent from the update path.
      primary_company_id = case when p_data ? 'primary_company_id'
                                then nullif(p_data->>'primary_company_id','')::uuid
                                else primary_company_id end
    where id=p_id and workspace_id = any(my);

  elsif p_object = 'invoices' then
    update invoices set
      number          = case when p_data ? 'number' then nullif(p_data->>'number','') else number end,
      organization_id = case when p_data ? 'organization_id' then nullif(p_data->>'organization_id','')::uuid else organization_id end,
      kind            = case when p_data ? 'kind' then coalesce(nullif(p_data->>'kind',''), kind) else kind end,
      direction       = case when p_data ? 'direction' then coalesce(nullif(p_data->>'direction',''), direction) else direction end,
      amount          = case when p_data ? 'amount' then coalesce(nullif(p_data->>'amount','')::numeric, amount) else amount end,
      status          = case when p_data ? 'status' then coalesce(nullif(p_data->>'status',''), status) else status end,
      category        = case when p_data ? 'category' then nullif(p_data->>'category','') else category end,
      issued_at       = case when p_data ? 'issued_at' then nullif(p_data->>'issued_at','')::date else issued_at end,
      due_at          = case when p_data ? 'due_at' then nullif(p_data->>'due_at','')::date else due_at end,
      notes           = case when p_data ? 'notes' then nullif(p_data->>'notes','') else notes end
    where id=p_id and workspace_id = any(my);

  elsif p_object = 'expenses' then
    update expenses set
      vendor   = case when p_data ? 'vendor' then nullif(p_data->>'vendor','') else vendor end,
      category = case when p_data ? 'category' then coalesce(nullif(p_data->>'category',''), category) else category end,
      amount   = case when p_data ? 'amount' then coalesce(nullif(p_data->>'amount','')::numeric, amount) else amount end,
      status   = case when p_data ? 'status' then coalesce(nullif(p_data->>'status',''), status) else status end,
      spent_at = case when p_data ? 'spent_at' then nullif(p_data->>'spent_at','')::date else spent_at end,
      notes    = case when p_data ? 'notes' then nullif(p_data->>'notes','') else notes end
    where id=p_id and workspace_id = any(my);

  elsif p_object = 'transactions' then
    -- Unchanged. This branch was already correct, and is what the rest of the
    -- function has now been made to match.
    update transactions set
      bank_account_id = case when p_data ? 'bank_account_id' then nullif(p_data->>'bank_account_id','')::uuid else bank_account_id end,
      txn_date = coalesce(nullif(p_data->>'txn_date','')::date, txn_date),
      description = case when p_data ? 'description' then nullif(p_data->>'description','') else description end,
      amount = coalesce(nullif(regexp_replace(coalesce(p_data->>'amount',''), '[^0-9.-]', '', 'g'),'')::numeric, amount),
      category = case when p_data ? 'category' then nullif(p_data->>'category','') else category end,
      method = coalesce(nullif(p_data->>'method',''), method),
      status = coalesce(nullif(p_data->>'status',''), status),
      tax_rate = case when p_data ? 'tax_rate' then nullif(p_data->>'tax_rate','')::numeric else tax_rate end,
      notes = case when p_data ? 'notes' then nullif(p_data->>'notes','') else notes end
    where id=p_id and workspace_id = any(my);

  elsif p_object = 'products' then
    update products set
      name        = case when p_data ? 'name' then coalesce(nullif(p_data->>'name',''), name) else name end,
      sku         = case when p_data ? 'sku' then nullif(p_data->>'sku','') else sku end,
      description = case when p_data ? 'description' then nullif(p_data->>'description','') else description end,
      unit_price  = case when p_data ? 'unit_price' then coalesce(nullif(p_data->>'unit_price','')::numeric, unit_price) else unit_price end,
      unit        = case when p_data ? 'unit' then nullif(p_data->>'unit','') else unit end,
      category    = case when p_data ? 'category' then nullif(p_data->>'category','') else category end,
      image_url   = case when p_data ? 'image_url' then nullif(p_data->>'image_url','') else image_url end
    where id=p_id and workspace_id = any(my);

  elsif p_object = 'campaigns' then
    update campaigns set
      name      = case when p_data ? 'name' then coalesce(nullif(p_data->>'name',''), name) else name end,
      channel   = case when p_data ? 'channel' then coalesce(nullif(p_data->>'channel',''), channel) else channel end,
      status    = case when p_data ? 'status' then coalesce(nullif(p_data->>'status',''), status) else status end,
      budget    = case when p_data ? 'budget' then coalesce(nullif(p_data->>'budget','')::numeric, budget) else budget end,
      spend     = case when p_data ? 'spend' then coalesce(nullif(p_data->>'spend','')::numeric, spend) else spend end,
      leads     = case when p_data ? 'leads' then coalesce(nullif(p_data->>'leads','')::int, leads) else leads end,
      starts_on = case when p_data ? 'starts_on' then nullif(p_data->>'starts_on','')::date else starts_on end,
      ends_on   = case when p_data ? 'ends_on' then nullif(p_data->>'ends_on','')::date else ends_on end,
      notes     = case when p_data ? 'notes' then nullif(p_data->>'notes','') else notes end
    where id=p_id and workspace_id = any(my);

  elsif p_object = 'projects' then
    update projects set
      name        = case when p_data ? 'name' then coalesce(nullif(p_data->>'name',''), name) else name end,
      identifier  = case when p_data ? 'identifier' then nullif(p_data->>'identifier','') else identifier end,
      status      = case when p_data ? 'status' then coalesce(nullif(p_data->>'status',''), status) else status end,
      description = case when p_data ? 'description' then nullif(p_data->>'description','') else description end
    where id=p_id and workspace_id = any(my);

  elsif p_object = 'issues' then
    update issues set
      title       = case when p_data ? 'title' then coalesce(nullif(p_data->>'title',''), title) else title end,
      status      = case when p_data ? 'status' then coalesce(nullif(p_data->>'status',''), status) else status end,
      priority    = case when p_data ? 'priority' then coalesce(nullif(p_data->>'priority',''), priority) else priority end,
      due_date    = case when p_data ? 'due_date' then nullif(p_data->>'due_date','')::date else due_date end,
      description = case when p_data ? 'description' then nullif(p_data->>'description','') else description end,
      -- New here, same reason as people.primary_company_id.
      project_id  = case when p_data ? 'project_id' then nullif(p_data->>'project_id','')::uuid else project_id end
    where id=p_id and workspace_id = any(my);

  elsif p_object = 'assets' then
    -- Entirely new: `assets` had no update branch at all, so it fell through to
    -- the UNKNOWN_OBJECT error and an asset could never be edited.
    update assets set
      name          = case when p_data ? 'name' then coalesce(nullif(p_data->>'name',''), name) else name end,
      category      = case when p_data ? 'category' then nullif(p_data->>'category','') else category end,
      serial_number = case when p_data ? 'serial_number' then nullif(p_data->>'serial_number','') else serial_number end,
      status        = case when p_data ? 'status' then coalesce(nullif(p_data->>'status',''), status) else status end,
      notes         = case when p_data ? 'notes' then nullif(p_data->>'notes','') else notes end,
      assigned_to_person_id = case when p_data ? 'assigned_to_person_id'
                                   then nullif(p_data->>'assigned_to_person_id','')::uuid
                                   else assigned_to_person_id end
    where id=p_id and workspace_id = any(my);

  else
    -- ── Custom objects (0087) ────────────────────────────────────────────────
    select r.id, r.object_id, r.data into v_id, v_obj, v_existing
      from custom_records r join custom_objects o on o.id = r.object_id
     where r.id = p_id and o.slug = p_object and r.workspace_id = any(my);
    if v_id is null then raise exception 'UNKNOWN_OBJECT: %', p_object; end if;
    update custom_records set data = build_custom_data(v_obj, coalesce(p_data, '{}'::jsonb), v_existing)
     where id = v_id;
  end if;
end $$;
grant execute on function update_record(text, text, uuid, jsonb) to authenticated, anon;

-- ── create_record, redefined in full to add the missing `assets` branch ────
create or replace function create_record(p_privy text, p_workspace uuid, p_object text, p_data jsonb)
returns uuid language plpgsql security definer set search_path = public as $$
declare v_obj uuid; v_id uuid;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  if p_object in ('companies','organizations') then
    insert into organizations (workspace_id, name, domain, industry, employee_count, tax_id, address, country)
    values (p_workspace, p_data->>'name', nullif(p_data->>'domain',''), nullif(p_data->>'industry',''), nullif(p_data->>'employee_count','')::int,
            nullif(p_data->>'tax_id',''), nullif(p_data->>'address',''), nullif(p_data->>'country',''))
    returning id into v_id;
  elsif p_object = 'people' then
    insert into people (workspace_id, first_name, last_name, email, phone, title, source)
    values (p_workspace, p_data->>'first_name', nullif(p_data->>'last_name',''), nullif(p_data->>'email',''), nullif(p_data->>'phone',''), nullif(p_data->>'title',''), nullif(p_data->>'source',''))
    returning id into v_id;
  elsif p_object = 'invoices' then
    insert into invoices (workspace_id, number, organization_id, kind, direction, amount, status, category, issued_at, due_at, notes)
    values (p_workspace, nullif(p_data->>'number',''), nullif(p_data->>'organization_id','')::uuid, coalesce(nullif(p_data->>'kind',''),'invoice'), coalesce(nullif(p_data->>'direction',''),'income'),
            coalesce(nullif(p_data->>'amount','')::numeric,0), coalesce(nullif(p_data->>'status',''),'draft'), nullif(p_data->>'category',''),
            nullif(p_data->>'issued_at','')::date, nullif(p_data->>'due_at','')::date, nullif(p_data->>'notes',''))
    returning id into v_id;
  elsif p_object = 'expenses' then
    insert into expenses (workspace_id, vendor, category, amount, status, spent_at, notes)
    values (p_workspace, nullif(p_data->>'vendor',''), coalesce(nullif(p_data->>'category',''),'other'), coalesce(nullif(p_data->>'amount','')::numeric,0), coalesce(nullif(p_data->>'status',''),'pending'), nullif(p_data->>'spent_at','')::date, nullif(p_data->>'notes',''))
    returning id into v_id;
  elsif p_object = 'transactions' then
    insert into transactions (workspace_id, bank_account_id, txn_date, description, amount, currency, category, method, status, tax_rate, tags, notes)
    values (p_workspace, nullif(p_data->>'bank_account_id','')::uuid,
            coalesce(nullif(p_data->>'txn_date','')::date, now()::date), nullif(p_data->>'description',''),
            coalesce(nullif(regexp_replace(coalesce(p_data->>'amount',''), '[^0-9.-]', '', 'g'),'')::numeric, 0),
            coalesce(nullif(p_data->>'currency',''),'USD'), nullif(p_data->>'category',''),
            coalesce(nullif(p_data->>'method',''),'transfer'), coalesce(nullif(p_data->>'status',''),'posted'),
            nullif(p_data->>'tax_rate','')::numeric,
            case when nullif(p_data->>'tags','') is not null then string_to_array(p_data->>'tags', ',') else '{}'::text[] end,
            nullif(p_data->>'notes',''))
    returning id into v_id;
  elsif p_object = 'products' then
    insert into products (workspace_id, name, sku, description, unit_price, unit, category, image_url)
    values (p_workspace, p_data->>'name', nullif(p_data->>'sku',''), nullif(p_data->>'description',''), coalesce(nullif(p_data->>'unit_price','')::numeric,0), nullif(p_data->>'unit',''), nullif(p_data->>'category',''), nullif(p_data->>'image_url',''))
    returning id into v_id;
  elsif p_object = 'campaigns' then
    insert into campaigns (workspace_id, name, channel, status, budget, spend, leads, starts_on, ends_on, notes)
    values (p_workspace, p_data->>'name', coalesce(nullif(p_data->>'channel',''),'email'), coalesce(nullif(p_data->>'status',''),'planned'),
            coalesce(nullif(p_data->>'budget','')::numeric,0), coalesce(nullif(p_data->>'spend','')::numeric,0), coalesce(nullif(p_data->>'leads','')::int,0),
            nullif(p_data->>'starts_on','')::date, nullif(p_data->>'ends_on','')::date, nullif(p_data->>'notes',''))
    returning id into v_id;
  elsif p_object = 'projects' then
    insert into projects (workspace_id, name, identifier, status, description)
    values (p_workspace, p_data->>'name', nullif(p_data->>'identifier',''), coalesce(nullif(p_data->>'status',''),'active'), nullif(p_data->>'description',''))
    returning id into v_id;
  elsif p_object = 'issues' then
    insert into issues (workspace_id, title, status, priority, due_date, description)
    values (p_workspace, p_data->>'title', coalesce(nullif(p_data->>'status',''),'backlog'), coalesce(nullif(p_data->>'priority',''),'none'), nullif(p_data->>'due_date','')::date, nullif(p_data->>'description',''))
    returning id into v_id;
  elsif p_object = 'assets' then
    -- Entirely new. `assets` appears in list_records and in delete_record's
    -- table map, and it has a nav entry and a page — but it had no create or
    -- update branch, so the Add button on Team → Assets raised UNKNOWN_OBJECT.
    -- The object was readable and deletable and nothing else.
    insert into assets (workspace_id, name, category, serial_number, status, notes, assigned_to_person_id)
    values (p_workspace, coalesce(nullif(p_data->>'name',''),'Untitled'), nullif(p_data->>'category',''),
            nullif(p_data->>'serial_number',''), coalesce(nullif(p_data->>'status',''),'available'),
            nullif(p_data->>'notes',''), nullif(p_data->>'assigned_to_person_id','')::uuid)
    returning id into v_id;
  else
    -- ── Custom objects (0087) ────────────────────────────────────────────────
    v_obj := (select id from custom_objects
               where workspace_id = p_workspace and slug = p_object and enabled);
    if v_obj is null then raise exception 'UNKNOWN_OBJECT: %', p_object; end if;
    -- build_custom_data validates every value against its field and drops
    -- anything undeclared, so a payload cannot widen the row's shape.
    insert into custom_records (workspace_id, object_id, data, created_by_privy)
    values (p_workspace, v_obj, build_custom_data(v_obj, coalesce(p_data, '{}'::jsonb)), p_privy)
    returning id into v_id;
  end if;
  return v_id;
end $$;

grant execute on function create_record(text, uuid, text, jsonb) to authenticated, anon;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0089_relation_labels.sql
-- ══════════════════════════════════════════════════════════════════════════
-- 0089 — a link shows the thing it points at, not its uuid.
--
-- A custom object's relation field stores a uuid in `data`, and list_records
-- returned that uuid untouched. Every built-in resolves its links in SQL — an
-- invoice row carries the company NAME, an issue carries its project's — so a
-- Work order sitting next to them showed `fd6b33e9-c2e0-…` under Customer.
-- Custom objects are supposed to be first-class; a column of uuids is the most
-- visible possible way for them not to be.
--
-- WHY IN SQL AND NOT IN THE CLIENT. The table is not the only consumer. The
-- CSV feed, the Excel sync, `/api/mcp` and the agent tools all read these same
-- two functions, and an agent that reads "customer: fd6b33e9" cannot say who
-- the customer is. Resolving it once here fixes every one of them; resolving it
-- in RecordTable would fix the screen and leave the rest wrong.
--
-- The label is added under `<key>_label` and the raw uuid is KEPT, because the
-- form needs the id to edit the link and the label is for reading. Nothing is
-- renamed, so every existing consumer is unaffected.
--
-- Per the convention, list_records and get_record are redefined IN FULL rather
-- than shadowed by a parallel function. Only the custom branches changed.

-- ── The label of one linked record ──────────────────────────────────────────
-- A whitelist CASE, never dynamic SQL — same reasoning as segment_match: a
-- SECURITY DEFINER path that builds EXECUTE from a stored `relation_to` string
-- is one escaping mistake from arbitrary SQL across every tenant.
--
-- An unknown target returns NULL rather than raising, and NULL means "no label"
-- — the reader falls back to showing the raw value, which is exactly today's
-- behaviour. Failing closed here would blank a link that does exist.
--
-- The HR tables (candidates, positions) are deliberately absent: they are
-- tenanted by company_id through a different resolver, and quietly reading them
-- with a workspace id would be a tenancy claim this function cannot check.
create or replace function custom_relation_label(p_workspace uuid, p_target text, p_id uuid)
returns text language sql stable security definer set search_path = public as $$
  select case p_target
    when 'companies' then (select o.name from organizations o where o.id = p_id and o.workspace_id = p_workspace)
    when 'organizations' then (select o.name from organizations o where o.id = p_id and o.workspace_id = p_workspace)
    when 'people' then (select nullif(trim(coalesce(pe.first_name,'') || ' ' || coalesce(pe.last_name,'')), '')
                          from people pe where pe.id = p_id and pe.workspace_id = p_workspace)
    when 'invoices' then (select i.number from invoices i where i.id = p_id and i.workspace_id = p_workspace)
    when 'offers' then (select i.number from invoices i where i.id = p_id and i.workspace_id = p_workspace)
    when 'expenses' then (select e.vendor from expenses e where e.id = p_id and e.workspace_id = p_workspace)
    when 'transactions' then (select t.description from transactions t where t.id = p_id and t.workspace_id = p_workspace)
    when 'products' then (select pr.name from products pr where pr.id = p_id and pr.workspace_id = p_workspace)
    when 'campaigns' then (select c.name from campaigns c where c.id = p_id and c.workspace_id = p_workspace)
    when 'projects' then (select p.name from projects p where p.id = p_id and p.workspace_id = p_workspace)
    when 'issues' then (select i.title from issues i where i.id = p_id and i.workspace_id = p_workspace)
    when 'assets' then (select a.name from assets a where a.id = p_id and a.workspace_id = p_workspace)
    -- Another custom object, in the same workspace. Its own primary field is
    -- what it is called, so this is the same rule the object itself uses.
    else (select custom_record_label(r.object_id, r.data)
            from custom_records r
            join custom_objects o on o.id = r.object_id
           where r.id = p_id and o.workspace_id = p_workspace and o.slug = p_target)
  end;
$$;
grant execute on function custom_relation_label(uuid, text, uuid) to authenticated, anon;

-- ── Every link on one row ───────────────────────────────────────────────────
create or replace function custom_relation_labels(p_workspace uuid, p_object uuid, p_data jsonb)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare v_out jsonb := '{}'::jsonb; f record; v_id uuid; v_label text;
begin
  for f in select key, relation_to from custom_fields
            where object_id = p_object and type = 'relation'
              and coalesce(relation_to, '') <> ''
  loop
    -- A stored value that is not a uuid is not a broken link, it is not a link
    -- at all: coerce_custom_value only accepts uuids, but data written before a
    -- field's type changed can be anything. Casting without this raises and
    -- takes the whole list down.
    begin
      v_id := nullif(p_data ->> f.key, '')::uuid;
    exception when others then v_id := null;
    end;
    if v_id is null then continue; end if;

    v_label := custom_relation_label(p_workspace, f.relation_to, v_id);
    if v_label is not null then
      v_out := v_out || jsonb_build_object(f.key || '_label', v_label);
    end if;
  end loop;
  return v_out;
end $$;
grant execute on function custom_relation_labels(uuid, uuid, jsonb) to authenticated, anon;

-- ── The CRUD monolith, redefined in full ────────────────────────────────────
create or replace function list_records(p_privy text, p_workspace uuid, p_object text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_obj uuid;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;

  if p_object = 'people' then
    return coalesce((select jsonb_agg(jsonb_build_object(
      'id', pe.id, 'name', trim(coalesce(pe.first_name,'')||' '||coalesce(pe.last_name,'')),
      'title', pe.title, 'company', co.name, 'email', pe.email, 'source', pe.source,
      'synergy', (select ps.overall from psychometrics ps where ps.person_id=pe.id order by ps.assessed_at desc limit 1)
    ) order by pe.created_at desc)
    from people pe left join organizations co on co.id = pe.primary_company_id
    where pe.workspace_id=p_workspace), '[]'::jsonb);

  elsif p_object in ('companies','organizations') then
    return coalesce((select jsonb_agg(jsonb_build_object(
      'id', o.id, 'name', o.name, 'domain', o.domain, 'industry', o.industry, 'employee_count', o.employee_count,
      'tax_id', o.tax_id, 'address', o.address, 'country', o.country
    ) order by o.created_at desc) from organizations o where o.workspace_id=p_workspace), '[]'::jsonb);

  elsif p_object = 'invoices' then
    return coalesce((select jsonb_agg(jsonb_build_object(
      'id', i.id, 'number', i.number, 'company', o.name, 'kind', i.kind, 'direction', i.direction,
      'category', i.category, 'amount', i.amount, 'status', i.status, 'due_at', i.due_at
    ) order by i.created_at desc)
    from invoices i left join organizations o on o.id = i.organization_id
    where i.workspace_id=p_workspace), '[]'::jsonb);

  elsif p_object = 'expenses' then
    return coalesce((select jsonb_agg(jsonb_build_object(
      'id', e.id, 'vendor', e.vendor, 'category', e.category, 'amount', e.amount, 'status', e.status, 'spent_at', e.spent_at
    ) order by e.created_at desc) from expenses e where e.workspace_id=p_workspace), '[]'::jsonb);

  elsif p_object = 'transactions' then
    return coalesce((select jsonb_agg(jsonb_build_object(
      'id', t.id, 'txn_date', t.txn_date, 'description', t.description, 'amount', t.amount, 'currency', t.currency,
      'category', t.category, 'method', t.method, 'status', t.status, 'tax_rate', t.tax_rate,
      'account', ba.name, 'bank_account_id', t.bank_account_id,
      'matched_invoice_id', t.matched_invoice_id, 'matched_expense_id', t.matched_expense_id
    ) order by t.txn_date desc, t.created_at desc)
    from transactions t left join bank_accounts ba on ba.id = t.bank_account_id
    where t.workspace_id=p_workspace), '[]'::jsonb);

  elsif p_object = 'products' then
    return coalesce((select jsonb_agg(jsonb_build_object(
      'id', p.id, 'name', p.name, 'image', p.image_url, 'sku', p.sku, 'category', p.category, 'unit_price', p.unit_price, 'unit', p.unit
    ) order by p.created_at desc) from products p where p.workspace_id=p_workspace), '[]'::jsonb);

  elsif p_object = 'campaigns' then
    return coalesce((select jsonb_agg(jsonb_build_object(
      'id', c.id, 'name', c.name, 'channel', c.channel, 'status', c.status,
      'budget', c.budget, 'spend', c.spend, 'leads', c.leads, 'starts_on', c.starts_on, 'ends_on', c.ends_on
    ) order by c.created_at desc) from campaigns c where c.workspace_id=p_workspace), '[]'::jsonb);

  elsif p_object = 'projects' then
    return coalesce((select jsonb_agg(jsonb_build_object(
      'id', pr.id, 'name', pr.name, 'identifier', pr.identifier, 'status', pr.status,
      'issues', (select count(*) from issues i where i.project_id = pr.id)
    ) order by pr.created_at desc) from projects pr where pr.workspace_id=p_workspace), '[]'::jsonb);

  elsif p_object = 'issues' then
    return coalesce((select jsonb_agg(jsonb_build_object(
      'id', i.id, 'name', i.title, 'project', pr.name, 'status', i.status,
      'priority', i.priority, 'due_date', i.due_date,
      'assignee', (select a.full_name from accounts a where a.id = i.assignee_account_id)
    ) order by i.sort_order)
    from issues i left join projects pr on pr.id = i.project_id
    where i.workspace_id=p_workspace), '[]'::jsonb);

  elsif p_object = 'assets' then
    return coalesce((select jsonb_agg(jsonb_build_object(
      'id', a.id, 'name', a.name, 'category', a.category, 'serial_number', a.serial_number, 'status', a.status,
      'assigned_to', (select trim(coalesce(pe.first_name,'')||' '||coalesce(pe.last_name,'')) from people pe where pe.id=a.assigned_to_person_id)
    ) order by a.created_at desc) from assets a where a.workspace_id=p_workspace), '[]'::jsonb);
  end if;

  -- ── Custom objects (0087) ──────────────────────────────────────────────────
  -- LAST, after every built-in has matched. That ordering is the safety
  -- property: a custom object can never shadow a built-in one, whatever it is
  -- called. reserved_object_slug refuses the name at creation too, so the
  -- collision is impossible rather than merely lost.
  v_obj := (select id from custom_objects
             where workspace_id = p_workspace and slug = p_object and enabled);
  if v_obj is not null then
    return coalesce((select jsonb_agg(
      -- id and name are spliced on top of the row's own data, so a custom
      -- object presents the same shape as a built-in one and every consumer
      -- (the table, the CSV feed, the agent tools) works unchanged.
      -- Links resolved to names (0089), then id and name spliced on top, so a
      -- custom object presents the same shape as a built-in one and every
      -- consumer (the table, the CSV feed, the agent tools) works unchanged.
      r.data
        || custom_relation_labels(p_workspace, v_obj, r.data)
        || jsonb_build_object('id', r.id, 'name', custom_record_label(v_obj, r.data))
      order by r.created_at desc
    ) from custom_records r where r.object_id = v_obj), '[]'::jsonb);
  end if;

  return '[]'::jsonb;
end $$;
grant execute on function list_records(text, uuid, text) to authenticated, anon;

create or replace function get_record(p_privy text, p_object text, p_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare my uuid[] := (select array_agg(workspace_id) from accounts where privy_user_id = p_privy);
begin
  if p_object in ('companies','organizations') then
    return (select to_jsonb(t) from (select id, name, domain, industry, employee_count, tax_id, address, country from organizations where id=p_id and workspace_id = any(my)) t);
  elsif p_object = 'people' then
    return (select to_jsonb(t) from (select id, first_name, last_name, email, phone, title, source from people where id=p_id and workspace_id = any(my)) t);
  elsif p_object = 'invoices' then
    return (select to_jsonb(t) from (select id, number, organization_id, kind, direction, amount, status, category, issued_at, due_at, notes from invoices where id=p_id and workspace_id = any(my)) t);
  elsif p_object = 'expenses' then
    return (select to_jsonb(t) from (select id, vendor, category, amount, status, spent_at, notes from expenses where id=p_id and workspace_id = any(my)) t);
  elsif p_object = 'transactions' then
    return (select to_jsonb(t) from (select id, txn_date, description, amount, currency, category, method, status, tax_rate, bank_account_id, notes from transactions where id=p_id and workspace_id = any(my)) t);
  elsif p_object = 'products' then
    return (select to_jsonb(t) from (select id, name, sku, description, unit_price, unit, category, image_url from products where id=p_id and workspace_id = any(my)) t);
  elsif p_object = 'campaigns' then
    return (select to_jsonb(t) from (select id, name, channel, status, budget, spend, leads, starts_on, ends_on, notes from campaigns where id=p_id and workspace_id = any(my)) t);
  elsif p_object = 'projects' then
    return (select to_jsonb(t) from (select id, name, identifier, status, description from projects where id=p_id and workspace_id = any(my)) t);
  elsif p_object = 'issues' then
    return (select to_jsonb(t) from (select id, title, status, priority, due_date, description from issues where id=p_id and workspace_id = any(my)) t);
  end if;

  -- ── Custom objects (0087) ──────────────────────────────────────────────────
  -- Tenancy comes from `my` in SQL, exactly like every branch above: a foreign
  -- record id resolves to no row rather than to someone else's data.
  return (select r.data
                   || custom_relation_labels(o.workspace_id, r.object_id, r.data)
                   || jsonb_build_object('id', r.id,
                        'name', custom_record_label(r.object_id, r.data))
            from custom_records r
            join custom_objects o on o.id = r.object_id
           where r.id = p_id and o.slug = p_object and r.workspace_id = any(my));
end $$;
grant execute on function get_record(text, text, uuid) to authenticated, anon;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0090_plan_sync_and_names.sql
-- ══════════════════════════════════════════════════════════════════════════
-- 0090 — a paid plan reaches the product it was bought for.
--
-- Two defects on the billing path, both invisible until money changes hands.
--
-- 1. THE PLAN NEVER REACHED THE NEW PLATFORM. The Stripe webhook updates
--    `companies.plan`. The CRM reads `workspaces.plan` (get_my_workspace, 0051).
--    The only thing that ever copied one to the other was 0005's trigger, and it
--    fires AFTER INSERT ONLY — it seeds a workspace when a company is created and
--    never looks again. So a customer paid, the ATS half saw the upgrade, and
--    every screen in Sales, Finance, Marketing and Projects stayed on Free. That
--    reads as "I paid and nothing happened", which is the worst bug a billing
--    system can have.
--
-- 2. THE DATABASE DID NOT KNOW THE CURRENT PLAN NAMES. `companies_plan_check`
--    still allowed only ('free','starter','professional','enterprise') from the
--    ATS era, while the product sells free/team/business/enterprise. Setting a
--    plan to 'business' — the documented way to test one, and the obvious thing
--    for an admin to type — was rejected outright.
--
-- The legacy names stay ALLOWED rather than being removed. `normalizePlan()` in
-- lib/plans.ts maps starter→team and professional→business, so old rows are read
-- correctly today; a constraint that rejected them would turn a historical value
-- into an error the next time anything touched that row. They are converted
-- here, and still permitted afterwards, because a rejection is not worth it.

-- ── 1. The names the database accepts ───────────────────────────────────────
alter table companies drop constraint if exists companies_plan_check;
alter table companies add constraint companies_plan_check
  check (plan in ('free', 'team', 'business', 'enterprise',
                  -- pre-pivot values, kept valid so no old row becomes unwritable
                  'starter', 'professional', 'pro'));

-- workspaces.plan has never had a constraint. It is deliberately left without
-- one: it is a copy of the companies value, and a second place to enforce the
-- same rule is a second place for the two to disagree.

-- ── 2. Convert what is already stored ───────────────────────────────────────
update companies  set plan = 'team'     where plan = 'starter';
update companies  set plan = 'business' where plan in ('professional', 'pro');
update workspaces set plan = 'team'     where plan = 'starter';
update workspaces set plan = 'business' where plan in ('professional', 'pro');

-- ── 3. Keep the workspace's plan following the company's ────────────────────
-- Exception-safe like every other sync trigger here: a failure to mirror a plan
-- must never roll back the write that recorded a payment.
create or replace function sync_company_plan_to_workspace()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  begin
    if new.plan is distinct from old.plan then
      update workspaces
         set plan = case
                      when new.plan = 'starter' then 'team'
                      when new.plan in ('professional', 'pro') then 'business'
                      else coalesce(new.plan, 'free')
                    end,
             updated_at = now()
       where id = new.id;
    end if;
  exception when others then
    null;  -- best-effort; never block a billing update
  end;
  return new;
end $$;

drop trigger if exists trg_company_plan_to_workspace on companies;
create trigger trg_company_plan_to_workspace after update of plan on companies
  for each row execute function sync_company_plan_to_workspace();

-- ── 4. Repair anything that already drifted ─────────────────────────────────
-- Every workspace whose company was upgraded before this migration existed —
-- i.e. every customer who has ever paid.
update workspaces w
   set plan = case
                when c.plan = 'starter' then 'team'
                when c.plan in ('professional', 'pro') then 'business'
                else coalesce(c.plan, 'free')
              end,
       updated_at = now()
  from companies c
 where c.id = w.id
   and w.plan is distinct from case
                                 when c.plan = 'starter' then 'team'
                                 when c.plan in ('professional', 'pro') then 'business'
                                 else coalesce(c.plan, 'free')
                               end;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0091_get_record_assets.sql
-- ══════════════════════════════════════════════════════════════════════════
-- 0091 — opening an asset shows the asset.
--
-- The fifth function. 0088 gave `assets` its missing create and update branches
-- after the Add button raised UNKNOWN_OBJECT; `get_record` was the one nobody
-- checked, so clicking an asset row called it, fell through every branch to the
-- custom-object lookup, found no custom object called `assets`, and returned
-- NULL. The list showed the row, the detail panel showed nothing.
--
-- Found by asking the database rather than the code: for every object in the
-- nav registry, does a branch for it exist in ALL FIVE CRUD functions? That
-- check is worth re-running whenever an object is added — it is the third time
-- this exact shape of bug has surfaced.
--
-- Redefined in full, per the convention.

create or replace function get_record(p_privy text, p_object text, p_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare my uuid[] := (select array_agg(workspace_id) from accounts where privy_user_id = p_privy);
begin
  if p_object in ('companies','organizations') then
    return (select to_jsonb(t) from (select id, name, domain, industry, employee_count, tax_id, address, country from organizations where id=p_id and workspace_id = any(my)) t);
  elsif p_object = 'people' then
    return (select to_jsonb(t) from (select id, first_name, last_name, email, phone, title, source from people where id=p_id and workspace_id = any(my)) t);
  elsif p_object = 'invoices' then
    return (select to_jsonb(t) from (select id, number, organization_id, kind, direction, amount, status, category, issued_at, due_at, notes from invoices where id=p_id and workspace_id = any(my)) t);
  elsif p_object = 'expenses' then
    return (select to_jsonb(t) from (select id, vendor, category, amount, status, spent_at, notes from expenses where id=p_id and workspace_id = any(my)) t);
  elsif p_object = 'transactions' then
    return (select to_jsonb(t) from (select id, txn_date, description, amount, currency, category, method, status, tax_rate, bank_account_id, notes from transactions where id=p_id and workspace_id = any(my)) t);
  elsif p_object = 'products' then
    return (select to_jsonb(t) from (select id, name, sku, description, unit_price, unit, category, image_url from products where id=p_id and workspace_id = any(my)) t);
  elsif p_object = 'campaigns' then
    return (select to_jsonb(t) from (select id, name, channel, status, budget, spend, leads, starts_on, ends_on, notes from campaigns where id=p_id and workspace_id = any(my)) t);
  elsif p_object = 'projects' then
    return (select to_jsonb(t) from (select id, name, identifier, status, description from projects where id=p_id and workspace_id = any(my)) t);
  elsif p_object = 'issues' then
    return (select to_jsonb(t) from (select id, title, status, priority, due_date, description from issues where id=p_id and workspace_id = any(my)) t);
  elsif p_object = 'assets' then
    return (select to_jsonb(t) from (select id, name, category, serial_number, status, assigned_to_person_id, purchased_at, notes from assets where id=p_id and workspace_id = any(my)) t);
  end if;

  -- ── Custom objects (0087) ──────────────────────────────────────────────────
  -- Tenancy comes from `my` in SQL, exactly like every branch above: a foreign
  -- record id resolves to no row rather than to someone else's data.
  return (select r.data
                   || custom_relation_labels(o.workspace_id, r.object_id, r.data)
                   || jsonb_build_object('id', r.id,
                        'name', custom_record_label(r.object_id, r.data))
            from custom_records r
            join custom_objects o on o.id = r.object_id
           where r.id = p_id and o.slug = p_object and r.workspace_id = any(my));
end $$;
grant execute on function get_record(text, text, uuid) to authenticated, anon;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0092_pipeline_records_crud.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0092_pipeline_records_crud.sql
-- Deals you can actually create, and a board that knows which company they are for.
--
-- WHAT WAS WRONG. `pipeline_records` has existed since 0001 and there has never
-- been a way to put a row in it. `seed_default_pipelines` created the stages,
-- `get_pipeline_board` read them, `move_pipeline_record` moved cards between
-- them — and nothing anywhere, in SQL or in the app, ever inserted one. The
-- Sales → Deals screen is the flagship CRM surface and it was structurally
-- incapable of holding a deal: every workspace saw four empty columns and the
-- sample-data button did not help, because it only writes through
-- `create_record` and pipeline records are not a CRUD object.
--
-- TWO SMALLER THINGS FIXED HERE.
--
-- 1. `get_pipeline_board` returned `'company', null` with the comment "CRM
--    organizations join added with the Sales module". 0004 shipped the Sales
--    module and the join was never added, so a deal attached to a company
--    rendered without it — the card fell back to its title and the logo was an
--    initial of the wrong thing. It is redefined IN FULL below (the convention
--    for this codebase) with the join in place.
--
-- 2. `chk_record_subject` demanded a person or a company. That is right for a
--    recruitment record — an applicant IS a person — and wrong for a deal,
--    where "Q4 renewal" is a perfectly good row that has not been matched to an
--    organization yet. The constraint is widened to accept a title, which keeps
--    the thing it was protecting against (a record about nothing) while
--    allowing the thing people actually type first.
-- ============================================================================

-- A record must still be ABOUT something — it just no longer has to be about a
-- row in another table.
alter table pipeline_records drop constraint if exists chk_record_subject;
alter table pipeline_records add constraint chk_record_subject
  check (
    person_id is not null
    or company_id is not null
    or nullif(btrim(coalesce(title, '')), '') is not null
  );

-- ── Create ──────────────────────────────────────────────────────────────────
-- p_stage is optional: dropping into the first stage is what "New deal" means
-- almost every time, and making the caller resolve a stage id first is how a
-- create button ends up needing two round trips.
--
-- company_id has no foreign key (0001 left it loose so the Sales module could
-- ship later), so the workspace check on it happens HERE. Without that, a uuid
-- from another tenant would be stored happily and then joined on read.
create or replace function create_pipeline_record(
  p_privy text, p_workspace uuid, p_pipeline uuid,
  p_stage uuid default null, p_title text default null,
  p_amount numeric default null, p_company uuid default null, p_person uuid default null
) returns uuid language plpgsql security definer set search_path = public as $$
declare v_stage uuid; v_id uuid; v_title text;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;

  if not exists (select 1 from pipelines where id = p_pipeline and workspace_id = p_workspace) then
    raise exception 'PIPELINE_NOT_FOUND';
  end if;

  -- A stage from another pipeline would put the card in a column nobody can see.
  v_stage := (select s.id from pipeline_stages s
               where s.id = p_stage and s.pipeline_id = p_pipeline);
  if v_stage is null then
    v_stage := (select s.id from pipeline_stages s
                 where s.pipeline_id = p_pipeline order by s.position limit 1);
  end if;
  if v_stage is null then raise exception 'PIPELINE_HAS_NO_STAGES'; end if;

  if p_company is not null
     and not exists (select 1 from organizations o where o.id = p_company and o.workspace_id = p_workspace) then
    raise exception 'COMPANY_NOT_FOUND';
  end if;
  if p_person is not null
     and not exists (select 1 from people pe where pe.id = p_person and pe.workspace_id = p_workspace) then
    raise exception 'PERSON_NOT_FOUND';
  end if;

  v_title := nullif(btrim(coalesce(p_title, '')), '');
  if v_title is null and p_company is null and p_person is null then
    raise exception 'NEEDS_A_SUBJECT: give it a name, a company or a person';
  end if;

  insert into pipeline_records (workspace_id, pipeline_id, stage_id, person_id, company_id,
                                title, amount, status, position)
  values (p_workspace, p_pipeline, v_stage, p_person, p_company,
          v_title, p_amount,
          coalesce((select case when s.stage_type = 'open' then 'active' else s.stage_type end
                    from pipeline_stages s where s.id = v_stage), 'active'),
          -- New cards go to the TOP of their column. Appending puts the thing
          -- you just typed below everything you have not looked at in a month.
          coalesce((select min(r.position) from pipeline_records r
                     where r.pipeline_id = p_pipeline and r.stage_id = v_stage), 0) - 1)
  returning id into v_id;

  return v_id;
end $$;
grant execute on function create_pipeline_record(text, uuid, uuid, uuid, text, numeric, uuid, uuid)
  to authenticated, anon;

-- ── Update ──────────────────────────────────────────────────────────────────
-- Only the fields a card shows. Moving between stages stays in
-- move_pipeline_record, which also keeps `status` and `entered_stage_at`
-- honest — two writers for one column is how a board starts disagreeing with
-- the forecast.
create or replace function update_pipeline_record(
  p_privy text, p_record uuid, p_title text default null,
  p_amount numeric default null, p_company uuid default null, p_person uuid default null
) returns void language plpgsql security definer set search_path = public as $$
declare v_workspace uuid;
begin
  select workspace_id into v_workspace from pipeline_records where id = p_record;
  if v_workspace is null then raise exception 'RECORD_NOT_FOUND'; end if;
  if not is_workspace_member(v_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;

  if p_company is not null
     and not exists (select 1 from organizations o where o.id = p_company and o.workspace_id = v_workspace) then
    raise exception 'COMPANY_NOT_FOUND';
  end if;
  if p_person is not null
     and not exists (select 1 from people pe where pe.id = p_person and pe.workspace_id = v_workspace) then
    raise exception 'PERSON_NOT_FOUND';
  end if;

  -- NULL means "not mentioned", the same rule save_workspace_branding follows:
  -- a partial save must never blank the fields it does not name.
  update pipeline_records
     set title      = coalesce(nullif(btrim(coalesce(p_title, '')), ''), title),
         amount     = coalesce(p_amount, amount),
         company_id = coalesce(p_company, company_id),
         person_id  = coalesce(p_person, person_id)
   where id = p_record;
end $$;
grant execute on function update_pipeline_record(text, uuid, text, numeric, uuid, uuid) to authenticated, anon;

-- ── Delete ──────────────────────────────────────────────────────────────────
create or replace function delete_pipeline_record(p_privy text, p_record uuid)
returns void language plpgsql security definer set search_path = public as $$
declare v_workspace uuid;
begin
  select workspace_id into v_workspace from pipeline_records where id = p_record;
  if v_workspace is null then return; end if;   -- already gone; deleting twice is not an error
  if not is_workspace_member(v_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  delete from pipeline_records where id = p_record;
end $$;
grant execute on function delete_pipeline_record(text, uuid) to authenticated, anon;

-- ── Board, redefined IN FULL with the organizations join ────────────────────
create or replace function get_pipeline_board(p_privy text, p_pipeline uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_workspace uuid;
begin
  select workspace_id into v_workspace from pipelines where id = p_pipeline;
  if v_workspace is null then raise exception 'PIPELINE_NOT_FOUND'; end if;
  if not is_workspace_member(v_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;

  return jsonb_build_object(
    'stages', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', s.id, 'name', s.name, 'color', s.color, 'stage_type', s.stage_type
      ) order by s.position)
      from pipeline_stages s where s.pipeline_id = p_pipeline), '[]'::jsonb),
    'records', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', r.id, 'stage_id', r.stage_id, 'title', r.title, 'amount', r.amount,
        'status', r.status, 'position', r.position,
        'person', case when pe.id is null then null else jsonb_build_object(
          'id', pe.id, 'name', trim(coalesce(pe.first_name,'')||' '||coalesce(pe.last_name,'')),
          'title', pe.title, 'avatar_url', pe.avatar_url) end,
        -- The join 0002 promised. Scoped to the same workspace as well as the
        -- id, because company_id carries no foreign key.
        'company', case when co.id is null then null else jsonb_build_object(
          'id', co.id, 'name', co.name, 'domain', co.domain) end
      ) order by r.position)
      from pipeline_records r
      left join people pe on pe.id = r.person_id
      left join organizations co on co.id = r.company_id and co.workspace_id = v_workspace
      where r.pipeline_id = p_pipeline), '[]'::jsonb)
  );
end $$;
grant execute on function get_pipeline_board(text, uuid) to authenticated, anon;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0093_rename_workspace.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0093_rename_workspace.sql
-- A workspace can be renamed. Until now it could not, anywhere, ever.
--
-- THE BUG, AND WHY IT LOOKED LIKE A DOZEN SMALL ONES. An organisation's name
-- lives in THREE columns:
--
--   workspaces.name        the sidebar, the workspace switcher, get_my_workspace
--   companies.name         the HR half, and the careers-page fallback
--   workspaces.legal_name  invoices and documents  (branding — already editable)
--
-- 0005's trigger copies companies.name into workspaces.name exactly once, on
-- INSERT, with `on conflict do nothing`. Nothing has ever written either of the
-- first two again. So an owner who renamed their company changed `legal_name`
-- in Branding — the only name with a form attached — watched the invoices and
-- the careers page update, and then kept seeing the OLD name in the sidebar,
-- the switcher and half the HR screens, with nowhere to go and fix it.
--
-- The lesson in the shape of it: adding a fourth editable name would have made
-- this worse. One function writes both display names together.
--
-- legal_name is deliberately NOT touched. "RunButter" and "RunButter Sp. z o.o."
-- are different facts — one is what a colleague calls the place, the other is
-- what goes on an invoice — and collapsing them would silently rewrite a legal
-- document's issuer the next time someone tidied up their sidebar.
--
-- The SLUG is deliberately not touched either. workspaces.slug and the careers
-- address are live public URLs; changing one 404s every link anyone has shared.
-- That is a separate, deliberate act with its own warning, not a side effect of
-- fixing a typo in a display name.
-- ============================================================================

create or replace function rename_workspace(p_privy text, p_workspace uuid, p_name text)
returns text language plpgsql security definer set search_path = public as $$
declare v_name text;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  -- Renaming changes what every member sees and what recipients of a document
  -- read, so it sits at the same bar as changing branding: owner or admin.
  if workspace_role(p_privy, p_workspace) not in ('owner','admin') then
    raise exception 'FORBIDDEN: only an owner or admin can rename the workspace';
  end if;

  v_name := btrim(coalesce(p_name, ''));
  if v_name = '' then raise exception 'NAME_REQUIRED'; end if;
  if length(v_name) > 80 then raise exception 'NAME_TOO_LONG: 80 characters maximum'; end if;

  update workspaces set name = v_name where id = p_workspace;

  -- The HR half reads companies.name, and get_careers_page falls back to it
  -- when legal_name is blank. Renaming one and not the other is how this
  -- became three disagreeing names in the first place.
  update companies set name = v_name where id = p_workspace;

  return v_name;
end $$;
grant execute on function rename_workspace(text, uuid, text) to authenticated, anon;

-- ── Repair ──────────────────────────────────────────────────────────────────
-- Existing workspaces whose two display names already disagree, because the
-- 0005 trigger only ever ran on insert. companies.name is the authority: it is
-- the one the signup form wrote and the one the HR screens have been showing.
update workspaces w
   set name = c.name
  from companies c
 where c.id = w.id
   and coalesce(nullif(btrim(c.name), ''), '') <> ''
   and w.name is distinct from c.name;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0094_hr_positions_rpc.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0094_hr_positions_rpc.sql
-- Gives the HR positions screens a server-side path, which they never had.
--
-- WHAT BROKE AND WHY. 0077 closed the anon read/write hole on the legacy ATS
-- tables, and its final act per table is:
--
--     revoke all on table public.<t> from anon, authenticated
--
-- with `positions` and `companies` both in the target list. That is a GRANT
-- revocation, not an RLS policy — so the browser does not get "zero rows", it
-- gets `permission denied for table companies`. Every HR positions screen still
-- read those tables straight from the browser with the anon key, so the moment
-- 0077 ran:
--
--   • Positions → the list read is denied, the page renders empty, and it looks
--     exactly like the roles were DELETED. They were never touched.
--   • New role → "Could not check your plan: permission denied for table
--     companies", from a direct read of companies.plan.
--   • Edit / careers / sources → same shape.
--
-- 0077's header warns to deploy the client changes first. 0076 did that for
-- login, register, plans and team — the positions screens were missed, and
-- nothing failed until the revoke landed.
--
-- WHY THIS IS A MIGRATION AND NOT A CLIENT PATCH. There was no write RPC for
-- positions at all: `hr_list_positions_min` returns id+title of ACTIVE rows
-- only (built for a dropdown), and nothing anywhere could insert, update or
-- delete one. Restoring the grants instead would reopen precisely the hole
-- 0077 closed — the anon key ships in the browser bundle, so a read grant there
-- is a public read.
--
-- Every function is SECURITY DEFINER, derives its tenant from hr_company_id()
-- (never from an argument), and is service_role only — reachable solely through
-- the /api/rpc proxy, which verifies the Privy JWT. Same shape as 0044/0045.
--
-- Plan limits are deliberately NOT encoded here: lib/plans.ts is the single
-- source for those numbers, and a copy in SQL is how the pricing in CLAUDE.md
-- drifted a whole model behind reality. The client reads its plan from
-- get_my_workspace and its count from hr_list_positions.
-- ============================================================================

-- ── Read ────────────────────────────────────────────────────────────────────

/**
 * The full list for the positions screen, with applicant counts.
 *
 * Counts come from a LATERAL subquery rather than a join + group by: a join
 * would drop positions with no candidates unless it were a LEFT join, and the
 * previous client code learned that lesson the hard way when one embedded
 * PostgREST join emptied the whole list.
 */
create or replace function hr_list_positions(p_privy text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_c uuid;
begin
  v_c := hr_company_id(p_privy);
  if v_c is null then return '[]'::jsonb; end if;

  return coalesce((
    select jsonb_agg(row_to_json(x)::jsonb order by x.created_at desc)
    from (
      select p.id, p.company_id, p.title, p.description, p.department, p.location,
             p.employment_type, p.neuro_profile, p.is_active, p.is_published,
             p.created_at, p.updated_at, p.created_by,
             coalesce(c.n, 0) as applicant_count
      from positions p
      left join lateral (
        select count(*)::int as n from candidates cd where cd.position_id = p.id
      ) c on true
      where p.company_id = v_c
    ) x
  ), '[]'::jsonb);
end $$;

create or replace function hr_get_position(p_privy text, p_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_c uuid; v_row jsonb;
begin
  v_c := hr_company_id(p_privy);
  if v_c is null then return null; end if;
  -- The company check is in the WHERE clause, so a guessed id from another
  -- tenant returns null rather than raising — an error message that
  -- distinguishes "not yours" from "does not exist" is an enumeration oracle.
  select row_to_json(p)::jsonb into v_row
  from positions p where p.id = p_id and p.company_id = v_c;
  return v_row;
end $$;

-- ── Write ───────────────────────────────────────────────────────────────────

/**
 * Insert or update. `p_id` null means insert.
 *
 * Keys ABSENT from p_data are left alone on update, matching update_record's
 * semantics (0088) — the bug that one fixed was a partial update blanking every
 * column it did not mention, and the same shape would be just as wrong here.
 */
create or replace function hr_save_position(p_privy text, p_id uuid, p_data jsonb, p_assessment jsonb default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_c uuid; v_member uuid; v_id uuid; v_title text;
begin
  v_c := hr_company_id(p_privy);
  if v_c is null then raise exception 'NO_COMPANY: your account is not linked to a company'; end if;

  v_title := nullif(btrim(coalesce(p_data->>'title', '')), '');

  if p_id is null then
    if v_title is null then raise exception 'TITLE_REQUIRED'; end if;

    -- created_by references company_users(id) and is nullable; a workspace
    -- member with no legacy ATS row still gets to create a position rather
    -- than being blocked by a row they never knew existed.
    select cu.id into v_member
    from company_users cu
    where cu.privy_user_id = p_privy and cu.company_id = v_c
    order by cu.created_at asc limit 1;

    insert into positions (company_id, title, description, department, location,
                           employment_type, neuro_profile, is_active, is_published, created_by)
    values (v_c, v_title,
            nullif(p_data->>'description', ''),
            nullif(p_data->>'department', ''),
            nullif(p_data->>'location', ''),
            nullif(p_data->>'employment_type', ''),
            nullif(p_data->>'neuro_profile', ''),
            coalesce((p_data->>'is_active')::boolean, true),
            coalesce((p_data->>'is_published')::boolean, true),
            v_member)
    returning id into v_id;

    -- The default assessment is created HERE, in the same transaction, because
    -- assessment_templates is in 0077's revoke list too and the client can no
    -- longer insert it. Atomicity is the bonus: the old two-step could leave a
    -- position with no assessment, which breaks the candidate flow silently —
    -- the client even had a comment apologising for that state.
    if p_assessment is not null and jsonb_typeof(p_assessment->'questions') = 'array' then
      insert into assessment_templates (company_id, position_id, name, description, questions, is_default)
      values (v_c, v_id,
              coalesce(nullif(p_assessment->>'name', ''), v_title || ' Assessment'),
              nullif(p_assessment->>'description', ''),
              p_assessment->'questions', true);
    end if;
  else
    update positions p set
      title            = case when p_data ? 'title'           then coalesce(v_title, p.title) else p.title end,
      description      = case when p_data ? 'description'     then nullif(p_data->>'description', '') else p.description end,
      department       = case when p_data ? 'department'      then nullif(p_data->>'department', '') else p.department end,
      location         = case when p_data ? 'location'        then nullif(p_data->>'location', '') else p.location end,
      employment_type  = case when p_data ? 'employment_type' then nullif(p_data->>'employment_type', '') else p.employment_type end,
      neuro_profile    = case when p_data ? 'neuro_profile'   then nullif(p_data->>'neuro_profile', '') else p.neuro_profile end,
      is_active        = case when p_data ? 'is_active'       then (p_data->>'is_active')::boolean else p.is_active end,
      is_published     = case when p_data ? 'is_published'    then (p_data->>'is_published')::boolean else p.is_published end,
      updated_at       = now()
    where p.id = p_id and p.company_id = v_c
    returning p.id into v_id;

    if v_id is null then raise exception 'NOT_FOUND'; end if;
  end if;

  return hr_get_position(p_privy, v_id);
end $$;

create or replace function hr_delete_position(p_privy text, p_id uuid)
returns boolean language plpgsql security definer set search_path = public as $$
declare v_c uuid; v_n int;
begin
  v_c := hr_company_id(p_privy);
  if v_c is null then return false; end if;
  delete from positions where id = p_id and company_id = v_c;
  get diagnostics v_n = row_count;
  return v_n > 0;
end $$;

-- ── Grants ──────────────────────────────────────────────────────────────────
-- service_role only. Anon EXECUTE was revoked wholesale in 0046, and these
-- reach the browser exclusively through /api/rpc, which verifies the Privy JWT
-- and overwrites p_privy with the verified subject — so a caller cannot pass
-- somebody else's id.
revoke all on function hr_list_positions(text)              from public, anon, authenticated;
revoke all on function hr_get_position(text, uuid)          from public, anon, authenticated;
revoke all on function hr_save_position(text, uuid, jsonb, jsonb) from public, anon, authenticated;
revoke all on function hr_delete_position(text, uuid)       from public, anon, authenticated;

grant execute on function hr_list_positions(text)             to service_role;
grant execute on function hr_get_position(text, uuid)         to service_role;
grant execute on function hr_save_position(text, uuid, jsonb, jsonb) to service_role;
grant execute on function hr_delete_position(text, uuid)      to service_role;

-- ── get_my_hr_companies gains two fields ────────────────────────────────────
/**
 * Redefined IN FULL (0076's version), adding `id` and `open_positions`.
 *
 * `id` is company_users.id — the membership id. Its absence is why
 * resolveHrCompany could not stop reading company_users directly: it needs that
 * value for `created_by`. Adding a key to the returned JSON is backward
 * compatible; every existing caller reads by name.
 *
 * `logo_url` and `subdomain` join them so Settings can render the company
 * without its own read of `companies`.
 *
 * `open_positions` lets the company switcher say "6 roles are in your other
 * workspace" instead of rendering an empty list with no explanation — the
 * screens counted that with a cross-company read of `positions`, which 0077
 * also revoked.
 */
create or replace function get_my_hr_companies(p_privy text)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if coalesce(trim(p_privy), '') = '' then return '[]'::jsonb; end if;
  return coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at) from (
    select cu.id, cu.company_id, cu.role, cu.full_name, cu.email, cu.created_at,
           c.name as company_name, c.plan, c.subdomain, c.logo_url,
           coalesce(op.n, 0) as open_positions
      from company_users cu
      join companies c on c.id = cu.company_id
      left join lateral (
        select count(*)::int as n from positions p
         where p.company_id = cu.company_id and p.is_active
      ) op on true
     where cu.privy_user_id = p_privy
  ) x), '[]'::jsonb);
end $$;

revoke all on function get_my_hr_companies(text) from public, anon, authenticated;
grant execute on function get_my_hr_companies(text) to service_role;

notify pgrst, 'reload schema';

-- ── The default assessment, for the edit screen ─────────────────────────────
/**
 * assessment_templates is in 0077's revoke list too, so the edit screen could
 * neither read its questions back nor save them. Both are scoped through the
 * POSITION's company, never through a company id passed in — the old client
 * insert took `company_id` from resolveHrCompanyId and would happily have
 * written a template into whichever company that returned.
 */
create or replace function hr_get_assessment(p_privy text, p_position uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_c uuid; v_row jsonb;
begin
  v_c := hr_company_id(p_privy);
  if v_c is null then return null; end if;
  select to_jsonb(a) into v_row
  from assessment_templates a
  join positions p on p.id = a.position_id
  where a.position_id = p_position and a.is_default and p.company_id = v_c
  limit 1;
  return v_row;
end $$;

/** Upsert the default template for a position. Returns it. */
create or replace function hr_save_assessment(p_privy text, p_position uuid, p_data jsonb)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_c uuid; v_existing uuid;
begin
  v_c := hr_company_id(p_privy);
  if v_c is null then raise exception 'NO_COMPANY'; end if;
  -- The position must be ours before anything is written against it.
  if not exists (select 1 from positions where id = p_position and company_id = v_c) then
    raise exception 'NOT_FOUND';
  end if;
  if jsonb_typeof(p_data->'questions') <> 'array' then raise exception 'QUESTIONS_REQUIRED'; end if;

  select id into v_existing from assessment_templates
   where position_id = p_position and is_default limit 1;

  if v_existing is null then
    insert into assessment_templates (company_id, position_id, name, description, questions, is_default)
    values (v_c, p_position,
            coalesce(nullif(p_data->>'name', ''), 'Assessment'),
            nullif(p_data->>'description', ''),
            p_data->'questions', true);
  else
    update assessment_templates
       set questions = p_data->'questions',
           name = coalesce(nullif(p_data->>'name', ''), name),
           updated_at = now()
     where id = v_existing;
  end if;

  return hr_get_assessment(p_privy, p_position);
end $$;

revoke all on function hr_get_assessment(text, uuid)         from public, anon, authenticated;
revoke all on function hr_save_assessment(text, uuid, jsonb) from public, anon, authenticated;
grant execute on function hr_get_assessment(text, uuid)         to service_role;
grant execute on function hr_save_assessment(text, uuid, jsonb) to service_role;

notify pgrst, 'reload schema';

-- ── get_apply_branding gains neuro_profile ──────────────────────────────────
/**
 * Redefined IN FULL (0064's version), adding `neuro_profile`.
 *
 * The assessment page read that column straight off `positions` to choose which
 * benchmark to score an applicant against. Anon lost that grant in 0077, and
 * the read DISCARDED its error, so it silently fell back to 'hard-tech' — every
 * applicant to every role scored against one profile, with nothing on screen or
 * in the logs to say so. A wrong number reported confidently is worse than an
 * error, so this closes it rather than leaving the fallback to do the work.
 *
 * This is the only anon-reachable function that already resolves a position, so
 * it is the right place: no new public surface, and it keeps the same
 * active-AND-published visibility rule, which means a hidden role still cannot
 * be probed by id.
 */
create or replace function get_apply_branding(p_position_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v jsonb;
begin
  select jsonb_build_object(
           'title', p.title,
           'neuro_profile', p.neuro_profile,
           'company_name', coalesce(nullif(w.legal_name, ''), c.name),
           'logo_url', coalesce(nullif(w.logo_url, ''), c.logo_url),
           'accent_color', nullif(w.accent_color, ''),
           'apply_intro', nullif(w.apply_intro, '')
         )
    into v
    from positions p
    join companies c on c.id = p.company_id
    left join workspaces w on w.id = c.id
   where p.id = p_position_id
     and p.is_active and p.is_published;

  return v;   -- null when the position is missing or not public
end $$;

grant execute on function get_apply_branding(uuid) to authenticated, anon, service_role;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0095_live_agent_runs.sql
-- ══════════════════════════════════════════════════════════════════════════
-- 0095: watch an agent work.
--
-- WHY THIS EXISTS. `agent_runs.steps` has recorded every thought and tool call
-- since 0043 — and the runner built that array in memory and wrote it ONCE, in
-- `finish_agent_run`, after the whole loop had finished. So a run that takes
-- forty seconds and calls nine tools showed a spinner for forty seconds and
-- then a wall of text. The most interesting thing the product does was
-- invisible while it was happening.
--
-- Nothing here changes the schema. It adds the two functions that let the steps
-- be written as they happen and read while the run is still going:
--
--   append_agent_run_step  service_role, called by the runner once per step
--   get_agent_run          membership-checked, called by the browser to poll
--
-- WHY POLLING AND NOT REALTIME. Supabase Realtime needs anon-key RLS policies
-- on the table, which would undo the /api/rpc proxy that every other read goes
-- through — the same reason team chat (0075) polls. A run emits a step every
-- few seconds at most, so a 1.2s poll is well inside "live" and costs one
-- indexed primary-key read.
--
-- `finish_agent_run` STILL WRITES THE WHOLE ARRAY and remains the source of
-- truth. The appends are a progress feed: if one fails, the run is unaffected
-- and the complete transcript lands at the end anyway. That is why the runner
-- ignores errors from it, and why this is not a schema change.

-- Append one step to a run in progress, or replace the last one.
--
-- WHY REPLACE EXISTS. A tool call is announced BEFORE it runs — a lookup that
-- takes four seconds should read as one that is taking four seconds, not appear
-- retroactively once it is already done. So the runner writes the call with
-- `status: 'running'`, then writes it again with its result. Replacing the last
-- element keeps the stored transcript identical to the array the runner holds
-- in memory, which is what `finish_agent_run` writes at the end; without it the
-- live view and the final record would disagree about how many steps there were.
--
-- `jsonb - integer` deletes an array element by index, so dropping the last one
-- is a single expression. The alternative — sending the whole growing array on
-- every step — re-transmits every tool result already stored, and `list_records`
-- results are not small.
--
-- jsonb_build_array wraps the step at THIS level rather than at the call site so
-- a caller passing an array can never flatten two steps into the transcript.
create or replace function append_agent_run_step(p_id uuid, p_step jsonb, p_replace_last boolean default false)
returns void language plpgsql security definer set search_path = public as $$
begin
  update agent_runs
     set steps = case
                   when p_replace_last and jsonb_array_length(coalesce(steps, '[]'::jsonb)) > 0
                     then (steps - (jsonb_array_length(steps) - 1)) || jsonb_build_array(p_step)
                   else coalesce(steps, '[]'::jsonb) || jsonb_build_array(p_step)
                 end
   where id = p_id
     -- A finished run is closed. Without this, a late append from a crashed
     -- loop could reopen the transcript of a run somebody has already read.
     and status = 'running';
end $$;
revoke all on function append_agent_run_step(uuid, jsonb, boolean) from public, authenticated, anon;
grant execute on function append_agent_run_step(uuid, jsonb, boolean) to service_role;

-- The caller may now name the run.
--
-- WHY. `POST /api/agents/run` does not answer until the loop has finished, so
-- the id it returns arrives exactly when the live view stops being useful. The
-- browser therefore mints a uuid, sends it with the task, and starts polling
-- immediately — the ordinary idempotency-key shape.
--
-- A client-chosen id is only safe because it CANNOT TAKE OVER AN EXISTING ROW.
-- `on conflict do nothing` leaves a colliding insert with no returned id, and
-- the function then falls back to a server-generated one. So the worst a client
-- achieves by guessing another workspace's run id is getting a different id back
-- than it asked for — never a write into somebody else's run.
--
-- Signature change, so the old one is DROPPED first: adding a parameter to a
-- Postgres function creates an overload rather than replacing it, and both
-- definitions would then be live with PostgREST picking by argument names.
drop function if exists create_agent_run(uuid, uuid, text, text, text);
create or replace function create_agent_run(
  p_workspace uuid, p_agent_id uuid, p_agent_name text, p_task text, p_privy text,
  p_id uuid default null
) returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid;
begin
  if p_id is not null then
    insert into agent_runs (id, workspace_id, agent_id, agent_name, task, created_by_privy)
    values (p_id, p_workspace, p_agent_id, p_agent_name, p_task, p_privy)
    on conflict (id) do nothing
    returning id into v_id;
    if v_id is not null then return v_id; end if;
  end if;
  insert into agent_runs (workspace_id, agent_id, agent_name, task, created_by_privy)
  values (p_workspace, p_agent_id, p_agent_name, p_task, p_privy) returning id into v_id;
  return v_id;
end $$;
revoke all on function create_agent_run(uuid, uuid, text, text, text, uuid) from public, authenticated, anon;
grant execute on function create_agent_run(uuid, uuid, text, text, text, uuid) to service_role;

-- Read ONE run, for polling.
--
-- `get_agent_runs` (0043) returns the last fifty with their full step arrays,
-- which is the wrong shape to call every 1.2 seconds — it grows with the
-- workspace's history and re-sends every transcript to learn about one. This
-- reads a single row by primary key and checks membership on the run's OWN
-- workspace, so an id belonging to another tenant resolves to null rather than
-- to a permission error that confirms the id exists.
create or replace function get_agent_run(p_privy text, p_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare rec record;
begin
  select r.id, r.agent_id, r.agent_name, r.task, r.status, r.steps, r.proposed,
         r.result, r.created_at, r.finished_at, r.workspace_id
    into rec
    from agent_runs r where r.id = p_id;
  if not found then return null; end if;
  if not is_workspace_member(rec.workspace_id, p_privy) then return null; end if;
  return to_jsonb(rec) - 'workspace_id';
end $$;
grant execute on function get_agent_run(text, uuid) to authenticated, anon;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0096_agent_run_usage.sql
-- ══════════════════════════════════════════════════════════════════════════
-- 0096: what did that agent cost?
--
-- WHY THIS EXISTS. Every provider returns a token count on every response and
-- RunButter dropped it on the floor. So the one question a BYO-key customer
-- actually has — "which agent is spending my money" — had no answer anywhere in
-- the product, and the only place to look was the provider's own billing page,
-- which knows nothing about agents.
--
-- COUNTED, NEVER ESTIMATED. These columns hold what the provider reported.
-- Nothing here derives tokens from character counts: a number that looks
-- authoritative and is guessed is worse than no number, and the UI says "not
-- reported" rather than "0" when a gateway omits usage.
--
-- `cached_tokens` IS A SUBSET OF `input_tokens`, not an addition. Adding the two
-- together double-counts the cheap half of the bill, so the column comment says
-- so and every reader has to honour it. Anthropic reports cache reads outside
-- `input_tokens`; the client folds them in before they reach this table, so the
-- meaning is the same on every provider.

alter table agent_runs add column if not exists input_tokens  bigint not null default 0;
alter table agent_runs add column if not exists output_tokens bigint not null default 0;
alter table agent_runs add column if not exists cached_tokens bigint not null default 0;
alter table agent_runs add column if not exists model text not null default '';

comment on column agent_runs.cached_tokens is
  'Part of input_tokens served from a prompt cache. A SUBSET of input_tokens — never add the two.';

-- `finish_agent_run` gains the counts. Signature change, so the old definition
-- is dropped first: adding a parameter to a Postgres function creates an
-- OVERLOAD rather than replacing it, and PostgREST would then pick between two
-- live definitions by argument name.
drop function if exists finish_agent_run(uuid, text, jsonb, jsonb, text);
create or replace function finish_agent_run(
  p_id uuid, p_status text, p_steps jsonb, p_proposed jsonb, p_result text,
  -- NULL means "leave the column alone", exactly as `update_record` reads an
  -- absent key (0088). This is not a style choice: `/api/agents/approve` calls
  -- this function a second time to close an approved run, and it has no usage
  -- to pass. With a `0` default that second call would silently ERASE the token
  -- count of every run anybody approved — the runs that matter most, wiped by
  -- the act of accepting them.
  p_input_tokens bigint default null, p_output_tokens bigint default null,
  p_cached_tokens bigint default null, p_model text default null
) returns void language plpgsql security definer set search_path = public as $$
begin
  update agent_runs set status = p_status, steps = coalesce(p_steps,'[]'::jsonb),
    proposed = coalesce(p_proposed,'[]'::jsonb), result = coalesce(p_result,''),
    input_tokens = greatest(coalesce(p_input_tokens, input_tokens), 0),
    output_tokens = greatest(coalesce(p_output_tokens, output_tokens), 0),
    cached_tokens = greatest(coalesce(p_cached_tokens, cached_tokens), 0),
    model = coalesce(nullif(p_model, ''), model),
    finished_at = case when p_status in ('done','error') then now() else finished_at end
  where id = p_id;
end $$;
revoke all on function finish_agent_run(uuid, text, jsonb, jsonb, text, bigint, bigint, bigint, text) from public, authenticated, anon;
grant execute on function finish_agent_run(uuid, text, jsonb, jsonb, text, bigint, bigint, bigint, text) to service_role;

-- Spend, by agent, over a window.
--
-- Aggregated in SQL rather than by reading fifty runs into the browser and
-- summing: `get_agent_runs` caps at fifty, so a busy workspace would silently
-- report a month's cost from whatever fitted in the last fifty rows — a wrong
-- number with no symptom.
--
-- `p_days` is clamped. An unbounded window on a table with no date predicate is
-- a sequential scan somebody triggers by typing a large number into a URL.
create or replace function get_agent_usage(p_privy text, p_workspace uuid, p_days int default 30)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_days int := least(greatest(coalesce(p_days, 30), 1), 365);
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  return jsonb_build_object(
    'days', v_days,
    'totals', (
      select jsonb_build_object(
        'runs', count(*),
        'input', coalesce(sum(input_tokens), 0),
        'output', coalesce(sum(output_tokens), 0),
        'cached', coalesce(sum(cached_tokens), 0),
        -- Runs that reported nothing at all. Without this the UI cannot tell
        -- "cheap" from "this gateway does not report usage", and would present
        -- a confident total that is missing an unknown share of the spend.
        'unreported', count(*) filter (where input_tokens = 0 and output_tokens = 0)
      )
      from agent_runs
      where workspace_id = p_workspace and created_at > now() - make_interval(days => v_days)
    ),
    -- GROUPED BY id OR NAME, not by id alone.
    --
    -- `agent_runs.agent_id` is `on delete set null` (0043), so every deleted
    -- agent's runs carry a null id — and grouping on that alone folds all of
    -- them into ONE row labelled with whichever name happened to sort highest.
    -- Three deleted agents then appear as one big spender that never existed.
    -- `agent_name` is snapshotted on the run, so it still identifies them.
    --
    -- Ordered by total, not by input: an agent that writes long summaries costs
    -- more per token than one that reads, and ranking on input alone would put
    -- the cheaper one at the top.
    'by_agent', coalesce((
      select jsonb_agg(a order by (a->>'input')::bigint + (a->>'output')::bigint desc) from (
        select jsonb_build_object(
          'agent_id', max(agent_id::text),
          'name', max(agent_name),
          'model', max(model),
          'runs', count(*),
          'input', coalesce(sum(input_tokens), 0),
          'output', coalesce(sum(output_tokens), 0),
          'cached', coalesce(sum(cached_tokens), 0)
        ) as a
        from agent_runs
        where workspace_id = p_workspace and created_at > now() - make_interval(days => v_days)
        group by coalesce(agent_id::text, 'deleted:' || agent_name)
      ) x
    ), '[]'::jsonb)
  );
end $$;
grant execute on function get_agent_usage(text, uuid, int) to authenticated, anon;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0097_editable_objects.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0097_editable_objects.sql
-- The built-in objects become yours: rename them, hide them, move them,
-- rename and reorder their columns, and add your own fields to them.
--
-- ── WHY ─────────────────────────────────────────────────────────────────────
-- 0087 made a workspace able to define its OWN objects, and that was the half
-- of the problem nobody had solved. The other half stayed frozen: eleven
-- built-in objects with names we chose, columns we chose, and no way to add a
-- field to any of them. A recruitment agency calls Companies "Clients". A
-- clinic does not want Campaigns in the sidebar at all. A haulier needs one
-- extra field on Companies — a depot code — and the only route was to abandon
-- Companies and rebuild it as a custom object, losing sanctions screening,
-- invoicing, the careers page and every relation pointing at it.
--
-- So a built-in gets the two things a custom object already had: a per-
-- workspace presentation, and fields.
--
-- ── TWO SEPARATE THINGS, DELIBERATELY ───────────────────────────────────────
-- `object_overrides` is PRESENTATION. Name, icon, nav section, hidden, column
-- order and column labels. It never changes what is stored, so it is safe to
-- reset — and resetting is a delete, which is why it is one row per object
-- rather than a column on eleven tables.
--
-- `custom_fields.builtin_slug` is DATA. It reuses the 0087 field table
-- verbatim: the same eleven types, the same coercion, the same fail-closed
-- rules. A second field vocabulary for built-ins would have drifted from the
-- first inside a month, and the CSV feed and the agents would then have to
-- know which kind of field they were looking at.
--
-- ── VALUES GO IN THE COLUMN THAT WAS ALWAYS THERE ───────────────────────────
-- `custom_fields jsonb` has been on people, organizations, invoices, expenses,
-- assets and pipeline_records since 0001 — declared, indexed by nothing, read
-- by nothing, written by nothing. `object_fields` was created in the same
-- migration to describe them and never got an RPC either. This is that idea
-- finally connected, minus `object_fields`, which only ever covered four object
-- types and used a different type vocabulary from the one 0087 settled on.
-- The five tables that lacked the column get it here.
--
-- ── THE MONOLITH IS EXTENDED, NOT FORKED ────────────────────────────────────
-- list/get/create/update_record are redefined IN FULL, per the convention, and
-- each gains exactly one call: a merge on the way out, a write on the way in.
-- That is what makes an extra field on Companies real everywhere at once — the
-- table, the form, the CSV feed, Excel sync, /api/mcp and every agent tool read
-- those same five functions. A field only the browser could see would be the
-- third time this product learned that lesson.
--
-- Depends on 0001, 0087, 0088, 0089, 0091. Idempotent & prod-safe.
-- ============================================================================

-- ── The column that holds the values ────────────────────────────────────────
-- Six tables had it from 0001; these five did not. Same name, same default, so
-- there is one shape to reason about rather than "which tables support this".
alter table transactions add column if not exists custom_fields jsonb not null default '{}'::jsonb;
alter table products     add column if not exists custom_fields jsonb not null default '{}'::jsonb;
alter table campaigns    add column if not exists custom_fields jsonb not null default '{}'::jsonb;
alter table projects     add column if not exists custom_fields jsonb not null default '{}'::jsonb;
alter table issues       add column if not exists custom_fields jsonb not null default '{}'::jsonb;

-- ── Fields on a built-in ────────────────────────────────────────────────────
-- `custom_fields` gains an alternative owner. A row belongs to EITHER a custom
-- object or a built-in slug, never both and never neither — the check is what
-- stops a field existing in no object at all, which would be invisible in every
-- screen and still returned by every query that forgets the filter.
alter table custom_fields alter column object_id drop not null;
alter table custom_fields add column if not exists builtin_slug text;

do $$ begin
  alter table custom_fields add constraint custom_fields_owner_check
    check (num_nonnulls(object_id, builtin_slug) = 1);
exception when duplicate_object then null; end $$;

-- `unique (object_id, key)` from 0087 stops enforcing anything once object_id
-- is null (two nulls never conflict in Postgres), so the built-in half needs
-- its own. Partial, so it costs nothing for custom objects.
create unique index if not exists uq_custom_fields_builtin
  on custom_fields (workspace_id, builtin_slug, key) where builtin_slug is not null;
create index if not exists idx_custom_fields_builtin
  on custom_fields (workspace_id, builtin_slug, position) where builtin_slug is not null;

-- ── Presentation ────────────────────────────────────────────────────────────
create table if not exists object_overrides (
  id           uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspaces(id) on delete cascade,
  -- A BUILT-IN slug. Custom objects carry their own name and icon on
  -- custom_objects, so a row here for one would be a second source of truth.
  slug         text not null,
  -- NULL means "keep what ships". Not '' — an empty string is a name somebody
  -- chose, and a workspace that clears the field wants the default back, not a
  -- blank sidebar entry.
  singular     text,
  plural       text,
  icon         text,
  group_key    text,
  hidden       boolean not null default false,
  /**
   * Column presentation: [{ "key": "domain", "label": "Website", "hidden": true }]
   *
   * ORDER IS THE ARRAY ORDER, and keys not listed keep their shipped position
   * after the ones that are. That rule is what makes this survive a release:
   * when we add a column to Companies next year, a workspace that reordered
   * three columns gets the new one appended instead of losing it.
   */
  columns      jsonb not null default '[]'::jsonb,
  position     int,
  updated_at   timestamptz not null default now(),
  unique (workspace_id, slug)
);
alter table object_overrides enable row level security;
revoke all on table object_overrides from anon, authenticated;
drop trigger if exists trg_object_overrides_upd on object_overrides;
create trigger trg_object_overrides_upd before update on object_overrides
  for each row execute function set_updated_at();

-- ── Which built-ins can carry fields, and where the values live ─────────────
/**
 * Canonical slug for a built-in object.
 *
 * `companies` and `organizations` are one table under two names, and so are
 * `invoices` and `offers` (an offer is an invoice with kind='offer'). Field
 * definitions are stored under the canonical name so the same physical column
 * cannot end up with two different declarations of the same key — which would
 * make one of them silently unreadable.
 */
create or replace function builtin_object_slug(p_object text)
returns text language sql immutable as $$
  select case lower(coalesce(p_object, ''))
    when 'organizations' then 'companies'
    when 'offers'        then 'invoices'
    else lower(coalesce(p_object, ''))
  end;
$$;

/**
 * Canonical slug for a SCREEN, which is not the same question.
 *
 * `organizations` is a pure alias of `companies` — one nav entry, one page —
 * so the two must share a name and an icon. `offers` is not: it is its own
 * screen with its own nav entry, and a workspace renaming Offers to "Quotes"
 * must not rename Invoices too. Fields are the opposite case, because both
 * screens write the same physical column, which is why the two functions exist
 * and why `builtin_object_slug` above is the one used for fields.
 */
create or replace function builtin_view_slug(p_object text)
returns text language sql immutable as $$
  select case lower(coalesce(p_object, ''))
    when 'organizations' then 'companies'
    else lower(coalesce(p_object, ''))
  end;
$$;

/**
 * Built-in slug → the table its rows live in, or NULL if it is not a built-in.
 *
 * A WHITELIST CASE returning a constant, exactly like `delete_record`'s table
 * map (0087) and `custom_relation_label` (0089). The identifier that reaches
 * `format('%I')` below can only ever be one of these eleven literals, which is
 * the whole reason dynamic SQL is acceptable here and is not acceptable
 * anywhere a user string could reach.
 */
create or replace function builtin_extras_table(p_object text)
returns text language sql immutable as $$
  select case builtin_object_slug(p_object)
    when 'companies'    then 'organizations'
    when 'people'       then 'people'
    when 'invoices'     then 'invoices'
    when 'expenses'     then 'expenses'
    when 'transactions' then 'transactions'
    when 'products'     then 'products'
    when 'campaigns'    then 'campaigns'
    when 'projects'     then 'projects'
    when 'issues'       then 'issues'
    when 'assets'       then 'assets'
  end;
$$;

/** Has this workspace actually added anything to this object? */
create or replace function builtin_has_extras(p_workspace uuid, p_object text)
returns boolean language sql stable as $$
  select exists (select 1 from custom_fields
                  where workspace_id = p_workspace
                    and builtin_slug = builtin_object_slug(p_object));
$$;

/**
 * Validate a payload against the fields defined on a built-in object.
 *
 * The built-in twin of `build_custom_data` (0087), and it borrows that
 * function's two rules wholesale because they are the reason a declared type
 * can be trusted downstream: a value that does not match its type is REJECTED
 * rather than stored as text, and a key nobody declared is DROPPED so a payload
 * cannot widen the row.
 *
 * The difference is `p_partial`. Creating a record considers every declared
 * field (so `required` is enforced); updating considers only the keys present,
 * because `update_record` has meant "absent = leave alone" since 0088 and an
 * agent setting one field must not be asked for the other six.
 */
create or replace function builtin_extras_data(p_workspace uuid, p_object text, p_data jsonb, p_partial boolean)
returns jsonb language plpgsql stable as $$
declare f custom_fields; out jsonb := '{}'::jsonb;
begin
  for f in select * from custom_fields
            where workspace_id = p_workspace
              and builtin_slug = builtin_object_slug(p_object)
            order by position, key
  loop
    if p_partial and not (coalesce(p_data, '{}'::jsonb) ? f.key) then continue; end if;
    out := out || jsonb_build_object(f.key, coerce_custom_value(f, coalesce(p_data, '{}'::jsonb) -> f.key));
  end loop;
  return out;
end $$;

/**
 * Write the extras for one row.
 *
 * Merged into whatever is already there, never replacing it, so a partial
 * update leaves the fields it did not mention alone — the same contract the
 * named columns have had since 0088. Deleting a field definition therefore
 * leaves its values in place exactly as it does for a custom object, and
 * re-adding the field brings them back.
 *
 * Silent no-op when the object carries no extra fields, which is every
 * workspace on the day this runs.
 */
create or replace function builtin_extras_write(p_workspace uuid, p_object text, p_id uuid, p_data jsonb, p_partial boolean)
returns void language plpgsql security definer set search_path = public as $$
declare tbl text := builtin_extras_table(p_object); v_new jsonb;
begin
  if tbl is null or p_id is null then return; end if;
  if not builtin_has_extras(p_workspace, p_object) then return; end if;
  v_new := builtin_extras_data(p_workspace, p_object, p_data, p_partial);
  if v_new = '{}'::jsonb then return; end if;
  execute format(
    'update %I set custom_fields = coalesce(custom_fields, ''{}''::jsonb) || $1 where id = $2 and workspace_id = $3', tbl)
    using v_new, p_id, p_workspace;
end $$;

/**
 * The same write, for a caller that has no workspace argument.
 *
 * `update_record` derives tenancy from `p_privy` in SQL rather than taking a
 * `p_workspace` — the asymmetry CLAUDE.md warns against "fixing" — so the
 * workspace has to come from the ROW, and then be checked against the caller's.
 * Reading the workspace off the row and trusting it would let any authenticated
 * user write a field into another tenant's record: the named-column update
 * above would match nothing and the extras write would succeed, which is the
 * quietest possible version of that bug.
 */
create or replace function builtin_extras_write_scoped(p_object text, p_id uuid, p_data jsonb, p_partial boolean, p_my uuid[])
returns void language plpgsql security definer set search_path = public as $$
declare tbl text := builtin_extras_table(p_object); v_ws uuid;
begin
  if tbl is null or p_id is null or p_my is null then return; end if;
  execute format('select workspace_id from %I where id = $1', tbl) into v_ws using p_id;
  if v_ws is null or not (v_ws = any(p_my)) then return; end if;
  perform builtin_extras_write(v_ws, p_object, p_id, p_data, p_partial);
end $$;

/**
 * Merge one row's extras into the json a built-in branch just built.
 *
 * Under the named columns, not over them: a workspace cannot add a field called
 * `amount` and have it shadow the real amount in the CSV feed. `save_custom_field`
 * refuses those keys anyway (see `builtin_reserved_field_key`), and this is the
 * belt to that pair of braces.
 */
create or replace function builtin_extras_add(p_object text, p_id uuid, p_row jsonb)
returns jsonb language plpgsql security definer set search_path = public as $$
declare tbl text := builtin_extras_table(p_object); v_extra jsonb; v_ws uuid;
begin
  if p_row is null or tbl is null then return p_row; end if;
  execute format('select workspace_id, custom_fields from %I where id = $1', tbl) into v_ws, v_extra using p_id;
  if v_ws is null or v_extra is null or v_extra = '{}'::jsonb then return p_row; end if;
  if not builtin_has_extras(v_ws, p_object) then return p_row; end if;
  return v_extra || p_row;
end $$;

/**
 * The same, for a whole list, in one query rather than one per row.
 *
 * Returns the array untouched when the workspace has defined nothing — which
 * keeps the cost of this feature at one cheap EXISTS for everybody who is not
 * using it.
 */
create or replace function builtin_extras_addmany(p_workspace uuid, p_object text, p_rows jsonb)
returns jsonb language plpgsql security definer set search_path = public as $$
declare tbl text := builtin_extras_table(p_object); v_map jsonb;
begin
  if p_rows is null or jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) = 0 then return p_rows; end if;
  if tbl is null or not builtin_has_extras(p_workspace, p_object) then return p_rows; end if;

  execute format(
    'select coalesce(jsonb_object_agg(id::text, custom_fields), ''{}''::jsonb)
       from %I where workspace_id = $1 and custom_fields <> ''{}''::jsonb', tbl)
    into v_map using p_workspace;
  if v_map = '{}'::jsonb then return p_rows; end if;

  return (select coalesce(jsonb_agg(
            coalesce(v_map -> (r ->> 'id'), '{}'::jsonb) || r
            order by ord), '[]'::jsonb)
          from jsonb_array_elements(p_rows) with ordinality as t(r, ord));
end $$;

/**
 * Keys a workspace may not claim on a built-in.
 *
 * A field whose key collides with a real column would be written into the jsonb
 * and then shadowed by the column on the way out — stored, never shown, and
 * impossible to explain. Refusing the key at definition time makes that
 * impossible rather than merely confusing, the same reasoning as
 * `reserved_object_slug`.
 *
 * The list is every key any built-in branch emits, in one set rather than per
 * object: a workspace does not think in terms of which of eleven functions
 * mentions `status`, and a single conservative list costs a few names nobody
 * wanted.
 */
create or replace function builtin_reserved_field_key(p_key text)
returns boolean language sql immutable as $$
  select lower(coalesce(p_key, '')) in (
    'id','created_at','updated_at','workspace_id','custom_fields','name','title',
    'first_name','last_name','email','phone','company','domain','industry',
    'employee_count','tax_id','address','country','source','synergy',
    'number','organization_id','kind','direction','amount','currency','status',
    'category','issued_at','due_at','due_date','notes','vendor','spent_at',
    'txn_date','description','method','tax_rate','bank_account_id','account',
    'matched_invoice_id','matched_expense_id','sku','unit_price','unit','image',
    'image_url','channel','budget','spend','leads','starts_on','ends_on',
    'identifier','issues','project','priority','assignee','serial_number',
    'assigned_to','assigned_to_person_id','purchased_at'
  );
$$;

-- ── Managing it ─────────────────────────────────────────────────────────────
/**
 * Add or change a field on a BUILT-IN object.
 *
 * A sibling of `save_custom_field` rather than a parameter on it: adding one
 * would create an overload (the trap this project has hit four times), and the
 * two differ in what they refuse. There is no `p_primary` here — a built-in
 * already has a headline column in its own table, and letting a workspace point
 * it at a jsonb key would break every join that resolves a record to a name.
 *
 * Both write the same table, with the same types and the same coercion, so
 * there is one field vocabulary and not two.
 */
create or replace function save_builtin_field(
  p_privy text, p_workspace uuid, p_slug text, p_id uuid,
  p_key text, p_label text, p_type text,
  p_options text[] default '{}', p_relation_to text default null,
  p_required boolean default false, p_position int default null
) returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid; v_key text; v_slug text := builtin_object_slug(p_slug);
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  if workspace_role(p_privy, p_workspace) not in ('owner','admin') then
    raise exception 'FORBIDDEN: only an owner or admin can change fields';
  end if;
  -- Only objects whose rows have somewhere to put the value. Refusing here
  -- rather than at write time is what stops a field being defined, shown in the
  -- form, filled in by somebody, and dropped on save.
  if builtin_extras_table(v_slug) is null then raise exception 'UNKNOWN_OBJECT: %', p_slug; end if;

  v_key := lower(btrim(coalesce(p_key, '')));
  if v_key !~ '^[a-z][a-z0-9_]{0,30}$' then
    raise exception 'BAD_FIELD_KEY: use lowercase letters, numbers and underscores';
  end if;
  if builtin_reserved_field_key(v_key) then raise exception 'RESERVED_FIELD_KEY: %', v_key; end if;
  if p_type not in ('text','long_text','number','currency','date','checkbox',
                    'select','email','url','phone','relation') then
    raise exception 'BAD_FIELD_TYPE: %', p_type;
  end if;

  if p_id is null then
    insert into custom_fields (builtin_slug, workspace_id, key, label, type, options, relation_to,
                               required, is_primary, position)
    values (v_slug, p_workspace, v_key,
            coalesce(nullif(btrim(p_label), ''), initcap(replace(v_key, '_', ' '))),
            p_type, coalesce(p_options, '{}'), nullif(p_relation_to, ''),
            coalesce(p_required, false), false,
            coalesce(p_position, (select coalesce(max(position), 0) + 1 from custom_fields
                                   where workspace_id = p_workspace and builtin_slug = v_slug)))
    returning id into v_id;
  else
    update custom_fields
       set key = v_key,
           label = coalesce(nullif(btrim(p_label), ''), label),
           type = p_type, options = coalesce(p_options, options),
           relation_to = nullif(p_relation_to, ''),
           required = coalesce(p_required, required),
           position = coalesce(p_position, position)
     where id = p_id and workspace_id = p_workspace and builtin_slug = v_slug
    returning id into v_id;
    if v_id is null then raise exception 'NO_SUCH_FIELD'; end if;
  end if;
  return v_id;
end $$;
grant execute on function save_builtin_field(text, uuid, text, uuid, text, text, text, text[], text, boolean, int) to authenticated, anon;

/**
 * Rename, re-icon, re-file or hide a built-in object; relabel and reorder its
 * columns.
 *
 * `p_data ? key` throughout, so a screen that saves one thing does not blank
 * the rest — the rule 0088 was written to fix, applied here from the start.
 * Passing an explicit null CLEARS an override and restores what ships, which is
 * why the columns are nullable rather than defaulted.
 */
create or replace function save_object_override(p_privy text, p_workspace uuid, p_slug text, p_data jsonb)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_slug text := builtin_view_slug(p_slug); v_row object_overrides;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  if workspace_role(p_privy, p_workspace) not in ('owner','admin') then
    raise exception 'FORBIDDEN: only an owner or admin can change objects';
  end if;
  if builtin_extras_table(v_slug) is null then raise exception 'UNKNOWN_OBJECT: %', p_slug; end if;

  insert into object_overrides (workspace_id, slug) values (p_workspace, v_slug)
  on conflict (workspace_id, slug) do nothing;

  update object_overrides set
    singular  = case when p_data ? 'singular'  then nullif(btrim(p_data->>'singular'), '')  else singular end,
    plural    = case when p_data ? 'plural'    then nullif(btrim(p_data->>'plural'), '')    else plural end,
    icon      = case when p_data ? 'icon'      then nullif(btrim(p_data->>'icon'), '')      else icon end,
    group_key = case when p_data ? 'group_key' then nullif(btrim(p_data->>'group_key'), '') else group_key end,
    hidden    = case when p_data ? 'hidden'    then coalesce((p_data->>'hidden')::boolean, false) else hidden end,
    -- Only an array is accepted. A malformed value here would make the column
    -- list unreadable for the object, and falling back to '[]' means "no
    -- overrides", which is the shipped order — the safe answer.
    columns   = case when p_data ? 'columns'
                     then case when jsonb_typeof(p_data->'columns') = 'array' then p_data->'columns' else '[]'::jsonb end
                     else columns end,
    position  = case when p_data ? 'position'  then nullif(p_data->>'position','')::int      else position end
  where workspace_id = p_workspace and slug = v_slug
  returning * into v_row;

  return to_jsonb(v_row);
end $$;
grant execute on function save_object_override(text, uuid, text, jsonb) to authenticated, anon;

/** Back to what ships. A delete, so there is no half-reset state to explain. */
create or replace function reset_object_override(p_privy text, p_workspace uuid, p_slug text)
returns boolean language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  if workspace_role(p_privy, p_workspace) not in ('owner','admin') then
    raise exception 'FORBIDDEN: only an owner or admin can change objects';
  end if;
  delete from object_overrides
   where workspace_id = p_workspace and slug = builtin_view_slug(p_slug);
  -- The FIELDS are deliberately untouched. "Put the name back" and "throw away
  -- a column of data" are different requests, and only one of them is
  -- recoverable by clicking again.
  return found;
end $$;
grant execute on function reset_object_override(text, uuid, text) to authenticated, anon;

/**
 * Everything Settings → Objects and the nav need, in one round trip.
 *
 * One call rather than two because both are read on every page load that draws
 * the sidebar, and a second request there is a second chance for the nav to
 * flash the shipped names before the workspace's own arrive.
 */
create or replace function get_object_settings(p_privy text, p_workspace uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  return jsonb_build_object(
    'overrides', coalesce((select jsonb_agg(to_jsonb(o) order by o.slug)
                             from object_overrides o where o.workspace_id = p_workspace), '[]'::jsonb),
    'fields', coalesce((select jsonb_agg(jsonb_build_object(
                          'id', f.id, 'object', f.builtin_slug, 'key', f.key, 'label', f.label,
                          'type', f.type, 'options', f.options, 'relation_to', f.relation_to,
                          'required', f.required, 'position', f.position)
                        order by f.builtin_slug, f.position, f.key)
                          from custom_fields f
                         where f.workspace_id = p_workspace and f.builtin_slug is not null), '[]'::jsonb)
  );
end $$;
grant execute on function get_object_settings(text, uuid) to authenticated, anon;


-- ── The five, redefined in full ─────────────────────────────────────────────
-- Mechanically identical to 0088/0089/0091 apart from ONE call each: a merge on
-- the way out, a write on the way in. Both are no-ops until a workspace defines
-- a field, so nothing changes for anybody who never opens this screen.
--
-- delete_record is unchanged and deliberately not repeated here — the extras
-- live in a column of the row it already deletes.

create or replace function list_records(p_privy text, p_workspace uuid, p_object text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_obj uuid;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;

  if p_object = 'people' then
    return builtin_extras_addmany(p_workspace, p_object, coalesce((select jsonb_agg(jsonb_build_object(
      'id', pe.id, 'name', trim(coalesce(pe.first_name,'')||' '||coalesce(pe.last_name,'')),
      'title', pe.title, 'company', co.name, 'email', pe.email, 'source', pe.source,
      'synergy', (select ps.overall from psychometrics ps where ps.person_id=pe.id order by ps.assessed_at desc limit 1)
    ) order by pe.created_at desc)
    from people pe left join organizations co on co.id = pe.primary_company_id
    where pe.workspace_id=p_workspace), '[]'::jsonb));

  elsif p_object in ('companies','organizations') then
    return builtin_extras_addmany(p_workspace, p_object, coalesce((select jsonb_agg(jsonb_build_object(
      'id', o.id, 'name', o.name, 'domain', o.domain, 'industry', o.industry, 'employee_count', o.employee_count,
      'tax_id', o.tax_id, 'address', o.address, 'country', o.country
    ) order by o.created_at desc) from organizations o where o.workspace_id=p_workspace), '[]'::jsonb));

  elsif p_object = 'invoices' then
    return builtin_extras_addmany(p_workspace, p_object, coalesce((select jsonb_agg(jsonb_build_object(
      'id', i.id, 'number', i.number, 'company', o.name, 'kind', i.kind, 'direction', i.direction,
      'category', i.category, 'amount', i.amount, 'status', i.status, 'due_at', i.due_at
    ) order by i.created_at desc)
    from invoices i left join organizations o on o.id = i.organization_id
    where i.workspace_id=p_workspace), '[]'::jsonb));

  elsif p_object = 'expenses' then
    return builtin_extras_addmany(p_workspace, p_object, coalesce((select jsonb_agg(jsonb_build_object(
      'id', e.id, 'vendor', e.vendor, 'category', e.category, 'amount', e.amount, 'status', e.status, 'spent_at', e.spent_at
    ) order by e.created_at desc) from expenses e where e.workspace_id=p_workspace), '[]'::jsonb));

  elsif p_object = 'transactions' then
    return builtin_extras_addmany(p_workspace, p_object, coalesce((select jsonb_agg(jsonb_build_object(
      'id', t.id, 'txn_date', t.txn_date, 'description', t.description, 'amount', t.amount, 'currency', t.currency,
      'category', t.category, 'method', t.method, 'status', t.status, 'tax_rate', t.tax_rate,
      'account', ba.name, 'bank_account_id', t.bank_account_id,
      'matched_invoice_id', t.matched_invoice_id, 'matched_expense_id', t.matched_expense_id
    ) order by t.txn_date desc, t.created_at desc)
    from transactions t left join bank_accounts ba on ba.id = t.bank_account_id
    where t.workspace_id=p_workspace), '[]'::jsonb));

  elsif p_object = 'products' then
    return builtin_extras_addmany(p_workspace, p_object, coalesce((select jsonb_agg(jsonb_build_object(
      'id', p.id, 'name', p.name, 'image', p.image_url, 'sku', p.sku, 'category', p.category, 'unit_price', p.unit_price, 'unit', p.unit
    ) order by p.created_at desc) from products p where p.workspace_id=p_workspace), '[]'::jsonb));

  elsif p_object = 'campaigns' then
    return builtin_extras_addmany(p_workspace, p_object, coalesce((select jsonb_agg(jsonb_build_object(
      'id', c.id, 'name', c.name, 'channel', c.channel, 'status', c.status,
      'budget', c.budget, 'spend', c.spend, 'leads', c.leads, 'starts_on', c.starts_on, 'ends_on', c.ends_on
    ) order by c.created_at desc) from campaigns c where c.workspace_id=p_workspace), '[]'::jsonb));

  elsif p_object = 'projects' then
    return builtin_extras_addmany(p_workspace, p_object, coalesce((select jsonb_agg(jsonb_build_object(
      'id', pr.id, 'name', pr.name, 'identifier', pr.identifier, 'status', pr.status,
      'issues', (select count(*) from issues i where i.project_id = pr.id)
    ) order by pr.created_at desc) from projects pr where pr.workspace_id=p_workspace), '[]'::jsonb));

  elsif p_object = 'issues' then
    return builtin_extras_addmany(p_workspace, p_object, coalesce((select jsonb_agg(jsonb_build_object(
      'id', i.id, 'name', i.title, 'project', pr.name, 'status', i.status,
      'priority', i.priority, 'due_date', i.due_date,
      'assignee', (select a.full_name from accounts a where a.id = i.assignee_account_id)
    ) order by i.sort_order)
    from issues i left join projects pr on pr.id = i.project_id
    where i.workspace_id=p_workspace), '[]'::jsonb));

  elsif p_object = 'assets' then
    return builtin_extras_addmany(p_workspace, p_object, coalesce((select jsonb_agg(jsonb_build_object(
      'id', a.id, 'name', a.name, 'category', a.category, 'serial_number', a.serial_number, 'status', a.status,
      'assigned_to', (select trim(coalesce(pe.first_name,'')||' '||coalesce(pe.last_name,'')) from people pe where pe.id=a.assigned_to_person_id)
    ) order by a.created_at desc) from assets a where a.workspace_id=p_workspace), '[]'::jsonb));
  end if;

  -- ── Custom objects (0087) ──────────────────────────────────────────────────
  -- LAST, after every built-in has matched. That ordering is the safety
  -- property: a custom object can never shadow a built-in one, whatever it is
  -- called. reserved_object_slug refuses the name at creation too, so the
  -- collision is impossible rather than merely lost.
  v_obj := (select id from custom_objects
             where workspace_id = p_workspace and slug = p_object and enabled);
  if v_obj is not null then
    return coalesce((select jsonb_agg(
      -- id and name are spliced on top of the row's own data, so a custom
      -- object presents the same shape as a built-in one and every consumer
      -- (the table, the CSV feed, the agent tools) works unchanged.
      -- Links resolved to names (0089), then id and name spliced on top, so a
      -- custom object presents the same shape as a built-in one and every
      -- consumer (the table, the CSV feed, the agent tools) works unchanged.
      r.data
        || custom_relation_labels(p_workspace, v_obj, r.data)
        || jsonb_build_object('id', r.id, 'name', custom_record_label(v_obj, r.data))
      order by r.created_at desc
    ) from custom_records r where r.object_id = v_obj), '[]'::jsonb);
  end if;

  return '[]'::jsonb;
end $$;
grant execute on function list_records(text, uuid, text) to authenticated, anon;

create or replace function get_record(p_privy text, p_object text, p_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare my uuid[] := (select array_agg(workspace_id) from accounts where privy_user_id = p_privy);
begin
  if p_object in ('companies','organizations') then
    return builtin_extras_add(p_object, p_id, (select to_jsonb(t) from (select id, name, domain, industry, employee_count, tax_id, address, country from organizations where id=p_id and workspace_id = any(my)) t));
  elsif p_object = 'people' then
    return builtin_extras_add(p_object, p_id, (select to_jsonb(t) from (select id, first_name, last_name, email, phone, title, source from people where id=p_id and workspace_id = any(my)) t));
  elsif p_object = 'invoices' then
    return builtin_extras_add(p_object, p_id, (select to_jsonb(t) from (select id, number, organization_id, kind, direction, amount, status, category, issued_at, due_at, notes from invoices where id=p_id and workspace_id = any(my)) t));
  elsif p_object = 'expenses' then
    return builtin_extras_add(p_object, p_id, (select to_jsonb(t) from (select id, vendor, category, amount, status, spent_at, notes from expenses where id=p_id and workspace_id = any(my)) t));
  elsif p_object = 'transactions' then
    return builtin_extras_add(p_object, p_id, (select to_jsonb(t) from (select id, txn_date, description, amount, currency, category, method, status, tax_rate, bank_account_id, notes from transactions where id=p_id and workspace_id = any(my)) t));
  elsif p_object = 'products' then
    return builtin_extras_add(p_object, p_id, (select to_jsonb(t) from (select id, name, sku, description, unit_price, unit, category, image_url from products where id=p_id and workspace_id = any(my)) t));
  elsif p_object = 'campaigns' then
    return builtin_extras_add(p_object, p_id, (select to_jsonb(t) from (select id, name, channel, status, budget, spend, leads, starts_on, ends_on, notes from campaigns where id=p_id and workspace_id = any(my)) t));
  elsif p_object = 'projects' then
    return builtin_extras_add(p_object, p_id, (select to_jsonb(t) from (select id, name, identifier, status, description from projects where id=p_id and workspace_id = any(my)) t));
  elsif p_object = 'issues' then
    return builtin_extras_add(p_object, p_id, (select to_jsonb(t) from (select id, title, status, priority, due_date, description from issues where id=p_id and workspace_id = any(my)) t));
  elsif p_object = 'assets' then
    return builtin_extras_add(p_object, p_id, (select to_jsonb(t) from (select id, name, category, serial_number, status, assigned_to_person_id, purchased_at, notes from assets where id=p_id and workspace_id = any(my)) t));
  end if;

  -- ── Custom objects (0087) ──────────────────────────────────────────────────
  -- Tenancy comes from `my` in SQL, exactly like every branch above: a foreign
  -- record id resolves to no row rather than to someone else's data.
  return (select r.data
                   || custom_relation_labels(o.workspace_id, r.object_id, r.data)
                   || jsonb_build_object('id', r.id,
                        'name', custom_record_label(r.object_id, r.data))
            from custom_records r
            join custom_objects o on o.id = r.object_id
           where r.id = p_id and o.slug = p_object and r.workspace_id = any(my));
end $$;
grant execute on function get_record(text, text, uuid) to authenticated, anon;

create or replace function create_record(p_privy text, p_workspace uuid, p_object text, p_data jsonb)
returns uuid language plpgsql security definer set search_path = public as $$
declare v_obj uuid; v_id uuid;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  if p_object in ('companies','organizations') then
    insert into organizations (workspace_id, name, domain, industry, employee_count, tax_id, address, country)
    values (p_workspace, p_data->>'name', nullif(p_data->>'domain',''), nullif(p_data->>'industry',''), nullif(p_data->>'employee_count','')::int,
            nullif(p_data->>'tax_id',''), nullif(p_data->>'address',''), nullif(p_data->>'country',''))
    returning id into v_id;
  elsif p_object = 'people' then
    insert into people (workspace_id, first_name, last_name, email, phone, title, source)
    values (p_workspace, p_data->>'first_name', nullif(p_data->>'last_name',''), nullif(p_data->>'email',''), nullif(p_data->>'phone',''), nullif(p_data->>'title',''), nullif(p_data->>'source',''))
    returning id into v_id;
  elsif p_object = 'invoices' then
    insert into invoices (workspace_id, number, organization_id, kind, direction, amount, status, category, issued_at, due_at, notes)
    values (p_workspace, nullif(p_data->>'number',''), nullif(p_data->>'organization_id','')::uuid, coalesce(nullif(p_data->>'kind',''),'invoice'), coalesce(nullif(p_data->>'direction',''),'income'),
            coalesce(nullif(p_data->>'amount','')::numeric,0), coalesce(nullif(p_data->>'status',''),'draft'), nullif(p_data->>'category',''),
            nullif(p_data->>'issued_at','')::date, nullif(p_data->>'due_at','')::date, nullif(p_data->>'notes',''))
    returning id into v_id;
  elsif p_object = 'expenses' then
    insert into expenses (workspace_id, vendor, category, amount, status, spent_at, notes)
    values (p_workspace, nullif(p_data->>'vendor',''), coalesce(nullif(p_data->>'category',''),'other'), coalesce(nullif(p_data->>'amount','')::numeric,0), coalesce(nullif(p_data->>'status',''),'pending'), nullif(p_data->>'spent_at','')::date, nullif(p_data->>'notes',''))
    returning id into v_id;
  elsif p_object = 'transactions' then
    insert into transactions (workspace_id, bank_account_id, txn_date, description, amount, currency, category, method, status, tax_rate, tags, notes)
    values (p_workspace, nullif(p_data->>'bank_account_id','')::uuid,
            coalesce(nullif(p_data->>'txn_date','')::date, now()::date), nullif(p_data->>'description',''),
            coalesce(nullif(regexp_replace(coalesce(p_data->>'amount',''), '[^0-9.-]', '', 'g'),'')::numeric, 0),
            coalesce(nullif(p_data->>'currency',''),'USD'), nullif(p_data->>'category',''),
            coalesce(nullif(p_data->>'method',''),'transfer'), coalesce(nullif(p_data->>'status',''),'posted'),
            nullif(p_data->>'tax_rate','')::numeric,
            case when nullif(p_data->>'tags','') is not null then string_to_array(p_data->>'tags', ',') else '{}'::text[] end,
            nullif(p_data->>'notes',''))
    returning id into v_id;
  elsif p_object = 'products' then
    insert into products (workspace_id, name, sku, description, unit_price, unit, category, image_url)
    values (p_workspace, p_data->>'name', nullif(p_data->>'sku',''), nullif(p_data->>'description',''), coalesce(nullif(p_data->>'unit_price','')::numeric,0), nullif(p_data->>'unit',''), nullif(p_data->>'category',''), nullif(p_data->>'image_url',''))
    returning id into v_id;
  elsif p_object = 'campaigns' then
    insert into campaigns (workspace_id, name, channel, status, budget, spend, leads, starts_on, ends_on, notes)
    values (p_workspace, p_data->>'name', coalesce(nullif(p_data->>'channel',''),'email'), coalesce(nullif(p_data->>'status',''),'planned'),
            coalesce(nullif(p_data->>'budget','')::numeric,0), coalesce(nullif(p_data->>'spend','')::numeric,0), coalesce(nullif(p_data->>'leads','')::int,0),
            nullif(p_data->>'starts_on','')::date, nullif(p_data->>'ends_on','')::date, nullif(p_data->>'notes',''))
    returning id into v_id;
  elsif p_object = 'projects' then
    insert into projects (workspace_id, name, identifier, status, description)
    values (p_workspace, p_data->>'name', nullif(p_data->>'identifier',''), coalesce(nullif(p_data->>'status',''),'active'), nullif(p_data->>'description',''))
    returning id into v_id;
  elsif p_object = 'issues' then
    insert into issues (workspace_id, title, status, priority, due_date, description)
    values (p_workspace, p_data->>'title', coalesce(nullif(p_data->>'status',''),'backlog'), coalesce(nullif(p_data->>'priority',''),'none'), nullif(p_data->>'due_date','')::date, nullif(p_data->>'description',''))
    returning id into v_id;
  elsif p_object = 'assets' then
    -- Entirely new. `assets` appears in list_records and in delete_record's
    -- table map, and it has a nav entry and a page — but it had no create or
    -- update branch, so the Add button on Team → Assets raised UNKNOWN_OBJECT.
    -- The object was readable and deletable and nothing else.
    -- `category` is NOT NULL DEFAULT 'other', and passing an explicit null
    -- OVERRIDES a default rather than falling back to it — so every attempt to
    -- add an asset without picking a category has raised a constraint violation
    -- since 0088 shipped this branch. 0088 fixed the missing branch and the
    -- branch it added was itself broken; the form does not mark category
    -- required, so this is the ordinary path, not an edge case.
    insert into assets (workspace_id, name, category, serial_number, status, notes, assigned_to_person_id)
    values (p_workspace, coalesce(nullif(p_data->>'name',''),'Untitled'), coalesce(nullif(p_data->>'category',''),'other'),
            nullif(p_data->>'serial_number',''), coalesce(nullif(p_data->>'status',''),'available'),
            nullif(p_data->>'notes',''), nullif(p_data->>'assigned_to_person_id','')::uuid)
    returning id into v_id;
  else
    -- ── Custom objects (0087) ────────────────────────────────────────────────
    v_obj := (select id from custom_objects
               where workspace_id = p_workspace and slug = p_object and enabled);
    if v_obj is null then raise exception 'UNKNOWN_OBJECT: %', p_object; end if;
    -- build_custom_data validates every value against its field and drops
    -- anything undeclared, so a payload cannot widen the row's shape.
    insert into custom_records (workspace_id, object_id, data, created_by_privy)
    values (p_workspace, v_obj, build_custom_data(v_obj, coalesce(p_data, '{}'::jsonb)), p_privy)
    returning id into v_id;
  end if;
  -- Fields this workspace added to a built-in object (0097). v_obj is set only
  -- by the custom-object branch, so this runs for built-ins and nothing else —
  -- a custom object's values were already validated by build_custom_data.
  if v_obj is null then
    perform builtin_extras_write(p_workspace, p_object, v_id, coalesce(p_data, '{}'::jsonb), false);
  end if;
  return v_id;
end $$;

grant execute on function create_record(text, uuid, text, jsonb) to authenticated, anon;

create or replace function update_record(p_privy text, p_object text, p_id uuid, p_data jsonb)
returns void language plpgsql security definer set search_path = public as $$
declare v_id uuid; v_obj uuid; v_existing jsonb; my uuid[] := (select array_agg(workspace_id) from accounts where privy_user_id = p_privy);
begin
  if p_object in ('companies','organizations') then
    update organizations set
      name           = case when p_data ? 'name' then coalesce(nullif(p_data->>'name',''), name) else name end,
      domain         = case when p_data ? 'domain' then nullif(p_data->>'domain','') else domain end,
      industry       = case when p_data ? 'industry' then nullif(p_data->>'industry','') else industry end,
      employee_count = case when p_data ? 'employee_count' then nullif(p_data->>'employee_count','')::int else employee_count end,
      tax_id         = case when p_data ? 'tax_id' then nullif(p_data->>'tax_id','') else tax_id end,
      address        = case when p_data ? 'address' then nullif(p_data->>'address','') else address end,
      country        = case when p_data ? 'country' then nullif(p_data->>'country','') else country end
    where id=p_id and workspace_id = any(my);

  elsif p_object = 'people' then
    update people set
      first_name = case when p_data ? 'first_name' then nullif(p_data->>'first_name','') else first_name end,
      last_name  = case when p_data ? 'last_name' then nullif(p_data->>'last_name','') else last_name end,
      email      = case when p_data ? 'email' then nullif(p_data->>'email','') else email end,
      phone      = case when p_data ? 'phone' then nullif(p_data->>'phone','') else phone end,
      title      = case when p_data ? 'title' then nullif(p_data->>'title','') else title end,
      source     = case when p_data ? 'source' then nullif(p_data->>'source','') else source end,
      -- New here: a person could be attached to a company at creation and never
      -- moved afterwards, because this column was absent from the update path.
      primary_company_id = case when p_data ? 'primary_company_id'
                                then nullif(p_data->>'primary_company_id','')::uuid
                                else primary_company_id end
    where id=p_id and workspace_id = any(my);

  elsif p_object = 'invoices' then
    update invoices set
      number          = case when p_data ? 'number' then nullif(p_data->>'number','') else number end,
      organization_id = case when p_data ? 'organization_id' then nullif(p_data->>'organization_id','')::uuid else organization_id end,
      kind            = case when p_data ? 'kind' then coalesce(nullif(p_data->>'kind',''), kind) else kind end,
      direction       = case when p_data ? 'direction' then coalesce(nullif(p_data->>'direction',''), direction) else direction end,
      amount          = case when p_data ? 'amount' then coalesce(nullif(p_data->>'amount','')::numeric, amount) else amount end,
      status          = case when p_data ? 'status' then coalesce(nullif(p_data->>'status',''), status) else status end,
      category        = case when p_data ? 'category' then nullif(p_data->>'category','') else category end,
      issued_at       = case when p_data ? 'issued_at' then nullif(p_data->>'issued_at','')::date else issued_at end,
      due_at          = case when p_data ? 'due_at' then nullif(p_data->>'due_at','')::date else due_at end,
      notes           = case when p_data ? 'notes' then nullif(p_data->>'notes','') else notes end
    where id=p_id and workspace_id = any(my);

  elsif p_object = 'expenses' then
    update expenses set
      vendor   = case when p_data ? 'vendor' then nullif(p_data->>'vendor','') else vendor end,
      category = case when p_data ? 'category' then coalesce(nullif(p_data->>'category',''), category) else category end,
      amount   = case when p_data ? 'amount' then coalesce(nullif(p_data->>'amount','')::numeric, amount) else amount end,
      status   = case when p_data ? 'status' then coalesce(nullif(p_data->>'status',''), status) else status end,
      spent_at = case when p_data ? 'spent_at' then nullif(p_data->>'spent_at','')::date else spent_at end,
      notes    = case when p_data ? 'notes' then nullif(p_data->>'notes','') else notes end
    where id=p_id and workspace_id = any(my);

  elsif p_object = 'transactions' then
    -- Unchanged. This branch was already correct, and is what the rest of the
    -- function has now been made to match.
    update transactions set
      bank_account_id = case when p_data ? 'bank_account_id' then nullif(p_data->>'bank_account_id','')::uuid else bank_account_id end,
      txn_date = coalesce(nullif(p_data->>'txn_date','')::date, txn_date),
      description = case when p_data ? 'description' then nullif(p_data->>'description','') else description end,
      amount = coalesce(nullif(regexp_replace(coalesce(p_data->>'amount',''), '[^0-9.-]', '', 'g'),'')::numeric, amount),
      category = case when p_data ? 'category' then nullif(p_data->>'category','') else category end,
      method = coalesce(nullif(p_data->>'method',''), method),
      status = coalesce(nullif(p_data->>'status',''), status),
      tax_rate = case when p_data ? 'tax_rate' then nullif(p_data->>'tax_rate','')::numeric else tax_rate end,
      notes = case when p_data ? 'notes' then nullif(p_data->>'notes','') else notes end
    where id=p_id and workspace_id = any(my);

  elsif p_object = 'products' then
    update products set
      name        = case when p_data ? 'name' then coalesce(nullif(p_data->>'name',''), name) else name end,
      sku         = case when p_data ? 'sku' then nullif(p_data->>'sku','') else sku end,
      description = case when p_data ? 'description' then nullif(p_data->>'description','') else description end,
      unit_price  = case when p_data ? 'unit_price' then coalesce(nullif(p_data->>'unit_price','')::numeric, unit_price) else unit_price end,
      unit        = case when p_data ? 'unit' then nullif(p_data->>'unit','') else unit end,
      category    = case when p_data ? 'category' then nullif(p_data->>'category','') else category end,
      image_url   = case when p_data ? 'image_url' then nullif(p_data->>'image_url','') else image_url end
    where id=p_id and workspace_id = any(my);

  elsif p_object = 'campaigns' then
    update campaigns set
      name      = case when p_data ? 'name' then coalesce(nullif(p_data->>'name',''), name) else name end,
      channel   = case when p_data ? 'channel' then coalesce(nullif(p_data->>'channel',''), channel) else channel end,
      status    = case when p_data ? 'status' then coalesce(nullif(p_data->>'status',''), status) else status end,
      budget    = case when p_data ? 'budget' then coalesce(nullif(p_data->>'budget','')::numeric, budget) else budget end,
      spend     = case when p_data ? 'spend' then coalesce(nullif(p_data->>'spend','')::numeric, spend) else spend end,
      leads     = case when p_data ? 'leads' then coalesce(nullif(p_data->>'leads','')::int, leads) else leads end,
      starts_on = case when p_data ? 'starts_on' then nullif(p_data->>'starts_on','')::date else starts_on end,
      ends_on   = case when p_data ? 'ends_on' then nullif(p_data->>'ends_on','')::date else ends_on end,
      notes     = case when p_data ? 'notes' then nullif(p_data->>'notes','') else notes end
    where id=p_id and workspace_id = any(my);

  elsif p_object = 'projects' then
    update projects set
      name        = case when p_data ? 'name' then coalesce(nullif(p_data->>'name',''), name) else name end,
      identifier  = case when p_data ? 'identifier' then nullif(p_data->>'identifier','') else identifier end,
      status      = case when p_data ? 'status' then coalesce(nullif(p_data->>'status',''), status) else status end,
      description = case when p_data ? 'description' then nullif(p_data->>'description','') else description end
    where id=p_id and workspace_id = any(my);

  elsif p_object = 'issues' then
    update issues set
      title       = case when p_data ? 'title' then coalesce(nullif(p_data->>'title',''), title) else title end,
      status      = case when p_data ? 'status' then coalesce(nullif(p_data->>'status',''), status) else status end,
      priority    = case when p_data ? 'priority' then coalesce(nullif(p_data->>'priority',''), priority) else priority end,
      due_date    = case when p_data ? 'due_date' then nullif(p_data->>'due_date','')::date else due_date end,
      description = case when p_data ? 'description' then nullif(p_data->>'description','') else description end,
      -- New here, same reason as people.primary_company_id.
      project_id  = case when p_data ? 'project_id' then nullif(p_data->>'project_id','')::uuid else project_id end
    where id=p_id and workspace_id = any(my);

  elsif p_object = 'assets' then
    -- Entirely new: `assets` had no update branch at all, so it fell through to
    -- the UNKNOWN_OBJECT error and an asset could never be edited.
    update assets set
      name          = case when p_data ? 'name' then coalesce(nullif(p_data->>'name',''), name) else name end,
      category      = case when p_data ? 'category' then nullif(p_data->>'category','') else category end,
      serial_number = case when p_data ? 'serial_number' then nullif(p_data->>'serial_number','') else serial_number end,
      status        = case when p_data ? 'status' then coalesce(nullif(p_data->>'status',''), status) else status end,
      notes         = case when p_data ? 'notes' then nullif(p_data->>'notes','') else notes end,
      assigned_to_person_id = case when p_data ? 'assigned_to_person_id'
                                   then nullif(p_data->>'assigned_to_person_id','')::uuid
                                   else assigned_to_person_id end
    where id=p_id and workspace_id = any(my);

  else
    -- ── Custom objects (0087) ────────────────────────────────────────────────
    select r.id, r.object_id, r.data into v_id, v_obj, v_existing
      from custom_records r join custom_objects o on o.id = r.object_id
     where r.id = p_id and o.slug = p_object and r.workspace_id = any(my);
    if v_id is null then raise exception 'UNKNOWN_OBJECT: %', p_object; end if;
    update custom_records set data = build_custom_data(v_obj, coalesce(p_data, '{}'::jsonb), v_existing)
     where id = v_id;
  end if;

  -- Fields this workspace added to a built-in object (0097). Partial, matching
  -- the named columns above: a key that is absent leaves its value alone.
  if v_obj is null then
    perform builtin_extras_write(
      (select workspace_id from accounts where privy_user_id = p_privy and workspace_id = any(my) limit 1),
      p_object, p_id, coalesce(p_data, '{}'::jsonb), true);
  end if;
end $$;
grant execute on function update_record(text, text, uuid, jsonb) to authenticated, anon;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0098_email_blocks.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0098_email_blocks.sql
-- A fourth newsletter template: the one you build yourself.
--
-- ── WHY A FOURTH RATHER THAN A BUILDER ──────────────────────────────────────
-- 0070 shipped three fixed layouts and a comment explaining why there was no
-- drag-and-drop builder: a canvas produces nested-table HTML that has to be
-- maintained against every client's rendering quirks forever, and the output is
-- reliably worse than a good fixed layout. That argument still holds and this
-- does not contradict it.
--
-- What it adds is a LINEAR LIST OF TYPED BLOCKS. Stack only — no canvas, no
-- absolute positioning, no arbitrary HTML nesting. Every block is rendered by
-- the one renderer we already maintain, into the same 600px table shell with
-- the same inline styles, the same preheader, the same unsubscribe footer and
-- the same tracking pixel. So the composable half is the ORDER and the CHOICE
-- of blocks, and the fragile half — what the HTML actually is — stays ours.
--
-- ── ALL THE VALIDATION THAT MATTERS IS IN THE RENDERER, NOT HERE ────────────
-- `content` has been free-form jsonb since 0070 and stays that way. A CHECK
-- constraint describing a block list would have to be kept in step with
-- TypeScript by hand, and the failure mode is a save that raises at 2am rather
-- than a block that renders as nothing. The renderer drops what it does not
-- recognise, escapes every string and refuses any URL that is not http(s) —
-- which is the boundary that actually protects a recipient's inbox.
--
-- The only thing SQL must change is the CHECK on `template`, which is a closed
-- vocabulary, and `save_newsletter`, which silently rewrites an unknown
-- template to 'plain' — so without this a workspace could build a block email,
-- press save, and get a plain one back with no error at all.
--
-- Depends on 0070. Idempotent & prod-safe.
-- ============================================================================

alter table newsletters drop constraint if exists newsletters_template_check;
alter table newsletters add constraint newsletters_template_check
  check (template in ('plain', 'announcement', 'digest', 'blocks'));

/**
 * Redefined IN FULL from 0070 — the only change is 'blocks' in the two
 * whitelists.
 *
 * Note what those whitelists do on a miss: INSERT falls back to 'plain' and
 * UPDATE keeps the existing value. Both are deliberate and neither raises,
 * because this argument comes from a client that may be a version behind. That
 * is also exactly why this migration exists rather than the app simply sending
 * the new value: the fallback is silent by design, so a missing whitelist entry
 * costs somebody their layout without ever reporting an error.
 */
create or replace function save_newsletter(
  p_privy text, p_workspace uuid, p_id uuid, p_subject text, p_preheader text,
  p_template text, p_content jsonb, p_from_name text, p_reply_to text, p_list_ids uuid[]
) returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid; v_status text;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  -- Unchanged at 512 KB. A block list is bigger than a plain body but not by
  -- an order of magnitude, and the cap is what stops `content` becoming a
  -- place to paste an entire base64 image into every row of the table.
  if pg_column_size(coalesce(p_content, '{}'::jsonb)) > 524288 then raise exception 'CONTENT_TOO_LARGE'; end if;

  if p_id is null then
    insert into newsletters (workspace_id, subject, preheader, template, content, from_name, reply_to, created_by_privy)
    values (p_workspace, coalesce(p_subject,''), coalesce(p_preheader,''),
            case when p_template in ('plain','announcement','digest','blocks') then p_template else 'plain' end,
            coalesce(p_content,'{}'::jsonb), coalesce(p_from_name,''), coalesce(p_reply_to,''), p_privy)
    returning id into v_id;
  else
    select status into v_status from newsletters where id = p_id and workspace_id = p_workspace;
    if v_status is null then return null; end if;
    if v_status in ('sending','sent') then raise exception 'ALREADY_SENT'; end if;
    update newsletters set
      subject = coalesce(p_subject, subject), preheader = coalesce(p_preheader, preheader),
      template = case when p_template in ('plain','announcement','digest','blocks') then p_template else template end,
      content = coalesce(p_content, content),
      from_name = coalesce(p_from_name, from_name), reply_to = coalesce(p_reply_to, reply_to)
    where id = p_id and workspace_id = p_workspace
    returning id into v_id;
  end if;

  if p_list_ids is not null then
    delete from newsletter_targets where newsletter_id = v_id;
    -- Only lists in THIS workspace survive, so a foreign list id cannot be
    -- stapled on to make a send reach another tenant's subscribers.
    insert into newsletter_targets (newsletter_id, list_id)
    select v_id, l.id from newsletter_lists l
     where l.workspace_id = p_workspace and l.id = any(p_list_ids)
    on conflict do nothing;
  end if;
  return v_id;
end $$;
grant execute on function save_newsletter(text, uuid, uuid, text, text, text, jsonb, text, text, uuid[]) to authenticated, anon;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0099_oauth_mcp.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0099_oauth_mcp.sql
-- OAuth 2.1 for the MCP server, so runbutter.app can be added to Claude with a
-- URL and a login instead of a config file and a pasted key.
--
-- ── WHY ─────────────────────────────────────────────────────────────────────
-- `/api/mcp` has been a correct MCP server since it shipped, and it authenticates
-- with `Authorization: Bearer hb_…` — the same workspace API keys as /api/v1.
-- That works for Claude Code, Claude Desktop and Cursor, which read a config
-- file and can send arbitrary headers.
--
-- It does NOT work for claude.ai's connector flow, which takes a URL, discovers
-- the authorization server, and sends the human through a login. There is
-- nowhere to paste a static key. So the server was reachable by developers and
-- unreachable by everybody else, and that is a gap in us rather than a
-- limitation of the client.
--
-- ── THE HUMAN IS ALREADY AUTHENTICATED; THIS IS ABOUT DELEGATION ────────────
-- Privy says who the person is. What was missing is a way for that person to
-- hand ONE workspace to ONE client with a scope, and to take it back. So the
-- authorize screen is an ordinary app page behind the ordinary Privy session,
-- and the token it mints is the same shape `resolve_api_key` already returns:
-- a workspace, an owner, a scope. Nothing downstream had to learn a new idea.
--
-- ── EVERY SECRET IS STORED HASHED ───────────────────────────────────────────
-- Authorization codes, access tokens and refresh tokens are all kept as SHA-256
-- hashes, exactly like `api_keys.key_hash` (0078). A database dump is then not a
-- set of live credentials, and this table is more attractive than most: a token
-- here is a standing grant to a whole workspace.
--
-- ── PKCE IS REQUIRED, NOT OPTIONAL ──────────────────────────────────────────
-- OAuth 2.1 removes the implicit flow and requires PKCE for every authorization
-- code. Registered clients are PUBLIC (`token_endpoint_auth_method = 'none'`) —
-- a desktop client or a browser cannot keep a client secret, and pretending
-- otherwise is what made OAuth 2.0's public-client story unsafe. PKCE is what
-- actually binds the code to the client that asked for it.
--
-- Depends on 0001 and 0078. Idempotent & prod-safe.
-- ============================================================================

-- ── Clients, registered dynamically (RFC 7591) ──────────────────────────────
/**
 * A client registers ITSELF. There is no admin screen and no allowlist, which
 * is the point of RFC 7591: claude.ai has never heard of this deployment and
 * this deployment has never heard of claude.ai, and neither should have to.
 *
 * That is safe only because a registered client can do NOTHING on its own. It
 * cannot read a workspace, cannot mint a token, and cannot get past
 * /oauth/authorize without a signed-in human choosing a workspace and pressing
 * a button. Registration buys a client_id and a promise about redirect_uris —
 * nothing else.
 */
create table if not exists oauth_clients (
  id             uuid primary key default gen_random_uuid(),
  client_id      text not null unique,
  client_name    text not null default '',
  client_uri     text,
  logo_uri       text,
  -- Exact-match only, no wildcards, no prefix matching. A redirect_uri that is
  -- compared loosely is how an authorization code ends up at somebody else's
  -- host, and it is the single most exploited weakness in OAuth deployments.
  redirect_uris  text[] not null default '{}',
  -- 'none' — public clients with PKCE. Stored rather than assumed so a future
  -- confidential client is a column change, not a rewrite.
  token_endpoint_auth_method text not null default 'none',
  created_at     timestamptz not null default now(),
  last_used_at   timestamptz
);
alter table oauth_clients enable row level security;
revoke all on table oauth_clients from anon, authenticated;

-- ── Authorization codes ─────────────────────────────────────────────────────
create table if not exists oauth_authorizations (
  id             uuid primary key default gen_random_uuid(),
  code_hash      text not null unique,
  client_id      text not null,
  workspace_id   uuid not null references workspaces(id) on delete cascade,
  owner_privy    text not null,
  redirect_uri   text not null,
  scope          text not null default 'full',
  -- PKCE. S256 only: `plain` is in the spec and is worth nothing, because a
  -- verifier that equals its own challenge protects against nobody who can see
  -- the request.
  code_challenge text not null,
  -- Codes are single-use and short-lived. `used_at` rather than a delete so a
  -- REPLAYED code is distinguishable from an expired one — the spec says a
  -- replayed code should revoke the tokens already issued from it, and that is
  -- only possible if the row is still there.
  used_at        timestamptz,
  expires_at     timestamptz not null default now() + interval '10 minutes',
  created_at     timestamptz not null default now()
);
alter table oauth_authorizations enable row level security;
revoke all on table oauth_authorizations from anon, authenticated;
create index if not exists idx_oauth_auth_expiry on oauth_authorizations(expires_at);

-- ── Tokens ──────────────────────────────────────────────────────────────────
create table if not exists oauth_tokens (
  id             uuid primary key default gen_random_uuid(),
  token_hash     text not null unique,
  refresh_hash   text unique,
  client_id      text not null,
  workspace_id   uuid not null references workspaces(id) on delete cascade,
  owner_privy    text not null,
  scope          text not null default 'full',
  -- Which code minted this, so replaying that code can revoke its descendants.
  authorization_id uuid references oauth_authorizations(id) on delete set null,
  expires_at     timestamptz not null,
  refresh_expires_at timestamptz,
  revoked_at     timestamptz,
  last_used_at   timestamptz,
  created_at     timestamptz not null default now()
);
alter table oauth_tokens enable row level security;
revoke all on table oauth_tokens from anon, authenticated;
create index if not exists idx_oauth_tokens_ws on oauth_tokens(workspace_id, created_at desc);
create index if not exists idx_oauth_tokens_owner on oauth_tokens(owner_privy);

-- ── Registration ────────────────────────────────────────────────────────────
create or replace function oauth_register_client(
  p_client_name text, p_redirect_uris text[], p_client_uri text default null, p_logo_uri text default null
) returns jsonb language plpgsql security definer set search_path = public as $$
declare v_id text; v_uris text[]; u text;
begin
  if p_redirect_uris is null or cardinality(p_redirect_uris) = 0 then
    raise exception 'INVALID_REDIRECT_URI: at least one redirect_uri is required';
  end if;
  if cardinality(p_redirect_uris) > 10 then raise exception 'INVALID_REDIRECT_URI: too many'; end if;

  foreach u in array p_redirect_uris loop
    -- https, or http on loopback. A desktop client legitimately redirects to
    -- 127.0.0.1 on a random port; anything else over plain http would put an
    -- authorization code on the wire in clear.
    -- The third branch is for a private-use scheme (com.example.app:/cb), and
    -- it REQUIRES A DOT IN THE SCHEME. Without that requirement `http` itself
    -- matches `[a-z][a-z0-9+.-]*`, and the branch meant to allow native apps
    -- quietly re-admitted plain http to any host — which the branch above it
    -- exists to forbid. Caught by the test that asserts a plain-http
    -- non-loopback redirect is refused.
    if not (u ~* '^https://[^\s]+$'
            or u ~* '^http://(127\.0\.0\.1|\[::1\]|localhost)(:[0-9]+)?(/[^\s]*)?$'
            or u ~* '^[a-z][a-z0-9+-]*(\.[a-z0-9+-]+)+:/[^\s]*$') then
      raise exception 'INVALID_REDIRECT_URI: %', u;
    end if;
    if length(u) > 2000 then raise exception 'INVALID_REDIRECT_URI: too long'; end if;
  end loop;

  v_uris := p_redirect_uris;
  v_id := 'rbc_' || encode(gen_random_bytes(18), 'hex');
  insert into oauth_clients (client_id, client_name, client_uri, logo_uri, redirect_uris)
  values (v_id, left(coalesce(nullif(btrim(p_client_name), ''), 'Unnamed client'), 120),
          nullif(p_client_uri, ''), nullif(p_logo_uri, ''), v_uris);

  return jsonb_build_object(
    'client_id', v_id,
    'client_name', left(coalesce(nullif(btrim(p_client_name), ''), 'Unnamed client'), 120),
    'redirect_uris', to_jsonb(v_uris),
    'token_endpoint_auth_method', 'none',
    'grant_types', jsonb_build_array('authorization_code', 'refresh_token'),
    'response_types', jsonb_build_array('code')
  );
end $$;
revoke all on function oauth_register_client(text, text[], text, text) from public, anon, authenticated;
grant execute on function oauth_register_client(text, text[], text, text) to service_role;

/** What the authorize screen needs to name the client asking, and to check the redirect. */
create or replace function oauth_get_client(p_client_id text, p_redirect_uri text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_row oauth_clients;
begin
  select * into v_row from oauth_clients where client_id = p_client_id;
  if v_row.id is null then return null; end if;
  return jsonb_build_object(
    'client_id', v_row.client_id, 'client_name', v_row.client_name,
    'client_uri', v_row.client_uri, 'logo_uri', v_row.logo_uri,
    -- EXACT match against the registered list. Never a prefix, never a
    -- wildcard: a loosely compared redirect_uri is how an authorization code
    -- ends up at an attacker's host.
    'redirect_ok', p_redirect_uri = any(v_row.redirect_uris)
  );
end $$;
revoke all on function oauth_get_client(text, text) from public, anon, authenticated;
grant execute on function oauth_get_client(text, text) to service_role;

-- ── Consent → code ──────────────────────────────────────────────────────────
/**
 * Mint an authorization code for a workspace the caller is actually in.
 *
 * The membership check is the whole security of this function: the client
 * supplies a workspace id in the consent POST, and without this a signed-in
 * person could be walked into granting a workspace they do not belong to.
 */
create or replace function oauth_create_authorization(
  p_privy text, p_client_id text, p_workspace uuid, p_redirect_uri text,
  p_code_hash text, p_code_challenge text, p_scope text
) returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid; v_client oauth_clients;
begin
  select * into v_client from oauth_clients where client_id = p_client_id;
  if v_client.id is null then raise exception 'UNKNOWN_CLIENT'; end if;
  if not (p_redirect_uri = any(v_client.redirect_uris)) then raise exception 'INVALID_REDIRECT_URI'; end if;
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  if coalesce(p_code_challenge, '') = '' then raise exception 'PKCE_REQUIRED'; end if;

  insert into oauth_authorizations (code_hash, client_id, workspace_id, owner_privy,
                                    redirect_uri, scope, code_challenge)
  values (p_code_hash, p_client_id, p_workspace, p_privy, p_redirect_uri,
          case when p_scope = 'read' then 'read' else 'full' end, p_code_challenge)
  returning id into v_id;

  update oauth_clients set last_used_at = now() where client_id = p_client_id;
  return v_id;
end $$;
revoke all on function oauth_create_authorization(text, text, uuid, text, text, text, text) from public, anon, authenticated;
grant execute on function oauth_create_authorization(text, text, uuid, text, text, text, text) to service_role;

-- ── Code → tokens ───────────────────────────────────────────────────────────
/**
 * Redeem a code, once.
 *
 * The single-use claim is `update … where used_at is null returning`, which is
 * atomic: two simultaneous redemptions of one code cannot both win, whatever
 * the client does. That matters because a stolen code races the legitimate one.
 *
 * A REPLAY revokes everything that code produced. The spec asks for this and
 * the reasoning is worth keeping: if a code is presented twice, one of the two
 * presenters is not the client that asked for it, and there is no way to tell
 * which — so the safe answer is that neither keeps the tokens.
 *
 * The PKCE verifier is compared HERE rather than in the route, so the check
 * cannot be skipped by a caller that forgets it.
 */
create or replace function oauth_redeem_code(
  p_code_hash text, p_client_id text, p_redirect_uri text, p_challenge_from_verifier text,
  p_token_hash text, p_refresh_hash text, p_ttl_seconds int default 3600
) returns jsonb language plpgsql security definer set search_path = public as $$
declare v_auth oauth_authorizations; v_id uuid; v_ttl int;
begin
  v_ttl := greatest(60, least(coalesce(p_ttl_seconds, 3600), 86400));

  select * into v_auth from oauth_authorizations where code_hash = p_code_hash;
  if v_auth.id is null then return jsonb_build_object('error', 'unknown code'); end if;

  if v_auth.used_at is not null then
    -- REPLAYED. Burn every token this code produced.
    --
    -- This RETURNS an error rather than raising one, and that is the whole
    -- reason the function has this shape: `raise` aborts the transaction, which
    -- rolls back the UPDATE immediately above it. The first version did exactly
    -- that — it refused the second redemption and left the first redemption's
    -- token live, which is the precise opposite of what replay detection is
    -- for. Caught by the test that asserts the first token is dead afterwards.
    update oauth_tokens set revoked_at = now()
     where authorization_id = v_auth.id and revoked_at is null;
    return jsonb_build_object('error', 'code already used');
  end if;
  if v_auth.expires_at < now() then return jsonb_build_object('error', 'code expired'); end if;
  if v_auth.client_id <> p_client_id then return jsonb_build_object('error', 'wrong client'); end if;
  if v_auth.redirect_uri <> p_redirect_uri then return jsonb_build_object('error', 'redirect_uri mismatch'); end if;
  if v_auth.code_challenge <> p_challenge_from_verifier then
    return jsonb_build_object('error', 'PKCE verification failed');
  end if;

  -- Single-use, claimed atomically: two simultaneous redemptions of one code
  -- cannot both win, whatever the client does. A stolen code races the real one.
  update oauth_authorizations set used_at = now()
   where id = v_auth.id and used_at is null
  returning id into v_id;
  if v_id is null then return jsonb_build_object('error', 'code already used'); end if;

  insert into oauth_tokens (token_hash, refresh_hash, client_id, workspace_id, owner_privy,
                            scope, authorization_id, expires_at, refresh_expires_at)
  values (p_token_hash, p_refresh_hash, v_auth.client_id, v_auth.workspace_id, v_auth.owner_privy,
          v_auth.scope, v_auth.id,
          now() + make_interval(secs => v_ttl), now() + interval '90 days');

  return jsonb_build_object('scope', v_auth.scope, 'workspace_id', v_auth.workspace_id, 'expires_in', v_ttl);
end $$;
revoke all on function oauth_redeem_code(text, text, text, text, text, text, int) from public, anon, authenticated;
grant execute on function oauth_redeem_code(text, text, text, text, text, text, int) to service_role;

/**
 * Refresh, with rotation AND reuse detection.
 *
 * The old refresh token is revoked and a new one issued on every use — the same
 * rule the X integration follows (0082), because a refresh token that never
 * changes is a permanent credential sitting in somebody's config file.
 *
 * Presenting an ALREADY-ROTATED refresh token means one of two things: a client
 * retried, or a stolen token is being used. There is no way to tell which, so
 * the whole grant is revoked — OAuth 2.1 §4.14.2 asks for exactly this. Like
 * the replay case above it RETURNS rather than raises, so the revocation
 * actually commits.
 */
create or replace function oauth_refresh_token(
  p_refresh_hash text, p_client_id text, p_token_hash text, p_new_refresh_hash text,
  p_ttl_seconds int default 3600
) returns jsonb language plpgsql security definer set search_path = public as $$
declare v_old oauth_tokens; v_ttl int;
begin
  v_ttl := greatest(60, least(coalesce(p_ttl_seconds, 3600), 86400));

  select * into v_old from oauth_tokens where refresh_hash = p_refresh_hash;
  if v_old.id is null then return jsonb_build_object('error', 'unknown refresh token'); end if;
  if v_old.client_id <> p_client_id then return jsonb_build_object('error', 'wrong client'); end if;

  if v_old.revoked_at is not null then
    -- Reused. Burn the whole family this authorization produced.
    update oauth_tokens set revoked_at = now()
     where authorization_id is not distinct from v_old.authorization_id
       and client_id = v_old.client_id and revoked_at is null;
    return jsonb_build_object('error', 'refresh token already used');
  end if;
  if v_old.refresh_expires_at is not null and v_old.refresh_expires_at < now() then
    return jsonb_build_object('error', 'refresh token expired');
  end if;

  update oauth_tokens set revoked_at = now() where id = v_old.id;

  insert into oauth_tokens (token_hash, refresh_hash, client_id, workspace_id, owner_privy,
                            scope, authorization_id, expires_at, refresh_expires_at)
  values (p_token_hash, p_new_refresh_hash, v_old.client_id, v_old.workspace_id, v_old.owner_privy,
          v_old.scope, v_old.authorization_id,
          now() + make_interval(secs => v_ttl),
          -- The window does NOT extend with use; it keeps the original
          -- deadline, so a grant nobody re-consents to does eventually expire.
          v_old.refresh_expires_at);

  return jsonb_build_object('scope', v_old.scope, 'workspace_id', v_old.workspace_id, 'expires_in', v_ttl);
end $$;
revoke all on function oauth_refresh_token(text, text, text, text, int) from public, anon, authenticated;
grant execute on function oauth_refresh_token(text, text, text, text, int) to service_role;

/**
 * Resolve a bearer token to a workspace — the same shape `resolve_api_key`
 * returns, so `/api/mcp` treats an OAuth token and an `hb_` key identically
 * from the moment it is resolved.
 */
create or replace function oauth_resolve_token(p_hash text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_row oauth_tokens;
begin
  select * into v_row from oauth_tokens where token_hash = p_hash limit 1;
  if v_row.id is null then return null; end if;
  if v_row.revoked_at is not null or v_row.expires_at < now() then return null; end if;
  update oauth_tokens set last_used_at = now() where id = v_row.id;
  return jsonb_build_object(
    'id', v_row.id, 'workspace_id', v_row.workspace_id,
    'owner_privy', v_row.owner_privy,
    'scope', coalesce(v_row.scope, 'full'),
    'client_id', v_row.client_id
  );
end $$;
revoke all on function oauth_resolve_token(text) from public, anon, authenticated;
grant execute on function oauth_resolve_token(text) to service_role;

-- ── Taking it back ──────────────────────────────────────────────────────────
/** RFC 7009. Revoking by either token or refresh token, whichever was sent. */
create or replace function oauth_revoke_token(p_hash text, p_client_id text)
returns boolean language plpgsql security definer set search_path = public as $$
begin
  update oauth_tokens set revoked_at = now()
   where (token_hash = p_hash or refresh_hash = p_hash)
     and client_id = p_client_id and revoked_at is null;
  -- RFC 7009 says an unknown token is a SUCCESS, so a client cannot use this
  -- endpoint to discover which tokens exist.
  return true;
end $$;
revoke all on function oauth_revoke_token(text, text) from public, anon, authenticated;
grant execute on function oauth_revoke_token(text, text) to service_role;

/**
 * What a person has connected, and how to disconnect it.
 *
 * A grant nobody can see is a grant nobody revokes. Owner/admin scoped because
 * the token acts on the whole workspace, not on the person who created it.
 */
create or replace function oauth_list_grants(p_privy text, p_workspace uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', t.id, 'client_id', t.client_id, 'client_name', coalesce(c.client_name, t.client_id),
      'client_uri', c.client_uri, 'scope', t.scope,
      'created_at', t.created_at, 'last_used_at', t.last_used_at, 'expires_at', t.expires_at)
      order by t.created_at desc)
    from oauth_tokens t left join oauth_clients c on c.client_id = t.client_id
    where t.workspace_id = p_workspace and t.revoked_at is null and t.expires_at > now()
  ), '[]'::jsonb);
end $$;
grant execute on function oauth_list_grants(text, uuid) to authenticated, anon;

create or replace function oauth_revoke_grant(p_privy text, p_workspace uuid, p_id uuid)
returns boolean language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  if workspace_role(p_privy, p_workspace) not in ('owner','admin') then
    raise exception 'FORBIDDEN: only an owner or admin can disconnect an app';
  end if;
  -- The whole grant, not one access token: revoking the row a client is
  -- currently using while leaving its refresh token alive disconnects nothing.
  update oauth_tokens t set revoked_at = now()
   where t.workspace_id = p_workspace and t.revoked_at is null
     and t.client_id = (select client_id from oauth_tokens where id = p_id and workspace_id = p_workspace);
  return found;
end $$;
grant execute on function oauth_revoke_grant(text, uuid, uuid) to authenticated, anon;

/** Housekeeping for the cron: expired codes and long-dead tokens. */
create or replace function oauth_sweep()
returns int language plpgsql security definer set search_path = public as $$
declare n int;
begin
  delete from oauth_authorizations where expires_at < now() - interval '1 day';
  get diagnostics n = row_count;
  delete from oauth_tokens
   where (revoked_at is not null and revoked_at < now() - interval '30 days')
      or (refresh_expires_at is not null and refresh_expires_at < now() - interval '30 days');
  return n;
end $$;
revoke all on function oauth_sweep() from public, anon, authenticated;
grant execute on function oauth_sweep() to service_role;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0100_oauth_refresh_grace.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0100_oauth_refresh_grace.sql
-- A refresh retry must not destroy the connection.
--
-- ── THE BUG ─────────────────────────────────────────────────────────────────
-- 0099 rotates refresh tokens and detects reuse: presenting an already-rotated
-- token revokes the whole family, per OAuth 2.1 §4.14.2. That rule is right and
-- it is what the tests asserted.
--
-- What the tests did not cover is the ordinary case it also catches. A client
-- refreshes; the response is lost to a timeout, a dropped connection, or two
-- concurrent requests from the same client. The client retries with the same
-- refresh token — because it never received the replacement — and 0099 treats
-- that as theft and burns the grant. Permanently. The user sees
-- "requires re-authorization (token expired)" and reconnecting is the only fix,
-- until it happens again.
--
-- Observed for real against claude.ai, which is what makes this worth a
-- migration of its own rather than a note: the connector authorised
-- successfully, listed all 27 tools, and then died on the first refresh.
--
-- ── THE FIX, AND WHY IT IS NOT A WEAKENING ──────────────────────────────────
-- A GRACE WINDOW. Re-presenting a refresh token within 30 seconds of its
-- rotation is treated as a retry: fresh tokens are issued and the successor
-- that was minted in that window is revoked, so the chain does not fork.
-- Outside the window it is still theft and the family still burns.
--
-- The security question is what an attacker gains. To use a stolen refresh
-- token inside the window they must steal it and replay it within 30 seconds of
-- the legitimate client rotating it — and the legitimate client's next refresh
-- then lands outside ITS window and burns everything, so the theft is still
-- detected, just one cycle later. Weighed against a connection that breaks on
-- any dropped packet, this is the trade every serious implementation makes.
--
-- Depends on 0099. Idempotent & prod-safe.
-- ============================================================================

/**
 * Redefined IN FULL from 0099. The only change is the grace branch.
 */
create or replace function oauth_refresh_token(
  p_refresh_hash text, p_client_id text, p_token_hash text, p_new_refresh_hash text,
  p_ttl_seconds int default 3600
) returns jsonb language plpgsql security definer set search_path = public as $$
declare v_old oauth_tokens; v_ttl int; v_grace constant interval := interval '30 seconds';
begin
  v_ttl := greatest(60, least(coalesce(p_ttl_seconds, 3600), 86400));

  select * into v_old from oauth_tokens where refresh_hash = p_refresh_hash;
  if v_old.id is null then return jsonb_build_object('error', 'unknown refresh token'); end if;
  if v_old.client_id <> p_client_id then return jsonb_build_object('error', 'wrong client'); end if;

  if v_old.revoked_at is not null then
    if v_old.revoked_at > now() - v_grace then
      -- A RETRY, not a theft. The client never got the last response, so it is
      -- asking again with the only token it has. Revoke the successor minted in
      -- this window — otherwise every retry forks the chain and leaves live
      -- tokens nobody holds — and fall through to issue a fresh pair.
      update oauth_tokens set revoked_at = now()
       where authorization_id is not distinct from v_old.authorization_id
         and client_id = v_old.client_id
         and revoked_at is null
         and created_at >= v_old.revoked_at - v_grace;
    else
      -- Outside the window: treat as compromise and burn the family.
      update oauth_tokens set revoked_at = now()
       where authorization_id is not distinct from v_old.authorization_id
         and client_id = v_old.client_id and revoked_at is null;
      return jsonb_build_object('error', 'refresh token already used');
    end if;
  end if;

  if v_old.refresh_expires_at is not null and v_old.refresh_expires_at < now() then
    return jsonb_build_object('error', 'refresh token expired');
  end if;

  update oauth_tokens set revoked_at = now() where id = v_old.id and revoked_at is null;

  insert into oauth_tokens (token_hash, refresh_hash, client_id, workspace_id, owner_privy,
                            scope, authorization_id, expires_at, refresh_expires_at)
  values (p_token_hash, p_new_refresh_hash, v_old.client_id, v_old.workspace_id, v_old.owner_privy,
          v_old.scope, v_old.authorization_id,
          now() + make_interval(secs => v_ttl),
          -- The window does NOT extend with use; it keeps the original
          -- deadline, so a grant nobody re-consents to does eventually expire.
          v_old.refresh_expires_at);

  return jsonb_build_object('scope', v_old.scope, 'workspace_id', v_old.workspace_id, 'expires_in', v_ttl);
end $$;
revoke all on function oauth_refresh_token(text, text, text, text, int) from public, anon, authenticated;
grant execute on function oauth_refresh_token(text, text, text, text, int) to service_role;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0101_ai_usage.sql
-- ══════════════════════════════════════════════════════════════════════════
-- 0101: what is AI costing this workspace, across ALL of it
--
-- WHY THIS EXISTS. 0096 answered "which agent is spending my money" and stopped
-- there, because `agent_runs` is the only place a token count had somewhere to
-- live. Every other AI call in the product went through `callAI`, which
-- returned a bare string and threw the provider's usage block away at the
-- source — so the writing assistant, the newsletter drafter, the workspace
-- builder, the skill generator and the AI step inside automations were all
-- invisible. Five features, one of them (automations) running unattended on a
-- cron, and the usage screen showed a confident total that excluded every one
-- of them.
--
-- COUNTED, NEVER ESTIMATED — the same rule as 0096. These columns hold what the
-- provider reported. Nothing derives tokens from character counts: a number
-- that looks authoritative and is guessed is worse than no number, which is why
-- `unreported` is its own bucket rather than being folded into zero.
--
-- `cached_tokens` IS A SUBSET OF `input_tokens`, not an addition. Anthropic
-- reports cache reads outside `input_tokens`; the client folds them in before
-- they get here so the meaning is identical on every provider.

create table if not exists ai_usage (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspaces(id) on delete cascade,
  -- Who ran it. Kept as the privy id rather than a FK: the row survives the
  -- person leaving, and a cost report with a hole where a departed colleague
  -- used to be is the report nobody trusts.
  privy_user_id text,
  -- Which part of the product. A short stable slug, not a display name —
  -- renaming a screen must not split its history into two rows.
  feature text not null,
  provider text not null default '',
  model text not null default '',
  input_tokens  bigint not null default 0,
  output_tokens bigint not null default 0,
  cached_tokens bigint not null default 0,
  -- A failed call still costs. A model that spends its whole budget thinking
  -- and returns nothing is billed in full, and it is exactly the call somebody
  -- is trying to find when they ask why the bill is high.
  ok boolean not null default true,
  created_at timestamptz not null default now()
);

comment on column ai_usage.cached_tokens is
  'Part of input_tokens served from a prompt cache. A SUBSET of input_tokens — never add the two.';

-- The only query this table has: a workspace over a window. Ordering by
-- created_at inside the index means the window predicate is the index scan
-- rather than a filter over every row the workspace ever wrote.
create index if not exists idx_ai_usage_ws_time on ai_usage (workspace_id, created_at desc);

alter table ai_usage enable row level security;
-- No policy, deliberately: this table is written by service_role through
-- `record_ai_usage` and read through `get_ai_usage`, both SECURITY DEFINER.
-- A browser-reachable INSERT here would let anyone write numbers into their own
-- cost report, which is a strange thing to want and a worse thing to allow.

-- ── Writing ─────────────────────────────────────────────────────────────────
--
-- service_role only, and deliberately ABSENT from /api/rpc's ALLOWED list —
-- same rule as `claim_excel_links` and the social token functions. A client
-- that could write here could also hide its own spend.
create or replace function record_ai_usage(
  p_workspace uuid, p_privy text, p_feature text, p_provider text, p_model text,
  p_input bigint, p_output bigint, p_cached bigint, p_ok boolean
) returns void language plpgsql security definer set search_path = public as $$
begin
  -- A usage row is never worth failing the request that produced it. The caller
  -- already has the user's answer in hand; losing the accounting is a smaller
  -- harm than losing the work, so anything unusable is dropped quietly here
  -- rather than raised into a route that has nothing useful to do with it.
  if p_workspace is null or coalesce(p_feature,'') = '' then return; end if;
  insert into ai_usage (workspace_id, privy_user_id, feature, provider, model,
                        input_tokens, output_tokens, cached_tokens, ok)
  values (p_workspace, nullif(p_privy,''), p_feature, coalesce(p_provider,''), coalesce(p_model,''),
          greatest(coalesce(p_input,0),0), greatest(coalesce(p_output,0),0),
          greatest(coalesce(p_cached,0),0), coalesce(p_ok,true));
end $$;
revoke all on function record_ai_usage(uuid, text, text, text, text, bigint, bigint, bigint, boolean) from public, authenticated, anon;
grant execute on function record_ai_usage(uuid, text, text, text, text, bigint, bigint, bigint, boolean) to service_role;

-- ── Reading ─────────────────────────────────────────────────────────────────
--
-- ONE FUNCTION OVER BOTH TABLES, and that is the point of the migration rather
-- than an optimisation. Agent spend lives in `agent_runs` and everything else
-- lives in `ai_usage`; a screen that reads one of them is the same bug this
-- migration exists to fix, one level up. So the union happens here, in SQL,
-- where it cannot be forgotten by the next caller.
--
-- `p_days` is clamped: an unbounded window with no date predicate is a
-- sequential scan somebody triggers by typing a large number into a URL.
create or replace function get_ai_usage(p_privy text, p_workspace uuid, p_days int default 30)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_days int := least(greatest(coalesce(p_days, 30), 1), 365);
  v_since timestamptz;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  v_since := now() - make_interval(days => v_days);

  return (
    with rows as (
      select feature, provider, model, input_tokens, output_tokens, cached_tokens, ok, created_at
      from ai_usage
      where workspace_id = p_workspace and created_at > v_since
      union all
      -- Agent runs, as one feature. `agent_runs` has no provider column, so it
      -- reports blank rather than a guess — the model is what identifies the
      -- spend anyway, and inventing a provider from a model name would be wrong
      -- for exactly the OpenRouter and custom-gateway rows that need it most.
      select 'agents', '', model, input_tokens, output_tokens, cached_tokens,
             status <> 'error', created_at
      from agent_runs
      where workspace_id = p_workspace and created_at > v_since
    )
    select jsonb_build_object(
      'days', v_days,
      'totals', (
        select jsonb_build_object(
          'calls', count(*),
          'input', coalesce(sum(input_tokens),0),
          'output', coalesce(sum(output_tokens),0),
          'cached', coalesce(sum(cached_tokens),0),
          'failed', count(*) filter (where not ok),
          -- Calls that reported nothing at all. Without this the screen cannot
          -- tell "cheap" from "this gateway does not report usage", and would
          -- present a total missing an unknown share of the spend.
          'unreported', count(*) filter (where input_tokens = 0 and output_tokens = 0)
        ) from rows
      ),
      'by_feature', coalesce((
        select jsonb_agg(x order by (x->>'input')::bigint + (x->>'output')::bigint desc) from (
          select jsonb_build_object(
            'feature', feature, 'calls', count(*),
            'input', coalesce(sum(input_tokens),0),
            'output', coalesce(sum(output_tokens),0),
            'cached', coalesce(sum(cached_tokens),0),
            'failed', count(*) filter (where not ok)
          ) as x
          from rows group by feature
        ) a
      ), '[]'::jsonb),
      'by_model', coalesce((
        select jsonb_agg(x order by (x->>'input')::bigint + (x->>'output')::bigint desc) from (
          select jsonb_build_object(
            'model', nullif(model,''), 'provider', max(provider), 'calls', count(*),
            'input', coalesce(sum(input_tokens),0),
            'output', coalesce(sum(output_tokens),0),
            'cached', coalesce(sum(cached_tokens),0)
          ) as x
          from rows group by model
        ) a
      ), '[]'::jsonb),
      -- A day series, so a spike has a date on it. Zero-filled from
      -- generate_series: a chart that silently omits quiet days compresses the
      -- x-axis and makes every gap look like activity.
      'daily', coalesce((
        select jsonb_agg(jsonb_build_object(
          'day', to_char(d.day, 'YYYY-MM-DD'),
          'input', coalesce(r.input, 0), 'output', coalesce(r.output, 0)
        ) order by d.day)
        from generate_series(date_trunc('day', v_since), date_trunc('day', now()), interval '1 day') as d(day)
        left join (
          select date_trunc('day', created_at) as day,
                 sum(input_tokens) as input, sum(output_tokens) as output
          from rows group by 1
        ) r on r.day = d.day
      ), '[]'::jsonb)
    )
  );
end $$;
grant execute on function get_ai_usage(text, uuid, int) to authenticated, anon;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0102_copilot.sql
-- ══════════════════════════════════════════════════════════════════════════
-- 0102: the Copilot — a conversation that can act on the workspace
--
-- WHY THIS IS A THREAD TABLE AND NOT A NEW AGENT SYSTEM. Everything a copilot
-- needs in order to DO things already exists and is already tenancy-safe: 27
-- tools behind one executor (`lib/agents/tools.ts`), suggest/auto autonomy,
-- proposal-and-approval, a per-run audit log (0043), live steps (0095) and
-- token accounting (0096/0101). The only thing missing was memory — `runAgent`
-- takes one task string and returns, so every question started from nothing.
-- So this adds the conversation and nothing else: each assistant turn is still
-- an ordinary `agent_runs` row, which is what makes approvals, the transcript
-- and the cost report work here for free rather than needing a second copy.
--
-- A THREAD BELONGS TO A PERSON, NOT TO THE WORKSPACE. Every other object here
-- is workspace-scoped, and this one deliberately is not: a copilot thread
-- contains whatever someone typed into it — half-formed plans, salary
-- questions, a draft of a message about a colleague. Making those readable by
-- every member because they share a workspace is a surprise nobody consented
-- to. Membership is still required (the workspace is where the data lives), but
-- ownership is the row's own `privy_user_id`.

create table if not exists copilot_threads (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspaces(id) on delete cascade,
  privy_user_id text not null,
  -- Derived from the first message rather than asked for. A "name this chat"
  -- box is a question nobody wants at the moment they have just thought of
  -- something.
  title text not null default '',
  -- Per THREAD, not per workspace. "Draft me a plan" and "clean up these
  -- invoices" want different answers to "should this execute", and a single
  -- global switch means the honest choice is always the restrictive one.
  autonomy text not null default 'suggest' check (autonomy in ('suggest','auto')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists idx_copilot_threads_owner
  on copilot_threads (workspace_id, privy_user_id, updated_at desc);

create table if not exists copilot_messages (
  id uuid primary key default gen_random_uuid(),
  thread_id uuid not null references copilot_threads(id) on delete cascade,
  role text not null check (role in ('user','assistant')),
  content text not null default '',
  -- The run that produced an assistant turn. `set null` rather than cascade:
  -- losing the run must not delete the reply the person actually read, and the
  -- reply is the part of the record that matters afterwards.
  run_id uuid references agent_runs(id) on delete set null,
  -- What the person was looking at when they asked. Stored because "add her to
  -- the list" is only answerable with it, and because a transcript that cannot
  -- explain why the copilot picked an object is a transcript nobody can audit.
  page_path text not null default '',
  created_at timestamptz not null default now()
);
create index if not exists idx_copilot_messages_thread
  on copilot_messages (thread_id, created_at);

alter table copilot_threads enable row level security;
alter table copilot_messages enable row level security;
-- No policies: everything below is SECURITY DEFINER and re-checks both
-- membership AND ownership. Anon reaches these only through /api/rpc, which
-- overwrites p_privy from the verified token.

-- ── Ownership, in one place ─────────────────────────────────────────────────
--
-- Every function below calls this. Scattering the rule is how the private half
-- of a private thread eventually leaks — the same reasoning as
-- `can_read_channel` in 0075.
create or replace function copilot_thread_owned(p_thread uuid, p_privy text)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from copilot_threads t
    where t.id = p_thread
      and t.privy_user_id = p_privy
      and is_workspace_member(t.workspace_id, p_privy)
  );
$$;

create or replace function get_copilot_threads(p_privy text, p_workspace uuid, p_limit int default 30)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_limit int := least(greatest(coalesce(p_limit, 30), 1), 100);
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', t.id, 'title', t.title, 'autonomy', t.autonomy, 'updated_at', t.updated_at
    ) order by t.updated_at desc)
    from (
      select * from copilot_threads
      where workspace_id = p_workspace and privy_user_id = p_privy
      order by updated_at desc limit v_limit
    ) t
  ), '[]'::jsonb);
end $$;
grant execute on function get_copilot_threads(text, uuid, int) to authenticated, anon;

-- One thread, with its messages and whatever each assistant turn actually did.
--
-- The run is joined here rather than fetched per message by the client: a
-- twenty-turn thread would otherwise be twenty round trips, and the steps are
-- what make the reply believable.
create or replace function get_copilot_thread(p_privy text, p_thread uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not copilot_thread_owned(p_thread, p_privy) then raise exception 'NOT_FOUND'; end if;
  return (
    select jsonb_build_object(
      'id', t.id, 'title', t.title, 'autonomy', t.autonomy,
      'messages', coalesce((
        select jsonb_agg(jsonb_build_object(
          'id', m.id, 'role', m.role, 'content', m.content,
          'page_path', m.page_path, 'created_at', m.created_at,
          'run_id', m.run_id,
          'status', r.status, 'steps', r.steps, 'proposed', r.proposed
        ) order by m.created_at)
        from copilot_messages m
        left join agent_runs r on r.id = m.run_id
        where m.thread_id = t.id
      ), '[]'::jsonb)
    )
    from copilot_threads t where t.id = p_thread
  );
end $$;
grant execute on function get_copilot_thread(text, uuid) to authenticated, anon;

create or replace function create_copilot_thread(p_privy text, p_workspace uuid, p_autonomy text default 'suggest')
returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  insert into copilot_threads (workspace_id, privy_user_id, autonomy)
  -- An unrecognised value falls back to the SAFE one, never to 'auto'. A typo
  -- must not be how a thread starts executing writes without being asked.
  values (p_workspace, p_privy, case when p_autonomy = 'auto' then 'auto' else 'suggest' end)
  returning id into v_id;
  return v_id;
end $$;
grant execute on function create_copilot_thread(text, uuid, text) to authenticated, anon;

create or replace function set_copilot_thread(p_privy text, p_thread uuid, p_title text default null, p_autonomy text default null)
returns void language plpgsql security definer set search_path = public as $$
begin
  if not copilot_thread_owned(p_thread, p_privy) then raise exception 'NOT_FOUND'; end if;
  -- NULL means "leave it alone", the same reading `update_record` gives an
  -- absent key (0088) — otherwise renaming a thread would silently reset its
  -- autonomy to whatever the caller happened to not send.
  update copilot_threads set
    title = coalesce(nullif(p_title, ''), title),
    autonomy = case when p_autonomy in ('suggest','auto') then p_autonomy else autonomy end,
    updated_at = now()
  where id = p_thread;
end $$;
grant execute on function set_copilot_thread(text, uuid, text, text) to authenticated, anon;

create or replace function delete_copilot_thread(p_privy text, p_thread uuid)
returns void language plpgsql security definer set search_path = public as $$
begin
  if not copilot_thread_owned(p_thread, p_privy) then raise exception 'NOT_FOUND'; end if;
  delete from copilot_threads where id = p_thread;
end $$;
grant execute on function delete_copilot_thread(text, uuid) to authenticated, anon;

-- ── Writing a turn ──────────────────────────────────────────────────────────
--
-- service_role ONLY, and deliberately absent from /api/rpc's ALLOWED list. The
-- same rule that keeps `append_agent_run_step` server-side: a client that could
-- write assistant messages could forge a transcript of work that never
-- happened, complete with a run id pointing at somebody else's run.
create or replace function append_copilot_message(
  p_thread uuid, p_role text, p_content text,
  p_run uuid default null, p_page text default ''
) returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid;
begin
  if p_role not in ('user','assistant') then raise exception 'BAD_ROLE'; end if;
  insert into copilot_messages (thread_id, role, content, run_id, page_path)
  values (p_thread, p_role, coalesce(p_content,''), p_run, coalesce(p_page,''))
  returning id into v_id;

  -- The title is the first thing the person said, trimmed. Set once and never
  -- overwritten, so a thread keeps the name its owner recognises even after
  -- twenty turns have moved the subject on.
  update copilot_threads set
    updated_at = now(),
    title = case
      when title <> '' or p_role <> 'user' then title
      else left(regexp_replace(coalesce(p_content,''), '\s+', ' ', 'g'), 60)
    end
  where id = p_thread;
  return v_id;
end $$;
revoke all on function append_copilot_message(uuid, text, text, uuid, text) from public, authenticated, anon;
grant execute on function append_copilot_message(uuid, text, text, uuid, text) to service_role;

-- The conversation so far, as plain turns, for seeding the next run.
--
-- PLAIN TEXT, NOT PROVIDER HISTORY. A Claude turn is content blocks and an
-- OpenAI turn is a message list; storing either would make a thread break the
-- moment somebody changes their model, and tool traffic inside a past run is
-- not context the next run needs. Newest-N then reversed, so a long thread
-- stays affordable rather than growing the prompt without limit.
create or replace function get_copilot_history(p_thread uuid, p_turns int default 12)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_turns int := least(greatest(coalesce(p_turns, 12), 1), 40);
begin
  return coalesce((
    select jsonb_agg(jsonb_build_object('role', m.role, 'content', m.content) order by m.created_at)
    from (
      select role, content, created_at from copilot_messages
      where thread_id = p_thread and content <> ''
      order by created_at desc limit v_turns
    ) m
  ), '[]'::jsonb);
end $$;
revoke all on function get_copilot_history(uuid, int) from public, authenticated, anon;
grant execute on function get_copilot_history(uuid, int) to service_role;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0103_skill_source_copilot.sql
-- ══════════════════════════════════════════════════════════════════════════
-- 0103: a skill the copilot wrote should say so
--
-- `skills.source` has been `local | github` since 0068 — written by hand, or
-- imported from a public SKILL.md. The copilot can now write one (it has
-- `save_skill`), and it is neither: `local` claims a person typed it.
--
-- WHY THIS IS A MIGRATION AND NOT A COMMENT. The client passed `'copilot'`
-- and `save_skill` quietly mapped it back to `'local'` — the CHECK constraint
-- would have rejected the row, so 0068's `case when p_source in (...)` fell
-- through to the default. Nothing failed, nothing warned, and the code carried
-- a comment explaining an attribution the database was discarding. That is the
-- same shape as every silent bug in this schema's history, and the fix is to
-- make the database able to store the truth rather than to delete the comment.
--
-- It matters for the same reason `record_notes.source` is NOT NULL: a claim you
-- cannot trace is a claim you cannot check. Somebody reviewing a skill that is
-- teaching every agent how this company chases money should be able to see, a
-- year later, whether a person wrote it.

alter table skills drop constraint if exists skills_source_check;
alter table skills add constraint skills_source_check
  check (source in ('local', 'github', 'copilot'));

-- Redefined IN FULL rather than patched: the whitelist lives inside the
-- function body as well as in the constraint, and leaving the two disagreeing
-- is how the value gets silently rewritten a second time.
create or replace function save_skill(
  p_privy text, p_workspace uuid, p_id uuid, p_name text, p_description text,
  p_instructions text, p_suggested_tools text[], p_source text, p_source_url text
) returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid;
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  -- A skill body becomes part of a system prompt; an unbounded one would blow
  -- the context window of every agent carrying it, so it is capped here rather
  -- than only in the UI (the RPC is reachable without the UI).
  if length(coalesce(p_instructions, '')) > 20000 then raise exception 'SKILL_TOO_LARGE'; end if;
  if p_id is null then
    insert into skills (workspace_id, name, description, instructions, suggested_tools,
                        source, source_url, created_by_privy)
    values (p_workspace, coalesce(nullif(p_name, ''), 'New skill'), coalesce(p_description, ''),
            coalesce(p_instructions, ''), coalesce(p_suggested_tools, '{}'),
            case when p_source in ('local', 'github', 'copilot') then p_source else 'local' end,
            coalesce(p_source_url, ''), p_privy)
    returning id into v_id;
  else
    -- `source` is deliberately NOT updatable. Editing a skill the copilot wrote
    -- does not make it hand-written, and letting an update relabel it would
    -- make the field worth nothing the first time somebody fixed a typo.
    update skills set
      name = coalesce(nullif(p_name, ''), name),
      description = coalesce(p_description, description),
      instructions = coalesce(p_instructions, instructions),
      suggested_tools = coalesce(p_suggested_tools, suggested_tools)
    where id = p_id and workspace_id = p_workspace
    returning id into v_id;
  end if;
  return v_id;
end $$;
grant execute on function save_skill(text, uuid, uuid, text, text, text, text[], text, text) to authenticated, anon;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0104_model_prices.sql
-- ══════════════════════════════════════════════════════════════════════════
-- 0104: a workspace's own model prices
--
-- `lib/ai/pricing.ts` ships list prices with a date on them, and says in its own
-- header that a shipped table cannot be the final answer. This is the other
-- half: the numbers a workspace is ACTUALLY billed.
--
-- Three cases the shipped table can never get right, all of them common:
--   • A negotiated rate. Anyone spending real money has one.
--   • OpenRouter, whose price for the same model varies by which upstream served
--     it — there is no single number to ship.
--   • A self-hosted model, which costs nothing per token and appears in the
--     shipped table as "unknown" forever.
--
-- WORKSPACE-SCOPED, NOT GLOBAL. A price is a fact about somebody's contract, not
-- about the model, so one workspace's negotiated rate must never become another
-- workspace's estimate.
--
-- USD per MILLION tokens, matching both how providers publish and how the
-- shipped table stores them. Per-token would be six leading zeros and a typo
-- nobody catches in review.

create table if not exists model_prices (
  workspace_id uuid not null references workspaces(id) on delete cascade,
  -- Stored lowercase so matching cannot depend on how somebody typed it; the
  -- client matches exact-then-prefix, exactly as `priceFor` does.
  model text not null,
  input_usd  numeric(12,6) not null default 0,
  output_usd numeric(12,6) not null default 0,
  -- NULL means "billed as input", which is what most providers do. NOT zero:
  -- zero claims cache reads are free, which under-reports precisely the agent
  -- loops that cache the most.
  cached_usd numeric(12,6),
  note text not null default '',
  updated_at timestamptz not null default now(),
  primary key (workspace_id, model)
);

alter table model_prices enable row level security;
-- No policies: everything goes through the SECURITY DEFINER functions below.

create or replace function get_model_prices(p_privy text, p_workspace uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_workspace_member(p_workspace, p_privy) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((
    select jsonb_object_agg(model, jsonb_build_object(
      'input', input_usd, 'output', output_usd, 'cached', cached_usd, 'note', note
    ))
    from model_prices where workspace_id = p_workspace
  ), '{}'::jsonb);
end $$;
grant execute on function get_model_prices(text, uuid) to authenticated, anon;

-- Owner/admin only. A price changes what every cost figure in the workspace
-- says, which is the same class of change as branding or the plan — not
-- something one member should do to everyone else's numbers.
create or replace function save_model_price(
  p_privy text, p_workspace uuid, p_model text,
  p_input numeric, p_output numeric, p_cached numeric, p_note text
) returns void language plpgsql security definer set search_path = public as $$
declare v_role text;
begin
  select role into v_role from accounts
   where workspace_id = p_workspace and privy_user_id = p_privy;
  if v_role is null or v_role not in ('owner','admin') then raise exception 'NOT_ALLOWED'; end if;
  if coalesce(trim(p_model), '') = '' then raise exception 'MODEL_REQUIRED'; end if;
  -- A negative price is not a discount, it is a typo that makes spend shrink as
  -- usage grows.
  if p_input < 0 or p_output < 0 or coalesce(p_cached, 0) < 0 then raise exception 'NEGATIVE_PRICE'; end if;

  insert into model_prices (workspace_id, model, input_usd, output_usd, cached_usd, note)
  values (p_workspace, lower(trim(p_model)), p_input, p_output, p_cached, coalesce(p_note, ''))
  on conflict (workspace_id, model) do update set
    input_usd = excluded.input_usd, output_usd = excluded.output_usd,
    cached_usd = excluded.cached_usd, note = excluded.note, updated_at = now();
end $$;
grant execute on function save_model_price(text, uuid, text, numeric, numeric, numeric, text) to authenticated, anon;

create or replace function delete_model_price(p_privy text, p_workspace uuid, p_model text)
returns void language plpgsql security definer set search_path = public as $$
declare v_role text;
begin
  select role into v_role from accounts
   where workspace_id = p_workspace and privy_user_id = p_privy;
  if v_role is null or v_role not in ('owner','admin') then raise exception 'NOT_ALLOWED'; end if;
  -- Deleting an override falls BACK to the shipped list price. It does not make
  -- the model unpriced — that is what makes an override an override.
  delete from model_prices where workspace_id = p_workspace and model = lower(trim(p_model));
end $$;
grant execute on function delete_model_price(text, uuid, text) to authenticated, anon;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0105_revoke_public_execute_again.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0105_revoke_public_execute_again.sql
--
-- 0046 closed this hole. Every migration written since re-opened it, one
-- function at a time, and nothing noticed for fifty-nine migrations.
--
-- WHAT WENT WRONG
--   Postgres grants EXECUTE to PUBLIC on every new function. 0046 revoked that
--   from `public, anon, authenticated` and granted `service_role` instead —
--   correctly, and by iteration so nothing was missed. But it fixed the
--   FUNCTIONS THAT EXISTED IN 0046, not the convention. From 0047 onward the
--   house style became
--       grant execute on function <name>(...) to authenticated, anon;
--   which is what 0104 still does. That line is not merely redundant with the
--   PUBLIC default — it re-states it explicitly, so every function added after
--   0046 shipped anon-callable.
--
--   Measured against production on 2026-08-14: 69 SECURITY DEFINER functions
--   were executable by `anon`. DEFINER bypasses RLS, and the anon key is public
--   by construction (NEXT_PUBLIC_SUPABASE_ANON_KEY ships in the browser bundle),
--   so each one was reachable straight against the Supabase REST endpoint,
--   routing around /api/rpc exactly as 0046 describes.
--
--   Among them: the whole CRUD monolith (list/get/create/update/delete_record),
--   create_api_key, get_api_keys, rename_workspace, save_agent,
--   save_custom_object, oauth_revoke_grant, post_message, save_doc.
--   Most authorize on the p_privy the CALLER supplies, so the barrier is
--   knowing a member's Privy DID and a workspace uuid — identifiers, not
--   credentials. That is the same barrier 0046 judged insufficient.
--
--   THREE ARE WORSE, because they take no p_privy and authorize nothing:
--     • builtin_extras_write(p_workspace, p_object, p_id, p_data, p_partial)
--       trusts p_workspace from its caller and runs
--         update <table> set custom_fields = custom_fields || $1
--          where id = $2 and workspace_id = $3
--       That trust is correct for an INTERNAL helper — create_record validated
--       the workspace before calling it — and is a cross-tenant write primitive
--       the moment anon can call it directly.
--     • builtin_extras_add(p_object, p_id, p_row) reads workspace_id and
--       custom_fields off any row by id and returns the extras merged in, so it
--       reads another tenant's custom fields with no argument but the record id.
--     • builtin_extras_addmany, same shape in bulk.
--   These are gated only by uuid unguessability, which is not authorization:
--   record ids travel in URLs, CSV exports, agent transcripts and screenshots.
--
-- WHY A SWEEP RATHER THAN EDITING THE OFFENDING MIGRATIONS
--   0047–0104 have already run on production and on every self-hosted install.
--   Editing their grant lines would fix a fresh `npm run migrate` and leave
--   every existing database untouched. A sweep that runs LAST fixes both, and
--   re-running it is free — which is what makes it safe to keep re-applying as
--   the convention keeps slipping.
--
-- ⚠️ RUN ORDER — SAME CAVEAT 0046 CARRIED, CHECK IT FIRST:
--   /api/rpc must be talking to Postgres as `service_role`. It falls back to the
--   anon key when SUPABASE_SERVICE_ROLE_KEY is unset (app/api/rpc/route.ts), and
--   after this migration the anon key can no longer execute these functions —
--   every dashboard read would start failing. 0046 already shipped, so this is
--   true today; confirm it is still true before running.
--
-- Rollback for one function if a public flow turns out to need it:
--   grant execute on function public.<name>(<args>) to anon;
--   …and add it to keep_public below, or the next run takes it away again.
--
-- Idempotent. Verify with supabase/audit-security.sql — section B should list
-- ONLY the keep_public names afterwards.
-- ============================================================================

do $$
declare
  r record;
  -- Genuinely public surfaces: callers with no Privy session, talking to
  -- Postgres with the anon key through the direct supabase client rather than
  -- through /api/rpc. Each is token-gated (the caller must already hold a uuid
  -- or secret) or writes only its own row.
  --
  -- Verified against the repo by finding every `.rpc(` callsite that is NOT
  -- lib/rpc.ts (the proxy) and NOT a server route holding the admin client.
  keep_public text[] := array[
    -- 0046's original list, unchanged.
    'apply_to_position',            -- public job application
    'set_candidate_cv',             -- CV upload during apply (token-gated)
    'get_assessment_init_data',     -- assessment load (token-gated)
    'submit_assessment',            -- assessment submit (token-gated)
    'log_consent',                  -- GDPR consent during apply
    'register_link_click',          -- tracking-link click counter
    'company_can_accept_candidate', -- plan cap check in the apply flow
    'get_invoice_document_public',  -- shared invoice view (token-gated)
    'get_post_public',              -- shared post review (token-gated)
    'add_post_comment_public',      -- comment on a shared post (token-gated)

    -- ADDED HERE. app/apply/[positionId]/page.tsx and its assessment page call
    -- this on the direct supabase client, before anyone has signed in — it is
    -- what puts the employer's logo and colours on the application form. It
    -- postdates 0046, so 0046's list could not have known about it, and
    -- sweeping it away would break the apply flow for every candidate.
    'get_apply_branding',

    -- Also public, and listed so a future migration that makes one of them
    -- SECURITY DEFINER does not silently break the page. They are no-ops today:
    -- the loop below only touches functions that are DEFINER *and* currently
    -- granted, and these are neither.
    'get_careers_page',             -- /careers/<slug>
    'get_careers_position',         -- /careers/<slug>/<positionId>
    'get_public_form',              -- /f/<slug>
    'submit_form',                  -- /f/<slug> submit
    'get_sign_request',             -- /sign/<token>
    'get_invite_by_token',          -- /auth/accept
    'newsletter_confirm',           -- double opt-in link
    'newsletter_unsubscribe',       -- unsubscribe link
    'register_short_click'          -- /l/<code>
  ];
  n_revoked int := 0;
begin
  for r in
    select p.oid,
           p.proname,
           pg_get_function_identity_arguments(p.oid) as args
    from pg_proc p
    join pg_namespace ns on ns.oid = p.pronamespace
    where ns.nspname = 'public'
      and p.prosecdef                       -- DEFINER only: these bypass RLS
      and not (p.proname = any(keep_public))
      and (has_function_privilege('anon', p.oid, 'execute')
        or has_function_privilege('authenticated', p.oid, 'execute'))
  loop
    -- Trigger functions are included deliberately. PostgreSQL does not check
    -- EXECUTE on a trigger function when the trigger fires, so revoking here
    -- hardens them without breaking the triggers that call them.
    execute format('revoke all on function public.%I(%s) from public, anon, authenticated',
                   r.proname, r.args);
    execute format('grant execute on function public.%I(%s) to service_role',
                   r.proname, r.args);
    n_revoked := n_revoked + 1;
  end loop;
  raise notice 'revoked public EXECUTE on % SECURITY DEFINER function(s)', n_revoked;
end $$;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════════
-- 0106_webhook_endpoints.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ============================================================================
-- RunButter — 0106_webhook_endpoints.sql
--
-- Settings → Integrations has called three functions that do not exist on
-- production since the day it was written.
--
-- `webhook_endpoints`, get_webhook_endpoints, upsert_webhook_endpoint and
-- delete_webhook_endpoint live in supabase/legacy/add-webhooks.sql, and
-- scripts/migrate.mjs runs supabase/legacy/* ONLY on a genuinely empty
-- database. Production predates the numbered migrations and was never empty, so
-- that file never ran there: the table is absent and so are all three RPCs.
--
-- HOW IT STAYED INVISIBLE. app/dashboard/settings/page.tsx reads the list with
--     const { data } = await rpc('get_webhook_endpoints', …)
-- and never looks at `error` — the recurring bug this codebase names in its own
-- conventions. So the call fails, `data` is null, and the panel renders "no
-- integrations" rather than a fault. Adding one does surface the PostgREST
-- error, which is why the feature reads as broken-on-save rather than missing.
-- lib/webhooks.ts logs its load error and returns, so nothing was ever
-- delivered either.
--
-- THE LEGACY DEFINITION IS NOT COPIED VERBATIM — it resolves the company with
--     select company_id into v_company_id from company_users
--      where privy_user_id = p_privy_user_id limit 1;
-- three times. A bare LIMIT 1 with no ORDER BY returns an ARBITRARY row for
-- anyone who belongs to two companies, which is the defect this repo already
-- paid for once ("my positions disappeared" while the careers page still showed
-- them). hr_company_id() is the resolver that mirrors it correctly — active
-- workspace first, else the OLDEST membership — so all three use it.
--
-- GRANTS ARE service_role ONLY. These are reached from the browser through
-- /api/rpc, which is where the Privy token is verified; they are not a public
-- surface. Granting anon here is what 0105 exists to undo.
--
-- AND GRANTING service_role IS NOT ENOUGH ON ITS OWN — the REVOKE is the half
-- that does the work. Postgres grants EXECUTE to PUBLIC on every new function,
-- and anon/authenticated inherit through PUBLIC, so a function that merely
-- omits the `to authenticated, anon` line is still anon-callable the moment it
-- is created. This migration shipped that way for one run and CI's own
-- check:grants gate caught all three functions; the fix is to revoke first,
-- every time, which is why each one below is a revoke/grant pair.
-- ============================================================================

create table if not exists webhook_endpoints (
  id         uuid primary key default gen_random_uuid(),
  company_id uuid references companies(id) on delete cascade,
  label      text not null default '',
  type       text not null default 'generic',   -- slack | discord | generic
  url        text not null,
  events     text[] not null default array['application.created','candidate.stage_changed','candidate.hired'],
  is_active  boolean not null default true,
  created_at timestamptz not null default now()
);

create index if not exists idx_webhook_endpoints_company on webhook_endpoints(company_id);

alter table webhook_endpoints enable row level security;
-- No policies, deliberately. Every read and write goes through the SECURITY
-- DEFINER functions below; the legacy file's anon-readable SELECT policy is the
-- shape 0077 spent a migration removing.

-- Adding a parameter to a Postgres function creates an OVERLOAD rather than
-- replacing it, and PostgREST answers an ambiguous call with a 400 it cannot
-- explain. Drop every existing signature first so a re-run cannot leave two.
do $$
declare r record;
begin
  for r in
    select 'drop function if exists ' || oid::regprocedure || ' cascade;' as stmt
      from pg_proc
     where pronamespace = 'public'::regnamespace
       and proname in ('get_webhook_endpoints', 'upsert_webhook_endpoint', 'delete_webhook_endpoint')
  loop
    execute r.stmt;
  end loop;
end $$;

create or replace function get_webhook_endpoints(p_privy_user_id text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_company_id uuid := hr_company_id(p_privy_user_id);
begin
  if v_company_id is null then return '[]'::jsonb; end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
             'id', t.id, 'label', t.label, 'type', t.type,
             'url', t.url, 'events', t.events, 'is_active', t.is_active
           ) order by t.created_at)
      from webhook_endpoints t
     where t.company_id = v_company_id
  ), '[]'::jsonb);
end $$;
revoke all on function get_webhook_endpoints(text) from public, anon, authenticated;
grant execute on function get_webhook_endpoints(text) to service_role;

create or replace function upsert_webhook_endpoint(
  p_privy_user_id text, p_id uuid, p_label text, p_type text, p_url text,
  p_events text[], p_is_active boolean
) returns jsonb language plpgsql security definer set search_path = public as $$
declare v_company_id uuid := hr_company_id(p_privy_user_id); v_row webhook_endpoints;
begin
  if v_company_id is null then raise exception 'RECRUITER_NOT_FOUND'; end if;
  if coalesce(trim(p_url), '') = '' then raise exception 'URL_REQUIRED'; end if;

  if p_id is null then
    insert into webhook_endpoints (company_id, label, type, url, events, is_active)
    values (
      v_company_id, coalesce(p_label, ''), coalesce(nullif(p_type, ''), 'generic'), p_url,
      coalesce(p_events, array['application.created','candidate.stage_changed','candidate.hired']),
      coalesce(p_is_active, true)
    )
    returning * into v_row;
  else
    update webhook_endpoints
       set label     = coalesce(p_label, ''),
           type      = coalesce(nullif(p_type, ''), 'generic'),
           url       = p_url,
           events    = coalesce(p_events, events),
           is_active = coalesce(p_is_active, is_active)
     where id = p_id and company_id = v_company_id
    returning * into v_row;
    -- Scoped to the caller's company, so a missing row means "not yours" just
    -- as much as "not there". Both are NOT_FOUND on purpose: telling them apart
    -- would confirm the id exists in some other tenant.
    if v_row.id is null then raise exception 'ENDPOINT_NOT_FOUND'; end if;
  end if;
  return to_jsonb(v_row);
end $$;
revoke all on function upsert_webhook_endpoint(text, uuid, text, text, text, text[], boolean) from public, anon, authenticated;
grant execute on function upsert_webhook_endpoint(text, uuid, text, text, text, text[], boolean) to service_role;

create or replace function delete_webhook_endpoint(p_privy_user_id text, p_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_company_id uuid := hr_company_id(p_privy_user_id);
begin
  if v_company_id is null then raise exception 'RECRUITER_NOT_FOUND'; end if;
  delete from webhook_endpoints where id = p_id and company_id = v_company_id;
  return jsonb_build_object('ok', true);
end $$;
revoke all on function delete_webhook_endpoint(text, uuid) from public, anon, authenticated;
grant execute on function delete_webhook_endpoint(text, uuid) to service_role;

notify pgrst, 'reload schema';

